// Content for Your Path, Your Call (node g54, ages 22+, Chapter 7): NEW v2 build to GDD 54 (mechanic-embodying),
// the EQUITY HEART of Chapter 7 and the essential counterpoint to Choosing & Building (g53): marriage and children
// are ONE valid path, not the measure of a life or a verdict on worth. 84 researched, India-grounded scenarios
// across script-and-choice → not-marrying → childfree-complete → hold-your-ground → worth-beyond-status →
// tools-and-reflection, each encoded as one of the shared v2 play actions (strike-rewrite / branch / role-play /
// sort / reflect / match / spot): no binary "tap the right card". Lead: strike-rewrite (bust the stigma), branch
// (your call), role-play (hold your ground). Five themes: the script & the choice (autonomy over your own life
// whether, when and whom to marry, whether to have children), not marrying (a full life needs no marriage; bust
// the "still unmarried?" worth-questioning stigma, heaviest on women; UN&RE), childfree complete (the freedom not
// to have children; womanhood isn't motherhood), hold your ground (handle family & social pressure kindly but
// firmly, without a family war), worth beyond status (your value is never your marital state, looks or the
// marriage market: incl. colourism). NO pressure in any direction; every path dignified; NEVER shames those who
// DO marry or have children (incl. early); even-handed (men feel a version of "settle down" too, though it falls
// hardest on women). Distress from family conflict or coercion routed to support; forced marriage routed to help
// (181, 1091, 112, Childline 1098). Builds on Equal & Confident (g50) and Equalize (g26). India: the marriage
// timeline, "log kya kahenge", and the worth-questioning stigma fall sharpest on women. gameId "your-path-your-call".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"yp-001","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Marriage and kids are the measure of a successful life.\"","myth":{"un":"Marriage and kids are the measure of a successful life.","re":"They're one valid path, not the measure; a full life takes many forms.","why":"A meaningful life is defined by far more than marital status."},"relearn":"Marriage and kids are one valid path, not the measure of a life.","persona":"Sneha","source":"one path not the path"},
  {"id":"yp-002","cat":"script-and-choice","type":"spot","hook":"Spot the two that are NOT yours to decide.","scene":[{"id":"a","text":"Whether and when you marry","trick":false},{"id":"b","text":"What the neighbours decide for you","trick":true},{"id":"c","text":"Whether you have children","trick":false},{"id":"d","text":"The deadline your relatives set","trick":true},{"id":"e","text":"Whom, if anyone, you marry","trick":false}],"why":"The neighbours' verdict and a relative's deadline aren't yours; whether, when and whom you marry, and whether you have kids, are.","relearn":"Whether, when and whom to marry, and whether to have children, are yours to decide.","persona":"any","source":"autonomy"},
  {"id":"yp-003","cat":"script-and-choice","type":"sort","hook":"Sort: a valid life path, or 'not a real option'?","items":[{"id":"a","text":"Marrying and having children"},{"id":"b","text":"Staying single by choice"},{"id":"c","text":"Being childfree"},{"id":"d","text":"Partnering later or differently"},{"id":"e","text":"Building a chosen family"},{"id":"f","text":"\"That's not a real life\""}],"bins":[{"id":"valid","label":"Valid path","valence":"pos"},{"id":"not","label":"'Not real'","valence":"neg"}],"key":{"a":"valid","b":"valid","c":"valid","d":"valid","e":"valid","f":"not"},"relearn":"Marrying, staying single, being childfree and partnering differently are all valid paths.","persona":"any","source":"all valid"},
  {"id":"yp-004","cat":"script-and-choice","type":"branch","persona":"any","source":"examine the script","hook":"You realise you've been chasing the default script without asking if you want it.","steps":[{"prompt":"You're filling out a matrimonial bio-data form on autopilot. What do you do?","options":[{"text":"Stop and ask if this is actually what you want","then":"You set the form aside, and the question sits there, honestly.","best":true},{"text":"Finish the form quickly. Questions can wait","then":"The form gets done, and the question waits a little longer."},{"text":"Delete the form and the whole idea outright","then":"The form's gone, but the real question stays, unanswered underneath."},{"text":"Ask a friend to fill it in for you","then":"The form gets finished by someone else's guess at your life."}],"why":"Pausing to ask is the first real step out of autopilot."},{"prompt":"A week later, you sit down to actually think it through. What do you do?","options":[{"text":"List what you actually want, separate from expectations","then":"The list surprises you, some overlap, some real differences.","best":true},{"text":"List what would make your parents proudest","then":"The list looks good on paper, and doesn't quite feel like yours."},{"text":"Avoid the list. It feels too big to face","then":"The bigger question stays exactly where it was."},{"text":"Copy a friend's list, since hers seemed to work","then":"Her answers don't quite fit, once you actually try them on."}],"why":"A list built from your own wants, not borrowed ones, tells the truth."},{"prompt":"Weeks later, without quite planning to, you notice which parts of the script fit. What do you do?","options":[{"text":"Keep the parts that fit, and let the rest go","then":"You build something that's actually yours, script and all.","best":true},{"text":"Keep the whole script, since sorting it feels risky","then":"The unexamined parts quietly cost you later."},{"text":"Reject the whole script on principle","then":"You throw out some parts that might have genuinely fit you."},{"text":"Wait for someone else to sort it for you","then":"The sorting waits, and so does the actual life."}],"why":"Keeping what fits and releasing what doesn't makes the life truly yours."}],"debrief":"The script is worth examining, not just following; the question is what life YOU want.","relearn":"Pause and ask what life you actually want, rather than following the default script."},
  {"id":"yp-005","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Settling down is the only way to be taken seriously as an adult.\"","myth":{"un":"Settling down is the only way to be taken seriously as an adult.","re":"Adulthood and respect aren't conferred by marital status; you're a full adult either way.","why":"Maturity is about character, not a marriage certificate."},"relearn":"Adulthood and respect aren't conferred by marital status.","persona":"any","source":"adulthood isn't marriage"},
  {"id":"yp-006","cat":"script-and-choice","type":"match","hook":"Match the life path to its validity.","pairs":[{"left":"Marrying and parenting","right":"Valid"},{"left":"Single by choice","right":"A full life"},{"left":"Childfree","right":"Complete"},{"left":"Partnering later","right":"On your timeline"},{"left":"A chosen family","right":"Real family"}],"relearn":"There are many good ways to build a life; all are valid.","persona":"any","source":"many ways"},
  {"id":"yp-007","cat":"script-and-choice","type":"sort","hook":"Sort: respects someone's life choice, or judges it?","items":[{"id":"a","text":"\"Whatever path is right for you\""},{"id":"b","text":"\"You'll change your mind, you have to\""},{"id":"c","text":"\"Your life, your call\""},{"id":"d","text":"\"That's not a real life\""},{"id":"e","text":"\"I trust you know your own life\""},{"id":"f","text":"\"You'll regret this someday\""}],"bins":[{"id":"respects","label":"Respects","valence":"pos"},{"id":"judges","label":"Judges","valence":"neg"}],"key":{"a":"respects","b":"judges","c":"respects","d":"judges","e":"respects","f":"judges"},"relearn":"'Whatever's right for you' and 'your call' respect a choice; 'you'll change your mind' and 'not a real life' judge it.","persona":"any","source":"respect vs judge"},
  {"id":"yp-008","cat":"script-and-choice","type":"branch","persona":"Aditya","source":"your own life","hook":"You've started noticing your own plans look nothing like everyone else's.","steps":[{"prompt":"You picture the life you actually want, not the one assumed for you. What do you do?","options":[{"text":"Write it down honestly, even the unconventional parts","then":"The list surprises you with how clear it actually is.","best":true},{"text":"Sketch a safer, more familiar version instead","then":"The safer version feels tidy, and quietly not quite yours."},{"text":"Wait until you're more certain to write anything","then":"The waiting keeps the real picture blurry a while longer."},{"text":"Ask a relative what they think you should want","then":"Their answer sounds like their life, not yours."}],"why":"Naming your real wants honestly, even unconventional ones, is where building starts."},{"prompt":"A friend asks how your plans are coming along. What do you do?","options":[{"text":"Say plainly that this is the right way for you","then":"He nods slowly. \"Fair, as long as it's actually working.\"","best":true},{"text":"Say you'll switch to the normal way eventually","then":"He relaxes, thinking normal is just a matter of time."},{"text":"Get defensive about being questioned","then":"The conversation turns tense over a fair question."},{"text":"Joke that your plans are a mess, before he can","then":"He laughs, but the joke leaves your real answer unsaid."}],"why":"Naming it as right for you, not wrong for being different, holds the line."},{"prompt":"You hit a real obstacle only your chosen path has. What do you do?","options":[{"text":"Work through it, since this path is still the right one","then":"The obstacle is real, and so is your reason for staying on this path.","best":true},{"text":"Take it as a sign to switch to the assumed path","then":"Switching solves this obstacle, and creates a different one."},{"text":"Pretend the obstacle isn't really there","then":"Ignoring it lets the obstacle grow, unaddressed."},{"text":"Blame yourself for choosing an unconventional path","then":"The blame doesn't actually solve the real, practical problem."}],"why":"An obstacle on the right path is still worth solving, not a sign to abandon it."},{"prompt":"Years later, you take stock of the life you've actually built. What do you do?","options":[{"text":"Own it fully, exactly as it actually is","then":"It fits you, assumption or not, and that's what actually matters.","best":true},{"text":"Tell yourself it just happened, not that you chose it","then":"It feels lighter to say it just happened, but it quietly erases the choices you made."},{"text":"Apologise for how the plan turned out","then":"The apology suggests a fault where there wasn't one."},{"text":"Compare it constantly to the assumed version","then":"The comparison keeps pulling focus from the life that's actually yours."}],"why":"Owning the life fully, without apology, is what makes it truly yours."}],"debrief":"A life built on your own values, even an unconventional one, beats a borrowed script.","relearn":"Build the life that's genuinely right for you, not the one assumed for you."},
  {"id":"yp-009","cat":"not-marrying","type":"strike-rewrite","hook":"\"An unmarried woman who's getting older has less worth.\"","myth":{"un":"An unmarried woman who's older has less worth.","re":"Worth is never marital status; that stigma is social control, not truth.","why":"No one's value rises or falls with a wedding."},"relearn":"Worth is never marital status; the 'still-unmarried' stigma is social control, not truth.","persona":"Sneha","source":"worth isn't marital status"},
  {"id":"yp-010","cat":"not-marrying","type":"strike-rewrite","hook":"\"If you're single, something must be wrong with you.\"","myth":{"un":"If you're single, something must be wrong with you.","re":"Nothing is wrong; single-by-choice is a valid path many choose from abundance.","why":"Being single can be a positive, deliberate choice."},"relearn":"Nothing is wrong with being single; many choose it, from abundance.","persona":"any","source":"nothing wrong"},
  {"id":"yp-011","cat":"not-marrying","type":"role-play","persona":"Sneha","source":"full life no marriage","hook":"A friend is quietly panicking about her future.","setup":"She's scrolling through other people's wedding photos.","steps":[{"prompt":"She says: \"I just worry I'll end up with nothing if I don't marry.\"","options":[{"text":"\"A full life needs no marriage. Love and joy come in many forms.\"","then":"She looks a little relieved. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Maybe you should start looking more seriously then, honestly.\"","then":"She nods, worried. \"Maybe you're right. I should try harder.\""},{"text":"\"You'll be fine. Don't even worry about it.\"","then":"She sighs. \"Everyone says that.\""},{"text":"\"That's a scary way to think about your future.\"","then":"She puts her phone down. \"So you think I should be scared?\""}],"why":"Naming a full life without marriage answers the real fear underneath."},{"prompt":"She says: \"I still don't know what a good life even looks like.\"","options":[{"text":"\"Purpose and love, in the shape you choose.\"","then":"She pauses. \"In the shape I choose. Hm.\"","best":true},{"text":"\"You'll probably still meet someone eventually.\"","then":"She smiles weakly. \"I hope so. Otherwise what?\""},{"text":"\"You'll have your job, I suppose.\"","then":"She looks deflated. \"Just a job? That's it?\""},{"text":"\"Don't think about it too much, honestly.\"","then":"She shrugs. \"I can't help thinking about it.\""}],"why":"Naming several real sources of meaning is more honest than one guess."},{"prompt":"Later, she says: \"Maybe I'm just scared of being the only one left out.\"","options":[{"text":"\"You'll be building a life, not missing one.\"","then":"She exhales. \"Building my own. I like how that sounds.\"","best":true},{"text":"\"You won't be. I promise you'll find someone.\"","then":"She smiles a little. \"You can't really promise that.\""},{"text":"\"That's not a healthy way to think, honestly.\"","then":"She looks stung. \"Great. Now I'm unhealthy too.\""},{"text":"\"Everyone feels that sometimes. Don't worry.\"","then":"She nods. \"I know. It still feels like it's just me.\""}],"why":"Naming her own life as the thing being built reframes the fear directly."}],"relearn":"A full, rich, meaningful life needs no marriage at all."},
  {"id":"yp-012","cat":"not-marrying","type":"branch","persona":"Sneha","source":"their pity isn't truth","hook":"At a wedding, relatives keep whispering that it's 'a shame' you're not married.","steps":[{"prompt":"You catch a cousin's eye mid-whisper. What do you do?","options":[{"text":"Let it pass; their pity isn't your truth","then":"You keep your peace and finish your plate at ease.","best":true},{"text":"Confront the whisperers directly at the table","then":"The table goes tense, and the whispers turn into open talk about your reaction."},{"text":"Absorb it and feel a little smaller","then":"The whisper lodges somewhere, and the evening feels heavier."},{"text":"Leave the function early to avoid it","then":"You miss the dancing, and the whisper follows you home anyway."}],"why":"Other people's pity says more about the script than about your life."},{"prompt":"Later, your mother asks if the whispers bothered you. What do you say?","options":[{"text":"Say honestly it stung, but it doesn't change your mind","then":"She nods and squeezes your hand. No more questions get asked.","best":true},{"text":"Say it's fine, though it's still bothering you","then":"She takes it at face value and lets it go, and you carry the sting alone all evening."},{"text":"Say she should have defended you louder","then":"She looks stung. \"I didn't even hear it,\" she says quietly."},{"text":"Say you're thinking of skipping weddings now","then":"She looks worried, and pulls you closer for the rest of the night."}],"why":"Naming the sting honestly, without letting it steer you, keeps both true."},{"prompt":"A week later, an aunt says kindly: \"Don't worry, beta. Someone will come along.\" What do you do?","options":[{"text":"Thank her for caring, and let the pity pass","then":"She pats your hand, and the moment passes without any weight.","best":true},{"text":"Explain all your reasons at length so she stops pitying you","then":"Each reason becomes something new for her to argue with."},{"text":"Take it in and start wondering if she is right","then":"The kind words settle in as a doubt you did not have before."},{"text":"Laugh and say you are behind schedule, to please her","then":"She nods happily, and the idea that you are behind travels back to your mother."}],"why":"You can accept her care without accepting her pity as your truth."}],"debrief":"Other people's pity about your single status says more about the script than about your life.","relearn":"Others' pity about being unmarried isn't your truth; let it pass."},
  {"id":"yp-013","cat":"not-marrying","type":"sort","hook":"Sort: a true belief about being single, or a stigma myth?","items":[{"id":"a","text":"Single life can be full and chosen"},{"id":"b","text":"Single means lonely and incomplete"},{"id":"c","text":"Your worth isn't your relationship status"},{"id":"d","text":"You must marry to be whole"},{"id":"e","text":"Many people are single from abundance, not lack"},{"id":"f","text":"An unmarried woman has 'missed her chance'"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Stigma myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Single life being full, worth-not-status and choosing-from-abundance are true; 'lonely', 'must marry to be whole' and 'missed her chance' are myths.","persona":"any","source":"single facts"},
  {"id":"yp-014","cat":"not-marrying","type":"strike-rewrite","hook":"\"You'll regret not marrying, so just do it before it's too late.\"","myth":{"un":"You'll regret not marrying, so just do it.","re":"Each person knows their own life; a pressure-driven marriage causes more regret than a freely-chosen path.","why":"Marrying to beat a clock rarely ends well."},"relearn":"A pressure-driven marriage causes more regret than a freely-chosen path.","persona":"any","source":"regret reframe"},
  {"id":"yp-015","cat":"not-marrying","type":"strike-rewrite","hook":"\"Choosing not to marry is a failure to launch.\"","myth":{"un":"Choosing not to marry is a failure to launch.","re":"Choosing not to marry, or to wait, is a positive, valid choice, not a failure.","why":"A deliberate choice isn't a failure."},"relearn":"Choosing not to marry, or to wait, is a valid choice, not a failure.","persona":"any","source":"valid choice"},
  {"id":"yp-016","cat":"not-marrying","type":"branch","persona":"any","source":"your own wants","hook":"You're content single, but the constant pressure is making you doubt yourself.","steps":[{"prompt":"A friend asks if you're 'really' happy or just saying so. What do you say?","options":[{"text":"Pause and actually check in with yourself first","then":"You realise, checking honestly, that you still mean it.","best":true},{"text":"Say yes quickly, to end an uncomfortable question","then":"The quick yes doesn't quite land, even to your own ears."},{"text":"Get defensive and change the subject fast","then":"The question goes unanswered, including for yourself."},{"text":"Say you're not sure anymore, out loud","then":"The doubt, once said aloud, gets a little heavier."}],"why":"Checking with yourself first, not the noise, gives the truest answer."},{"prompt":"That evening, three relatives call about the same matrimonial site. What do you do?","options":[{"text":"Take a breath and return to what you actually want","then":"Reconnecting with your own wants steadies the evening.","best":true},{"text":"Sign up quietly, just so the calls stop","then":"The calls stop, but a small yes you didn't mean sits there now."},{"text":"Ignore all three calls without explanation","then":"The calls come again tomorrow, unanswered and unresolved."},{"text":"Answer angrily and hang up on each one","then":"The evening ends in three separate small fires."}],"why":"Returning to your own wants is the anchor when pressure multiplies."},{"prompt":"A month on, you notice you actually feel settled again. What do you do?","options":[{"text":"Trust the settled feeling as real information","then":"You let the steadiness be proof, not a fluke.","best":true},{"text":"Second-guess it, since everyone else worries","then":"You talk yourself back into doubt, despite the calm."},{"text":"Tell everyone you're 'cured' of doubting","then":"The framing turns your peace into something to defend again."},{"text":"Say nothing and wait for the doubt to return","then":"The quiet waiting keeps you braced instead of settled."}],"why":"Your own steadiness is real evidence, worth trusting over outside noise."}],"debrief":"Relentless pressure can shake even a happy choice; returning to your own wants is the anchor.","relearn":"Reconnect with what you actually want, not the pressure's noise."},
  {"id":"yp-017","cat":"childfree-complete","type":"strike-rewrite","hook":"\"A woman isn't complete without becoming a mother.\"","myth":{"un":"A woman isn't complete without becoming a mother.","re":"Womanhood isn't motherhood; being childfree is a complete, valid life.","why":"A person is whole regardless of parenthood."},"relearn":"Womanhood isn't motherhood; childfree is a complete, valid life.","persona":"Nisha","source":"womanhood isn't motherhood"},
  {"id":"yp-018","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Choosing not to have children is selfish.\"","myth":{"un":"Choosing not to have children is selfish.","re":"It's a legitimate, thoughtful, autonomous choice, not a moral failing.","why":"Deciding honestly about parenthood is responsible, not selfish."},"relearn":"Choosing not to have children is a legitimate, autonomous choice, not selfish.","persona":"any","source":"not selfish"},
  {"id":"yp-019","cat":"childfree-complete","type":"branch","persona":"any","source":"you know yourself","hook":"You're sure you don't want children, but everyone says you'll change your mind.","steps":[{"prompt":"At Diwali, your masi says the same thing again. What do you do?","options":[{"text":"Say calmly that you know your own mind","then":"She raises an eyebrow, then moves on to the mithai.","best":true},{"text":"Laugh it off and say 'let's see'","then":"She looks satisfied, as if the matter's still open."},{"text":"List every reason you don't want kids","then":"She listens, then repeats the same line an hour later."},{"text":"Quietly leave the room","then":"She calls out, confused, and asks the same thing over the phone that night."}],"why":"Stating it plainly, without leaving room to doubt, respects your own certainty."},{"prompt":"A week later, her comment resurfaces in the family group chat. What do you do?","options":[{"text":"Reply once, firmly, then mute the chat","then":"The thread moves on to Diwali photos within a day.","best":true},{"text":"Type a long explanation for everyone to see","then":"Two more relatives jump in with their own opinions."},{"text":"Ask your mother to handle it for you","then":"She softens your words, and the doubt lingers in the thread."},{"text":"Leave the group chat to avoid it","then":"Your cousin says everyone's still discussing it, just without you."}],"why":"One firm reply beats an ongoing defence, and muting protects your peace."},{"prompt":"At the next big family function, someone brings it up again, right in front of everyone. What do you do?","options":[{"text":"Trust your own knowledge of yourself and say so, once, warmly","then":"The aunty shrugs and turns back to the caterer.","best":true},{"text":"Let the moment make you wonder if they're right","then":"You spend the evening second guessing a decision you'd already made."},{"text":"Snap that it's none of anyone's business","then":"The table goes quiet, and your mother looks embarrassed."},{"text":"Ask a cousin to change the subject for you","then":"She does, but the aunty circles back to you five minutes later."}],"why":"Trusting what you already know about yourself outlasts other people's doubt."}],"debrief":"You're the authority on your own life; 'you'll change your mind' is pressure, not insight.","relearn":"Trust your own knowledge of yourself about having children."},
  {"id":"yp-020","cat":"childfree-complete","type":"reflect","hook":"Lensy: the right to choose your life includes the right not to have children. Sit right with you?","prompt":"What do you think?","options":["Yes","My right","Includes not to"],"affirm":"A real right to choose your life must include the right not to have children; it's fully yours.","relearn":"The right to choose your life includes the right not to have children.","persona":"any","source":"the right not to"},
  {"id":"yp-021","cat":"childfree-complete","type":"sort","hook":"Sort: respects a childfree choice, or pressures against it?","items":[{"id":"a","text":"\"Whatever's right for you and your partner\""},{"id":"b","text":"\"You'll regret it, everyone does\""},{"id":"c","text":"\"It's your decision to make\""},{"id":"d","text":"\"A family needs children\""},{"id":"e","text":"\"I trust you know your own life\""},{"id":"f","text":"\"Just have one, you'll thank me\""}],"bins":[{"id":"respects","label":"Respects","valence":"pos"},{"id":"pressures","label":"Pressures","valence":"neg"}],"key":{"a":"respects","b":"pressures","c":"respects","d":"pressures","e":"respects","f":"pressures"},"relearn":"'Whatever's right for you' and 'your decision' respect a childfree choice; 'you'll regret it' and 'needs children' pressure.","persona":"any","source":"respect vs pressure"},
  {"id":"yp-022","cat":"childfree-complete","type":"branch","persona":"Nisha","source":"the kids question","hook":"At every family gathering, someone asks when you and your husband will start a family. You haven't decided yet.","steps":[{"prompt":"Your masi asks it again over lunch, in front of everyone. What do you do?","options":[{"text":"Deflect lightly and steer the talk elsewhere","then":"She shrugs and starts talking about the wedding photos instead.","best":true},{"text":"Explain that you're still deciding","then":"She nods, then asks a dozen follow up questions about your plan."},{"text":"Claim you've decided against kids, just to end it","then":"The table goes quiet, and the family now treats an open question as settled."},{"text":"Laugh and say 'you'll be the first to know'","then":"She takes that as a promise and starts a countdown."}],"why":"A light deflection ends the moment without explaining, or faking, a decision you haven't made."},{"prompt":"That evening, your husband asks how you handled it. What do you say?","options":[{"text":"Tell him honestly it still isn't easy","then":"He nods and says he feels the pressure too.","best":true},{"text":"Say it was nothing, so he doesn't worry","then":"He seems relieved, but the topic never really gets talked through."},{"text":"Ask him to handle the next one instead","then":"He agrees, though the question always lands on you first."},{"text":"Suggest you both just give people an answer","then":"He hesitates, unsure what answer that would even be."}],"why":"Naming the pressure to each other keeps you a team facing it, not each alone."},{"prompt":"The question comes up again at a cousin's wedding, from someone you barely know. What do you do?","options":[{"text":"Give a light, closed deflection","then":"The woman shrugs and moves on to the buffet.","best":true},{"text":"Justify your whole timeline to a near stranger","then":"She listens with interest and mentions it to your masi later."},{"text":"Avoid the wedding hall to dodge more questions","then":"You miss the dancing, and the questions find you online later."},{"text":"Snap that it's not her business","then":"She looks startled, and your mother apologises for you."}],"why":"You don't owe everyone a full justification of your private choices, however often it's asked."}],"debrief":"'When are you having kids?' is pressure you can deflect; you don't owe everyone an explanation.","relearn":"Deflect 'when are you having kids?' calmly; you don't owe a justification."},
  {"id":"yp-023","cat":"childfree-complete","type":"strike-rewrite","hook":"\"A childfree life is emptier than one with children.\"","myth":{"un":"A childfree life is emptier than one with children.","re":"A childfree life can be just as full of love, purpose and meaning as any other.","why":"Fullness comes in many forms."},"relearn":"A childfree life can be just as full of love, purpose and meaning as any other.","persona":"any","source":"just as full"},
  {"id":"yp-024","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Having kids is what gives a woman's life meaning.\"","myth":{"un":"Having kids is what gives a woman's life meaning.","re":"Meaning comes from many sources, work, love, purpose, contribution; parenthood is one, not the only one.","why":"No single role is the sole source of a meaningful life."},"relearn":"Meaning comes from many sources; parenthood is one, not the only one.","persona":"any","source":"many sources of meaning"},
  {"id":"yp-025","cat":"hold-your-ground","type":"role-play","persona":"any","source":"holding ground with family","hook":"A parent pressures you about marriage at every conversation.","setup":"Tonight it comes up again before you've even sat down.","steps":[{"prompt":"Your mother asks: \"So, any update on the marriage front?\"","options":[{"text":"\"I know you care. This is my call, in my own time.\"","then":"She softens. \"I do care. I just worry sometimes.\"","best":true},{"text":"\"I'll think about it seriously. I promise you.\"","then":"She brightens. \"Good, so maybe by next year?\""},{"text":"\"Can we please not do this every single time?\"","then":"She looks hurt. \"I only ask because I love you.\""},{"text":"\"There's truly no update, because there's nothing to update.\"","then":"She sighs. \"That's not really an answer.\""}],"why":"Naming it as your decision, warmly, sets the boundary without a fight."},{"prompt":"She says: \"I just want to see you settled before I get too old.\"","options":[{"text":"\"I hear that worry. I want you around a long time.\"","then":"She smiles a little. \"That's kind of you to say.\"","best":true},{"text":"\"Fine, I'll try to meet someone seriously this year.\"","then":"She relaxes. \"That's all I wanted to hear.\""},{"text":"\"You say that every single time.\"","then":"She looks stung. \"Because it's true every time.\""},{"text":"\"Don't guilt me into this, please.\"","then":"She goes quiet, and dinner gets tense."}],"why":"Answering the worry directly, without agreeing to a timeline, keeps both things true."},{"prompt":"She asks: \"Your cousin just got engaged. Doesn't that make you think?\"","options":[{"text":"\"I'm happy for her. Her timeline isn't mine.\"","then":"She nods slowly. \"That's fair, I suppose.\"","best":true},{"text":"\"Maybe I should be moving a lot faster then.\"","then":"She perks up. \"See, I knew you'd come around.\""},{"text":"\"Stop comparing me to her, please.\"","then":"She raises her hands. \"I'm just talking.\""},{"text":"\"Sure, whatever you say.\"","then":"She takes it as agreement and starts naming names."}],"why":"Being glad for someone else doesn't mean borrowing their timeline."},{"prompt":"Before you leave, she says: \"Just promise you'll think about it.\"","options":[{"text":"\"I think about my life daily. I'll share real news.\"","then":"She hugs you. \"Okay. I trust you.\"","best":true},{"text":"\"Okay, I promise faithfully, just to make you happy.\"","then":"She looks pleased and mentions it again the next week."},{"text":"\"Why does everything need a promise from me?\"","then":"The goodbye feels colder than usual."},{"text":"\"Fine, whatever gets me out the door fast.\"","then":"She takes it seriously, and it comes up again sooner than you'd like."}],"why":"A true answer, not a promise to please her, is what actually closes the topic."}],"relearn":"Hold a marriage boundary warmly: 'I know you care, and this is my decision.'"},
  {"id":"yp-026","cat":"hold-your-ground","type":"branch","persona":"Sneha","source":"kind firm boundaries","hook":"Relatives keep raising your marriage at every gathering, and it's starting to wear on you.","steps":[{"prompt":"At your cousin's wedding, three different relatives bring it up before the starters arrive. What do you do?","options":[{"text":"Set a kind, firm boundary and redirect each time","then":"Each one nods and moves the conversation elsewhere without a fuss.","best":true},{"text":"Explode at the third one, tired of hearing it","then":"The relative looks stunned, and the rest of the wedding feels tense."},{"text":"Shrink and give vague non answers all night","then":"You spend the wedding dodging instead of enjoying it."},{"text":"Avoid the reception hall entirely","then":"You miss the dancing, and the questions find you at the exit anyway."}],"why":"A kind, firm boundary protects you without exploding or shrinking through the whole event."},{"prompt":"The next morning, your mother mentions relatives were 'just asking out of love'. What do you do?","options":[{"text":"Agree they mean well, and hold the boundary anyway","then":"She nods, and doesn't push the topic further that morning.","best":true},{"text":"Say their love doesn't excuse the pressure","then":"Your mother feels caught defending them, and gets a little prickly."},{"text":"Apologise for how you responded at the wedding","then":"She takes the apology as agreement that you overreacted."},{"text":"Say you'll try to answer more warmly next time","then":"Your mother takes it as a sign you'll give the relatives more room."}],"why":"Acknowledging the love behind it while holding the boundary keeps both things true at once."},{"prompt":"At the next family gathering, the questions start again before you've even sat down. What do you do?","options":[{"text":"Answer with a kind, firm line and redirect","then":"The relative nods, and the table moves on to the food.","best":true},{"text":"Brace defensively the moment the first question lands","then":"You come across tense before the conversation even starts."},{"text":"Skip the gathering to avoid another round","then":"Skipping it doesn't stop the pattern, just delays the next round."},{"text":"Ask a cousin to run interference for you all evening","then":"It works for a bit, but the questions find you the moment you're alone."}],"why":"A calm line and a redirect settle the question before it takes over the evening."},{"prompt":"Months later, a relative jokes that you've become 'hard to catch' on the marriage question. What do you do?","options":[{"text":"Laugh along, and say kindly it's still your call","then":"The relative laughs too, and the conversation moves somewhere easier.","best":true},{"text":"Take offence at being teased about it","then":"The moment turns awkward over a comment that was mostly friendly."},{"text":"Take it as a sign to finally give a real answer","then":"You end up explaining your whole life, and the relative asks follow up questions."},{"text":"Say you're just tired of everyone, generally","then":"The relative looks hurt, and word spreads that you're 'fed up with family'."}],"why":"Laughing along while keeping it your call holds the boundary and the warmth together."}],"debrief":"Kind-but-firm boundaries deflect repeated pressure without rupturing the relationship.","relearn":"Set a kind, firm boundary and redirect when pressure repeats."},
  {"id":"yp-027","cat":"hold-your-ground","type":"role-play","persona":"any","source":"the light deflection","hook":"At a family function, a distant aunty corners you near the snack table. You aren't looking and want to keep it light.","setup":"She's mid-samosa, and you can tell a question is coming.","steps":[{"prompt":"She asks: \"So beta, why is nobody thinking of you yet?\"","options":[{"text":"\"I'm happy with how my life is going, thanks for asking.\"","then":"She blinks, a little surprised. \"Oh. Well, good for you then.\"","best":true},{"text":"\"I'm still looking around, aunty. Do you have someone in mind?\"","then":"Her eyes light up. \"Let me think who would suit you.\""},{"text":"\"Why does everyone keep asking me that?\"","then":"She looks taken aback. \"I was only being friendly.\""},{"text":"\"Nobody wants someone like me, I guess.\"","then":"She looks concerned. \"Don't say that, beta.\""}],"why":"A light, closed answer ends the question without opening a debate."},{"prompt":"Over chai, she comes back to you: \"Tell me honestly. Don't you get lonely, living alone?\"","options":[{"text":"\"Not really. My life is full. How have you been keeping?\"","then":"She pauses, then smiles. \"Oh, busy as ever, beta.\"","best":true},{"text":"\"I've got friends, work, hobbies, a full calendar. Ask anyone.\"","then":"She nods, unconvinced. \"That's a lot of busy, beta. Busy isn't the same as happy.\""},{"text":"\"That's a strange thing to ask someone.\"","then":"She looks stung. \"I only asked because I care.\""},{"text":"\"Maybe I am lonely. Maybe I should let you find someone.\"","then":"She pats your hand. \"Now you're talking. I'll start tonight.\""}],"why":"Redirecting warmly closes the topic without inviting a rescue mission."},{"prompt":"As you leave, she calls out: \"I'll keep an eye out for a match for you!\"","options":[{"text":"\"That's kind, but I'm not looking right now.\"","then":"She shrugs. \"Okay, okay, just saying.\" She lets it go.","best":true},{"text":"\"Sure, send whatever you find, I guess.\"","then":"She beams. \"I'll send three by tonight!\""},{"text":"\"Please don't. Honestly, it's not needed.\"","then":"She looks hurt. \"I was only trying to help.\""},{"text":"\"Whatever makes you happy, aunty.\"","then":"She takes it as a yes. \"I'll call your mother soon!\""}],"why":"A kind, clear no closes the offer without leaving room for a follow-up."}],"relearn":"A light, closed deflection ends a nosy question without a fight."},
  {"id":"yp-028","cat":"hold-your-ground","type":"sort","persona":"any","source":"holding without losing","relearn":"A calm boundary and staying warm-but-firm holds your ground; caving or letting them decide loses you.","hook":"Sort: holds your ground kindly, or loses you in the process?","items":[{"id":"a","text":"A calm, repeated boundary"},{"id":"b","text":"Caving to keep the peace"},{"id":"c","text":"Staying warm but firm"},{"id":"d","text":"Letting them decide your life"},{"id":"e","text":"One clear, kind 'no'"},{"id":"f","text":"Promising a date you don't mean"}],"bins":[{"id":"holds","label":"Holds your ground","valence":"pos"},{"id":"loses","label":"Loses you","valence":"neg"}],"key":{"a":"holds","b":"loses","c":"holds","d":"loses","e":"holds","f":"loses"}},
  {"id":"yp-029","cat":"hold-your-ground","type":"branch","persona":"any","source":"log kya kahenge","hook":"The 'log kya kahenge' line is being used to push you into a choice you're not ready for.","steps":[{"prompt":"Your father uses the line at dinner, hoping it'll settle the matter. What do you do?","options":[{"text":"Name it as social pressure, not your obligation","then":"He pauses, like he hadn't heard it put that way before.","best":true},{"text":"Let the phrase quietly sway you toward saying yes","then":"You go quiet and say you'll 'think about it', which the family hears as nearly a yes."},{"text":"Mock the phrase to dismiss it","then":"Your father feels his concern was laughed at, not answered."},{"text":"Ask what people would even say, specifically","then":"The talk gets lost debating hypothetical opinions instead of your choice."}],"why":"Naming the phrase for what it is keeps the decision yours, not the neighbourhood's."},{"prompt":"A week later, an aunty uses the same line, more pointedly, to press the matter. What do you do?","options":[{"text":"Name the pressure clearly, calmly","then":"She looks a little surprised, but doesn't repeat the line again.","best":true},{"text":"Get visibly frustrated this time","then":"The frustration becomes the story of the visit, not the actual point."},{"text":"Ask her what people are actually saying","then":"She lists a few names, and the pressure ends up feeling more real."},{"text":"Change your answer slightly to sound more agreeable","then":"It reads as the pressure working, even a little."}],"why":"Naming the pressure calmly works on a pointed aunty too, without heat or giving ground."},{"prompt":"Months later, your 24-year-old cousin says she might agree to a match because 'people are talking'. What do you do?","options":[{"text":"Ask what she wants, apart from what people will say","then":"She pauses, then admits she hasn't let herself think about that.","best":true},{"text":"Tell her people will talk less once she's married","then":"She nods, and says yes before working out what she wants."},{"text":"Tell her firmly not to marry just because of gossip","then":"She bristles, feeling told what to do by one more person."},{"text":"Stay out of it, not wanting to interfere","then":"She thanks you anyway, and the talk of people stays the loudest voice."}],"why":"Asking what she wants helps her tell her own wish apart from what people will say."}],"debrief":"'What will people say' is a powerful but illegitimate basis for life-defining choices.","relearn":"Recognise 'log kya kahenge' as social pressure, not your obligation."},
  {"id":"yp-030","cat":"hold-your-ground","type":"role-play","persona":"any","source":"considered choice","hook":"A relative refuses to take your life choices seriously.","setup":"Tonight he brings it up again, in front of everyone.","steps":[{"prompt":"He says: \"You'll grow out of this phase eventually, trust me.\"","options":[{"text":"\"This is a considered choice, and I'd like it respected.\"","then":"He pauses. \"Fair enough. I didn't mean to dismiss it.\"","best":true},{"text":"\"Maybe you're right. We'll just have to see about that.\"","then":"He nods, satisfied. \"That's more like it.\""},{"text":"\"You have no idea what you're talking about.\"","then":"He crosses his arms. \"I'm just saying what I see.\""},{"text":"\"Whatever helps you sleep at night.\"","then":"He looks put off, and the table goes quiet."}],"why":"Naming it as considered, not a phase, states your truth without a fight."},{"prompt":"Over tea, he asks: \"I'm trying to understand. Why is this what you want?\"","options":[{"text":"\"It's right for me, and I know my own mind.\"","then":"He tilts his head. \"Okay. I hope it stays right for you.\"","best":true},{"text":"\"I've explained it before, and I'm tired of repeating myself.\"","then":"He raises an eyebrow. \"No need to snap at me. I'm only asking.\""},{"text":"\"Why do you need me to justify it?\"","then":"He shrugs. \"Just trying to understand you.\""},{"text":"\"Maybe you're right. It might be a phase after all.\"","then":"He smiles, taking it as an opening. \"So you do think it's a phase.\""}],"why":"Trusting what you know about yourself answers him without a fight."},{"prompt":"Later, he tells the table: \"Give it a few years. This will pass.\"","options":[{"text":"\"I'm not waiting for it to pass. This is who I am.\"","then":"The table goes quiet. Then someone changes the subject.","best":true},{"text":"\"Let him think whatever he wants to think about it.\"","then":"He takes that as agreement, and repeats the comment at the next dinner."},{"text":"\"How dare you say that about me.\"","then":"The table tenses, and the evening ends early."},{"text":"\"Maybe he's right, actually. Who knows.\"","then":"He looks triumphant, and the phase talk continues for years."}],"why":"Correcting it plainly, in the moment, stops the story from being told for you."}],"relearn":"Calmly affirm that your life choice is considered and deserves respect."},
  {"id":"yp-031","cat":"hold-your-ground","type":"branch","persona":"any","source":"supportive circle","hook":"Critical comments from relatives keep circling around your life choices.","steps":[{"prompt":"After another critical comment from a relative, you feel your certainty wobble. What do you do?","options":[{"text":"Call a friend who's always respected your path","then":"Just hearing her voice helps, a little, though the feeling doesn't fully leave.","best":true},{"text":"Scroll social media to distract from the feeling","then":"The scrolling passes the time without actually settling the wobble."},{"text":"Replay the critical comment over and over","then":"The wobble grows the longer you sit with just the criticism."},{"text":"Message the critical relative to explain yourself further","then":"The explanation invites more critique, not less."}],"why":"Reaching for someone who respects your path steadies you faster than sitting with the criticism alone."},{"prompt":"The wobble doesn't fully settle by evening. What do you do next?","options":[{"text":"Make plans to spend more time with people who respect your path","then":"The next few weeks feel noticeably lighter.","best":true},{"text":"Decide your time doesn't really matter that much","then":"You keep spending most of your time exactly where it drains you."},{"text":"Tell yourself you shouldn't need help with something so small","then":"The wobble stays, unaddressed and a little heavier."},{"text":"Wait for the feeling to pass on its own","then":"It passes for now, though nothing about the pattern actually changes."}],"why":"Choosing where your time goes protects your confidence better than just enduring the critics."},{"prompt":"A month later, at a cousin's engagement, the same relative starts in on your choices again. What do you do?","options":[{"text":"Answer briefly, then join the cousins who back you","then":"The comment still stings, but among them it shrinks back to size.","best":true},{"text":"Stay near her all evening to show it doesn't bother you","then":"Each remark lands, and you head home more drained than you arrived."},{"text":"Leave early, before she can say anything else","then":"You miss the celebration, and her comment follows you home anyway."},{"text":"Explain your choices to her, point by point, at the party","then":"She listens with a frown, then finds three new things to question."}],"why":"Joining the cousins who back you keeps one comment from setting the tone of the whole evening."}],"debrief":"A supportive circle that respects your path protects your confidence against constant pressure.","relearn":"Surround yourself with people who respect your path."},
  {"id":"yp-032","cat":"hold-your-ground","type":"reflect","hook":"Lensy: you can love your family and still not let them dictate your life. Hold both?","prompt":"What do you think?","options":["Yes","Love and boundaries","Both"],"affirm":"Loving your family and keeping your own autonomy aren't opposites; you can hold both.","relearn":"You can love your family and still not let them dictate your life.","persona":"any","source":"love and autonomy"},
  {"id":"yp-033","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"Your looks and the marriage market decide your value.\"","myth":{"un":"Your looks and the marriage market decide your value.","re":"Your worth isn't your looks, your skin tone or the marriage market's scrutiny.","why":"Marriage-market judgement, including colourism, measures nothing real about you."},"relearn":"Your worth isn't your looks, skin tone or the marriage market's scrutiny.","persona":"any","source":"beyond looks & market"},
  {"id":"yp-034","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: your worth was never your marital or parental status, and never will be. Let that land?","prompt":"What do you think?","options":["Yes","Never my status","I'm whole"],"affirm":"Your worth has nothing to do with whether or when you marry or have children; it's inherent.","relearn":"Your worth was never your marital or parental status.","persona":"any","source":"worth beyond status"},
  {"id":"yp-035","cat":"worth-beyond-status","type":"sort","hook":"Sort: a real source of worth, or a status the world imposes?","items":[{"id":"a","text":"Your character and how you treat people"},{"id":"b","text":"Whether you're married"},{"id":"c","text":"What you contribute and care about"},{"id":"d","text":"Your standing in the marriage market"},{"id":"e","text":"The work and growth you're proud of"},{"id":"f","text":"Whether relatives approve of your timeline"}],"bins":[{"id":"real","label":"Real worth","valence":"pos"},{"id":"imposed","label":"Imposed status","valence":"neg"}],"key":{"a":"real","b":"imposed","c":"real","d":"imposed","e":"real","f":"imposed"},"relearn":"Character and contribution are real worth; marital status and marriage-market standing are imposed.","persona":"any","source":"real vs imposed"},
  {"id":"yp-036","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"Men don't face this pressure, so it's only a women's issue.\"","myth":{"un":"Men don't face this pressure, so it's only a women's issue.","re":"Men feel a version of the 'settle down' pressure too, though it falls hardest on women.","why":"The script constrains everyone, unequally."},"relearn":"Men feel a version of this pressure too, though it falls hardest on women.","persona":"Karthik","source":"even-handed"},
  {"id":"yp-037","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that say you're worth less without a spouse.","scene":[{"id":"a","text":"\"You're whole as you are\"","trick":false},{"id":"b","text":"\"You're incomplete without a spouse\"","trick":true},{"id":"c","text":"\"Worthy partnered or not\"","trick":false},{"id":"d","text":"\"Unmarried means unfinished\"","trick":true},{"id":"e","text":"\"Your worth doesn't wait on a wedding\"","trick":false}],"why":"'Incomplete' and 'unfinished' say a wedding decides your worth; the others affirm you're whole either way.","relearn":"You are whole and worthy exactly as you are, partnered or not, parent or not.","persona":"any","source":"whole as you are"},
  {"id":"yp-038","cat":"worth-beyond-status","type":"spot","hook":"Spot the two moves that tie your value to your status.","scene":[{"id":"a","text":"Anchoring worth in who you are","trick":false},{"id":"b","text":"Tying value to relationship status","trick":true},{"id":"c","text":"Valuing your character and growth","trick":false},{"id":"d","text":"Ranking yourself by 'settled' or not","trick":true},{"id":"e","text":"Measuring yourself by how you treat people","trick":false}],"why":"Tying value to status and ranking by 'settled' make worth conditional; the rest anchor it in who you are.","relearn":"Anchor your worth in who you are, not whether you've 'settled down'.","persona":"any","source":"off the status measure"},
  {"id":"yp-039","cat":"worth-beyond-status","type":"sort","hook":"Sort: a kind, true thing to tell yourself, or imposed shame?","items":[{"id":"a","text":"\"My life is valid as it is\""},{"id":"b","text":"\"I'm incomplete without a spouse\""},{"id":"c","text":"\"My worth is my own\""},{"id":"d","text":"\"I'm a disappointment for not marrying\""},{"id":"e","text":"\"I'm allowed to like my life\""},{"id":"f","text":"\"I've let everyone down by waiting\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"shame","label":"Imposed shame","valence":"neg"}],"key":{"a":"kind","b":"shame","c":"kind","d":"shame","e":"kind","f":"shame"},"relearn":"'My life is valid' and 'my worth is my own' are true; 'incomplete' and 'a disappointment' are imposed shame.","persona":"any","source":"self-talk"},
  {"id":"yp-040","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"supporting a friend","hook":"A friend is unmarried, and her relatives have been hard on her lately.","setup":"Tonight, she calls you, still shaken.","steps":[{"prompt":"She says: \"They called me a burden today. Maybe they're right.\"","options":[{"text":"\"You're not a burden. You're whole, marriage or not.\"","then":"She's quiet, then exhales. \"I needed to hear that.\"","best":true},{"text":"\"Yeah, maybe you should just marry someone.\"","then":"She sighs, and starts scrolling matrimonial profiles."},{"text":"\"That's a horrible thing for them to say to you.\"","then":"She agrees, but the word 'burden' still sits there."},{"text":"\"Try not to think about it too much.\"","then":"She nods, but the word keeps replaying anyway."}],"why":"Naming her worth plainly refuses the word instead of just sympathising with it."},{"prompt":"The next day she says: \"I keep hearing that word in my head.\"","options":[{"text":"\"That word was never true. Tell yourself 'I'm whole.'\"","then":"She repeats it quietly, and something in her voice steadies.","best":true},{"text":"\"Try to distract yourself for now. It'll pass eventually.\"","then":"She nods, but the word keeps circling back anyway."},{"text":"\"Honestly, I'd just ignore your relatives from now on.\"","then":"She looks unsure how to actually do that, practically."},{"text":"\"Maybe it'll feel less true with time.\"","then":"She waits for the feeling to pass, but it doesn't yet."}],"why":"Naming the truth out loud, in her own voice, helps it actually replace the old word."},{"prompt":"Weeks later, she says: \"That word doesn't land the same way anymore.\"","options":[{"text":"\"That's your own strength, not luck.\"","then":"She smiles. \"Maybe. I like hearing that, though.\"","best":true},{"text":"\"I'm glad they finally backed off.\"","then":"It's kind, but the shift she made herself goes unnamed."},{"text":"\"Are you sure it won't come back, though?\"","then":"She looks unsettled again, right after finding some peace."},{"text":"\"Good, took long enough.\"","then":"She looks a little stung by the offhand tone."}],"why":"Naming her own strength, not luck or circumstance, honours what she actually worked through."}],"relearn":"Remind a friend her worth has nothing to do with marriage; she's whole."},
  {"id":"yp-041","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: the most important question isn't 'what's expected?' but 'what do I actually want?'. Useful?","prompt":"What do you think?","options":["Yes","What I want","The real question"],"affirm":"'What do I actually want?' is the question that leads to a life that's truly yours.","relearn":"Ask not 'what's expected?' but 'what do I actually want?'.","persona":"any","source":"the real question"},
  {"id":"yp-042","cat":"tools-and-reflection","type":"sort","hook":"Sort: does this game stand for it, or against it?","items":[{"id":"a","text":"Respecting every life path"},{"id":"b","text":"Pressuring anyone toward marriage"},{"id":"c","text":"Worth beyond marital status"},{"id":"d","text":"Shaming those who marry early"},{"id":"e","text":"Your choice on kids is yours"},{"id":"f","text":"Ranking lives by 'log kya kahenge'"}],"bins":[{"id":"for","label":"Stands for","valence":"pos"},{"id":"against","label":"Stands against","valence":"neg"}],"key":{"a":"for","b":"against","c":"for","d":"against","e":"for","f":"against"},"relearn":"The stance is respect for every path and worth-beyond-status; not pressure toward marriage, not shame for marrying.","persona":"any","source":"the stance"},
  {"id":"yp-043","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: choosing to marry and have kids is equally valid and worthy of respect too. Agree?","prompt":"What do you think?","options":["Yes","Equally valid","Respect that too"],"affirm":"Marrying and having children is an equally valid, respected path; this is about freedom, not against anyone.","relearn":"Choosing to marry and have kids is equally valid and worthy of respect.","persona":"any","source":"no pressure either way"},
  {"id":"yp-044","cat":"tools-and-reflection","type":"match","hook":"Match each pressure to the truth that answers it.","pairs":[{"left":"\"Still unmarried?\"","right":"Worth isn't marital status"},{"left":"\"When are the kids?\"","right":"Childfree is complete"},{"left":"\"You'll regret it\"","right":"You know your own life"},{"left":"\"Log kya kahenge?\"","right":"Social pressure, not your duty"},{"left":"\"Your clock is ticking\"","right":"There's no boat to miss"}],"relearn":"Each common pressure has an answering truth: worth-isn't-status, childfree-is-complete, you-know-your-life.","persona":"any","source":"pressure to truth"},
  {"id":"yp-045","cat":"tools-and-reflection","type":"branch","persona":"any","source":"being an ally","hook":"A loved one is under heavy pressure about marriage from her family.","steps":[{"prompt":"Your friend admits she feels completely alone under the pressure from her family. What do you do?","options":[{"text":"Validate her choice and tell her you stand with her","then":"She looks relieved, like someone finally believes her.","best":true},{"text":"Tell her to just try to keep the peace for now","then":"She nods, but feels a little more alone than before."},{"text":"Add your own opinion about what she should choose","then":"She feels judged again, this time by you too."},{"text":"Change the subject so it doesn't get awkward","then":"The moment passes, and she's left carrying it alone."}],"why":"Being the one person who believes her choice changes how she weathers the rest."},{"prompt":"A week later, her mother asks you to 'talk some sense into her'. What do you do?","options":[{"text":"Tell her mother the choice is genuinely her daughter's","then":"Her mother sighs, but doesn't push you to intervene again.","best":true},{"text":"Gently hint to your friend that her mother has a point","then":"Your friend feels the ally she found start to waver."},{"text":"Agree to talk to her, just to end the awkward ask","then":"You feel caught between two people who both expect something from you."},{"text":"Avoid her mother's calls from now on","then":"The pressure on your friend continues, just without your visibility."}],"why":"Naming the choice as hers, even to her mother, keeps you a steady ally instead of a go-between."},{"prompt":"Months on, your friend says the pressure has eased overall. What do you say?","options":[{"text":"Say you'll keep standing with her, whatever she decides","then":"She smiles, like the ground under her finally feels solid.","best":true},{"text":"Say you're just relieved it's over now","then":"The relief feels more about you than about her."},{"text":"Ask if she's sure the pressure is really over","then":"She looks unsettled again, right when she'd started to feel lighter."},{"text":"Say you knew her family would come around eventually","then":"She nods, but it skips how hard the months were for her."}],"why":"Staying an ally for the long run, not just one hard moment, is what she'll remember."}],"debrief":"Being the one person who respects someone's choice can change how they weather the pressure.","relearn":"Validate a loved one's life choice and stand with them against pressure."},
  {"id":"yp-046","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: your life, your call, on marriage, on children, on the whole path. Feel the freedom in that?","prompt":"What do you think?","options":["Yes","My life my call","Freedom"],"affirm":"Your life is genuinely yours to shape, on marriage, children and the whole path; that's real freedom.","relearn":"Your life, your call, on marriage, children and the whole path.","persona":"any","source":"your life your call"},
  {"id":"yp-047","cat":"tools-and-reflection","type":"match","hook":"Match the need to where support lives (India).","pairs":[{"left":"Forced or coerced marriage","right":"181 / 1091 / 112"},{"left":"A child being married off","right":"Childline 1098"},{"left":"Family-conflict distress","right":"A counsellor or trusted person"},{"left":"Feeling alone with your choice","right":"A friend who respects your path"},{"left":"Just need to think it through","right":"A quiet, private moment"}],"relearn":"Forced marriage -> 181/1091/112; a child married off -> 1098; family-conflict distress -> a counsellor or trusted person.","persona":"any","source":"help routes"},
  {"id":"yp-048","cat":"tools-and-reflection","type":"match","hook":"Match each 'your path' truth to the freedom it gives.","pairs":[{"left":"One path, not the path","right":"Freedom to choose"},{"left":"Worth isn't status","right":"Freedom from shame"},{"left":"Childfree is complete","right":"Freedom not to"},{"left":"Your life, your call","right":"Freedom to own it"},{"left":"No one timeline","right":"Freedom from the deadline"}],"relearn":"Carry forward: one path not the path, worth isn't status, childfree is complete, your life your call.","persona":"any","source":"carry forward"},
  {"id":"yp-049","cat":"not-marrying","type":"branch","persona":"Sneha","source":"connection not marriage","hook":"You're happy single but worry about being lonely when older.","steps":[{"prompt":"A friend's Sunday brunch invite arrives, and you're tempted to rest alone again. What do you do?","options":[{"text":"Text to reschedule, and actually keep the new plan","then":"You rest today, and the friendship stays warm for next week.","best":true},{"text":"Cancel and let the friendship quietly fade","then":"Resting wins today, but the friend group drifts a little further."},{"text":"Go anyway, exhausted, to avoid seeming distant","then":"You're present but drained, and quietly resentful by the end."},{"text":"Reply 'maybe' and never confirm either way","then":"She waits until Sunday morning, then makes other plans without you."}],"why":"Deep friendships take small, repeated effort; a reschedule keeps that going."},{"prompt":"A cousin invites you to a big joint family Diwali. What do you do?","options":[{"text":"Go, and lean into chosen family and blood family both","then":"You leave with new numbers saved and old bonds refreshed.","best":true},{"text":"Skip it, since crowds feel like too much effort","then":"The quiet night is peaceful, and a little more isolated."},{"text":"Go, but stay on your phone the whole time","then":"You're there in body, but the connections don't really happen."},{"text":"Go only to prove you're not lonely","then":"You perform fine all evening, and come home more tired than filled."}],"why":"Showing up, present, is how connection actually gets built."},{"prompt":"One quiet evening, you picture your 60s. What do you do about it now?","options":[{"text":"Keep investing in friends and community, starting today","then":"You picture a full table, built one ordinary evening at a time.","best":true},{"text":"Decide to marry someone soon, just for the backup plan","then":"You start saying yes to profiles you feel nothing for, just in case."},{"text":"Assume future-you will sort it out somehow","then":"The plan stays vague, and the years pass without building it."},{"text":"Worry quietly and do nothing differently","then":"The worry stays, unaddressed by any real change."}],"why":"Chosen family and friendship, built now, are what actually hold you later."}],"debrief":"Connection and chosen family prevent loneliness better than a pressured marriage.","relearn":"Build deep friendships and chosen family; don't marry just to avoid loneliness."},
  {"id":"yp-050","cat":"childfree-complete","type":"branch","persona":"any","source":"release the guilt","hook":"You and your partner have agreed you don't want children, but guilt creeps in anyway.","steps":[{"prompt":"A friend casually asks if you're 'still sure' about no kids. What do you do?","options":[{"text":"Say yes. It's a decision you both stand behind","then":"She nods, and the conversation moves on easily.","best":true},{"text":"Say 'probably', to leave room for doubt","then":"She takes it as a maybe, and asks again a month later."},{"text":"Explain every reason behind the decision","then":"She listens, then asks what you'd do if you changed your mind."},{"text":"Change the subject fast, before she can ask more","then":"She notices, and wonders if something's wrong."}],"why":"Answering as a settled yes keeps the decision the couple's, not still open to debate."},{"prompt":"That night, alone, the guilt resurfaces anyway. What do you do?","options":[{"text":"Ask your partner to talk it through together","then":"He admits he feels a stray pang of guilt too, and saying it helps.","best":true},{"text":"Keep the guilt to yourself so he doesn't worry","then":"You carry it alone, and it quietly grows heavier."},{"text":"Search online whether the guilt means you're wrong","then":"The search turns up nothing but more questions."},{"text":"Decide the guilt means you should reconsider a child","then":"You spend the night planning a future neither of you actually wants."}],"why":"Guilt shared with the person who shares the decision loses its weight fastest."},{"prompt":"Your mother later says she 'just wants you to be happy', but keeps mentioning grandchildren. What do you do?","options":[{"text":"Thank her for caring and gently repeat that the choice stands","then":"She sighs, but stops bringing it up that visit.","best":true},{"text":"Let her comment reopen the guilt","then":"You leave the visit quieter than you arrived."},{"text":"Promise to think about it again","then":"She hears that as an opening and asks again the following week."},{"text":"Avoid visiting for a while","then":"The distance doesn't settle the guilt. It just delays the conversation."}],"why":"A warm thank you plus a repeated, clear choice holds the boundary without a fight."},{"prompt":"Months later, a cousin at a wedding asks when you'll 'finally' have a baby. What do you do?","options":[{"text":"Answer plainly that it isn't in your plans","then":"She blinks, then moves on to other wedding gossip.","best":true},{"text":"Feel the old guilt flicker and brace for more questions","then":"You spend the rest of the evening tense, waiting for the next one."},{"text":"Wonder if her question means you should reconsider","then":"You spend the drive home replaying a decision that was already settled."},{"text":"Give a long explanation to head off any follow up","then":"She nods along, then picks one of your reasons to debate over dessert."}],"why":"A settled choice doesn't need defending each time it's asked about."}],"debrief":"A mutual, considered childfree decision is valid; the guilt comes from the script, not from wrongdoing.","relearn":"Release guilt over a valid, mutual childfree choice; it's yours to make."},
  {"id":"yp-051","cat":"script-and-choice","type":"role-play","persona":"any","source":"naming your path","hook":"You want to tell your family you're choosing a different path for your life.","setup":"Tonight, at home, you decide it's time to say it out loud.","steps":[{"prompt":"Your mother asks: \"You've been quiet tonight. Is something on your mind?\"","options":[{"text":"\"There's a path I've chosen, and I want to tell you.\"","then":"She puts down her phone. \"Okay. Tell me.\"","best":true},{"text":"\"It's nothing. Don't worry about it tonight.\"","then":"She lets it go, but your face keeps giving you away."},{"text":"\"Why does it even matter what I'm thinking?\"","then":"She looks hurt. \"I just want to understand you.\""},{"text":"\"I'll explain everything to you later. I promise.\"","then":"She nods slowly, though her eyes stay on you, still waiting."}],"why":"Naming it plainly gives her something real to respond to, instead of a guess."},{"prompt":"Your father leans in and asks: \"Is there something you two aren't telling me?\"","options":[{"text":"\"There is. A life I've thought through, even if it's unexpected.\"","then":"He's quiet a moment. \"I want to understand it properly.\"","best":true},{"text":"\"You'll understand eventually. Let's not get into it now.\"","then":"He looks unsettled, filling the gap with his own guesses."},{"text":"\"It's my life. You really don't need every detail.\"","then":"He stiffens. \"I'm still your father. I'd like to know.\""},{"text":"\"It's something normal. Please don't overthink this.\"","then":"He nods, but you can tell he doesn't quite believe you."}],"why":"Naming it clearly, even without every detail, respects both his concern and your choice."},{"prompt":"Your mother asks quietly: \"Whatever it is, will it make you happy?\"","options":[{"text":"\"Yes. I've thought about it hard. This is right for me.\"","then":"She takes your hand. \"Then I want to try to understand it with you.\"","best":true},{"text":"\"Maybe I'm being selfish. I could still go your way instead.\"","then":"She looks torn, unsure whether the choice was ever really yours."},{"text":"\"Does it even matter what makes me happy?\"","then":"She looks stung. \"Of course it matters to me.\""},{"text":"\"Happiness isn't the point. Can we drop it now?\"","then":"She looks more worried, not less, at how quickly you close it."}],"why":"Honestly owning a choice you've already made gives her something real to respond to."}],"relearn":"Tell family honestly that you've chosen the life that's right for you."},
  {"id":"yp-052","cat":"hold-your-ground","type":"strike-rewrite","hook":"\"Resisting the pressure means you're being disrespectful to family.\"","myth":{"un":"Resisting the pressure means disrespecting family.","re":"You can respect your family and still make your own life choices; the two aren't opposites.","why":"Autonomy and love can coexist."},"relearn":"You can respect your family and still make your own life choices.","persona":"any","source":"respect and autonomy"},
  {"id":"yp-053","cat":"worth-beyond-status","type":"spot","hook":"Spot the two responses that let the marriage market measure you.","scene":[{"id":"a","text":"Rejecting it as measuring nothing real","trick":false},{"id":"b","text":"Internalising the market's judgement","trick":true},{"id":"c","text":"Knowing colourism measures nothing about you","trick":false},{"id":"d","text":"Believing a fairer skin tone makes you worth more","trick":true},{"id":"e","text":"Holding your worth steady whatever they say","trick":false}],"why":"Internalising the judgement and ranking yourself by skin tone hand it power; the rest measure nothing real.","relearn":"Reject the marriage-market scrutiny; it measures nothing real about you.","persona":"any","source":"rejecting the market"},
  {"id":"yp-054","cat":"not-marrying","type":"spot","hook":"Spot the two lines that shame a single life.","scene":[{"id":"a","text":"\"Single can be a full, chosen life\"","trick":false},{"id":"b","text":"\"You're incomplete until you marry\"","trick":true},{"id":"c","text":"\"Your worth isn't your status\"","trick":false},{"id":"d","text":"\"Poor thing, still all alone\"","trick":true},{"id":"e","text":"\"Your life is yours to build\"","trick":false}],"why":"'Incomplete until you marry' and 'poor thing, still alone' shame; the others affirm that a single life is whole.","relearn":"A single life is whole; lines that call you incomplete or pity you are the stigma, not the truth.","persona":"any","source":"affirming messages"},
  {"id":"yp-055","cat":"childfree-complete","type":"sort","hook":"Sort: respects the parenthood decision, or hijacks it?","items":[{"id":"a","text":"Letting the couple decide themselves"},{"id":"b","text":"Demanding grandchildren"},{"id":"c","text":"Accepting 'we've decided not to'"},{"id":"d","text":"Guilt-tripping them into it"},{"id":"e","text":"Trusting they know their own life"},{"id":"f","text":"Threatening to be 'so disappointed'"}],"bins":[{"id":"respects","label":"Respects it","valence":"pos"},{"id":"hijacks","label":"Hijacks it","valence":"neg"}],"key":{"a":"respects","b":"hijacks","c":"respects","d":"hijacks","e":"respects","f":"hijacks"},"relearn":"Letting the couple decide and accepting their choice respects it; demanding grandchildren or guilt-tripping hijacks it.","persona":"any","source":"whose decision"},
  {"id":"yp-056","cat":"script-and-choice","type":"match","hook":"Match the timeline belief to whether it frees or pressures.","pairs":[{"left":"No one right timeline","right":"Freeing"},{"left":"Yours can differ","right":"Liberating"},{"left":"Marry by a deadline","right":"Pressuring"},{"left":"\"It's getting late for you\"","right":"Imposing"},{"left":"\"Take the time you need\"","right":"Respecting"}],"relearn":"There's no one timeline; yours can look completely different.","persona":"any","source":"no one timeline"},
  {"id":"yp-057","cat":"hold-your-ground","type":"branch","persona":"any","source":"enforcing no","hook":"A well meaning relative keeps 'finding matches' for you despite your clear no.","steps":[{"prompt":"She sends another profile, cheerful as ever. What do you do?","options":[{"text":"Restate your no clearly and ask her to stop","then":"She's quiet for a second, then says she understands.","best":true},{"text":"Keep going along to be polite","then":"Another profile arrives within the week."},{"text":"Ignore the message entirely","then":"She assumes you just missed it and follows up again."},{"text":"Block her number over it","then":"Her messages stop, but she starts posting profiles for you on the family group."}],"why":"Restating your no plainly enforces the boundary better than politely going along ever could."},{"prompt":"A few days later, a new profile from her pops up: 'Just one more. This one's perfect for you.' What do you do?","options":[{"text":"Say no plainly, without a new explanation","then":"She sighs, but this time actually seems to register it.","best":true},{"text":"Look at the profile 'just this once'","then":"Looking once reads as an opening for the next one too."},{"text":"Explain in detail why you're not interested in matches","then":"The explanation invites debate instead of ending the topic."},{"text":"Get sharp with her for not listening the first time","then":"She feels hurt, and the sharpness becomes its own topic."}],"why":"A plain no, without fresh reasons to argue with, gives her nothing to debate."},{"prompt":"At a cousin's wedding, she seats you beside someone she calls 'just a family friend'. What do you do?","options":[{"text":"Stay polite, then tell her privately it's still no","then":"She sighs, but promises there'll be no more seating surprises.","best":true},{"text":"Play along all evening so no one feels awkward","then":"Their family calls the next day, sure the evening went well."},{"text":"Tell them at the table that she's setting you up","then":"They go red, and the whole table turns to stare at her."},{"text":"Move seats without a word to anyone","then":"They're left confused, and she tells everyone you were rude to a guest."}],"why":"Staying polite to them and clear with her keeps the evening kind and your no intact."},{"prompt":"Months later, she mentions she's finally stopped sending profiles. What do you do?","options":[{"text":"Thank her for respecting it, warmly","then":"She smiles, glad the effort to stop was actually noticed.","best":true},{"text":"Say it's about time","then":"She laughs awkwardly, and the warm moment cools."},{"text":"Ask if she's sure she's really stopped","then":"It reads as distrust of a boundary that's actually being respected."},{"text":"Say nothing, unsure if it'll jinx it","then":"The silence leaves her unsure whether the change even mattered."}],"why":"Thanking her warmly for stopping keeps the relationship close now the pressure has gone."}],"debrief":"A clear, repeated no, kindly delivered, is how you stop well-meaning but unwanted matchmaking.","relearn":"Restate your no clearly and ask them to stop the matchmaking."},
  {"id":"yp-058","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"who matters","hook":"A friend has been unusually quiet lately.","setup":"Tonight, they open up quietly over chai.","steps":[{"prompt":"They say: \"Sometimes I think my family only really values me if I marry.\"","options":[{"text":"\"The people who truly love you value who you are, not your status.\"","then":"They pause, turning that over. \"I want to believe that.\"","best":true},{"text":"\"Maybe marrying would win them over.\"","then":"They start picturing a wedding just to win the approval."},{"text":"\"That's a sad way to think about your family.\"","then":"They look a little more discouraged, not less."},{"text":"\"I'm sure that's not really true.\"","then":"They shrug, unconvinced, and the doubt stays exactly there."}],"why":"Naming that real love isn't conditional gives them something truer to hold onto."},{"prompt":"They ask: \"But what if they never actually come around, though?\"","options":[{"text":"\"Then that's about them, not about your worth.\"","then":"They nod slowly. \"That actually helps, hearing it that way.\"","best":true},{"text":"\"They probably will eventually. Don't worry.\"","then":"They wait on a change that may or may not come."},{"text":"\"Then maybe you should just prove them wrong.\"","then":"They feel the same old pressure, just aimed differently now."},{"text":"\"I don't really know, honestly.\"","then":"They're left without much to hold onto either way."}],"why":"Separating their worth from a relative's approval keeps the pressure from becoming the measure."},{"prompt":"A month later, they say: \"A cousin's wedding made the feeling worse again.\"","options":[{"text":"\"That's the comparison talking, not the truth about you.\"","then":"They exhale. \"Right. It's the comparison, not me.\"","best":true},{"text":"\"Weddings are hard for everyone, honestly.\"","then":"It's true in general, but what they're actually feeling goes unnamed."},{"text":"\"Try not to go to family events for a while.\"","then":"They avoid the next event, but the feeling waits for them anyway."},{"text":"\"I'm sure it'll fade after a bit.\"","then":"They wait for it to fade, but it doesn't yet."}],"why":"Naming the comparison as the source keeps the feeling from becoming a verdict on them."},{"prompt":"Months later, they say: \"The feeling doesn't come up as often now.\"","options":[{"text":"\"Good. Your worth was never really in question.\"","then":"They smile. \"It helped, having someone say that.\"","best":true},{"text":"\"Nice, I guess the family's finally coming around.\"","then":"It's kind, but it credits the family, not the steadiness they built."},{"text":"\"See, I told you it would work out.\"","then":"They feel a little dismissed, hearing it as your win."},{"text":"\"That's good to hear.\"","then":"The moment feels flatter than it should, given the distance travelled."}],"why":"Naming that their worth was never actually in doubt honours what they've come to trust in themselves."}],"relearn":"The people who truly love you value who you are, not your relationship status."},
  {"id":"yp-059","cat":"tools-and-reflection","type":"spot","hook":"Spot the two lines that do NOT match this game's stance.","scene":[{"id":"a","text":"Every life path is dignified","trick":false},{"id":"b","text":"Marriage is the only real success","trick":true},{"id":"c","text":"No pressure in any direction","trick":false},{"id":"d","text":"Choosing to marry is equally valid","trick":false},{"id":"e","text":"An unmarried woman is incomplete","trick":true}],"why":"'Marriage is the only success' and 'an unmarried woman is incomplete' are imposed myths, not this game's stance.","relearn":"The stance: every path is dignified, with no pressure in any direction.","persona":"any","source":"the stance"},
  {"id":"yp-060","cat":"not-marrying","type":"reflect","hook":"Lensy: you can be deeply happy and fulfilled without ever marrying, that's just true. Believe it?","prompt":"What do you think?","options":["Yes","Happy unmarried","It's true"],"affirm":"Deep happiness and fulfilment are wholly available without marriage; that's simply true.","relearn":"You can be deeply happy and fulfilled without ever marrying.","persona":"Sneha","source":"happy unmarried"},
  {"id":"yp-061","cat":"childfree-complete","type":"role-play","persona":"any","source":"defending the choice","hook":"At a family lunch, a relative keeps commenting on your childfree friend Meera.","setup":"She says it again, right as Meera walks back to the table.","steps":[{"prompt":"Your relative says: \"Poor Meera, incomplete without a child.\"","options":[{"text":"\"Her life is full and her own. That's complete enough.\"","then":"The relative pauses, then says \"Hmm. Maybe,\" not sounding convinced.","best":true},{"text":"\"Maybe she'll come around eventually.\"","then":"\"Exactly, give it time,\" the relative says, feeling proven right."},{"text":"\"Let's not talk about her like she's not here.\"","then":"\"Fine, fine,\" the relative mutters, though Meera overhears anyway."},{"text":"\"She's actually thought about it a lot, unlike some people.\"","then":"The relative bristles. \"There's no need to be rude about it.\""}],"why":"Naming Meera's life as complete on its own terms answers the judgement without a fight."},{"prompt":"After lunch, Meera says quietly: \"Every time I visit, someone decides my life is missing something.\"","options":[{"text":"\"Nothing's missing from your life. Sorry it keeps coming up.\"","then":"Meera's shoulders relax. \"Thank you. I needed someone to say that.\"","best":true},{"text":"\"You could just say 'maybe someday', so they finally stop.\"","then":"Meera frowns. \"And then they'd ask every year when someday is.\""},{"text":"\"Don't worry about her. She's always like that.\"","then":"\"Maybe,\" Meera says, \"but it still stings every time.\""},{"text":"\"Maybe skip these family lunches for a while, then.\"","then":"\"And miss seeing you?\" Meera says, managing a small smile."}],"why":"Telling her plainly that nothing's missing meets her hurt, instead of brushing it aside."},{"prompt":"Later, your relative circles back and asks: \"You'd back me up, wouldn't you? Meera's missing out.\"","options":[{"text":"\"No, actually. Her life is full and her own.\"","then":"\"Fine, fine,\" the relative says, and finally drops it.","best":true},{"text":"\"I'd rather not get into it again.\"","then":"\"So you agree, then,\" the relative says, taking the dodge as a yes."},{"text":"\"Everyone has their own path, I guess.\"","then":"\"Sure, sure,\" the relative says, unconvinced but unwilling to argue."},{"text":"\"You should really stop saying that about her.\"","then":"\"I'm only saying what everyone thinks,\" the relative says, defensive."}],"why":"A calm, direct no refuses to join the judgement, without turning lunch into a fight."}],"relearn":"Defend a childfree friend: a full life of one's own is complete enough."},
  {"id":"yp-062","cat":"hold-your-ground","type":"sort","persona":"any","source":"handling pressure","relearn":"Calm boundaries and supportive people handle pressure healthily; over-justifying and absorbing judgement erode you.","hook":"Sort: a healthy way to handle the pressure, or a self-eroding one?","items":[{"id":"a","text":"A calm boundary, repeated"},{"id":"b","text":"Constant self-justification"},{"id":"c","text":"Leaning on supportive people"},{"id":"d","text":"Absorbing every judgement"},{"id":"e","text":"Letting a nosy line pass"},{"id":"f","text":"Marrying to end the questions"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"eroding","label":"Self-eroding","valence":"neg"}],"key":{"a":"healthy","b":"eroding","c":"healthy","d":"eroding","e":"healthy","f":"eroding"}},
  {"id":"yp-063","cat":"script-and-choice","type":"branch","persona":"any","source":"your life weighs most","hook":"You feel torn between what you want and what would please everyone else.","steps":[{"prompt":"You're choosing between two paths at a real fork this week. What do you do?","options":[{"text":"Weigh your own life heavily; you're the one living it","then":"The choice gets clearer once your own weight tips the scale.","best":true},{"text":"Weigh everyone else's opinions equally with your own","then":"You go back and forth for days before finally making a call."},{"text":"Default to pleasing whoever's loudest","then":"The loudest voice wins, whether or not it's the right one."},{"text":"Flip a coin to avoid choosing at all","then":"The coin decides, and the real question stays unexamined."}],"why":"You'll live with the choice long after others move on; weight it accordingly."},{"prompt":"Whatever you decided, it disappoints one relative. What do you do?","options":[{"text":"Feel it, and reopen the choice only for your own reasons","then":"The disappointment is real, and you check the decision against what you want, not their mood.","best":true},{"text":"Reverse the decision, just to spare their disappointment","then":"The reversal spares a feeling, and costs you the chance to find out."},{"text":"Avoid the relative for a while and hope it blows over","then":"The avoidance delays the discomfort without resolving it."},{"text":"Argue until the relative comes round to your view","then":"The argument wins agreement, but not real understanding."}],"why":"Their disappointment matters, but only your own reasons should reopen a decision."},{"prompt":"Looking back a year later, you check how the choice feels. What do you do?","options":[{"text":"Notice how it feels now, and trust what you find","then":"A year on, sitting with it honestly tells you something true.","best":true},{"text":"Second-guess the choice because someone was disappointed","then":"The second-guessing reopens it, though nothing about your own reasons has changed."},{"text":"Credit the relative for how it turned out","then":"You tell the relative it was all thanks to them, and they happily take the credit."},{"text":"Avoid thinking about it at all","then":"You push the thought aside, and the year closes without you asking how it went."}],"why":"Checking back honestly confirms whether the weighting served you, or didn't."}],"debrief":"You'll live with the choice long after others move on; your own wants deserve the most weight.","relearn":"Weight your own life heavily in big choices; you're the one living it."},
  {"id":"yp-064","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"An unmarried or childfree person is to be pitied.\"","myth":{"un":"An unmarried or childfree person is to be pitied.","re":"Many live these paths happily and by choice; pity reveals the script's bias, not their reality.","why":"Assumed unhappiness says more about the assumer."},"relearn":"Many live single or childfree happily by choice; pity reveals the script's bias, not their reality.","persona":"any","source":"no pity needed"},
  {"id":"yp-065","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: a private moment to ask what YOU truly want, away from all the noise, can be clarifying. Try it?","prompt":"What do you think?","options":["Yes","Ask myself","Away from noise"],"affirm":"A quiet, honest check-in with your own wants, free of others' voices, often brings real clarity.","relearn":"Ask yourself privately what you truly want, away from the noise.","persona":"any","source":"private reflection"},
  {"id":"yp-066","cat":"not-marrying","type":"sort","hook":"Sort: a real reason someone stays single, or a stigma assumption?","items":[{"id":"a","text":"They're content and choosing it"},{"id":"b","text":"\"No one would have them\""},{"id":"c","text":"They have a full life already"},{"id":"d","text":"\"Something's wrong with them\""},{"id":"e","text":"They haven't met someone worth marrying yet"},{"id":"f","text":"\"They're too picky and will end up alone\""}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"stigma","label":"Stigma assumption","valence":"neg"}],"key":{"a":"real","b":"stigma","c":"real","d":"stigma","e":"real","f":"stigma"},"relearn":"Contentment, a full life and not-met-someone-yet are real reasons; 'no one would have them', 'something's wrong' and 'too picky' are stigma.","persona":"any","source":"real vs stigma"},
  {"id":"yp-067","cat":"childfree-complete","type":"role-play","persona":"any","source":"owe no one","hook":"Your friend Priya feels weighed down by her family's expectations.","setup":"She brings it up over coffee, stirring a cup she hasn't touched.","steps":[{"prompt":"Priya says: \"I feel like I owe them a grandchild after everything.\"","options":[{"text":"\"You don't owe anyone a child. That decision is fully yours.\"","then":"\"I know,\" she says, \"but it doesn't always feel that way.\"","best":true},{"text":"\"Well, they did raise you.\"","then":"\"Right,\" she says quietly, the guilt settling back in."},{"text":"\"Maybe just have one to stop feeling guilty.\"","then":"Priya goes quiet. \"I don't actually want that, though.\""},{"text":"\"You worry too much about what they think.\"","then":"\"Maybe,\" she says, \"but that doesn't make the worry go away.\""}],"why":"Naming the choice as fully hers, not a debt, answers the guilt at its root."},{"prompt":"Priya calls, upset: \"My mother brought it up again, and I froze.\"","options":[{"text":"\"That sounds hard. What did you say to her?\"","then":"\"Nothing, really,\" she admits. \"I didn't know how to answer.\"","best":true},{"text":"\"You should just tell her clearly this time.\"","then":"\"I know,\" she says, sounding a little scolded."},{"text":"\"Don't let it get to you.\"","then":"\"Easy for you to say,\" she replies, and goes quiet for a moment."},{"text":"\"Maybe she has a point, though.\"","then":"\"Oh,\" Priya says, the guilt she'd been shaking coming right back."}],"why":"Asking how it actually went, gently, keeps the conversation about supporting her, not correcting her."},{"prompt":"Priya asks: \"Is it normal to still feel guilty, even once you're sure?\"","options":[{"text":"\"Yes, and the guilt fades. It doesn't mean the decision's wrong.\"","then":"\"Okay,\" she says, sounding steadier already.","best":true},{"text":"\"If you still feel guilty, maybe you're not sure yet.\"","then":"\"Maybe you're right,\" she says, doubt creeping back in."},{"text":"\"Try not to think about it too much.\"","then":"\"I'll try,\" she says, though the advice doesn't quite land."},{"text":"\"Everyone feels that at first. It'll pass on its own.\"","then":"\"I hope so,\" she says, though the guilt is still sitting there, unnamed."}],"why":"Naming that guilt can outlast a right decision reassures her without reopening the question."},{"prompt":"Months later, Priya says: \"The guilt's actually gone now.\"","options":[{"text":"\"I'm glad. You never owed anyone that decision.\"","then":"\"Thanks for saying that,\" she laughs. \"I needed to hear it.\"","best":true},{"text":"\"See? I knew it would pass eventually.\"","then":"\"Yeah,\" she says, the moment landing a little flatter than it should."},{"text":"\"Good, now you can finally relax about it.\"","then":"\"I guess,\" she says, though 'finally' makes it sound like she was dragging her feet."},{"text":"\"Just don't let your mother bring it up again.\"","then":"\"I can't really control that part,\" she says, a little deflated."}],"why":"Celebrating her peace, without an 'I told you so', keeps the win hers."}],"relearn":"You don't owe anyone a child; that decision is fully yours."},
  {"id":"yp-068","cat":"hold-your-ground","type":"role-play","persona":"any","source":"firm loving no","hook":"Pressure is mounting, and you need a firm but loving no to marriage talk.","setup":"Your father brings it up again after dinner.","steps":[{"prompt":"He says: \"I just want an answer. Yes or no, when will you marry?\"","options":[{"text":"\"I hear you. My answer is no for now.\"","then":"He goes quiet, then nods. \"Okay. For now.\"","best":true},{"text":"\"Maybe soon. Let's not fight about it tonight.\"","then":"He relaxes. \"Soon is good. This year, then.\""},{"text":"\"Why does it have to be yes or no?\"","then":"He looks frustrated. \"Because I need to know something.\""},{"text":"\"Stop pushing me on this, seriously.\"","then":"He stiffens. \"Fine. We'll talk tomorrow.\""}],"why":"A clear no now saves you from a bigger fight over a maybe later."},{"prompt":"The next morning, he says: \"Your mother and I won't be around forever, you know.\"","options":[{"text":"\"I know. I love you, and the timing is still mine.\"","then":"He softens. \"That's fair. I just worry.\"","best":true},{"text":"\"Fine, I'll speed things up for you both then.\"","then":"He looks relieved. \"Good. I'll ask around for names.\""},{"text":"\"That's not fair to bring up right now.\"","then":"He looks hurt. \"I wasn't trying to guilt you.\""},{"text":"\"You'll be around. Let's not talk like that.\"","then":"He sighs. \"You always change the subject, beta.\""}],"why":"Naming the worry, without rushing the decision, honours both things at once."},{"prompt":"That afternoon, he asks quietly: \"Is there someone you haven't told us about?\"","options":[{"text":"\"This is about my own timing, not about anyone else.\"","then":"He looks at you for a moment. \"Okay. I'll take that.\"","best":true},{"text":"\"Maybe. Honestly, I'm not sure yet myself.\"","then":"He perks up. \"Oh? Tell me more.\""},{"text":"\"That's a strange thing to assume.\"","then":"He shrugs. \"I had to ask.\""},{"text":"\"I'll tell you the moment there's someone, I promise.\"","then":"He nods eagerly. \"Good. Then I'll stop asking.\""}],"why":"Keeping it about your own timing closes the guessing game without owing details."},{"prompt":"Before bed, he says: \"Just don't make us wait forever, beta.\"","options":[{"text":"\"I can't promise that. Please respect that it's my own choice.\"","then":"He nods. \"Okay. I'll try to respect that. Goodnight.\"","best":true},{"text":"\"I'll try not to take too long. I promise.\"","then":"He smiles. \"Good. Let's say by next year?\""},{"text":"\"You keep saying that. Please stop.\"","then":"He shakes his head. \"I'll stop when you listen.\""},{"text":"\"Send me a biodata or two, if it helps you worry less.\"","then":"He brightens. \"I'll forward some tomorrow.\""}],"why":"Restating that it's your choice, warmly, closes the night without a promise you can't keep."}],"relearn":"You can say a firm-but-loving no and ask for it to be respected."},
  {"id":"yp-069","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: imagine measuring a life by kindness, growth and love instead of marital status, fairer, isn't it?","prompt":"What do you think?","options":["Yes","Fairer measure","Kindness over status"],"affirm":"Measuring a life by kindness, growth and love is far truer than measuring it by marital status.","relearn":"Measure a life by kindness, growth and love, not marital status.","persona":"any","source":"a fairer measure"},
  {"id":"yp-070","cat":"script-and-choice","type":"sort","hook":"Sort: an autonomous life decision, or someone else's to make?","items":[{"id":"a","text":"Whether you marry"},{"id":"b","text":"Whether the neighbours approve"},{"id":"c","text":"Whether you have children"},{"id":"d","text":"What relatives prefer for you"},{"id":"e","text":"Whom you build a life with"},{"id":"f","text":"What the rishta market scores you"}],"bins":[{"id":"yours","label":"Yours","valence":"pos"},{"id":"theirs","label":"Not theirs to make","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"Whether you marry or have children is yours; neighbours' approval and relatives' preferences aren't the deciders.","persona":"any","source":"yours to decide"},
  {"id":"yp-071","cat":"tools-and-reflection","type":"branch","persona":"any","source":"breaking the cycle","hook":"You want to support a younger relative facing the same pressure you did.","steps":[{"prompt":"Your younger cousin, just 22, says relatives keep hinting she should 'start thinking about marriage soon'. What do you do?","options":[{"text":"Tell her clearly that her path and worth are her own","then":"She looks surprised, like she hadn't heard that before.","best":true},{"text":"Tell her to smile and let the comments pass for now","then":"She nods, but the comments start to sink in over time."},{"text":"Tell her the relatives probably mean well","then":"She hears that as permission for the comments to continue."},{"text":"Say nothing. It's not really your place","then":"She's left to make sense of the pressure alone."}],"why":"Naming her path as her own gives her words to hold onto when the comments return."},{"prompt":"A month later, she says she's started repeating those comments back to herself. What do you do?","options":[{"text":"Remind her those words came from pressure, not truth","then":"She looks relieved, like she can finally set them down.","best":true},{"text":"Tell her not to think about it too much","then":"She nods, but the comments keep replaying quietly in her head."},{"text":"Tell her the relatives may have a point about timing","then":"She takes that as a sign the timeline is real, and the words sink in deeper."},{"text":"Suggest she just ignore that side of the family","then":"The comments still land, just without anyone to talk to about them."}],"why":"Naming the pressure as pressure helps her tell it apart from her own real thoughts."},{"prompt":"At a family wedding, an aunty tells your cousin she 'should be next'. What do you do?","options":[{"text":"Step in warmly and say her path is her own to plan","then":"Aunty shrugs it off, and your cousin exhales, relieved.","best":true},{"text":"Laugh along so it doesn't feel awkward","then":"The joke lands anyway, and your cousin laughs to hide it."},{"text":"Pull your cousin aside afterward to reassure her","then":"It helps a little, but the comment already landed in front of everyone."},{"text":"Say nothing, since it was just a joke","then":"Your cousin absorbs it quietly, like the others before it."}],"why":"Speaking up in the moment protects her, instead of only comforting her after the fact."},{"prompt":"Years later, she tells you she's chosen her own path with confidence. What do you say?","options":[{"text":"Tell her you're proud she found her own voice","then":"She smiles. \"That means a lot, coming from you.\"","best":true},{"text":"Tell her you hope it works out for her","then":"She nods, but the moment feels a little smaller than it should."},{"text":"Ask if she's really thought it through enough","then":"She looks unsettled again, right when she'd felt sure."},{"text":"Say you always knew she'd figure it out","then":"She smiles, but something about it feels a little distant."}],"why":"Naming what she found, her own voice, honours the choice as fully hers."}],"debrief":"Breaking the pressure cycle, by affirming a younger person's autonomy, is a quiet, powerful gift.","relearn":"Tell a younger relative their path and worth are their own; break the pressure cycle."},
  {"id":"yp-072","cat":"not-marrying","type":"strike-rewrite","hook":"\"A single person past a certain age has 'missed the boat'.\"","myth":{"un":"A single person past a certain age has 'missed the boat'.","re":"There's no boat to miss; a good life and even partnership can come at any age, or not, and still be whole.","why":"Life isn't a single departure you either catch or lose."},"relearn":"There's no 'boat' to miss; a full life, and partnership if wanted, can come at any age.","persona":"any","source":"no boat to miss"},
  {"id":"yp-073","cat":"worth-beyond-status","type":"spot","hook":"Spot the two moves that let the 'you're less' message win.","scene":[{"id":"a","text":"Countering it with your own truth","trick":false},{"id":"b","text":"Letting it become your self-image","trick":true},{"id":"c","text":"Reminding yourself of your real worth","trick":false},{"id":"d","text":"Repeating their words about you as fact","trick":true},{"id":"e","text":"Naming it as their script, not your truth","trick":false}],"why":"Absorbing the message and repeating it as fact let it win; the others keep your own truth in charge.","relearn":"Counter the 'you're less for being unmarried' message deliberately with your own truth.","persona":"Sneha","source":"counter the drip"},
  {"id":"yp-074","cat":"childfree-complete","type":"branch","persona":"any","source":"allowed to be unsure","hook":"You're honestly unsure about having kids, and people keep demanding a definite answer.","steps":[{"prompt":"At dinner, a friend asks flat out whether you're having kids. What do you do?","options":[{"text":"Say honestly that you're not sure yet, and that's fine","then":"She's surprised, then says that actually makes sense.","best":true},{"text":"Pick an answer at random to end the question","then":"You spend the rest of dinner defending a stance you don't hold."},{"text":"Say you'll decide once you feel 'ready'","then":"She asks what ready would even look like, and you don't know."},{"text":"Deflect with a joke and change the subject","then":"The table laughs, but the real question sits there unanswered."}],"why":"An honest 'not sure yet' keeps the decision real, instead of faking a certainty you don't feel."},{"prompt":"A week later your mother asks the same thing, more pointedly. What do you do?","options":[{"text":"Tell her calmly that you're not sure yet","then":"She looks unconvinced, but doesn't push further.","best":true},{"text":"Say you'll probably have kids, to keep her happy","then":"She beams, and by the weekend the family has heard you're 'planning'."},{"text":"Get defensive since she's asked before","then":"The conversation turns sharp, and neither of you says what you meant."},{"text":"Ask your partner to answer for you","then":"He hedges, and your mother starts putting her questions to him instead of you."}],"why":"A calm, honest 'not sure' keeps your uncertainty from turning into pressure to pick a side."},{"prompt":"Months on, you notice you're still unsure, and that itself starts to worry you. What do you do?","options":[{"text":"Let yourself stay unsure without forcing a verdict","then":"The worry eases once you stop demanding an answer from yourself.","best":true},{"text":"Force a decision just to stop feeling unsettled","then":"The decision feels hollow, made to end discomfort, not to choose."},{"text":"Take the ongoing uncertainty as a sign you must want kids","then":"You start telling friends you're leaning yes, and the unease stays put."},{"text":"Take it as a sign you definitely don't want kids","then":"You close a door that honestly still feels open."}],"why":"Letting the question stay open takes the pressure off, so an answer can come in its own time."}],"debrief":"You're allowed to be unsure about children; you don't owe anyone a forced, premature certainty.","relearn":"You can be honestly unsure about children; you don't owe anyone forced certainty."},
  {"id":"yp-075","cat":"hold-your-ground","type":"reflect","hook":"Lensy: holding your ground on your own life, kindly, is a quiet act of self-respect. Worth practising?","prompt":"What do you think?","options":["Yes","Self-respect","Worth it"],"affirm":"Standing kindly but firmly for your own choices is self-respect in action; it gets easier with practice.","relearn":"Holding your ground on your own life, kindly, is a quiet act of self-respect.","persona":"any","source":"self-respect"},
  {"id":"yp-076","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Everyone secretly wants the same standard life.\"","myth":{"un":"Everyone secretly wants the same standard life.","re":"People genuinely want different lives; a meaningful life looks different for everyone.","why":"Diversity of wants is real, not a cover story."},"relearn":"People genuinely want different lives; a meaningful life looks different for everyone.","persona":"any","source":"different wants are real"},
  {"id":"yp-077","cat":"worth-beyond-status","type":"sort","hook":"Sort: builds worth that lasts, or worth the world can take away?","items":[{"id":"a","text":"Your values and how you live"},{"id":"b","text":"Approval for marrying 'on time'"},{"id":"c","text":"Your growth and relationships"},{"id":"d","text":"Marriage-market standing"},{"id":"e","text":"The people you've shown up for"},{"id":"f","text":"Relatives' praise at the next wedding"}],"bins":[{"id":"lasts","label":"Worth that lasts","valence":"pos"},{"id":"taken","label":"World can take it","valence":"neg"}],"key":{"a":"lasts","b":"taken","c":"lasts","d":"taken","e":"lasts","f":"taken"},"relearn":"Values, growth and relationships build worth that lasts; approval and market standing can be taken away.","persona":"any","source":"lasting worth"},
  {"id":"yp-078","cat":"not-marrying","type":"branch","persona":"any","source":"your timeline","hook":"You do want a partner eventually, but not on anyone else's timeline.","steps":[{"prompt":"A friend sets you up on a date 'before you get too old for it'. What do you do?","options":[{"text":"Go if you're genuinely curious, not because of her deadline","then":"You go, curious on your own terms, and enjoy the evening regardless.","best":true},{"text":"Go along mainly to prove her wrong about the deadline","then":"You go, but spend the night arguing with a clock in your head."},{"text":"Decline out of spite at the framing","then":"You decline at first, but curiosity gets the better of you within the week."},{"text":"Agree, and rush the whole evening to 'move fast'","then":"The rushing leaves little room to actually notice him."}],"why":"Going from your own curiosity, not someone's clock, keeps the choice yours."},{"prompt":"The date goes fine, and he asks to meet again next week. What do you do?","options":[{"text":"Say yes if you want to, at whatever pace feels right","then":"You agree to a pace that's actually yours, not anyone's schedule.","best":true},{"text":"Say yes and mentally start planning a fast timeline","then":"You say yes, already rushing ahead of where you actually are."},{"text":"Wait two days to reply, so you don't seem desperate","then":"He starts to wonder if you're even interested, and the second date feels stiff."},{"text":"Ask your friend how soon you should say yes","then":"Her advice comes with her deadline attached, and you start to feel it too."}],"why":"Choosing your own pace, not anyone's rulebook or clock, keeps the dating honest."},{"prompt":"Months in, relatives start asking when the wedding is. What do you do?","options":[{"text":"Tell them it's going well, and you're taking your time","then":"They nod, mostly satisfied, and the relationship keeps its own pace.","best":true},{"text":"Rush a proposal conversation to quiet the questions","then":"The conversation happens early, shaped more by them than by you."},{"text":"Tell them you broke up, so they'll stop asking","then":"The questions stop, but now there's a secret to keep at every visit."},{"text":"Snap that it's nobody's business how fast you go","then":"The sharpness surprises everyone, including you."}],"why":"Naming your own pace calmly keeps outside urgency from setting the terms."},{"prompt":"A year in, he asks how you feel about the pace things have taken. What do you do?","options":[{"text":"Tell him honestly where you are with it","then":"He shares where he is too, and the timing becomes something you decide together.","best":true},{"text":"Say you'll wait another year, just to prove you weren't rushed","then":"You name a delay you don't feel, just to make a point to no one."},{"text":"Push for a date soon to make up for 'lost time'","then":"The rush borrows urgency from years you never actually lost."},{"text":"Let him decide the timing entirely","then":"You hand over a choice that was meant to be yours together."}],"why":"Saying honestly where you are keeps the timing yours, not a reaction to pressure."}],"debrief":"Wanting a partner and refusing to rush it aren't in conflict; the right time is yours to judge.","relearn":"Wait for the right person on your own timeline; don't settle to meet a deadline."},
  {"id":"yp-079","cat":"tools-and-reflection","type":"match","hook":"Match each truth to the path it frees.","pairs":[{"left":"Worth isn't marital status","right":"Single, with dignity"},{"left":"Womanhood isn't motherhood","right":"Childfree, complete"},{"left":"Your life, your call","right":"Any path, freely"},{"left":"Many ways to build a family","right":"Partnered differently"},{"left":"No one timeline","right":"On your own schedule"}],"relearn":"Worth-isn't-status, womanhood-isn't-motherhood and your-life-your-call each free a path to live.","persona":"any","source":"truths that free"},
  {"id":"yp-080","cat":"childfree-complete","type":"match","hook":"Match each family size to its validity.","pairs":[{"left":"One child","right":"Can be right for some"},{"left":"Several children","right":"Can be right for others"},{"left":"No children","right":"Can be right too"},{"left":"Adopting","right":"A real way to build a family"},{"left":"Still deciding","right":"Honestly okay for now"}],"relearn":"One child, several, none, adopting or still deciding can all be right for different people.","persona":"Nisha","source":"all can be right"},
  {"id":"yp-081","cat":"hold-your-ground","type":"branch","persona":"any","source":"support in conflict","hook":"Family conflict over your choices has become genuinely distressing.","steps":[{"prompt":"After another argument, you notice you're exhausted before the conversation even starts. What do you do?","options":[{"text":"Reach for support, a counsellor or a trusted person","then":"Talking it through with someone outside the conflict actually helps.","best":true},{"text":"Push through it alone, since it's 'just family'","then":"The exhaustion keeps building, with nowhere for it to go."},{"text":"Assume you must be the reason the conflict won't stop","then":"You carry blame that was never yours to hold, and nothing actually changes."},{"text":"Cut contact suddenly, without a word","then":"The sudden silence creates its own stress, without any actual support, and the family reaches out anyway."}],"why":"Support helps you hold both your ground and your wellbeing through a conflict like this."},{"prompt":"That evening, a friend notices you seem off and asks if you're okay. What do you say?","options":[{"text":"Tell her honestly how heavy it's been","then":"She listens, then asks how she can help, and means it.","best":true},{"text":"Say you're fine, just busy","then":"She lets it go, though the exhaustion underneath doesn't."},{"text":"Downplay it as 'just family stuff'","then":"She nods, unaware of how much it's actually weighing on you."},{"text":"Vent everything at once, without a pause for her to reply","then":"She listens kindly, though you leave without hearing what she might have offered."}],"why":"Naming it honestly, even to a friend, opens the door toward real support."},{"prompt":"A few weeks on, a family member gets in touch, and the talk is calmer but still hard. What do you do?","options":[{"text":"Reach for support afterward, a counsellor or a trusted person","then":"It's still hard, but you have somewhere steady to bring it now.","best":true},{"text":"Expect to feel completely fine now, without needing any support","then":"You're caught off guard by how much it still affects you."},{"text":"Try to carry all of it alone this time","then":"The exhaustion from before starts to build again."},{"text":"Assume staying quiet will finally make it blow over","then":"The conflict doesn't blow over. It just waits for the next call."}],"why":"Knowing where you'll take a hard talk afterwards makes it easier to stay steady during it."}],"debrief":"Sustained family conflict is heavy, and it's never your fault; support helps you hold your ground and your wellbeing.","relearn":"If family conflict over your choices turns distressing, reach for support."},
  {"id":"yp-082","cat":"script-and-choice","type":"reflect","hook":"Lensy: the bravest, kindest thing can be to live honestly as yourself, on your own path. Believe it?","prompt":"What do you think?","options":["Yes","Live honestly","My own path"],"affirm":"Living honestly as yourself, on your own path, is a quiet bravery that gives others permission too.","relearn":"Living honestly as yourself, on your own path, is brave and kind.","persona":"any","source":"live honestly"},
  {"id":"yp-083","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"reframing worth","hook":"Your cousin has been withdrawn since the last family get-together.","setup":"Tonight, she confides in you, upset.","steps":[{"prompt":"She says: \"Everyone keeps saying I'm still single like it's something wrong with me.\"","options":[{"text":"\"Your worth has nothing to do with being single. You're whole.\"","then":"She's quiet, then a small smile. \"I needed to hear that.\"","best":true},{"text":"\"Don't worry, beta. We'll find you someone soon enough.\"","then":"She nods, but the fix quietly stays outside of her."},{"text":"\"Honestly, they really shouldn't say things like that to you at all.\"","then":"She agrees, but the feeling of being wrong stays there."},{"text":"\"Try not to let it get to you.\"","then":"She nods, but the feeling doesn't actually lift."}],"why":"Naming her worth plainly, separate from being single, gives her something truer to hold."},{"prompt":"She asks: \"But why does it bother people so much, then?\"","options":[{"text":"\"Because it's an old script, not because something's wrong with you.\"","then":"She nods slowly. \"That actually makes more sense.\"","best":true},{"text":"\"Because they care about you, probably.\"","then":"She takes that as reason to keep explaining herself to them."},{"text":"\"Because people are nosy about this sort of thing, honestly.\"","then":"She laughs, but the question stays half answered."},{"text":"\"I don't really know why they do that, honestly.\"","then":"She's left without much of an answer either way."}],"why":"Naming the script, not her, as the source keeps the comments from feeling like a verdict."},{"prompt":"Weeks later, she says: \"The comments don't shake me the way they used to.\"","options":[{"text":"\"That's you, standing in your own worth now.\"","then":"She grins. \"Yeah. It actually feels like mine.\"","best":true},{"text":"\"Good. Maybe they've finally stopped after all this time.\"","then":"It's kind, but the shift she made herself goes unnamed."},{"text":"\"Are you sure it'll last, though?\"","then":"She looks unsettled again, right after finding her footing."},{"text":"\"That's nice to hear.\"","then":"The moment feels a little flatter than it should."}],"why":"Naming the change as hers, not luck, honours the worth she's claimed for herself."}],"relearn":"Tell someone struggling that their worth has nothing to do with being single."},
  {"id":"yp-084","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: your path, your call, whichever path you choose, choose it freely and own it fully. Ready?","prompt":"What will you carry?","options":["Choose freely","Worth beyond status","Hold my ground","Respect every path"],"affirm":"Choose freely and own it fully, that's the whole heart of your path being your call.","relearn":"Whichever path you choose, choose it freely, own it fully, and respect everyone else's.","persona":"any","source":"carry forward"},
  {"id":"yp-900","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Every married woman's real job is to give the family a child.\"","myth":{"un":"Every married woman's real job is to give the family a child.","re":"A woman's life is her own; bearing a child is a choice, never a duty owed to anyone.","why":"No one is obligated to reproduce; the body and the decision are hers."},"relearn":"Bearing a child is a personal choice, never a duty a woman owes the family.","persona":"Nisha","source":"not a duty"},
  {"id":"yp-901","cat":"childfree-complete","type":"strike-rewrite","hook":"\"You'll be so lonely in old age with no children to care for you.\"","myth":{"un":"You'll be lonely in old age with no children to care for you.","re":"Care in later life comes from partners, friends, chosen family and planning, not only from children.","why":"Having children guarantees no one company or care; many parents age alone too."},"relearn":"Care in old age comes from many bonds and planning, not only from having children.","persona":"any","source":"old age care"},
  {"id":"yp-902","cat":"childfree-complete","type":"strike-rewrite","hook":"\"A woman who doesn't want kids must have something wrong with her.\"","myth":{"un":"A woman who doesn't want kids must have something wrong with her.","re":"Not wanting children is a normal, healthy preference, not a flaw or a symptom.","why":"People simply want different lives; a clear no is self-knowledge, not damage."},"relearn":"Not wanting children is a normal preference, not a flaw to be fixed.","persona":"any","source":"nothing wrong"},
  {"id":"yp-903","cat":"childfree-complete","type":"strike-rewrite","hook":"\"It's unnatural for a woman to not want to be a mother.\"","myth":{"un":"It's unnatural for a woman to not want to be a mother.","re":"Women have always wanted different lives; choosing not to mother is one human path among many.","why":"There is no single 'natural' script every woman must follow."},"relearn":"Choosing not to be a mother is one valid human path, not unnatural.","persona":"any","source":"not unnatural"},
  {"id":"yp-904","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Without your own kids you'll never know a parent's love.\"","myth":{"un":"Without your own kids you'll never know a parent's love.","re":"Love, mentoring and deep care flow through many bonds; no one form has a monopoly on it.","why":"Aunts, teachers, partners and friends give and receive profound love too."},"relearn":"Deep love and care flow through many bonds, not only biological parenthood.","persona":"any","source":"love is plural"},
  {"id":"yp-905","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Once you hold a baby your hormones will force you to want one.\"","myth":{"un":"Once you hold a baby your hormones will make you want one.","re":"Enjoying a friend's baby and wanting to raise one are different things; you decide which is yours.","why":"Liking children doesn't override a considered decision about your own life."},"relearn":"Loving other people's kids doesn't mean you must have your own.","persona":"any","source":"not hormones"},
  {"id":"yp-906","cat":"childfree-complete","type":"strike-rewrite","hook":"\"A marriage without children is incomplete and bound to fall apart.\"","myth":{"un":"A marriage without children is incomplete and bound to fall apart.","re":"A partnership is built on the two people in it; many strong, lasting marriages are childfree by choice.","why":"What holds a couple together is care and respect, not a third person."},"relearn":"A childfree marriage is complete; partnership rests on the two people in it.","persona":"any","source":"complete partnership"},
  {"id":"yp-907","cat":"childfree-complete","type":"strike-rewrite","hook":"\"It's fine to delay, but every woman secretly wants a baby eventually.\"","myth":{"un":"Every woman secretly wants a baby eventually.","re":"Some women genuinely never want children; that quiet, steady no is real and final for them.","why":"Assuming a hidden yes erases what she actually knows about herself."},"relearn":"Some women genuinely never want children; that settled no is real.","persona":"Nisha","source":"no hidden yes"},
  {"id":"yp-908","cat":"childfree-complete","type":"strike-rewrite","hook":"\"You owe your parents a grandchild for everything they did for you.\"","myth":{"un":"You owe your parents a grandchild for raising you.","re":"You can love and honour your parents fully without producing a grandchild on demand.","why":"Gratitude is real, but no one is owed a child as repayment for being raised."},"relearn":"You can honour your parents without owing them a grandchild.","persona":"any","source":"no debt owed"},
  {"id":"yp-909","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Your bloodline will end if you don't have children, what a waste.\"","myth":{"un":"Your bloodline will end if you don't have children, what a waste.","re":"A life's worth isn't measured by passing on a surname; what you build and give already matters.","why":"Meaning lives in how you spend your years, not in continuing a name."},"relearn":"Your worth isn't carrying on a bloodline; your life already matters.","persona":"any","source":"not a bloodline"},
  {"id":"yp-910","cat":"childfree-complete","type":"strike-rewrite","hook":"\"Choosing to be childfree is just modern selfishness from the city.\"","myth":{"un":"Being childfree is just modern selfishness.","re":"Deciding honestly about whether you can raise a child well is responsible and caring, not selfish.","why":"Thinking carefully about a huge life choice is the opposite of selfish."},"relearn":"Deciding honestly about parenthood is responsible, not selfish.","persona":"any","source":"not selfish-redux"},
  {"id":"yp-911","cat":"childfree-complete","type":"strike-rewrite","hook":"\"If you can have kids and choose not to, you're insulting those who can't.\"","myth":{"un":"Choosing to be childfree insults people who can't have children.","re":"Your private choice takes nothing from anyone; respect means no one owes the world a child.","why":"One person's freedom to choose doesn't harm another's different situation."},"relearn":"Your childfree choice harms no one; no one owes the world a child.","persona":"any","source":"no insult"},
  {"id":"yp-912","cat":"childfree-complete","type":"strike-rewrite","hook":"\"A childfree woman has nothing to look forward to as she gets older.\"","myth":{"un":"A childfree woman has nothing to look forward to as she ages.","re":"Work, friendships, travel, learning and chosen family fill a full life at every age.","why":"A future is built from many things; children are one possible thread, not the only one."},"relearn":"A full future is built from many things, not children alone.","persona":"Sneha","source":"full future"},
  {"id":"yp-913","cat":"childfree-complete","type":"strike-rewrite","hook":"\"You're being a bad daughter-in-law by not giving the family an heir.\"","myth":{"un":"You're a bad daughter-in-law for not giving the family an heir.","re":"Your value in a family isn't producing an heir; you are a person, not a means to a child.","why":"Worth in a family rests on who you are, never on what your body produces."},"relearn":"Your worth in a family isn't producing an heir.","persona":"Nisha","source":"not an heir-maker"},
  {"id":"yp-914","cat":"childfree-complete","type":"strike-rewrite","hook":"\"At least have one, so people don't talk and you're not pitied.\"","myth":{"un":"Have a child so people don't talk and you're not pitied.","re":"A child is never a shield against gossip; bring a person into the world only if you truly want to.","why":"Having a baby to silence relatives is unfair to you and to the child."},"relearn":"Never have a child to stop gossip; want them for their own sake.","persona":"any","source":"not to silence talk"},
  {"id":"yp-915","cat":"childfree-complete","type":"branch","persona":"any","source":"good news at wedding","hook":"A baby isn't in your plans, but at a wedding an aunty keeps asking when you'll 'give good news'.","steps":[{"prompt":"She asks again, louder, waiting for the table to hear your answer. What do you do?","options":[{"text":"Smile, say it's not on the cards, and change the subject","then":"She blinks, then turns back to the buffet line.","best":true},{"text":"Promise 'soon, aunty' just to end it","then":"She beams and tells the next table you're expecting news soon."},{"text":"Laugh nervously and say nothing","then":"She takes your silence as shyness and repeats the question."},{"text":"Walk away without a word","then":"She calls out after you, and half the table turns to look."}],"why":"A warm, closed answer ends the question without a scene or a promise you don't mean."},{"prompt":"By dessert, a different relative corners you with the very same question. What do you do?","options":[{"text":"Say warmly that it's not in your plans","then":"She nods and moves on, easily satisfied.","best":true},{"text":"Tell her 'soon' just to end it faster","then":"She lights up and adds you to her own gossip list."},{"text":"Stay silent, hoping she'll lose interest","then":"She fills the silence with guesses of her own."},{"text":"Ask her plainly why it matters so much to her","then":"She looks taken aback, and mutters something about tradition."}],"why":"A steady answer, however many times you're asked, keeps the decision yours to hold."},{"prompt":"At the next family wedding, the same aunty spots you across the hall. What do you do?","options":[{"text":"Greet her warmly and steer straight to another topic","then":"She takes the cue and asks about your work trip instead.","best":true},{"text":"Avoid her section of the hall all evening","then":"She corners you near the exit instead, question ready."},{"text":"Brace for the question and answer before she even asks","then":"She looks startled, since she was only saying hello."},{"text":"Prepare a joke to lighten the moment, just in case","then":"It gets a laugh when she does ask, though the real question stays open."}],"why":"Leading with warmth keeps the relationship easy, even while the boundary stays exactly the same."}],"debrief":"A warm, closed deflection ends the 'good news' question without lying or warring.","relearn":"Deflect the 'good news' question warmly and closed; you owe no promise."},
  {"id":"yp-916","cat":"childfree-complete","type":"branch","persona":"Nisha","source":"telling your partner","hook":"Your husband wants a child. You've realised you genuinely don't, and you're scared to say it.","steps":[{"prompt":"He mentions baby names over dinner, casually, the way he has for weeks. What do you do?","options":[{"text":"Say gently that you need to talk about something first","then":"He puts his fork down, ready to listen, but the doorbell rings and the moment slips away.","best":true},{"text":"Laugh along and pick a name to avoid the topic","then":"The dinner stays light, and the real talk waits another week."},{"text":"Stay quiet and hope the feeling passes","then":"It doesn't pass, and dinner ends with the names list still growing."},{"text":"Agree out loud that a baby sounds nice","then":"He looks pleased, and you spend the night regretting the agreement."}],"why":"Naming that something needs saying is the necessary first step, even if the moment slips away."},{"prompt":"A few days later, he brings up baby names again, then notices your face and asks: \"What's wrong?\"","options":[{"text":"Say honestly that you don't think you want a child","then":"He goes very quiet, then asks you to say more.","best":true},{"text":"Say it's nothing, not tonight","then":"He looks relieved, but the real thing still waits, heavier now."},{"text":"Blame it on work stress instead","then":"He believes you, and the actual conversation gets pushed off again."},{"text":"Say you're just tired of hearing about baby names","then":"He apologises for the names, missing the deeper thing you meant."}],"why":"Saying the real thing, however hard, is the only way this becomes a shared decision."},{"prompt":"That weekend, he says he can tell there's more you haven't said, and asks for all of it. What do you say?","options":[{"text":"Tell him all of it, including how long it's been","then":"He listens to every word, then goes quiet for a long moment.","best":true},{"text":"Say it's a brand new feeling, to soften it","then":"He nods, but the timeline doesn't quite add up. He falls quiet, thinking it over."},{"text":"Say you're not sure, to avoid the honest answer","then":"The conversation stalls. He goes quiet, unconvinced."},{"text":"Turn it back and ask why he's always wanted one","then":"He goes quiet, then says, \"You don't actually want this, do you?\""}],"why":"Being fully honest, even when it's hard, lets him understand the whole picture."},{"prompt":"A few days later, he says he needs time before he can talk about it more. What do you do?","options":[{"text":"Give him that space, and stay open when he's ready","then":"He comes back a few evenings later, calmer, ready to actually talk.","best":true},{"text":"Push to resolve it that same night","then":"The conversation turns into an argument neither of you meant to have."},{"text":"Assume his silence means he's already decided against you","then":"You spend the days bracing for an ending that hasn't happened."},{"text":"Fill the silence with reassurances he hasn't asked for","then":"He nods along, still working through it quietly on his own."}],"why":"A decision this size needs room for both of you to actually process it, not just announce it."},{"prompt":"When he's ready, he sits down and asks what you both do now. What do you say?","options":[{"text":"Say you want to decide this together, honestly, as a couple","then":"He agrees, and for the first time the decision feels like it belongs to both of you.","best":true},{"text":"Say you've already decided, so there's nothing left to discuss","then":"He feels shut out of a decision that affects his life too."},{"text":"Offer to have a child anyway, since he wants one so much","then":"He notices you don't mean it, and says he doesn't want that either."},{"text":"Suggest you each just keep your own view for now","then":"You both go quiet again, no closer to a shared answer."}],"why":"A childfree feeling this big deserves an honest, shared talk, not silence or self erasure."}],"debrief":"Honesty, given room and time, turns a hard feeling into a decision you make together.","relearn":"Share a genuine childfree decision honestly with your partner; decide together."},
  {"id":"yp-917","cat":"childfree-complete","type":"branch","persona":"any","source":"doctor pressure","hook":"You're not planning kids, yet a doctor warns you, unasked, to 'hurry up' before it's too late.","steps":[{"prompt":"She keeps talking about your 'window' instead of your actual appointment. What do you do?","options":[{"text":"Say the timing is yours, and steer back to your visit","then":"She pauses, then moves back to the actual reason you came.","best":true},{"text":"Sit quietly and let her finish her whole lecture","then":"The appointment runs long, and your real question never gets asked."},{"text":"Argue back point by point about your choices","then":"The visit turns into a debate instead of the checkup you came for."},{"text":"Leave and find another clinic on the spot","then":"You lose the appointment slot, and the actual concern still isn't seen to."}],"why":"A calm redirect keeps the appointment about what you actually came for."},{"prompt":"At the next visit, a nurse repeats a version of the same warning. What do you do?","options":[{"text":"Give a short, clear redirect","then":"She nods and moves on with the checkup.","best":true},{"text":"Assume every clinic will be like this and avoid checkups","then":"You skip your next checkup, and a small health worry goes unchecked for months."},{"text":"Explain your life choices to her in detail","then":"She listens, then adds her opinion anyway."},{"text":"Complain to the front desk instead of addressing it","then":"The complaint goes into a file, and the same thing happens next time."}],"why":"A short, clear redirect works with each new person, without a fresh argument every time."},{"prompt":"A friend asks if the comments ever get to you. What do you say?","options":[{"text":"Say they used to, but your timeline is yours to set","then":"She nods, glad you sound steady about it now.","best":true},{"text":"Say doctors know best, so maybe you should rush","then":"Saying it out loud, you start wondering if you should rush after all."},{"text":"Say you'll just tell them 'soon' next time","then":"She laughs, then asks what you'll say when they ask 'how soon'."},{"text":"Say you've learned to just agree with them in the room","then":"She frowns and asks whether agreeing is starting to change how you feel."}],"why":"Saying calmly that your timeline is yours shows the comments no longer steer you."}],"debrief":"You can decline unsolicited 'hurry up' advice and keep an appointment on track; your timeline is yours.","relearn":"Decline unsolicited 'hurry up' pressure; your timeline is yours to set."},
  {"id":"yp-918","cat":"childfree-complete","type":"branch","persona":"any","source":"unwanted tips","hook":"You've made your decision about children, yet relatives keep sending fertility tips and baby name lists.","steps":[{"prompt":"Another message lands, a whole list of 'lucky' names. What do you do?","options":[{"text":"Thank them once, say it's decided, and mute the topic","then":"The messages taper off within a week.","best":true},{"text":"Reply 'haha thanks' to be polite","then":"It reads as encouragement, and the lists keep coming."},{"text":"Ignore every message and hope they eventually stop sending more","then":"The relative assumes you haven't seen them yet, and sends more."},{"text":"Block the relative outright","then":"It stops the messages, but starts a family conversation about why."}],"why":"One clear, kind reply plus muting the topic ends it without engaging every single push."},{"prompt":"A week later, a different relative sends fertility tips 'just in case'. What do you do?","options":[{"text":"Send a clear, kind message and mute the chat","then":"This relative takes the hint and stops sending tips.","best":true},{"text":"Explain your whole decision to this relative in detail","then":"They reply with questions about each reason, and the thread keeps growing."},{"text":"Get sharp with them for repeating the pattern","then":"They're hurt, since they had no idea anyone else had sent tips."},{"text":"Just stop opening messages from the family group","then":"You miss things you actually wanted to see, not just the tips."}],"why":"A short, kind boundary works on each new person, without a fresh debate every time."},{"prompt":"Months later, someone forwards an old fertility article 'for your health'. What do you do?","options":[{"text":"Note that the decision hasn't changed, kindly, and leave it there","then":"They say fair enough, and it doesn't come up again from them.","best":true},{"text":"Read the whole article carefully, just in case there's something in it","then":"You spend an evening second guessing a decision you'd already settled."},{"text":"Get frustrated that this is still happening months later","then":"The frustration lingers longer than the actual message did."},{"text":"Forward it to your partner without comment","then":"Your partner isn't sure if you want to talk about it or just wanted them to see it."}],"why":"A settled decision doesn't need reopening every time someone forwards something new."}],"debrief":"A single clear 'it's decided' plus muting the topic holds your boundary kindly.","relearn":"Set one clear 'it's decided' and mute the topic; you needn't engage each push."},
  {"id":"yp-919","cat":"childfree-complete","type":"branch","persona":"any","source":"only as a mother","hook":"A colleague says you'll 'understand life' only once you become a mother.","steps":[{"prompt":"She says it again in the break room, in front of two others. What do you do?","options":[{"text":"Say your life teaches you plenty and leave it there","then":"She looks a little unsure what to add, and the talk moves on.","best":true},{"text":"Laugh it off and say nothing","then":"She takes the laugh as agreement, but seems to turn it over in her head after."},{"text":"List everything your life has taught you, in detail","then":"The others listen politely, but it starts to feel like an audition."},{"text":"Snap that she doesn't know your life","then":"The break room goes quiet, and she looks stung."}],"why":"Naming your own life as enough holds your worth without arguing to prove it."},{"prompt":"Later, she catches you alone and half apologises, saying she 'didn't mean it that way'. What do you do?","options":[{"text":"Accept it warmly, and name what actually bothered you","then":"She nods, and the next conversation is genuinely easier.","best":true},{"text":"Brush it off with \"It's fine. Don't worry about it.\"","then":"The comment goes unaddressed and she says something similar later."},{"text":"Say she should think before she speaks next time","then":"She feels lectured instead of heard, and the air stays tense."},{"text":"Accept the apology, then quietly keep your distance from her","then":"The awkwardness fades slowly, but the actual point never gets said."}],"why":"Accepting the apology and naming the real point keeps the moment honest, not just polite."},{"prompt":"At a team lunch weeks later, a new colleague repeats a version of the same line. What do you do?","options":[{"text":"State plainly that your life teaches you plenty too","then":"It lands easily, and the table moves on to other things.","best":true},{"text":"Let it go unanswered, not wanting to seem touchy","then":"The new colleague takes the silence as agreement."},{"text":"Make a joke that turns the moment awkward","then":"The joke lands oddly, and the actual point gets lost."},{"text":"Pull the new colleague aside privately to explain everything","then":"It becomes a bigger conversation than the moment actually needed."}],"why":"A plain, calm line answers someone new without a lecture, a joke or a silence."}],"debrief":"Parenthood is one way to grow, not the gate to understanding life; your path teaches you too.","relearn":"Parenthood is one way to grow, not the only road to understanding life."},
  {"id":"yp-920","cat":"childfree-complete","type":"branch","persona":"any","source":"unasked IVF offer","hook":"Your in-laws offer to fund IVF you never asked for, sure a child will 'fix' your marriage.","steps":[{"prompt":"Your partner's mother brings it up at dinner, offer already half planned. What do you do?","options":[{"text":"Thank her, and say firmly that children aren't the plan","then":"She's surprised, but says she understands.","best":true},{"text":"Say you'll think about the offer","then":"She starts mentioning clinics the very next week."},{"text":"Wonder aloud if they're right that a baby would help","then":"She squeezes your hand, sure now that the offer is welcome."},{"text":"Change the subject completely and hope the offer quietly fades","then":"It doesn't fade; she brings it up again at the next dinner."}],"why":"A firm, warm decline protects your real choice better than a vague maybe."},{"prompt":"Soon after, your partner's father says a baby would bring you two closer, and the offer stands. What do you do?","options":[{"text":"Say your marriage doesn't need a baby, and it isn't the plan","then":"He nods slowly, and doesn't mention it again that evening.","best":true},{"text":"Let the comment pass without correcting it, just this once","then":"The offer quietly stays 'open' in their minds."},{"text":"Get visibly annoyed at the repeated offer","then":"The evening turns tense, and he mutters that he was only trying to help."},{"text":"Ask your partner to handle it instead","then":"Your partner mumbles something vague, and their father takes it as a maybe."}],"why":"Answering the 'closer' idea plainly closes both the offer and the myth behind it."},{"prompt":"Weeks later, your partner asks how you really feel about their parents' offer. What do you say?","options":[{"text":"Tell your partner honestly, and ask for backing with their parents","then":"Your partner says they'll speak to their parents themselves, so it isn't all on you.","best":true},{"text":"Say it's fine, since you don't want trouble with their family","then":"Your partner takes you at your word, and the offer stays on the table."},{"text":"Say you feel guilty for letting their parents down","then":"Your partner looks worried, unsure now whether you want to accept."},{"text":"Suggest telling them you're 'still deciding' to keep the peace","then":"Your partner agrees, and their mother hears it as a yes waiting to happen."}],"why":"Being honest with your partner lets the two of you answer their parents together."},{"prompt":"A cousin later asks if you're 'considering it now', having heard about the offer. What do you do?","options":[{"text":"Say plainly that it isn't the plan, and leave it there","then":"The cousin nods, and doesn't bring it up again.","best":true},{"text":"Explain the whole backstory to the cousin, from the first dinner","then":"The cousin listens eagerly, and your story reaches three aunties by Sunday."},{"text":"Let the cousin assume whatever they want","then":"The rumour mill keeps a version of the offer alive anyway."},{"text":"Say maybe someday, to avoid a flat no","then":"The cousin repeats 'maybe someday' to someone else at the next wedding."}],"why":"A plain answer to the cousin stops the offer living on as family gossip."}],"debrief":"A funded offer doesn't change whose decision this is, and a child isn't a fix for a marriage; decline warmly and firmly.","relearn":"A funded offer doesn't change whose choice this is; decline warmly and firmly."},
  {"id":"yp-921","cat":"childfree-complete","type":"branch","persona":"any","source":"backing your sister","hook":"Your younger sister is pressured to 'prove herself' by having a baby soon after marriage.","steps":[{"prompt":"At a family lunch, an aunty tells her not to 'wait too long'. What do you do?","options":[{"text":"Gently say, right then, that her timing is hers to choose","then":"The aunty pauses, and your sister looks relieved someone said it.","best":true},{"text":"Stay quiet, not wanting to start a scene at lunch","then":"Your sister absorbs the comment alone, without any backup."},{"text":"Agree with the aunty to keep the table peaceful","then":"Your sister hears her own sister side with the pressure."},{"text":"Pull your sister aside privately afterward instead","then":"Later, she says it helped, but admits the comment sat with her all through lunch."}],"why":"Answering warmly in the moment stops the pressure landing unchallenged, without a scene."},{"prompt":"Later, your sister admits she's started to wonder if the aunty has a point. What do you do?","options":[{"text":"Tell her the timing is genuinely hers to choose","then":"She exhales, like she needed permission to trust herself.","best":true},{"text":"Tell her not to overthink one comment","then":"She feels dismissed rather than actually heard."},{"text":"Agree that maybe sooner would be easier for everyone","then":"You end up repeating the very pressure you meant to counter."},{"text":"Change the subject to something lighter","then":"The doubt the aunty planted stays exactly where it was."}],"why":"Telling her the timing is hers undoes the doubt better than brushing it aside."},{"prompt":"At the next function, a different relative brings it up to your sister directly. What do you do?","options":[{"text":"Step in and back her up on the spot","then":"The relative backs off, and your sister squeezes your hand.","best":true},{"text":"Let her handle this one alone, so she can find her feet","then":"She manages a shaky answer, and looks for you across the room afterwards."},{"text":"Wait until after to tell her she should've said something","then":"She feels judged for staying quiet, not supported for what happened."},{"text":"Tell the relative to mind their own business, loudly","then":"The scene it creates becomes its own topic of gossip."}],"why":"Standing with her in the moment, calmly, shows she isn't facing the pressure alone."},{"prompt":"Months later, your sister tells you the comments have mostly stopped. What do you say?","options":[{"text":"Tell her you're proud of how she's held her own timing","then":"She smiles, and says it's easier now that she trusts herself.","best":true},{"text":"Warn her they'll probably start again eventually","then":"The warning dims a moment that was actually good news."},{"text":"Take most of the credit for how it went","then":"She feels a little smaller in a story that's actually hers."},{"text":"Say she should still be ready with an answer, just in case","then":"It keeps her braced for pressure that's actually eased."}],"why":"Crediting her own steadiness keeps the win hers, and keeps her trusting herself."}],"debrief":"Standing with a younger relative's right to choose helps break the pressure cycle.","relearn":"Back a younger relative's right to her own timing; break the pressure cycle."},
  {"id":"yp-922","cat":"childfree-complete","type":"branch","persona":"any","source":"a passing doubt","hook":"You're happily childfree, but a low day makes you wonder if you'll regret it.","steps":[{"prompt":"The doubt hits hardest late at night, scrolling old photos of cousins' kids. What do you do?","options":[{"text":"Put the phone down and sit with the feeling calmly","then":"The feeling softens once you stop feeding it with photos.","best":true},{"text":"Message a friend at midnight, hoping she'll decide for you","then":"She's kind and stays up with you, but she can't answer it for you, and the doubt stays."},{"text":"Decide right then that you must want a baby after all","then":"You wake up unsure why you decided anything at midnight."},{"text":"Keep scrolling to see if the feeling gets clearer","then":"It doesn't get clearer, just heavier."}],"why":"A calm pause lets you tell a passing feeling apart from an actual change of mind."},{"prompt":"The next morning, the doubt has mostly faded, but a trace remains. What do you do?","options":[{"text":"Reflect quietly on what you actually want, away from the noise","then":"You realise the choice still feels right in daylight.","best":true},{"text":"Announce to your partner that you've changed your mind","then":"Your partner takes it seriously, and a big talk starts over a feeling that has mostly faded."},{"text":"Push the trace of doubt away without looking at it","then":"It lingers at the back of your mind all week, unexamined."},{"text":"Search online for stories of people who regretted this","then":"The stories are written to alarm, and you close the tab more unsettled."}],"why":"A quiet, private reflection tells you more than a midnight search or a sudden announcement would."},{"prompt":"A week later, a friend mentions she had a similar low day about her own choice to have kids. What do you say?","options":[{"text":"Tell her a passing doubt doesn't undo a real decision","then":"She nods, relieved someone else has felt the same wobble.","best":true},{"text":"Say her doubt sounds more serious than yours was","then":"She feels compared instead of understood."},{"text":"Avoid the topic since it stirs your own doubt back up","then":"You lose a chance to compare notes with someone who gets it."},{"text":"Suggest she reconsider her whole decision over it","then":"She spends the week second guessing a choice that wasn't shaky."}],"why":"Telling her a wobble isn't a verdict helps her, whichever path she chose."}],"debrief":"A passing doubt deserves calm reflection, not a fear-driven reversal; check in with yourself.","relearn":"Meet a passing doubt with calm reflection, not a fear-driven reversal."},
  {"id":"yp-923","cat":"childfree-complete","type":"branch","persona":"any","source":"unfair to husband","hook":"A neighbour says it's 'unfair to your husband' to deny him fatherhood.","steps":[{"prompt":"She says it again over the boundary wall, within his earshot. What do you do?","options":[{"text":"Say this was a decision you both made together","then":"She looks between you two, unsure what to add.","best":true},{"text":"Apologise to your husband later for 'costing him' fatherhood","then":"He's confused, since he never felt that way at all."},{"text":"Ignore her and go back inside","then":"She repeats the comment to another neighbour that same week."},{"text":"Argue with her over the wall","then":"The argument becomes the story the street repeats, not the point."}],"why":"Naming it as a joint decision centres the two people who actually share the choice."},{"prompt":"That evening your husband asks if comments like that ever bother you. What do you say?","options":[{"text":"Admit they sting sometimes, and ask how he feels","then":"He says the comment bothers him too, on your behalf.","best":true},{"text":"Say they don't bother you at all","then":"He can't tell if you're being brave or just avoiding the question."},{"text":"Say they're clearly about him, not you","then":"He feels put on the spot for someone else's comment."},{"text":"Suggest you both just avoid that neighbour going forward","then":"Avoiding her doesn't stop the same idea reaching you elsewhere."}],"why":"Being honest with each other keeps outside opinions from quietly working between you."},{"prompt":"Months later, the neighbour mentions it again at a building function. What do you do?","options":[{"text":"Calmly say it's a decision you both made together","then":"She finally seems to accept it and doesn't raise it again.","best":true},{"text":"Let your husband answer for both of you, and say nothing","then":"He answers well, but she still treats you as the one holding him back."},{"text":"Avoid the function next year to dodge her","then":"Avoiding it doesn't change what she thinks, just what you hear."},{"text":"Snap that she's the last person who should comment","then":"The function turns tense, and the building talks about the argument for weeks."}],"why":"Calmly naming it a joint decision answers her without turning the function into a scene."}],"debrief":"A childfree choice made together is the couple's; outsiders don't get a vote.","relearn":"A childfree choice made together is the couple's; outsiders get no vote."},
  {"id":"yp-924","cat":"childfree-complete","type":"branch","persona":"any","source":"your body your call","hook":"You want a permanent contraception procedure. A relative calls it a 'sin against the family'.","steps":[{"prompt":"She says it at a family lunch, loud enough for the table. What do you do?","options":[{"text":"Say plainly it's your body and your considered choice","then":"The table goes quiet, then someone changes the subject.","best":true},{"text":"Say you'll 'think about it' to end the argument","then":"She takes that as hesitation, and mentions it to the rest of the family anyway."},{"text":"Defend the decision with every medical detail you have","then":"She isn't actually asking for information, and repeats the line."},{"text":"Leave the lunch without responding","then":"She tells the rest of the family her version of the story."}],"why":"Naming it plainly as your own medical choice ends the debate without inviting a vote on it."},{"prompt":"Your mother calls that night, worried about what was said. What do you say?","options":[{"text":"Reassure her the decision stands, and it's yours to make","then":"She's relieved to hear you sound so sure of it.","best":true},{"text":"Tell her you might reconsider, just to calm her down","then":"She holds onto that as real hope and brings it up again."},{"text":"Get frustrated that she's calling about it at all","then":"The call ends tense, though she was only checking in."},{"text":"Avoid her calls for a while","then":"She worries more, not less, in the silence."}],"why":"A clear, warm reassurance settles her worry without reopening a decision you've already made."},{"prompt":"At the clinic, a staff member asks, almost casually, if your family 'approves'. What do you say?","options":[{"text":"Say it's your own considered decision either way","then":"The staff member nods and walks you through the clinic's own process.","best":true},{"text":"Say your family fully approves, even though they don't","then":"The small lie sits oddly with you the whole appointment."},{"text":"Get defensive with the staff for asking at all","then":"The appointment starts on an unnecessarily tense note."},{"text":"Hesitate, unsure if you need their approval after all","then":"You almost let a stranger's question shake a settled decision."}],"why":"Your family's approval isn't needed. You bring your own clear, considered decision."}],"debrief":"A contraception decision is a private, autonomous medical choice; no one else's verdict overrides it.","relearn":"A contraception decision is your private, autonomous medical choice."},
  {"id":"yp-925","cat":"childfree-complete","type":"branch","persona":"any","source":"you're next","hook":"At a baby shower, guests keep pushing you to 'be next'.","steps":[{"prompt":"Three women corner you near the cake table with the same line. What do you do?","options":[{"text":"Laugh it off lightly and steer back to the host","then":"The group turns back to admiring the baby gifts.","best":true},{"text":"Promise each of them you're 'thinking about it'","then":"Each one repeats that promise to someone else through the afternoon."},{"text":"Explain your actual plans in detail to end it","then":"It turns a party moment into a longer conversation than you wanted."},{"text":"Slip out to the kitchen to avoid the group","then":"One of them follows, cake plate in hand, still asking."}],"why":"A light redirect keeps the celebration warm without opening a conversation you didn't choose."},{"prompt":"Later, the host asks if the comments got to you. What do you say?","options":[{"text":"Say they were a bit much, but you're fine","then":"She laughs, relieved, and the party stays easy for both of you.","best":true},{"text":"Say they ruined the afternoon","then":"The host feels responsible for something outside her control."},{"text":"Say nothing, not wanting to make it her problem","then":"She senses something's off and worries she missed it happening."},{"text":"Vent about every comment in detail","then":"The venting takes over a conversation that was meant to be about her baby."}],"why":"A light, honest answer keeps your boundary intact and the day about the person it's for."},{"prompt":"At the next baby shower, the same group spots you across the room. What do you do?","options":[{"text":"Give a light, easy deflection","then":"They laugh along, and the room moves on to the games.","best":true},{"text":"Avoid baby showers altogether from now on","then":"You miss celebrating people you actually care about over three comments."},{"text":"Prepare a sharp comeback in advance, just in case","then":"The sharp line gets a gasp, and the host looks over, worried."},{"text":"Bring a partner along specifically to deflect for you","then":"The questions find you anyway, the moment you're alone for a minute."}],"why":"A light line ready in your pocket lets you enjoy the next shower without dodging anyone."}],"debrief":"A light deflection lets you keep your boundary and the celebration without a confrontation.","relearn":"Deflect 'you're next' lightly; keep your boundary and the good mood."},
  {"id":"yp-926","cat":"childfree-complete","type":"branch","persona":"any","source":"not a deadline","hook":"You're unsure about kids. Your partner wants a firm yes or no by this month.","steps":[{"prompt":"He brings up the deadline again over breakfast. What do you do?","options":[{"text":"Ask for an honest talk and real time, not a deadline","then":"He pauses, then says he hadn't meant it to feel like a test, and agrees to talk.","best":true},{"text":"Say a fake 'yes' to stop the pressure","then":"He's relieved for a day, but the fake yes starts to feel wrong to you both."},{"text":"Say a fake 'no' to close the question fast","then":"He accepts it quietly, though he keeps glancing at you as if he doesn't quite believe it."},{"text":"Leave for work early to avoid the topic","then":"The deadline he mentioned still sits there when you get home."}],"why":"Asking for real time over a rushed deadline keeps the decision genuine for both of you."},{"prompt":"A few days on, he says the deadline came from his own anxiety, and asks how you really feel. What do you do?","options":[{"text":"Thank him for saying so, and agree to talk without a clock","then":"The pressure in the room actually lifts, for both of you.","best":true},{"text":"Point out he still shouldn't have set a deadline at all","then":"He hears blame instead of the honest talk you were both aiming for."},{"text":"Use his admission to avoid the topic completely now","then":"The actual decision still hasn't moved. Only the deadline has."},{"text":"Agree, but quietly set a deadline of your own","then":"You just replace his pressure with a quieter version of your own."}],"why":"Naming the real feeling behind the deadline lets you both actually talk, instead of racing a clock."},{"prompt":"A month later, you check in with each other again. What do you do?","options":[{"text":"Say honestly where you're at, even if it's 'not sure'","then":"He says he's still unsure too, and it's a relief to hear it's mutual.","best":true},{"text":"Feel you should have made progress by now, clock or not","then":"You invent a sense of urgency neither of you actually needed."},{"text":"Keep the check in to small talk, since nothing's changed","then":"Skipping the real talk starts to feel like its own kind of answer."},{"text":"Push for a decision now that a month has passed","then":"It brings back the very clock that was causing the pressure."}],"why":"An honest check in, even with no answer yet, keeps you both talking instead of guessing."}],"debrief":"A genuine 'I'm not sure yet' deserves real time and honest talk, not a forced deadline.","relearn":"Honest uncertainty deserves real time and talk, not a snap deadline."},
  {"id":"yp-927","cat":"childfree-complete","type":"branch","persona":"any","source":"can't die in peace","hook":"You've chosen not to have children, and your mother says she can't die in peace until she sees your child.","steps":[{"prompt":"She says it again at Sunday lunch, her voice heavy with feeling. What do you do?","options":[{"text":"Tell her you love her, and your choice still stands","then":"She's quiet for a moment, then nods, though her eyes stay sad.","best":true},{"text":"Promise to 'think about it seriously' to comfort her","then":"Her face lights up with real hope, though she sees you've gone very quiet."},{"text":"Leave the table, unable to sit with the guilt of it","then":"She stares at your empty chair, more worried than before, not less."},{"text":"Point out the comment isn't fair to say","then":"She feels criticised on top of already feeling unheard."}],"why":"Holding both the love and the boundary together answers her without abandoning either."},{"prompt":"That night she calls, softer now, asking if you're upset with her. What do you say?","options":[{"text":"Say the moment was hard, but you're not upset with her","then":"She sounds relieved, and the call ends warmer than it started.","best":true},{"text":"Apologise for upsetting her with your choice","then":"She says there's nothing to apologise for, but you hang up feeling you backed down."},{"text":"Reassure her without addressing the actual comment","then":"The reassurance smooths the moment but leaves the real thing unsaid."},{"text":"Let the call go to voicemail","then":"She worries more overnight, unsure where things stand."}],"why":"Saying the moment was hard, while telling her you're not upset, keeps the relationship steady."},{"prompt":"A cousin later tells you your mother has been saying the line to relatives too. What do you do?","options":[{"text":"Talk to your mother directly about how that lands on you","then":"She's quiet for a moment, then says she didn't realise how far it had spread.","best":true},{"text":"Ask the cousin to tell your mother to stop instead","then":"The message gets diluted, and she never really hears it from you."},{"text":"Let it go, since it's 'just how she talks'","then":"The line keeps circulating, and more relatives repeat it back to you."},{"text":"Stop visiting for a while to avoid the topic","then":"The distance worries her more, and the comment keeps making the rounds."}],"why":"A direct, honest conversation with her reaches the source, rather than working around it."},{"prompt":"At her next birthday, she doesn't mention it at all, but looks a little sad during the toasts. What do you do?","options":[{"text":"Sit with her after, and let her be sad without fixing it","then":"She leans into you, and the sadness passes without turning into pressure.","best":true},{"text":"Cheer her up quickly so the sadness doesn't linger","then":"The sadness gets pushed down rather than actually felt through."},{"text":"Bring up the earlier conversation again to check she's okay","then":"It reopens a topic she was actually managing to let rest."},{"text":"Avoid her for the rest of the party, unsure what to say","then":"She notices you keeping your distance, and it adds a new quiet weight to the evening."}],"why":"Letting her feel what she feels, without needing to fix it, respects both her and your boundary."},{"prompt":"Years later, she brings it up one last time, gently, almost as a joke. What do you do?","options":[{"text":"Smile, and say the love and the choice both still stand","then":"She laughs softly and says she had to try one more time.","best":true},{"text":"Get frustrated it's come up again after all this time","then":"The frustration lands harder than the moment, which was mostly wistful."},{"text":"Finally give in, tired of hearing it after years","then":"You end up making a decision out of fatigue, not out of wanting it."},{"text":"Avoid answering and hope she drops it","then":"She's left unsure if anything's actually changed after all these years."}],"why":"A smile that keeps both the love and the choice lets her tease without reopening it."}],"debrief":"You can love your mother and still keep a childfree boundary; guilt isn't a reason.","relearn":"You can love family AND keep your childfree boundary; guilt isn't a reason."},
  {"id":"yp-928","cat":"childfree-complete","type":"branch","persona":"any","source":"online noise","hook":"Online, a stranger calls childfree women 'a danger to the nation'. It rattles you for a second.","steps":[{"prompt":"The comment sits there, dozens of replies piling on. What do you do?","options":[{"text":"Close the comment; a slogan isn't a truth about you","then":"You put the phone down, and the rattled feeling passes within minutes.","best":true},{"text":"Read every reply to see how bad it gets","then":"The rattled feeling grows with every angry reply you read."},{"text":"Reply to argue your case","then":"The argument spirals, and you're still typing an hour later."},{"text":"Screenshot it and send it to your friends, upset","then":"Two friends reply with their own outrage, and the thread keeps growing before you've calmed down."}],"why":"Closing the tab keeps a stranger's slogan from turning into a verdict on your actual life."},{"prompt":"That evening, a friend asks how you're feeling about the noise online. What do you say?","options":[{"text":"Wonder aloud whether they might have a point","then":"She looks surprised, and the stranger's line follows you around all evening."},{"text":"Say honestly how it felt, and that it's just noise","then":"She agrees, and you both laugh at the 'danger to the nation' line.","best":true},{"text":"Say you barely noticed it","then":"She raises an eyebrow, and the comment stays with you longer than you admitted."},{"text":"Ask her to send you every other post like it","then":"You end up deep in the replies long after she's logged off."}],"why":"Being honest about how it felt, while calling it noise, keeps the slogan in its place."},{"prompt":"Weeks later, a similar post goes around again, with the same kind of line. What do you do?","options":[{"text":"Scroll past without opening it","then":"It barely registers this time, just another post in a feed.","best":true},{"text":"Open it to see if this one's different","then":"It's the same noise in different words, and it still stings a little."},{"text":"Write a long post defending childfree life in response","then":"It gets a mix of support and more of the same hostility."},{"text":"Mute the whole topic, including supportive posts about it","then":"You lose sight of the people actually agreeing with you too."}],"why":"Scrolling past gives a hostile slogan none of your time, so it loses its pull."}],"debrief":"A hostile stranger's slogan is noise, not a verdict on your life; you can let it pass.","relearn":"A stranger's slogan is noise, not a truth about your childfree life."},
  {"id":"yp-929","cat":"childfree-complete","type":"branch","persona":"any","source":"reach for support","hook":"Family conflict over your childfree choice has turned constant, and it's leaving you distressed.","steps":[{"prompt":"After another tense call, you notice you're dreading your phone ringing. What do you do?","options":[{"text":"Reach out to a counsellor or a trusted person for support","then":"Just saying it out loud to someone outside the family helps you breathe.","best":true},{"text":"Believe a 'family matter' should be handled without outside help","then":"The dread keeps building, with nowhere for it to go."},{"text":"Tell yourself you must be the one causing all this trouble","then":"You spend the week questioning a choice that was never the problem."},{"text":"Cut off the whole family at once","then":"The sudden silence brings its own stress, and word still reaches you through a cousin."}],"why":"Reaching out for support helps more than carrying it alone; this pressure was never something you caused."},{"prompt":"By the weekend, a friend notices you've been quiet and asks what's going on. What do you say?","options":[{"text":"Tell her honestly, including how tired it's making you","then":"She listens, then says that sounds like a lot to carry alone.","best":true},{"text":"Say you're fine, just tired from work","then":"She lets it go, though the exhaustion underneath doesn't."},{"text":"Downplay it as 'just family drama'","then":"She has no idea how much it's actually wearing you down."},{"text":"Turn it into a rant about how awful your family is","then":"She listens kindly, but the talk stays on blaming them, not on what you need."}],"why":"An honest account of the toll lets someone who cares actually see what's wearing you down."},{"prompt":"A few weeks on, someone in the family gets in touch, and the talk turns tense again. What do you do?","options":[{"text":"Reach out to a counsellor or trusted person afterward","then":"The call is hard, but you have somewhere to bring it afterward now.","best":true},{"text":"Assume by now this should be easier to handle","then":"You judge yourself against a timeline that was never realistic."},{"text":"Try to handle this call completely alone this time","then":"The dread from before starts creeping back in."},{"text":"Assume you just need to try harder to keep the peace","then":"You take on more of the emotional weight, and nothing about the pattern changes."}],"why":"Needing support again is a strength, not a sign you should be coping alone by now."}],"debrief":"When family conflict over your choice turns distressing, reach for a counsellor or trusted person; the conflict isn't something you caused.","relearn":"If conflict over your choice turns distressing, reach for support."},
  {"id":"yp-930","cat":"childfree-complete","type":"reflect","hook":"Lensy: womanhood and motherhood are not the same thing. How does that land for you?","prompt":"What feels true to you?","options":["They're separate","I'm whole either way","Mine to decide"],"affirm":"Womanhood isn't motherhood; you are a whole woman whether or not you ever have a child.","relearn":"Womanhood isn't motherhood; you're whole either way.","persona":"any","source":"whole either way"},
  {"id":"yp-931","cat":"childfree-complete","type":"reflect","hook":"Lensy: 'you'll change your mind' is a guess about your future, not a fact. Sit right with you?","prompt":"What do you make of it?","options":["I know myself","It's their guess","Could change, my call"],"affirm":"You're the authority on your own life; whether you change is yours to discover, not theirs to decree.","relearn":"You're the authority on your own life; 'you'll change your mind' is a guess.","persona":"any","source":"my future my call"},
  {"id":"yp-932","cat":"childfree-complete","type":"reflect","hook":"Lensy: a life can brim with love and purpose without a single child in it. Thoughts?","prompt":"What rings true?","options":["Full of love","Purpose, many sources","Meaning is plural"],"affirm":"A childfree life can hold all the love, purpose and meaning anyone could want; it's complete as it is.","relearn":"A childfree life can be full of love, purpose and meaning.","persona":"any","source":"full and complete"},
  {"id":"yp-933","cat":"childfree-complete","type":"reflect","hook":"Lensy: you don't owe anyone an explanation for not having children. How does that feel?","prompt":"Which lands?","options":["No explanation owed","It's private","Relief"],"affirm":"Your reasons are yours alone; a calm 'we've decided not to' is a complete answer that needs no defence.","relearn":"You owe no one an explanation for not having children.","persona":"any","source":"no explanation owed"},
  {"id":"yp-934","cat":"childfree-complete","type":"reflect","hook":"Lensy: being honestly unsure about kids is allowed; you owe no one instant certainty. Thoughts?","prompt":"What sits right?","options":["Unsure is okay","No rush","My pace"],"affirm":"You can sit honestly with 'I'm not sure', for as long as you need; uncertainty isn't a fault to fix today.","relearn":"You can be honestly unsure about children; you owe no instant certainty.","persona":"any","source":"unsure is allowed"},
  {"id":"yp-935","cat":"childfree-complete","type":"reflect","hook":"Lensy: one child, a few, or none, each can be right for a different person. Where do you land?","prompt":"What feels true?","options":["None is valid","All are valid","Right for me"],"affirm":"One, several or none can all be right; the only question that matters is what's right for you.","relearn":"One child, several, or none can all be right for different people.","persona":"any","source":"all numbers valid"},
  {"id":"yp-936","cat":"childfree-complete","type":"reflect","hook":"Lensy: your worth was never tied to whether you become a parent. How does that sit?","prompt":"Which feels true?","options":["Worth isn't parenthood","Whole as I am","Always was mine"],"affirm":"Your worth is whole and yours, parent or not; nothing about a child adds to or subtracts from it.","relearn":"Your worth was never tied to becoming a parent.","persona":"any","source":"worth isn't parenthood"},
  {"id":"yp-937","cat":"childfree-complete","type":"sort","hook":"Sort: respects a childfree choice, or pressures against it?","items":[{"id":"a","text":"\"It's completely your decision to make\""},{"id":"b","text":"\"You'll regret it when you're old\""},{"id":"c","text":"\"Whatever you two feel is right\""},{"id":"d","text":"\"A real family needs children\""},{"id":"e","text":"\"I trust you know your own life\""},{"id":"f","text":"\"Just have one, you'll see\""}],"bins":[{"id":"respects","label":"Respects","valence":"pos"},{"id":"pressures","label":"Pressures","valence":"neg"}],"key":{"a":"respects","b":"pressures","c":"respects","d":"pressures","e":"respects","f":"pressures"},"relearn":"Lines that leave the choice with you respect it; 'you'll regret it' and 'just have one' pressure.","persona":"any","source":"respect vs pressure two"},
  {"id":"yp-938","cat":"childfree-complete","type":"sort","hook":"Sort: a real source of meaning in a life, or just the script talking?","items":[{"id":"a","text":"Work you care about"},{"id":"b","text":"\"Only a baby makes life worthwhile\""},{"id":"c","text":"Deep friendships and chosen family"},{"id":"d","text":"\"You're not a real woman until you're a mother\""},{"id":"e","text":"Causes and community you give to"},{"id":"f","text":"\"An empty house means an empty life\""}],"bins":[{"id":"real","label":"Real meaning","valence":"neutral"},{"id":"script","label":"Just the script","valence":"uhoh"}],"key":{"a":"real","b":"script","c":"real","d":"script","e":"real","f":"script"},"relearn":"Work, friendship and community are real sources of meaning; 'only a baby' lines are the script.","persona":"any","source":"meaning vs script"},
  {"id":"yp-939","cat":"childfree-complete","type":"sort","hook":"Sort: yours to decide privately, or not anyone else's call?","items":[{"id":"a","text":"Whether you have a child"},{"id":"b","text":"What aunty thinks you should do"},{"id":"c","text":"When, if ever, you'd want kids"},{"id":"d","text":"A neighbour's opinion on your choices"},{"id":"e","text":"How you and your partner plan your family"},{"id":"f","text":"What the relatives gossip about"}],"bins":[{"id":"yours","label":"Yours to decide","valence":"neutral"},{"id":"notyours","label":"Not their call","valence":"uhoh"}],"key":{"a":"yours","b":"notyours","c":"yours","d":"notyours","e":"yours","f":"notyours"},"relearn":"The decision and its timing are yours; relatives' opinions and gossip aren't your obligation.","persona":"any","source":"yours vs theirs"},
  {"id":"yp-940","cat":"childfree-complete","type":"sort","hook":"Sort: this answer holds your boundary, or hands the decision away?","items":[{"id":"a","text":"\"We've decided not to, and we're happy\""},{"id":"b","text":"\"Okay, fine, we'll have one if you insist\""},{"id":"c","text":"\"That's a private decision for us\""},{"id":"d","text":"\"You decide, you all know better\""},{"id":"e","text":"\"This one's settled, let's move on\""},{"id":"f","text":"\"Maybe, if it'll stop the nagging\""}],"bins":[{"id":"holds","label":"Holds your line","valence":"pos"},{"id":"hands","label":"Hands it away","valence":"neg"}],"key":{"a":"holds","b":"hands","c":"holds","d":"hands","e":"holds","f":"hands"},"relearn":"Calm, settled lines hold your boundary; 'fine, if you insist' or 'you decide' hand it away.","persona":"any","source":"holds vs hands"},
  {"id":"yp-941","cat":"childfree-complete","type":"sort","hook":"Sort: a fact about your worth, or imposed shame to let pass?","items":[{"id":"a","text":"You are whole exactly as you are"},{"id":"b","text":"\"A childless woman is incomplete\""},{"id":"c","text":"Your value isn't your fertility"},{"id":"d","text":"\"People will pity you forever\""},{"id":"e","text":"Your life is full and your own"},{"id":"f","text":"\"You've failed your duty as a wife\""}],"bins":[{"id":"truth","label":"True about you","valence":"pos"},{"id":"shame","label":"Imposed shame","valence":"neg"}],"key":{"a":"truth","b":"shame","c":"truth","d":"shame","e":"truth","f":"shame"},"relearn":"You're whole and your value isn't fertility; 'incomplete', 'pity' and 'failed duty' are imposed shame.","persona":"any","source":"worth vs shame"},
  {"id":"yp-942","cat":"childfree-complete","type":"sort","hook":"Sort: supports a friend's childfree choice, or quietly undermines it?","items":[{"id":"a","text":"\"Your life sounds full and happy\""},{"id":"b","text":"\"You'll feel differently, just wait\""},{"id":"c","text":"\"I'm glad you know what you want\""},{"id":"d","text":"\"But who'll look after you later?\""},{"id":"e","text":"\"However you build your family is great\""},{"id":"f","text":"\"Such a waste, you'd be a great mum\""}],"bins":[{"id":"supports","label":"Supports","valence":"pos"},{"id":"undermines","label":"Undermines","valence":"neg"}],"key":{"a":"supports","b":"undermines","c":"supports","d":"undermines","e":"supports","f":"undermines"},"relearn":"Validating her life supports her; 'just wait', 'who'll look after you' and 'such a waste' undermine it.","persona":"any","source":"support vs undermine"},
  {"id":"yp-964","cat":"childfree-complete","type":"sort","hook":"Sort: a calm boundary, or capitulating under pressure?","items":[{"id":"a","text":"\"I know you care, and this is our decision\""},{"id":"b","text":"\"Okay, we'll start trying, happy now?\""},{"id":"c","text":"\"Let's not make this a fight; it's settled\""},{"id":"d","text":"\"Whatever you all think is best\""},{"id":"e","text":"\"I love you, and the answer's still no\""},{"id":"f","text":"\"Fine, you win, we'll have one\""}],"bins":[{"id":"boundary","label":"Boundary","valence":"pos"},{"id":"caving","label":"Caving","valence":"neg"}],"key":{"a":"boundary","b":"caving","c":"boundary","d":"caving","e":"boundary","f":"caving"},"relearn":"Warm, firm lines set a boundary; 'happy now', 'you win' and 'whatever you think' are caving.","persona":"any","source":"boundary vs caving"},
  {"id":"yp-965","cat":"childfree-complete","type":"sort","hook":"Sort: an honest reason to consider a child, or pressure dressed as one?","items":[{"id":"a","text":"You both genuinely want to raise one"},{"id":"b","text":"To stop relatives gossiping"},{"id":"c","text":"You feel ready for it together"},{"id":"d","text":"To 'secure' a shaky marriage"},{"id":"e","text":"You've talked it through and want this"},{"id":"f","text":"Because everyone your age has one"}],"bins":[{"id":"honest","label":"Honest reason","valence":"neutral"},{"id":"pressure","label":"Pressure dressed up","valence":"uhoh"}],"key":{"a":"honest","b":"pressure","c":"honest","d":"pressure","e":"honest","f":"pressure"},"relearn":"Wanting to raise a child together is honest; gossip, 'securing' and 'everyone has one' are pressure.","persona":"any","source":"honest vs pressure reason"},
  {"id":"yp-943","cat":"childfree-complete","type":"role-play","persona":"any","source":"whole not incomplete","hook":"Your cousin Rahul has firm opinions on what your life is missing, and shares them often.","setup":"Today he's standing right in the kitchen doorway.","steps":[{"prompt":"Rahul says: \"You know you're incomplete without a baby, right?\"","options":[{"text":"\"I'm whole as I am. A child isn't what completes me.\"","then":"Rahul blinks, caught off guard for a second.","best":true},{"text":"\"I guess you're right. Something's missing.\"","then":"\"Exactly,\" he says, nodding like he's won the point."},{"text":"\"That's a really rude thing to say to someone, Rahul.\"","then":"\"I'm just being honest,\" he says, shrugging it off."},{"text":"\"Maybe. We'll see.\"","then":"\"That's the spirit,\" he says, taking it as an opening."}],"why":"Naming yourself whole, plainly, answers the claim instead of just reacting to the rudeness."},{"prompt":"At dinner, Rahul repeats it: \"Like I said, incomplete without a baby.\"","options":[{"text":"\"I don't agree. I'm complete as I am.\"","then":"Rahul shrugs and the table moves on to other things.","best":true},{"text":"\"Rahul, seriously, stop.\"","then":"\"I was just joking,\" he mutters, though he clearly wasn't."},{"text":"\"Can we not talk about this at the table?\"","then":"\"Fine,\" he says, though the comment sits there unanswered."},{"text":"\"Some people just don't get it.\"","then":"\"Excuse me?\" he says, hearing it as a jab back at him."}],"why":"A calm, plain disagreement shows it isn't a passing reaction. It's simply true."},{"prompt":"Your mother says quietly: \"He means well. He's just old fashioned.\"","options":[{"text":"\"Maybe, but the comment still isn't true.\"","then":"\"Fair,\" she says, and doesn't push back on that.","best":true},{"text":"\"It's fine. I know he doesn't mean it.\"","then":"\"Good,\" she says, relieved, though nothing's really been said."},{"text":"\"He should know better by now.\"","then":"\"He's trying,\" she says, sounding a little defensive of him."},{"text":"\"I don't want to make a whole thing of it.\"","then":"\"Probably wise,\" she says, relieved the topic's closing."}],"why":"Separating his intentions from the actual claim keeps a kind excuse from standing in for the truth."},{"prompt":"Months later, Rahul says, sheepishly: \"I've actually stopped saying that thing.\"","options":[{"text":"\"Thanks. What changed your mind?\"","then":"\"Seeing how full your life is,\" he says. \"It wasn't fair to say.\"","best":true},{"text":"\"Took you long enough.\"","then":"\"Fair,\" he says, the warmth of the moment fading a bit."},{"text":"\"I never even noticed, honestly.\"","then":"\"Oh,\" he says, a little deflated that it didn't register."},{"text":"\"Just don't start again.\"","then":"\"I won't,\" he says, though it lands more like a warning than thanks."}],"why":"Taking his change warmly, and asking why, lets him say what shifted in his own words."}],"relearn":"You're whole as you are; a child would be a choice, not what completes you."},
  {"id":"yp-944","cat":"childfree-complete","type":"role-play","persona":"any","source":"redirect the uncle","hook":"You and your partner have decided against kids, but an uncle won't stop asking about a baby.","setup":"He asks again between courses, fork mid air.","steps":[{"prompt":"Your uncle asks: \"So, when's the baby coming?\"","options":[{"text":"\"That's not on our cards, uncle, but tell me how your work's going.\"","then":"\"Oh, alright then,\" he says, launching happily into his work stories.","best":true},{"text":"\"Soon, soon. Stop asking.\"","then":"\"Good, good,\" he says, still grinning, clearly not done with the topic."},{"text":"\"That's a fairly personal question to be asking me at dinner, uncle.\"","then":"\"Just curious,\" he says, looking a little wounded."},{"text":"\"We're still figuring it out.\"","then":"\"Don't figure too long,\" he says, launching into advice you didn't ask for."}],"why":"A warm close plus a redirect ends the question without a fight or a false promise."},{"prompt":"Serving dessert, your uncle asks again: \"No news yet, then?\"","options":[{"text":"\"It's not on the cards, uncle, though this dessert looks great.\"","then":"\"Fine, fine,\" he laughs, taking a bite of the dessert himself.","best":true},{"text":"\"Uncle, I already answered that.\"","then":"\"Alright, alright,\" he says, looking a little scolded."},{"text":"\"Maybe one day, who knows.\"","then":"\"That's the spirit,\" he says, mistaking the maybe for real hope."},{"text":"\"Can we please not talk about this again, right at the table?\"","then":"\"Sorry, sorry,\" he says, though the actual answer never really lands."}],"why":"A warm, closed answer and a light change of topic end it without a scold or a maybe."},{"prompt":"Next dinner, before you've even sat down, your uncle asks: \"So? Anything to tell me?\"","options":[{"text":"\"Not on the cards, uncle. How's your garden doing?\"","then":"\"Blooming well, actually,\" he says, happily distracted for the rest of dinner.","best":true},{"text":"\"You really do ask me this every single time we get together.\"","then":"\"Just checking,\" he says, a little defensive now."},{"text":"\"Let's just skip it this time.\"","then":"\"Fair enough,\" he says, then circles back to it later in the meal."},{"text":"\"Ask my partner instead.\"","then":"He turns to your partner. \"Well, you tell me then?\" Your partner fumbles for an answer."}],"why":"A warm, closed answer plus a new topic gives him somewhere happier to go."}],"relearn":"Deflect the 'when's the baby' question warmly and redirect; you owe no timeline."},
  {"id":"yp-945","cat":"childfree-complete","type":"role-play","persona":"any","source":"every bit a woman","hook":"Your friend Kavya comes over, distraught about her choice not to have kids.","setup":"She's curled up on your couch, a cold cup of tea beside her.","steps":[{"prompt":"Kavya says, through tears: \"I feel like less of a woman for choosing this.\"","options":[{"text":"\"You're every bit a woman. Motherhood was never the price of that.\"","then":"She wipes her eyes. \"I needed to hear that, thank you.\"","best":true},{"text":"\"Well, it is what people expect.\"","then":"Kavya cries harder, hearing her fear confirmed instead of answered."},{"text":"\"Don't let other people's opinions get to you.\"","then":"\"I'm trying,\" she says, though the feeling underneath stays untouched."},{"text":"\"Maybe you'll change your mind eventually.\"","then":"\"Even you don't believe me,\" she says, crying harder."}],"why":"Naming her whole womanhood, directly, answers the fear instead of just soothing around it."},{"prompt":"A few minutes later, Kavya asks: \"Why does it still hurt so much?\"","options":[{"text":"\"Because the idea's everywhere, even though it isn't true.\"","then":"\"That actually makes sense,\" she says, sitting up a little straighter.","best":true},{"text":"\"Maybe you're not as settled in the choice as you think.\"","then":"\"Maybe not,\" she says, doubt creeping into a decision that wasn't the problem."},{"text":"\"It shouldn't hurt if you know it's not true.\"","then":"\"Sorry,\" she says, feeling judged for still hurting."},{"text":"\"It'll stop hurting eventually.\"","then":"\"I hope so,\" she says, still waiting for a feeling that hasn't actually shifted."}],"why":"Naming where the idea comes from separates it from any actual truth about her."},{"prompt":"The next week, Kavya says: \"A stranger's comment online brought it all back up.\"","options":[{"text":"\"That feeling isn't a fact. Remember what's actually true.\"","then":"\"Right,\" she says, sounding steadier than the week before.","best":true},{"text":"\"You should stop reading those comments.\"","then":"\"I know,\" she says, feeling blamed for having seen it."},{"text":"\"People online don't know what they're talking about.\"","then":"\"True,\" she says, though it doesn't quite reach how she's feeling."},{"text":"\"Try not to think about it too much.\"","then":"\"Okay,\" she says, though the feeling doesn't actually move."}],"why":"Separating the feeling from the facts helps her steady herself when the old idea resurfaces."}],"relearn":"Reassure a friend: motherhood was never the price of being a whole woman."},
  {"id":"yp-946","cat":"childfree-complete","type":"role-play","persona":"any","source":"at peace with it","hook":"You're settled on being childfree, but your partner Dev keeps circling back to it.","setup":"He speaks gently, after a long quiet moment.","steps":[{"prompt":"Dev asks: \"What if you regret this someday?\"","options":[{"text":"\"I've thought hard about this. It's a real choice I'm at peace with.\"","then":"He nods slowly. \"Okay. That actually helps to hear.\"","best":true},{"text":"\"Maybe you're right. Let's just have one then.\"","then":"\"Wait, do you mean that?\" he asks, startled."},{"text":"\"Don't worry about it so much.\"","then":"\"I can't really help it,\" he says, still worried."},{"text":"\"You're really the one who should be more sure about this, not me.\"","then":"\"That's not fair,\" he says, caught off guard by the redirect."}],"why":"Naming the choice as considered and settled answers his real worry, not just his words."},{"prompt":"A few days later, Dev asks again, a little more worried: \"Are you really sure, though?\"","options":[{"text":"\"I understand why you're asking. Let's talk about it again, honestly.\"","then":"\"Okay,\" he says. \"I just needed to ask again.\"","best":true},{"text":"\"We already talked about this.\"","then":"\"Sorry,\" he says, feeling shut down rather than heard."},{"text":"\"Fine, if it will actually make you feel better, we can reconsider it.\"","then":"\"Wait, really?\" he says, hearing an opening that wasn't meant."},{"text":"\"Why do you keep asking the same thing?\"","then":"He goes quiet, unsure if it's safe to keep asking."}],"why":"Letting him ask again, without punishing the asking, answers the worry underneath it."},{"prompt":"Months later, Dev says: \"I don't worry about it the way I used to.\"","options":[{"text":"\"I'm glad. Thanks for telling me about the worry.\"","then":"\"Yeah,\" he smiles. \"It feels solid now, for both of us.\"","best":true},{"text":"\"Well, I knew it eventually would.\"","then":"\"I guess,\" he says, the moment landing more like a win than a relief."},{"text":"\"Good, now we don't have to talk about it anymore.\"","then":"\"Sure,\" he says, though it feels like the door's shutting a bit fast."},{"text":"\"I never worried, so that's on you.\"","then":"\"Thanks,\" he says flatly, feeling a little alone in that worry."}],"why":"Thanking him for voicing the worry keeps it safe for him to bring things to you."}],"relearn":"Affirm a considered childfree choice as real and settled, not a whim."},
  {"id":"yp-947","cat":"childfree-complete","type":"role-play","persona":"any","source":"not a debt","hook":"An older relative who has always helped your family has strong views on your future.","setup":"Today, over tea, she finally says what she means.","steps":[{"prompt":"Your relative says: \"After everything we spent raising you, you owe us a grandchild.\"","options":[{"text":"\"I'm grateful. A child isn't a debt I owe.\"","then":"She's quiet a moment, though her expression doesn't fully soften.","best":true},{"text":"\"You're right. I suppose I owe you that.\"","then":"\"Good, glad you understand,\" she says, and mentions it to your mother."},{"text":"\"That's a strange way to talk about family.\"","then":"\"I'm only being honest,\" she says, getting defensive."},{"text":"\"I never asked you to spend all that.\"","then":"\"That's not the point,\" she says, and the argument shifts to money."}],"why":"Naming gratitude and the choice separately answers the guilt without denying what she did for you."},{"prompt":"That evening, having heard about tea, your mother asks: \"Do you feel you owe us too?\"","options":[{"text":"\"I'm grateful for all of it. A child isn't the repayment.\"","then":"Your mother is quiet, then says softly, \"No. I suppose it isn't.\"","best":true},{"text":"\"Maybe I do. I just don't know how I'd ever repay it.\"","then":"\"Don't talk like that,\" she says, though she doesn't disagree."},{"text":"\"Honestly, it feels like everyone's keeping score.\"","then":"Her face tightens. \"No one's keeping score, beta. We love you.\""},{"text":"\"Let's not get into it. It'll only upset everyone.\"","then":"\"Then when?\" she asks, and the question hangs between you."}],"why":"Holding gratitude and the choice apart answers her honestly, without guilt or blame."},{"prompt":"Before Sunday lunch with the relatives, your mother asks quietly: \"Can we please keep today calm?\"","options":[{"text":"\"I'll stay calm. I just won't agree I owe her a child.\"","then":"Your mother relaxes a little. \"That's fair. That's all I'm asking.\"","best":true},{"text":"\"Is she still upset about the grandchild thing?\"","then":"\"A little,\" your mother says, \"but please, not today.\""},{"text":"\"Don't worry. I'll just nod along with whatever she says.\"","then":"\"Thank you,\" she sighs, and at lunch your nods get taken as a promise."},{"text":"\"Maybe I should bring it up first, to clear the air.\"","then":"\"Please don't,\" your mother says. \"Let's just eat.\""}],"why":"Promising calm while holding your answer respects your mother's wish and your own choice."}],"relearn":"You can be grateful and still owe no one a grandchild as a debt."},
  {"id":"yp-948","cat":"childfree-complete","type":"role-play","persona":"any","source":"two is a family","hook":"Your childfree marriage draws comments at every family function.","setup":"A distant relative says it, half joking, at a cousin's function.","steps":[{"prompt":"Your relative says: \"Just the two of you? That's not really a family, is it?\"","options":[{"text":"\"The two of us are a real family. We don't need a third person to count.\"","then":"\"Fair point,\" she says, a little surprised by how direct that was.","best":true},{"text":"\"I suppose it's not, really.\"","then":"\"Right,\" she says, feeling her comment confirmed."},{"text":"\"That's a rude thing to say.\"","then":"\"I'm only saying what people think,\" she says, getting defensive."},{"text":"\"Well, maybe we will end up having kids eventually, once we're ready.\"","then":"\"There you go,\" she says, taking that as the real, better answer."}],"why":"Naming your household a real family, plainly, answers the idea, not just the tone."},{"prompt":"Your partner asks later: \"How'd that comment land with you?\"","options":[{"text":"\"It stung for a second, but I know we're a real family regardless.\"","then":"\"Good,\" they say, \"because I've never doubted we're a family.\"","best":true},{"text":"\"It was nothing. Let's not talk about it.\"","then":"\"Okay,\" they say, though they can tell something is left unsaid."},{"text":"\"It made me wonder if she's right that we're not a real family.\"","then":"\"Wait, really?\" they ask, sounding unsettled."},{"text":"\"People say things like that to us all the time, honestly speaking.\"","then":"\"Sure,\" they say, though the specific comment goes unaddressed."}],"why":"Saying honestly how it landed, and that you know you're a real family, reassures your partner."},{"prompt":"At a different function, another relative says: \"Just the two of you, still? No family plans?\"","options":[{"text":"\"We're a real family, just the two of us, and that's enough.\"","then":"\"Never thought of it that way, but sure,\" he says, and drops it.","best":true},{"text":"\"You're actually the second person to say that to me this month.\"","then":"\"Oh, sorry,\" he says, though the actual point stays unmade."},{"text":"\"Whatever you say.\"","then":"\"Right,\" he says, taking the shrug as agreement."},{"text":"\"Some people just don't get it.\"","then":"\"Excuse me?\" he says, hearing it as a jab rather than an answer."}],"why":"A clear, warm line answers the new relative without a jab, a shrug or a complaint."},{"prompt":"Months later, the first relative says: \"I've been thinking about what I said before.\"","options":[{"text":"\"I appreciate that. Thanks for saying so.\"","then":"\"Family's just who you build it with. I realise that now,\" she says.","best":true},{"text":"\"Took you long enough to figure that out.\"","then":"\"Fair,\" she says, the moment losing some of its warmth."},{"text":"\"I don't really remember that comment.\"","then":"\"Oh,\" she says, unsure whether her apology even landed."},{"text":"\"You should be more careful what you say to people.\"","then":"\"I know,\" she says, the genuine rethink turning into a lecture instead."}],"why":"Accepting her rethink warmly lets the change stick, instead of turning it into a lecture."}],"relearn":"Two people who choose each other are a real, complete family."},
  {"id":"yp-949","cat":"childfree-complete","type":"role-play","persona":"any","source":"not selfish say","hook":"A colleague keeps making pointed comments about your choice not to have kids.","setup":"He says it over lunch, in the office kitchen.","steps":[{"prompt":"Your colleague says: \"People who don't have kids are pretty selfish, honestly.\"","options":[{"text":"\"Deciding honestly about having kids is responsible, not selfish.\"","then":"He pauses. \"Huh. Hadn't thought of it that way.\"","best":true},{"text":"\"Maybe we are a bit selfish.\"","then":"\"See, I knew it,\" he says, feeling his point proven."},{"text":"\"You're one to talk.\"","then":"\"What's that supposed to mean?\" he says, turning personal."},{"text":"\"That's a genuinely offensive thing to say to any colleague, honestly speaking.\"","then":"\"I'm just being honest,\" he says, getting defensive about the tone."}],"why":"Naming the honest decision as responsible answers the claim directly, without matching his tone."},{"prompt":"The next day, half joking, he says: \"Still selfish, if you ask me.\"","options":[{"text":"\"I thought it through honestly. That isn't selfish.\"","then":"\"Fair enough,\" he shrugs, and actually seems to drop it this time.","best":true},{"text":"\"Can we not talk about this again?\"","then":"\"Touchy subject, huh,\" he says, taking the discomfort as a sign."},{"text":"\"Whatever helps you sleep at night.\"","then":"\"Ouch,\" he says, the jab landing harder than intended."},{"text":"\"Some people just aren't cut out for parenting, I guess.\"","then":"\"Exactly,\" he says, hearing it as agreement with his framing."}],"why":"A calm, plain answer shows his joke doesn't change the facts, without matching his jab."},{"prompt":"Weeks later, he admits: \"Honestly, that comment came from my own mother's pressure on me.\"","options":[{"text":"\"That makes sense. This isn't really about us at all, then.\"","then":"\"Yeah,\" he admits. \"I think I was just repeating her.\"","best":true},{"text":"\"So you already knew that it wasn't even true, all along.\"","then":"\"I guess,\" he says, feeling caught out."},{"text":"\"That explains a lot about you.\"","then":"\"Thanks a lot,\" he says, the moment turning into judging him."},{"text":"\"Well, at least you admitted it.\"","then":"\"Sure,\" he says, the moment feeling more like a win than an understanding."}],"why":"Seeing where his comment came from turns a jab into understanding, without scoring a point."}],"relearn":"Deciding honestly about parenthood is responsible, not selfish."},
  {"id":"yp-950","cat":"childfree-complete","type":"role-play","persona":"any","source":"her timing","hook":"Your sister Ritu is under pressure from her in-laws about starting a family.","setup":"She mentions it quietly, unsure what to think.","steps":[{"prompt":"Ritu says: \"They think I should hurry up so my marriage stays secure.\"","options":[{"text":"\"Your timing is yours. No baby has to 'secure' anything.\"","then":"She looks relieved. \"I needed someone to say that plainly.\"","best":true},{"text":"\"Better do it quickly, like they say.\"","then":"\"Right,\" she says quietly, the pressure settling back in."},{"text":"\"That's a really old fashioned way to think.\"","then":"\"Maybe,\" she says, still feeling just as pressured."},{"text":"\"Just ignore them. They really don't know anything about your marriage.\"","then":"\"Easier said than done,\" she says, since she sees them weekly."}],"why":"Naming that her timing is hers answers the actual fear, not just the outdated idea behind it."},{"prompt":"A week later, Ritu calls, anxious: \"My mother in law brought it up again.\"","options":[{"text":"\"How are you feeling about it, really?\"","then":"\"Honestly, scared I'll lose the marriage over timing,\" she admits.","best":true},{"text":"\"You already know what I think.\"","then":"\"I guess,\" she says, sounding a little dismissed."},{"text":"\"Tell her to mind her own business.\"","then":"\"I can't really say that to her,\" Ritu says, feeling unheard."},{"text":"\"Maybe just have a baby sooner to keep the peace.\"","then":"\"Really?\" she says, surprised to hear the pressure from you too."}],"why":"Asking how she really feels opens the actual fear, and none of this is her fault."},{"prompt":"Months later, Ritu says: \"It's eased a bit. But some days I still feel scared.\"","options":[{"text":"\"That makes sense. Would a counsellor or someone you trust help?\"","then":"She breathes out. \"Maybe. I think I'd like someone to talk to.\"","best":true},{"text":"\"I'm glad it's eased. Try to focus on the good side now.\"","then":"\"Thanks,\" she says, and the scared part goes unsaid again."},{"text":"\"I'll speak to your in-laws myself and settle it for good.\"","then":"\"Please don't,\" she says. \"That would only make it worse.\""},{"text":"\"Just be strong. It will pass once they get used to it.\"","then":"\"Okay,\" she says quietly, and doesn't say any more."}],"why":"Believing her fear and offering support, without pushing, helps more than cheering her up."}],"relearn":"Back her own timing; no baby has to secure a marriage. Point her to support if the pressure weighs on her."},
  {"id":"yp-951","cat":"childfree-complete","type":"match","hook":"Match each pressure line to the calm truth that answers it.","pairs":[{"left":"\"You'll regret it later\"","right":"I trust what I know about myself"},{"left":"\"A woman needs a child\"","right":"Womanhood isn't motherhood"},{"left":"\"You're being selfish\"","right":"Choosing honestly is responsible"},{"left":"\"Who'll care for you in old age?\"","right":"Care comes from many bonds"},{"left":"\"When's the good news?\"","right":"That's a private decision for us"}],"relearn":"Each pressure line has a calm, grounded answer; the truth deflects the script.","persona":"any","source":"pressure to truth"},
  {"id":"yp-952","cat":"childfree-complete","type":"match","hook":"Match each source of a full life to what it gives.","pairs":[{"left":"Work you care about","right":"Purpose"},{"left":"Close friends","right":"Belonging"},{"left":"Travel and learning","right":"Growth"},{"left":"A loving partner","right":"Companionship"},{"left":"Causes you give to","right":"Contribution"}],"relearn":"A childfree life draws meaning from many sources, each giving something real.","persona":"any","source":"sources of a full life"},
  {"id":"yp-953","cat":"childfree-complete","type":"match","hook":"Match the speaker's line to what it does to your choice.","pairs":[{"left":"\"It's entirely your call\"","right":"Respects it"},{"left":"\"Just have one, trust me\"","right":"Pressures it"},{"left":"\"However you build your family\"","right":"Accepts it"},{"left":"\"You'll change your mind\"","right":"Doubts it"},{"left":"\"I'm glad you know yourself\"","right":"Affirms it"}],"relearn":"Some lines respect and affirm your choice; others pressure or doubt it.","persona":"any","source":"respect or pressure match"},
  {"id":"yp-954","cat":"childfree-complete","type":"match","hook":"Match each nosy question to the warm reply that answers it.","pairs":[{"left":"\"When are you having kids?\"","right":"\"Not on our cards, thanks\""},{"left":"\"Don't you want a family?\"","right":"\"We are a family, just us\""},{"left":"\"Who'll inherit all this?\"","right":"\"We'll figure that out ourselves\""},{"left":"\"Aren't you lonely?\"","right":"\"My life is quite full, actually\""},{"left":"\"What will people say?\"","right":"\"That's their worry, not mine\""}],"relearn":"Each nosy question has a calm, closed reply that holds your boundary.","persona":"any","source":"nosy to reply"},
  {"id":"yp-955","cat":"childfree-complete","type":"match","hook":"Match each statement to whether it's a fact about worth or imposed shame.","pairs":[{"left":"You're whole exactly as you are","right":"A true fact about you"},{"left":"\"A childless woman is incomplete\"","right":"Imposed shame, not truth"},{"left":"Your value isn't your fertility","right":"A real measure of worth"},{"left":"\"You've failed as a wife\"","right":"A shaming script to refuse"},{"left":"Your life is full and your own","right":"Yours to claim"}],"relearn":"Worth-truths stand on their own; 'incomplete' and 'failed' are shame imposed from outside.","persona":"any","source":"fact or shame"},
  {"id":"yp-966","cat":"childfree-complete","type":"match","hook":"Match each myth to the truth that corrects it.","pairs":[{"left":"\"Womanhood means motherhood\"","right":"You're a whole woman either way"},{"left":"\"Childfree is selfish\"","right":"Deciding honestly is responsible"},{"left":"\"A marriage needs a child\"","right":"Partnership rests on the two of you"},{"left":"\"You'll change your mind\"","right":"You know your own life"},{"left":"\"Your bloodline ends\"","right":"Worth isn't carrying a surname"}],"relearn":"Each childfree myth has a clear truth that answers it.","persona":"any","source":"myth to truth"},
  {"id":"yp-967","cat":"childfree-complete","type":"match","hook":"Match each part of a couple's family plan to who it belongs to.","pairs":[{"left":"Whether to have a child","right":"The couple decides"},{"left":"When, if ever","right":"Theirs to time"},{"left":"How many","right":"Up to the two of them"},{"left":"The relatives' gossip","right":"Not your obligation"},{"left":"An aunty's opinion","right":"Hers to keep to herself"}],"relearn":"The decision and its timing belong to the couple; outsiders' opinions aren't your obligation.","persona":"any","source":"who decides match"},
  {"id":"yp-956","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that pressure, not respect, a childfree choice.","scene":[{"id":"a","text":"\"It's completely your decision\"","trick":false},{"id":"b","text":"\"You'll regret it once it's too late\"","trick":true},{"id":"c","text":"\"Whatever's right for you two\"","trick":false},{"id":"d","text":"\"A family isn't complete without kids\"","trick":true},{"id":"e","text":"\"I trust you know your own life\"","trick":false}],"why":"'You'll regret it' and 'not complete without kids' apply pressure; the rest leave the choice with you.","relearn":"Spot the pressure lines; respectful ones leave the childfree choice with you.","persona":"any","source":"spot the pressure"},
  {"id":"yp-957","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that shame a woman's worth over not having kids.","scene":[{"id":"a","text":"You're whole exactly as you are","trick":false},{"id":"b","text":"\"A childless woman is incomplete\"","trick":true},{"id":"c","text":"Your value isn't your fertility","trick":false},{"id":"d","text":"\"You've failed your duty as a wife\"","trick":true},{"id":"e","text":"Your life is full and your own","trick":false}],"why":"'Incomplete' and 'failed your duty' shame her worth; the others affirm she's whole as she is.","relearn":"Spot the shame lines; her worth isn't tied to having children.","persona":"any","source":"spot the shame"},
  {"id":"yp-958","cat":"childfree-complete","type":"spot","hook":"Spot the two replies that quietly hand your decision away instead of holding it.","scene":[{"id":"a","text":"\"We've decided not to, and we're happy\"","trick":false},{"id":"b","text":"\"Fine, we'll have one if you insist\"","trick":true},{"id":"c","text":"\"That's a private decision for us\"","trick":false},{"id":"d","text":"\"You all decide, you know better\"","trick":true},{"id":"e","text":"\"This one's settled, let's move on\"","trick":false}],"why":"'If you insist' and 'you all decide' give the choice away; the rest keep it firmly yours.","relearn":"Spot the replies that hand your decision away; settled lines keep it yours.","persona":"any","source":"spot handing away"},
  {"id":"yp-959","cat":"childfree-complete","type":"spot","hook":"Spot the two fear-based lines meant to scare you into having a child.","scene":[{"id":"a","text":"\"You'll die alone with no one to care for you\"","trick":true},{"id":"b","text":"Care in later life comes from many bonds","trick":false},{"id":"c","text":"\"Your clock is running out, hurry\"","trick":true},{"id":"d","text":"Your timeline is yours to set","trick":false},{"id":"e","text":"A childfree life can be full and planned for","trick":false}],"why":"'Die alone' and 'clock running out' are scare tactics; the others are calm, true and pressure-free.","relearn":"Spot the fear-based lines; a real choice needs no scare tactics.","persona":"any","source":"spot the scare"},
  {"id":"yp-960","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that assume she must secretly want a baby.","scene":[{"id":"a","text":"Some women genuinely never want children","trick":false},{"id":"b","text":"\"Deep down, every woman wants one\"","trick":true},{"id":"c","text":"A settled no is real self-knowledge","trick":false},{"id":"d","text":"\"You're just in denial about it\"","trick":true},{"id":"e","text":"You're the authority on your own life","trick":false}],"why":"'Deep down every woman wants one' and 'you're in denial' override her real no; the rest trust it.","relearn":"Spot the lines that override her real no; a settled no is true self-knowledge.","persona":"any","source":"spot the hidden-yes"},
  {"id":"yp-961","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that pressure a friend, not support her childfree choice.","scene":[{"id":"a","text":"\"Your life sounds full and happy\"","trick":false},{"id":"b","text":"\"Such a waste, you'd be a great mum\"","trick":true},{"id":"c","text":"\"I'm glad you know what you want\"","trick":false},{"id":"d","text":"\"You'll feel differently, just wait\"","trick":true},{"id":"e","text":"\"However you build your family is great\"","trick":false}],"why":"'Such a waste' and 'you'll feel differently' pressure her; the rest genuinely support her choice.","relearn":"Spot the pressuring lines; genuine support validates her childfree life.","persona":"any","source":"spot un-support"},
  {"id":"yp-968","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that guilt-trip a couple into having a child.","scene":[{"id":"a","text":"\"It's your decision, and we respect it\"","trick":false},{"id":"b","text":"\"I'll never be happy until I see your child\"","trick":true},{"id":"c","text":"\"We're glad you two know what you want\"","trick":false},{"id":"d","text":"\"You owe us a grandchild after all we did\"","trick":true},{"id":"e","text":"\"However you build your family is fine\"","trick":false}],"why":"'I'll never be happy until' and 'you owe us a grandchild' are guilt trips; the rest respect the choice.","relearn":"Spot the guilt trips; you owe no one a child to ease their feelings.","persona":"any","source":"spot the guilt-trip"},
  {"id":"yp-969","cat":"childfree-complete","type":"spot","hook":"Spot the two lines that assume a childfree woman's life must be empty or sad.","scene":[{"id":"a","text":"Her life is full of work, friends and purpose","trick":false},{"id":"b","text":"\"Poor thing, all alone with no little ones\"","trick":true},{"id":"c","text":"Meaning comes from many sources","trick":false},{"id":"d","text":"\"An empty home, how depressing\"","trick":true},{"id":"e","text":"A childfree life can be rich and chosen","trick":false}],"why":"'Poor thing, all alone' and 'empty home, how depressing' assume emptiness; the rest see a full life.","relearn":"Spot the pity lines; a childfree life can be rich, full and chosen.","persona":"any","source":"spot the pity"},
  {"id":"yp-990","cat":"hold-your-ground","type":"role-play","persona":"any","source":"wedding cornering","hook":"An aunty corners you near the buffet table at a cousin's wedding. You aren't looking and want to keep it warm.","setup":"She's got a samosa in one hand and a look in her eye.","steps":[{"prompt":"She asks: \"Beta, when is YOUR turn?\"","options":[{"text":"\"My turn will be whenever it's right for me. More gulab jamun?\"","then":"She laughs. \"Fair enough! And yes, very good today.\"","best":true},{"text":"\"Soon, aunty, hopefully soon. Please keep an eye out for me too!\"","then":"She beams. \"Good, good, I'll keep an ear out for you.\""},{"text":"\"Why is that any of your business?\"","then":"She looks stung. \"I was only asking.\""},{"text":"\"Sorry, I should go find my parents.\"","then":"She calls after you, unanswered. \"Come back! I wasn't finished!\""}],"why":"A warm, closed line plus a redirect ends the question without a fight."},{"prompt":"She follows you to the dessert table and asks: \"Seriously though, what's your plan, beta?\"","options":[{"text":"\"No plan today, just cake. This mango one is amazing.\"","then":"She grins. \"Okay, okay. Eat first, talk later.\"","best":true},{"text":"\"Fine. I'll think about it seriously. I truly promise you.\"","then":"She nods. \"Good. I'll ask your mother for updates.\""},{"text":"\"Can you please let this go now?\"","then":"She looks offended. \"I'm just making conversation.\""},{"text":"\"You're right. I have no plan. What would you do?\"","then":"She laughs, pulls up a chair and settles in to continue the topic."}],"why":"Staying light and redirecting again keeps the mood warm without giving ground."},{"prompt":"As the night ends, she says: \"I'm serious. I'll find someone for you.\"","options":[{"text":"\"That's sweet, but I'm not looking right now.\"","then":"She pats your hand. \"Alright, alright. Drive safe, beta.\"","best":true},{"text":"\"Sure, send me whoever you happen to find.\"","then":"She pulls out her phone and starts scrolling contacts immediately."},{"text":"\"Please, no, absolutely not, aunty.\"","then":"She looks wounded and says she was only trying to help."},{"text":"\"Okay, okay, whatever you say.\"","then":"She takes it as a yes and promises to call next week."}],"why":"A warm, firm no at the door closes the topic instead of leaving it open."}],"relearn":"A warm, closed line plus a redirect ends a nosy 'when's your turn' without a fight."},
  {"id":"yp-991","cat":"hold-your-ground","type":"role-play","persona":"any","source":"reputation pressure","hook":"Your dad says the family's reputation depends on you marrying soon.","setup":"He brings it up again over breakfast.","steps":[{"prompt":"He says: \"People are already talking, you know.\"","options":[{"text":"\"I love this family. My marriage is still my choice.\"","then":"He nods slowly. \"I know. I just worry about the whispers.\"","best":true},{"text":"\"Fine. I'll meet someone soon to stop the talk.\"","then":"He brightens. \"Good. I'll start asking around.\""},{"text":"\"Let them talk. It's not my problem.\"","then":"He frowns. \"It reflects on all of us, you know.\""},{"text":"\"Who exactly is talking about me?\"","then":"He waves a hand. \"Everyone. Relatives, neighbours.\""}],"why":"Naming both the love and the boundary keeps the choice yours."},{"prompt":"He asks: \"Meanwhile, what do I tell the relatives when they ask?\"","options":[{"text":"\"Tell them it's my decision, and you support me.\"","then":"He pauses. \"Alright. I can say that, I suppose.\"","best":true},{"text":"\"Tell them I'm 'still deciding', to buy some time.\"","then":"He relaxes. \"That works, for now.\""},{"text":"\"Tell them whatever keeps them quiet.\"","then":"He sighs. \"That's easier said than done.\""},{"text":"\"That's your problem, not mine.\"","then":"He looks hurt. \"I'm the one they corner, beta.\""}],"why":"Asking for real support, not a cover story, keeps your choice intact."},{"prompt":"He says: \"Your cousin's wedding is next month. People will ask there too.\"","options":[{"text":"\"I'll go, and answer them myself, briefly and kindly.\"","then":"He nods. \"Alright. I'll trust you with it.\"","best":true},{"text":"\"Maybe I should just skip the wedding then.\"","then":"He looks disappointed. \"That seems a bit drastic.\""},{"text":"\"Can you just tell them not to ask me?\"","then":"He shrugs. \"I can try, but people will ask anyway.\""},{"text":"\"I'll tell them I'm seeing someone, so they stop.\"","then":"He raises an eyebrow. \"And when they ask who?\""}],"why":"Going and answering briefly yourself beats hiding, or asking others to shield you."},{"prompt":"Later, he softens and says: \"I just want you happy, and settled.\"","options":[{"text":"\"I am happy. Settled doesn't have to mean married.\"","then":"He smiles, a little surprised. \"I hadn't thought of it that way.\"","best":true},{"text":"\"I'll try to be settled soon then, for you, honestly.\"","then":"He looks pleased. \"That's all I ask, beta.\""},{"text":"\"You only care about what the relatives think.\"","then":"He looks hurt. \"That isn't fair. I care about you.\""},{"text":"\"Don't worry about me quite so much, okay.\"","then":"He laughs softly. \"That's a father's job, beta.\""}],"why":"Separating happiness from marital status answers his real worry."}],"relearn":"You can honour the family and keep the marriage decision yours; a promise made under pressure isn't a real yes."},
  {"id":"yp-992","cat":"hold-your-ground","type":"role-play","persona":"Sneha","source":"career jokes","hook":"Your colleagues keep 'joking' that your career left no time for a husband.","setup":"It comes up again at the Friday team lunch.","steps":[{"prompt":"A colleague says: \"Career's great, but who's going to marry you now?\"","options":[{"text":"\"I built a life I love. Marriage, if ever, can fit around that.\"","then":"He shrugs, half-smiling. \"Fair enough, I guess.\"","best":true},{"text":"\"Ha, maybe I scared them all off. Who knows!\"","then":"The table laughs along, and the joke keeps coming back."},{"text":"\"That's a rude thing to say to someone.\"","then":"The table goes quiet, and he mutters that he was joking."},{"text":"\"Maybe you're right. I should slow down at work.\"","then":"He nods, pleased, like he's made his point."}],"why":"Naming your life as full, not lacking, ends the joke without a fight."},{"prompt":"Another colleague adds: \"Something must be wrong if no one's proposed yet.\"","options":[{"text":"\"Nothing's wrong. I haven't been looking. That's all.\"","then":"She pauses. \"Oh. I didn't think of it that way.\"","best":true},{"text":"\"Maybe I am doing something wrong, honestly.\"","then":"The table nods along, like it's settled."},{"text":"\"Can we please talk about something else?\"","then":"The topic shifts, but the comment lingers unanswered."},{"text":"\"You should mind your own relationship status, really.\"","then":"The table gets awkward, and lunch ends early."}],"why":"Correcting the frame, plainly, refuses the 'something's wrong' story."},{"prompt":"As you leave, someone calls out: \"Don't wait too long, though!\"","options":[{"text":"\"I'm not waiting. I'm just living my own life.\"","then":"He laughs. \"Okay, okay, fair point.\"","best":true},{"text":"\"Yeah, yeah, I'll get on it soon, promise.\"","then":"He grins, satisfied, and brings it up again next week."},{"text":"\"Wow, okay, noted, thanks so much.\"","then":"The sarcasm lands flat, and the joke continues anyway."},{"text":"\"That's honestly none of your business.\"","then":"The room goes a little quiet, and someone changes the subject."}],"why":"A calm, clear line closes the joke without leaving an opening for more."}],"relearn":"A calm, self-owned line names the full life you chose; you needn't accept a 'something's wrong' frame."},
  {"id":"yp-993","cat":"hold-your-ground","type":"role-play","persona":"Nisha","source":"good-news pressure","hook":"Your mother-in-law loves asking baby questions in front of the whole family.","setup":"Tonight, at dinner with guests, she brings it up again.","steps":[{"prompt":"She asks loudly: \"So when is the good news coming, beta?\"","options":[{"text":"\"That's between me and my husband, Mummy ji. More tea?\"","then":"She blinks, then laughs. \"Oh, alright, alright. Yes please.\"","best":true},{"text":"\"Soon, hopefully. We're trying our best!\"","then":"She beams at the table. \"Did you hear? Good news soon!\""},{"text":"\"That's a really personal thing to ask.\"","then":"She looks taken aback. \"I was only asking, beta.\""},{"text":"\"The doctor says we should wait a while, Mummy ji.\"","then":"Her eyes widen. \"Doctor? Why? What did they say?\""}],"why":"Keeping it private and light closes the question without a public debate."},{"prompt":"Later, she tells a guest: \"The good news will come soon. You'll see.\"","options":[{"text":"\"That's private, Mummy ji. Please don't share it.\"","then":"She looks startled, then nods. \"Oh. Sorry, beta.\"","best":true},{"text":"\"Ha, you know how it is!\"","then":"The guest smiles knowingly. \"Soon, then!\""},{"text":"\"We're not trying. We haven't even decided yet.\"","then":"The guest leans in. \"Haven't decided? Why ever not?\""},{"text":"\"Why would you tell people that?\"","then":"She looks hurt. \"I thought it was nice news to share.\""}],"why":"Naming the boundary directly stops the story from spreading further."},{"prompt":"Before the guests leave, she says: \"I just want to hold a grandchild someday.\"","options":[{"text":"\"I know. But whether and when is ours to decide.\"","then":"She nods slowly. \"Fair enough. I do trust you both.\"","best":true},{"text":"\"We'll try to give you that soon, Mummy ji.\"","then":"She squeezes your hand. \"I'll hold you to that.\""},{"text":"\"That's not really your decision to make.\"","then":"She looks stung. \"I wasn't trying to decide for you.\""},{"text":"\"Please stop bringing this up every time.\"","then":"She presses her lips together. \"Fine. I won't say another word.\""}],"why":"Naming her wish while keeping the choice yours honours both truths."}],"relearn":"Whether and when to have children is the couple's alone; you owe no one a public explanation."},
  {"id":"yp-994","cat":"hold-your-ground","type":"role-play","persona":"any","source":"matrimonial spam","hook":"A cousin keeps sending you matrimonial profiles after you've clearly said no.","setup":"Another one lands on WhatsApp this morning.","steps":[{"prompt":"He texts: \"Just look at this one. He's perfect for you!\"","options":[{"text":"\"I've said no, and I mean it. Please stop sending these.\"","then":"He replies: \"Oh. Okay, sorry, I just thought I'd help.\"","best":true},{"text":"\"Okay, fine. I'll take a quick look at this one, just so you know.\"","then":"He sends three more profiles within the hour."},{"text":"\"Stop spamming me, seriously, enough.\"","then":"He replies: \"Wow, okay, sorry for caring.\""},{"text":"\"Delete my number if you're going to do this.\"","then":"He goes quiet, and the tension carries into the next family call."}],"why":"A clear, kind no on record is how the messages actually stop."},{"prompt":"A week later, he sends another: \"Just one more, promise.\"","options":[{"text":"\"I asked you to stop. This really isn't okay.\"","then":"He replies: \"Right, sorry. I forgot.\"","best":true},{"text":"\"Ugh, fine, send it, last one though, honestly.\"","then":"He sends two more 'last ones' over the next month."},{"text":"\"You never listen to anything I say.\"","then":"He replies: \"That's a bit harsh, honestly.\""},{"text":"\"I'm blocking you if this continues.\"","then":"He goes quiet, but the tension lingers into the next visit."}],"why":"Restating the no, without new heat, keeps it clear and holds the line."},{"prompt":"He calls instead: \"Your mother asked me to send these, you know.\"","options":[{"text":"\"I'll talk to Mummy directly. You can stop now.\"","then":"He sounds relieved. \"Okay, that's easier for me anyway.\"","best":true},{"text":"\"Fine, tell Mummy I said yes to one meeting.\"","then":"He passes it on, and a meeting gets arranged by evening."},{"text":"\"That's between you and Mummy, not me.\"","then":"He sighs. \"Fine, but someone has to deal with this.\""},{"text":"\"I don't believe you, honestly.\"","then":"He gets defensive. \"Why would I lie about that?\""}],"why":"Going to the real source keeps the boundary from bouncing between people."},{"prompt":"Months later, a new profile arrives: \"Last try. I promise. Then I'll stop.\"","options":[{"text":"\"I'll ask if I ever want help. Please stop for good.\"","then":"He replies: \"Understood. Sorry it took this long.\"","best":true},{"text":"\"Fine, one more chance, and then that's truly it.\"","then":"Another profile arrives within the month regardless."},{"text":"\"You said that exact thing last time too.\"","then":"He apologises, but a new one shows up again soon."},{"text":"\"I'm done responding to these for good.\"","then":"The messages stop, but so does the conversation between you two."}],"why":"A clear, kind close, repeated as many times as needed, finally lands."}],"relearn":"A clear, repeated no, kindly delivered, is how you stop unwanted matchmaking; silence often invites more."},
  {"id":"yp-995","cat":"hold-your-ground","type":"role-play","persona":"any","source":"just a phase","hook":"At dinner, a relative keeps hinting your single life must be 'missing something'.","setup":"The table goes quiet, waiting for your reply.","steps":[{"prompt":"She says: \"You'll see. You'll want people around you eventually.\"","options":[{"text":"\"I've thought this through, and I'd like that respected.\"","then":"She pauses. \"Alright. Fair enough, I suppose.\"","best":true},{"text":"\"Maybe. I suppose we'll just have to see what happens.\"","then":"She nods, satisfied. \"That's more like it.\""},{"text":"\"You don't know my life at all.\"","then":"She looks taken aback. \"I'm just saying what I see.\""},{"text":"\"Sure, whatever you say, I guess.\"","then":"She smiles at the table. \"See? I told you all.\""}],"why":"Naming your choice as thought-through, not accidental, states your truth plainly."},{"prompt":"Someone else adds: \"It's not natural, living alone at your age.\"","options":[{"text":"\"Natural for me looks different, and that's alright.\"","then":"He shrugs. \"Hm. I suppose I've just never seen it.\"","best":true},{"text":"\"Maybe it isn't. I do wonder sometimes.\"","then":"He nods. \"See? Even you can feel it.\""},{"text":"\"That's a strange thing to call someone's life.\"","then":"He raises his hands. \"I'm only being honest.\""},{"text":"\"I'm not alone. I have lots of friends, actually.\"","then":"He smiles politely, and you notice you're defending your life now, not just living it."}],"why":"There's no single 'natural' way to live; yours is valid as it is."},{"prompt":"Later, your relative says: \"You'll thank me one day for pushing.\"","options":[{"text":"\"I'd rather you trusted me with my own life now.\"","then":"She softens a little. \"Alright. I do trust you, mostly.\"","best":true},{"text":"\"Maybe you're right. I'll think it over properly.\"","then":"She smiles, satisfied. \"You'll see I'm right.\""},{"text":"\"Please stop pushing, honestly.\"","then":"She looks hurt. \"I'm only trying to help.\""},{"text":"\"You've made your point already.\"","then":"She sniffs. \"Fine. I've said my piece.\""}],"why":"Asking for trust now, not gratitude later, keeps the choice yours."}],"relearn":"Calmly naming your choice as considered, and asking for respect, holds your ground without a row."},
  {"id":"yp-996","cat":"hold-your-ground","type":"role-play","persona":"Karthik","source":"men feel it too","hook":"Your uncle teases you about 'letting' your wife stay childfree.","setup":"He says it in front of the whole table, laughing.","steps":[{"prompt":"He says: \"A real man would have given her a child by now.\"","options":[{"text":"\"It's our decision, and we're at peace with it.\"","then":"He blinks. \"Oh. Well, if you're both happy.\"","best":true},{"text":"\"Maybe you're right. I should talk to her again.\"","then":"He nods, pleased. \"Good, glad you're seeing sense.\""},{"text":"\"That's a strange thing to say to me.\"","then":"He laughs. \"Arre, I'm only joking, yaar.\""},{"text":"\"That's an old-fashioned way to think, uncle.\"","then":"He shrugs. \"Maybe. Doesn't change what people think.\""}],"why":"Naming it as a shared, settled choice holds the line without a debate."},{"prompt":"He presses: \"People will think you can't, you know.\"","options":[{"text":"\"There'd be no shame in that. But it was our choice.\"","then":"He shrugs. \"Fair enough, I suppose.\"","best":true},{"text":"\"Maybe I should say it was my idea, not hers.\"","then":"He nods. \"That would help, actually.\""},{"text":"\"Why do you care so much about what people think?\"","then":"He spreads his hands. \"Just looking out for you, beta.\""},{"text":"\"That's none of anyone's business, uncle. Leave it there.\"","then":"He grunts. \"Everyone makes it their business.\""}],"why":"Neither infertility nor being childfree makes a man less; standing by the choice says so."},{"prompt":"Your aunt joins in: \"Won't you regret it later, though?\"","options":[{"text":"\"We've both thought about it, and we want this.\"","then":"She nods slowly. \"Alright. As long as you're both sure.\"","best":true},{"text":"\"Maybe. Who really knows what the future holds?\"","then":"She looks worried. \"Exactly. So think again.\""},{"text":"\"That's between us, not really your concern.\"","then":"She looks stung. \"I was only asking out of love.\""},{"text":"\"I don't think about it that much, honestly.\"","then":"She frowns. \"Maybe you should, beta.\""}],"why":"A shared, considered answer beats guessing about a future you don't fear."},{"prompt":"As you leave, your uncle says: \"Think about what I said, at least.\"","options":[{"text":"\"I will. What we've decided stays the same.\"","then":"He nods. \"Fair enough. I just worry. That's all.\"","best":true},{"text":"\"Okay. I'll bring it up with her again.\"","then":"He claps your back. \"Good man.\""},{"text":"\"There's nothing more to think about, uncle.\"","then":"He sighs. \"Stubborn, just like your father.\""},{"text":"\"Sure, sure, whatever you need to hear.\"","then":"He grins. \"Good. I'll tell your aunt you agreed.\""}],"why":"Hearing him out without bending the decision honours both things."}],"relearn":"Naming it as a shared, settled choice holds the line; manhood isn't proven by a child or by 'being in charge'."},
  {"id":"yp-997","cat":"hold-your-ground","type":"role-play","persona":"any","source":"decline the fear","hook":"An elder warns you'll 'die alone and regret it' if you don't marry now.","setup":"She says it gently, but she means it.","steps":[{"prompt":"She says: \"I'm telling you this because I love you. I've seen it happen.\"","options":[{"text":"\"I hear your worry, and I'm genuinely okay.\"","then":"She softens. \"Alright. I just worry.\"","best":true},{"text":"\"Maybe you're right. I should start looking harder.\"","then":"She nods, relieved. \"Good, that's more sensible.\""},{"text":"\"That's a scary thing to say to someone.\"","then":"She looks apologetic. \"I only meant to warn you.\""},{"text":"\"I won't end up alone. I have friends.\"","then":"She nods slightly. \"That's good to hear. I still worry, though.\""}],"why":"Naming the worry without absorbing the fear keeps your truth intact."},{"prompt":"She adds: \"Your great-uncle stayed single, and he regretted it, you know.\"","options":[{"text":"\"His story isn't mine. I'm choosing with open eyes.\"","then":"She pauses. \"That's true. Everyone's path is different.\"","best":true},{"text":"\"Maybe I'll end up regretting it too, then.\"","then":"She nods. \"Exactly what I'm afraid of.\""},{"text":"\"That's sad, but I don't think it'll happen to me.\"","then":"She looks unconvinced. \"That's what he thought too.\""},{"text":"\"I don't want to talk about him right now.\"","then":"She sighs. \"Someone has to tell you, beta.\""}],"why":"One person's regret isn't a forecast for a different, chosen life."},{"prompt":"Before you leave, she says: \"Just meet one person, for my peace of mind.\"","options":[{"text":"\"If I ever meet someone, it won't be out of fear.\"","then":"She nods slowly. \"Alright. I'll try to trust that.\"","best":true},{"text":"\"Okay, just one, to ease your mind.\"","then":"She brightens. \"I'll ask around this evening.\""},{"text":"\"Please stop trying to scare me into marrying.\"","then":"She looks hurt. \"I wasn't trying to scare you.\""},{"text":"\"Fine, whatever gets you off my back.\"","then":"She takes it seriously. \"Good. I'll fix a meeting.\""}],"why":"Choosing from want, not fear, keeps the decision truly yours."}],"relearn":"You can acknowledge an elder's worry while declining the fear; a scared yes isn't your truth."},
  {"id":"yp-998","cat":"hold-your-ground","type":"role-play","persona":"any","source":"don't settle","hook":"Your friend Meera thinks you are taking too long to find someone.","setup":"She says it over coffee, only half joking.","steps":[{"prompt":"She says: \"Just pick someone decent already, before it's too late.\"","options":[{"text":"\"I'd rather be happily single than settle to beat a deadline that isn't real.\"","then":"She raises an eyebrow. \"Fair. I just don't want you to miss out.\"","best":true},{"text":"\"Maybe you're right. I've probably been too picky about everyone.\"","then":"She nods. \"That's more realistic, honestly.\""},{"text":"\"Ha, true. Anyway, what are your holiday plans this year?\"","then":"She laughs and moves on, though the question feels only paused."},{"text":"\"Wow, thanks for the pressure, really. Very helpful.\"","then":"She looks a little sheepish. \"Sorry, I meant well.\""}],"why":"Choosing on your own terms, calmly, beats settling out of fear."},{"prompt":"She asks: \"Do you ever worry that the right one won't come?\"","options":[{"text":"\"Sometimes. But I'll have built a good life either way.\"","then":"She pauses. \"That's actually a nice way to see it.\"","best":true},{"text":"\"Yes, and I'd feel I had wasted my best years waiting for someone.\"","then":"She nods, worried. \"See, that's what I'm afraid of.\""},{"text":"\"That's a scary thing to ask me.\"","then":"She shrugs. \"Fair, I guess it is.\""},{"text":"\"I try not to think about that, honestly.\"","then":"She looks unconvinced, but drops it for now."}],"why":"A full life either way removes the fear that drives settling."},{"prompt":"Later she says: \"I just don't want you to end up alone like me.\"","options":[{"text":"\"Single isn't sad, and I'm here. I won't settle out of fear.\"","then":"She softens. \"Fair. I just worry for you. That's all.\"","best":true},{"text":"\"Maybe I should take dating more seriously then.\"","then":"She looks relieved and offers to set you up that week."},{"text":"\"You're not alone, you know. You have me, and I'm not going anywhere.\"","then":"She smiles, but the worry doesn't quite leave her face."},{"text":"\"That's a lot to put on me, honestly. Please don't.\"","then":"She looks apologetic, and the coffee goes quiet for a moment."}],"why":"You can be kind to her and still refuse to settle out of fear."}],"relearn":"There's no real deadline to beat; waiting for the right fit beats settling out of fear of being 'left behind'."},
  {"id":"yp-999","cat":"hold-your-ground","type":"role-play","persona":"any","source":"mother's tears","hook":"Your mother cries that you're 'shaming' her by staying unmarried.","setup":"She says it quietly, after everyone else has left.","steps":[{"prompt":"She says: \"What will people think of me, as your mother?\"","options":[{"text":"\"Mumma, I love you, and I'm not living for what people say.\"","then":"She wipes her eyes. \"I just don't want to be blamed.\"","best":true},{"text":"\"Maybe I should just marry someone, if it stops the tears.\"","then":"She brightens through her tears. \"Really? You'd do that?\""},{"text":"\"That's not fair. This isn't about you.\"","then":"She looks stung. \"It affects me too, you know.\""},{"text":"\"People will think whatever they want, Mumma.\"","then":"She sighs. \"That's exactly what scares me.\""}],"why":"Loving her and refusing the guilt can both be true at once."},{"prompt":"She says: \"Your aunty's daughter married last month. Everyone's asking about you now.\"","options":[{"text":"\"Her timeline was hers. Mine is still mine, Mumma.\"","then":"She sighs. \"I know. I just get scared, comparing.\"","best":true},{"text":"\"Maybe I am behind. I should catch up.\"","then":"She nods, hopeful. \"See? There's still time.\""},{"text":"\"Stop comparing me to her, please.\"","then":"She looks hurt. \"I'm only worried for you.\""},{"text":"\"I don't care what aunty's daughter did, really.\"","then":"She presses her lips together. \"I'm only saying.\""}],"why":"Someone else's timeline was never yours to match."},{"prompt":"Later, drying her eyes, she says: \"All I've ever wanted is to see you happy.\"","options":[{"text":"\"I am happy. Just not in the way you pictured.\"","then":"She nods slowly, still tearful. \"I'm trying to see that.\"","best":true},{"text":"\"Then tell me who to meet, and I'll try.\"","then":"She brightens. \"Let me call Sharma aunty tomorrow.\""},{"text":"\"If you wanted me happy, you'd stop crying about this.\"","then":"She flinches. \"That's cruel, beta.\""},{"text":"\"I'll be happy once all this pressure stops.\"","then":"She sighs. \"Then marry, and it will stop.\""}],"why":"Her happiness matters, and yours can look different from what she pictured."},{"prompt":"Before bed, she asks softly: \"Are we alright, beta?\"","options":[{"text":"\"We are. I love you, and the choice is still mine, Mumma.\"","then":"She hugs you tightly. \"Okay. I'll try to trust that.\"","best":true},{"text":"\"We are. Find someone, and I'll meet them.\"","then":"She dries her eyes. \"That's all I wanted.\""},{"text":"\"Are we? You keep pushing me like this.\"","then":"She looks hurt. \"Because I'm your mother.\""},{"text":"\"We will be, if you stop comparing me to others.\"","then":"She nods quickly. \"Deal. So you'll meet someone?\""}],"why":"A warm, true answer comforts her more than a promise made to stop the tears."}],"relearn":"You can love your mother AND not run your life on 'log kya kahenge'; a yes to stop tears isn't freely chosen."},
  {"id":"yp-1000","cat":"hold-your-ground","type":"role-play","persona":"Aditya","source":"not replacing him","hook":"Your relatives keep proposing 'a nice girl', though they know you're already partnered.","setup":"Your uncle brings it up again at Sunday lunch.","steps":[{"prompt":"He says: \"I found a lovely girl. Just meet her once.\"","options":[{"text":"\"I'm happily partnered. I'd love you to know him.\"","then":"He pauses. \"Oh. I didn't realise it was that serious.\"","best":true},{"text":"\"Fine. I'll meet her once, just to keep the peace.\"","then":"He beams. \"Wonderful. I'll fix it for next Sunday.\""},{"text":"\"Why do you keep doing this, uncle?\"","then":"He shrugs. \"I'm just trying to help you settle.\""},{"text":"\"That's not going to happen, ever.\"","then":"He looks stung. \"Never? That's a big word, beta.\""}],"why":"Naming the real partnership plainly is clearer than a polite dodge."},{"prompt":"He lowers his voice: \"Your aunts keep asking me about you and him. What do I say?\"","options":[{"text":"\"Nothing on my behalf. I'll talk to them myself, in my own time.\"","then":"He nods slowly. \"Alright. I'll leave it to you.\"","best":true},{"text":"\"Say I'll think about meeting girls. It keeps things calm.\"","then":"He relaxes. \"Good. That I can tell them.\""},{"text":"\"That's really your problem, not mine.\"","then":"He looks hurt. \"It affects the family too.\""},{"text":"\"Tell them whatever keeps them quiet.\"","then":"He sighs. \"That's easier said than done.\""}],"why":"Speaking for yourself, in your own time, beats a cover story or someone else's version."},{"prompt":"Your aunt adds: \"We just don't fully understand this.\"","options":[{"text":"\"I'm happy to answer questions. Or just get to know us.\"","then":"She nods, a little unsure but listening. \"Okay. I'd like that.\"","best":true},{"text":"\"You don't need to understand. Just accept it.\"","then":"She looks defensive. \"I'm trying, you know.\""},{"text":"\"Then I guess you'll never understand.\"","then":"She looks hurt. \"I only asked.\""},{"text":"\"It's simple. I just don't like girls.\"","then":"She looks more confused. \"So it's about girls, or about him?\""}],"why":"You owe no explanation; being open, without demanding acceptance, invites understanding."},{"prompt":"Before you leave, your uncle says: \"We'll always love you, meetings or not.\"","options":[{"text":"\"That means a lot. Please get to know him too.\"","then":"He smiles. \"Alright. Bring him next time, then.\"","best":true},{"text":"\"Thank you. I know it's hard for you to accept.\"","then":"He nods. \"It is. Give us time.\""},{"text":"\"Then maybe I should meet her once, to make it up to you.\"","then":"He brightens. \"Just once, that's all we ask. I'll fix it for next week.\""},{"text":"\"That's all I needed to hear, honestly.\"","then":"He hugs you. \"Good. And do think about that girl.\""}],"why":"Asking for real inclusion, not a substitute, keeps your partnership visible."}],"relearn":"A calm, plain statement of your real partnership holds your ground; you needn't perform a 'meeting' to keep peace."},
  {"id":"yp-1001","cat":"hold-your-ground","type":"role-play","persona":"any","source":"nosy neighbour","hook":"A nosy neighbour never misses a chance to comment on your relationship status. You aren't looking and would rather keep it light.","setup":"She catches you in the lift lobby, arms crossed.","steps":[{"prompt":"She asks: \"So why hasn't anyone taken you yet, beta?\"","options":[{"text":"\"I'm happy with how my life's going. How's your day been?\"","then":"She blinks, a little surprised. \"Oh. Fine, fine.\"","best":true},{"text":"\"Honestly, aunty, I'm still figuring it all out myself.\"","then":"She nods knowingly. \"Don't wait too long, though.\""},{"text":"\"That's a strange way to put it.\"","then":"She shrugs. \"Just an expression, beta.\""},{"text":"\"Nobody's 'taking' anybody these days.\"","then":"She laughs. \"You know what I mean.\""}],"why":"A light, closed line plus a redirect ends it without a defensive speech."},{"prompt":"She presses: \"Don't your parents worry about this?\"","options":[{"text":"\"They're fine, thanks. So, how's your week going?\"","then":"She hesitates. \"Oh, same as always, beta.\"","best":true},{"text":"\"Sometimes, I think, but they don't say much.\"","then":"She nods. \"I thought so. Parents always worry.\""},{"text":"\"Not at all. They know I've just been really busy.\"","then":"She raises an eyebrow. \"Busy? Too busy for a family?\""},{"text":"\"Why would that be your concern?\"","then":"She looks offended. \"I'm only being neighbourly.\""}],"why":"A light answer and a change of topic ends it, without handing her more to discuss."},{"prompt":"As the lift arrives, she says: \"I'll ask around for you, no charge!\"","options":[{"text":"\"That's kind, but I'm not looking right now.\"","then":"She shrugs. \"Suit yourself, beta.\" She lets it go.","best":true},{"text":"\"Sure, why not? It can't hurt to ask around.\"","then":"She grins. \"I already have two names in mind!\""},{"text":"\"No thanks. I'd rather you stayed out of it.\"","then":"She sniffs. \"Fine. No need to be rude.\""},{"text":"\"Oh, my lift's here! Bye, aunty!\"","then":"She calls after you. \"I'll find you someone!\""}],"why":"A clear, warm no closes the offer instead of leaving it hanging."}],"relearn":"A light, closed line plus a redirect ends a nosy question; you owe no defensive explanation."},
  {"id":"yp-1002","cat":"hold-your-ground","type":"role-play","persona":"Sneha","source":"name the pattern","hook":"Relatives keep raising your marriage at every single gathering.","setup":"It comes up again before the starters are even served.","steps":[{"prompt":"An uncle asks: \"So, any progress on the marriage front?\"","options":[{"text":"\"This comes up every time. Can we set it aside today?\"","then":"He pauses, a little surprised. \"Fair enough, fair enough.\"","best":true},{"text":"\"No progress, same as last time, uncle.\"","then":"He nods. \"Well, keep us posted, hmm?\""},{"text":"\"Why does this always come up first?\"","then":"He shrugs. \"Just making conversation, beta.\""},{"text":"\"Ha! You'll be the first to know if anything changes.\"","then":"He looks satisfied. \"Good, good. Don't keep us waiting!\""}],"why":"Naming the pattern, calmly, is steadier than exploding or shrinking."},{"prompt":"An hour later, an aunt starts again: \"So really, what's the holdup?\"","options":[{"text":"\"You're the second person to ask today. Can we let it rest?\"","then":"She laughs a little. \"Second already? Fine. I'll leave it.\"","best":true},{"text":"\"There's no holdup. I'm just busy with work right now.\"","then":"She nods. \"Work can wait, beta. Life can't.\""},{"text":"\"Can everyone please stop asking me this?\"","then":"She looks startled. \"Arre, I only asked once.\""},{"text":"\"I don't know. Maybe I'm the problem.\"","then":"She looks concerned. \"Don't say that. Let me help.\""}],"why":"Naming that it keeps coming up, and asking to let it rest, is steadier than another excuse."},{"prompt":"As the evening winds down, your aunt says: \"We only ask because we love you.\"","options":[{"text":"\"I know. Can we treat it as settled from now on?\"","then":"She hesitates, then pats your arm. \"Alright. I'll tell the others.\"","best":true},{"text":"\"I know. I'll try to have news for you soon.\"","then":"She beams. \"That's all we want to hear!\""},{"text":"\"Love shouldn't feel like this, honestly.\"","then":"She looks wounded. \"That's a hard thing to hear, beta.\""},{"text":"\"Fine. I'll stop coming to these dinners.\"","then":"She looks startled. \"Beta, that's not what we meant.\""}],"why":"Asking kindly to treat it as settled closes the pattern without a fight."}],"relearn":"Naming the repetition and asking to set it aside is a kind, firm boundary: steadier than exploding or shrinking."},
  {"id":"yp-1003","cat":"hold-your-ground","type":"role-play","persona":"Nisha","source":"decline the frame","hook":"Your mother-in-law keeps hinting that you're not yet a 'complete' woman.","setup":"Today she brings it up gently, over tea.","steps":[{"prompt":"She says: \"A real woman your age would already have a baby.\"","options":[{"text":"\"My womanhood isn't measured by motherhood. I'm whole as I am.\"","then":"She pauses. \"I didn't mean it that way, I suppose.\"","best":true},{"text":"\"Maybe you're right. I should think about it more, honestly.\"","then":"She nods, pleased. \"Good, I think so too.\""},{"text":"\"That's a hurtful thing to say to me.\"","then":"She looks apologetic. \"I didn't mean to hurt you.\""},{"text":"\"Plenty of women my age don't have kids.\"","then":"She shrugs. \"Maybe, but I still worry about you.\""}],"why":"Declining the frame states your worth without absorbing the dig."},{"prompt":"She adds: \"I just think motherhood completes a woman.\"","options":[{"text":"\"Motherhood fulfils some women. My life already feels full.\"","then":"She nods slowly. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Maybe it does. I suppose I just haven't felt it yet.\"","then":"She nods, satisfied. \"You will, beta. You'll see.\""},{"text":"\"That's an old-fashioned way to think.\"","then":"She stiffens. \"Old-fashioned? I'm only being honest.\""},{"text":"\"I don't need completing by anyone.\"","then":"She blinks. \"No need to be sharp, beta.\""}],"why":"Naming one path among many, gently, corrects the frame without a fight."},{"prompt":"Later, she says: \"I only worry you'll regret not trying.\"","options":[{"text":"\"I hear that worry. I know my own mind on this.\"","then":"She softens. \"Alright. I trust you know yourself.\"","best":true},{"text":"\"Maybe I will regret it. I hadn't thought of that.\"","then":"She nods. \"That's all I'm saying, beta.\""},{"text":"\"That's not something you need to worry about.\"","then":"She looks hurt. \"I can't help worrying.\""},{"text":"\"I've heard this speech a hundred times.\"","then":"She sets down her cup. \"Then maybe you should listen.\""}],"why":"Trusting your own knowledge of yourself answers the worry directly."}],"relearn":"Womanhood isn't motherhood; you can decline that frame warmly rather than absorb a dig as truth."},
  {"id":"yp-1004","cat":"hold-your-ground","type":"role-play","persona":"any","source":"refuse the shade card","hook":"A matchmaker auntie comments your skin is 'too dark' for good proposals.","setup":"She says it while flipping through her folder of profiles.","steps":[{"prompt":"She says: \"We might need to lighten your photos a bit.\"","options":[{"text":"\"My worth isn't a shade card. I'm not interested in that market.\"","then":"She pauses, a little surprised. \"Alright, fair enough.\"","best":true},{"text":"\"Maybe a lighter photo would genuinely help, just this once.\"","then":"She nods, pleased. \"Just a little brighter. You'll see.\""},{"text":"\"That's a really offensive thing to say.\"","then":"She shrugs. \"It's just how the market works, beta.\""},{"text":"\"Is my face really that bad? Be honest.\"","then":"She tilts her head. \"Not bad. Just a shade too dark, beta.\""}],"why":"Refusing the ranking names it as false, instead of feeding it."},{"prompt":"She adds: \"Lighter profiles just get more responses. That's all.\"","options":[{"text":"\"That says something about the market, not about me.\"","then":"She waves a hand. \"I'm just telling you how it goes.\"","best":true},{"text":"\"Maybe I should just accept that's how it is.\"","then":"She nods. \"Smart. No point fighting it.\""},{"text":"\"That's a horrible thing to accept.\"","then":"She looks defensive. \"I don't make the rules.\""},{"text":"\"Should I try a fairness cream, then?\"","then":"She brightens, then adds, \"Some of them do sting the skin, mind you.\""}],"why":"Naming the market as biased, not you as lacking, keeps your worth intact."},{"prompt":"She asks: \"Don't you want more options, though?\"","options":[{"text":"\"I want the right option, not just more of them.\"","then":"She pauses. \"Fair. Quality over quantity, I suppose.\"","best":true},{"text":"\"I do, so maybe a lighter photo isn't so bad.\"","then":"She nods, pleased. \"Good. I'll lighten the main one.\""},{"text":"\"Options don't matter if they're all shallow.\"","then":"She shrugs. \"Shallow or not, it's what works.\""},{"text":"\"Guess I'll just take whatever comes then.\"","then":"She nods, satisfied. \"That's more realistic.\""}],"why":"Wanting the right fit, not the widest pool, reframes what 'more' means."},{"prompt":"Before she leaves, she says: \"Tell me by Friday which photos to use, beta.\"","options":[{"text":"\"Use the photos I gave you, exactly as they are.\"","then":"She sighs. \"As they are, then. Your call, beta.\"","best":true},{"text":"\"I'll get some brighter ones taken this week.\"","then":"She smiles. \"Good. Soft lighting, remember.\""},{"text":"\"Lighten them a little, but only a little.\"","then":"She nods. \"Just a touch. No one will notice.\""},{"text":"\"Let me think about it and get back to you.\"","then":"She smiles. \"Don't think too long, beta.\""}],"why":"Keeping your photos exactly as they are refuses the ranking instead of feeding it."}],"relearn":"Skin tone measures nothing real about you; you can refuse the marriage market's ranking instead of absorbing it."},
  {"id":"yp-1005","cat":"hold-your-ground","type":"branch","persona":"any","source":"shortlisted without asking","hook":"Your parents announce they've 'shortlisted' a match without asking you first.","steps":[{"prompt":"They show you the photo over breakfast, already excited. What do you do?","options":[{"text":"Thank them, then say the decision and timing stay yours","then":"They're a little surprised, but say that's fair.","best":true},{"text":"Agree to a meeting, just to avoid a scene","then":"You end up quietly agreeing to something you didn't choose."},{"text":"Refuse to look at the photo at all","then":"They feel dismissed before you've even said what you think."},{"text":"Say yes to a meeting, quietly planning to cancel later on","then":"They start calling the other family, and your plan to cancel gets harder by the hour."}],"why":"Saying it at breakfast, kindly, stops their plan moving ahead on a yes you never gave."},{"prompt":"That evening, your mother asks if you're upset with them. What do you say?","options":[{"text":"Say you're not upset, just to keep the evening pleasant","then":"She nods, relieved, though something in your voice doesn't quite match your words."},{"text":"Say you are a little upset that they didn't ask you first","then":"\"That's fair,\" she says. \"We should have asked. We're sorry.\"","best":true},{"text":"Say it's fine, whatever they think is best","then":"It quietly signals you're fine with however they decide to proceed."},{"text":"Avoid the conversation and go to your room","then":"She worries more in the silence than she would with an answer."}],"why":"Naming the upset honestly, without hiding it, clears the air better than pretending it away."},{"prompt":"A month later, they mention a new match, this time asking first. What do you do?","options":[{"text":"Thank them for asking, and decide from there","then":"The whole conversation feels easier than the last one.","best":true},{"text":"Assume it's fine now to skip discussing timing at all","then":"The habit of deciding for you starts to creep back in quietly."},{"text":"Feel guilty, and agree before you've thought about it","then":"You're booked to meet the match before you've asked yourself if you want to."},{"text":"Say you'll think about it, then never give an answer","then":"Without an answer from you, the decision quietly drifts back to them."}],"why":"Thanking them for asking, then deciding for yourself, rewards the change and keeps the choice yours."}],"debrief":"A warm thank-you plus a clear 'the decision stays mine' honours their care without surrendering the choice.","relearn":"Thank them for caring, then keep the decision and the timing yours."},
  {"id":"yp-1006","cat":"hold-your-ground","type":"branch","persona":"any","source":"light deflection","hook":"An aunty keeps probing why you're 'still' single at every call.","steps":[{"prompt":"She opens the call with the same question again. What do you do?","options":[{"text":"Give a light, closed answer and change the subject","then":"She takes the cue and moves on to family gossip instead.","best":true},{"text":"Defend your whole life choice in detail","then":"The detailed defence just invites more questions."},{"text":"Go quiet and let her fill the silence","then":"She fills it with more questions, not fewer."},{"text":"Turn the question back on her, sharply","then":"The call turns tense over a comment that started fairly light."}],"why":"A short, closed answer gives her nothing to probe, and the call moves on."},{"prompt":"On the next call, she circles back to the topic within minutes. What do you do?","options":[{"text":"Keep it light and closed, then ask about her week","then":"She laughs, and starts telling you about her week instead.","best":true},{"text":"Get frustrated she's asking again so soon","then":"The frustration becomes the story of the call, not the actual answer."},{"text":"Give a fuller answer, hoping it satisfies her","then":"It doesn't satisfy her. It just gives her more to ask about."},{"text":"Cut the call short to avoid the topic","then":"She calls back the next day, question ready."}],"why":"A light answer and a new topic hold the line without growing into a defence."},{"prompt":"Months later, she mentions to your mother that you seem 'settled and happy' about it. What do you do?","options":[{"text":"Feel glad it's finally settled","then":"It's a quiet relief to hear it without the bigger conversation.","best":true},{"text":"Worry it means she's stopped taking your life seriously","then":"You read doubt into a comment that was actually a compliment."},{"text":"Bring it up directly to make sure she really means it","then":"It reopens a topic that had genuinely settled on its own."},{"text":"Credit it to her just giving up eventually","then":"You never quite figure out what actually shifted her mind."}],"why":"Taking the good news quietly lets the peace settle, without reopening a topic that has closed."}],"debrief":"A light, closed deflection ends a nosy question; you don't owe a detailed defence of your life.","relearn":"A light, closed deflection ends a nosy question; you owe no detailed defence."},
  {"id":"yp-1007","cat":"hold-your-ground","type":"branch","persona":"any","source":"log kya kahenge push","hook":"The 'log kya kahenge' line is being used to push you toward a wedding you're not ready for.","steps":[{"prompt":"Your uncle uses it at a family meeting about your marriage. What do you do?","options":[{"text":"Name it as social pressure, not your obligation","then":"He pauses, and for once doesn't have a ready reply.","best":true},{"text":"Let it sway you into saying you'll 'think about a date'","then":"You say you'll think about a date, and the family hears a yes. The doubt lingers quietly."},{"text":"Ask exactly who's supposedly saying these things","then":"The meeting spends an hour on hypothetical gossip, not your choice."},{"text":"Storm out of the meeting","then":"The meeting continues without you, deciding things you'll undo later."}],"why":"Calling it pressure out loud, at the meeting itself, stops it quietly setting your wedding date."},{"prompt":"A week later, your grandmother uses a gentler version of the same line to nudge things along. What do you do?","options":[{"text":"Explain kindly that this is still your decision to make","then":"She nods, softened by the gentle explanation, and lets it be.","best":true},{"text":"Let it land differently since it's your grandmother","then":"The exception quietly weakens the boundary everywhere else too."},{"text":"Get sharp, tired of hearing the phrase from everyone","then":"Her face falls, and she goes quiet for the rest of the visit."},{"text":"Change the subject without answering","then":"She brings it up again the next time you visit."}],"why":"A kind, clear answer holds even when the pressure comes gently, from someone you love."},{"prompt":"Months later, you catch yourself worrying what the neighbours will think of your plans. What do you do?","options":[{"text":"Ask yourself what you'd choose if nobody were watching","then":"The answer comes more easily than you expected, and it feels like yours.","best":true},{"text":"Take the worry as a sign the family must be right","then":"You start picturing a wedding date, and the knot in your stomach tightens."},{"text":"Push the worry away without looking at it","then":"It fades for the day, then returns at the next family meeting."},{"text":"Ask a few friends what people are probably saying","then":"Each friend guesses differently, and the noise gets louder, not clearer."}],"why":"Asking what you'd choose without an audience separates your own wish from what people might say."}],"debrief":"'Log kya kahenge' is social pressure, not your obligation; the choice isn't the neighbourhood's to make.","relearn":"Name 'log kya kahenge' as social pressure, not your obligation."},
  {"id":"yp-1008","cat":"hold-your-ground","type":"branch","persona":"any","source":"protect confidence","hook":"A hard week of family comments keeps chipping away at you.","steps":[{"prompt":"By Friday night, you're doubting decisions you used to feel sure of. What do you do?","options":[{"text":"Spend the weekend with people who respect your path","then":"By Sunday, the certainty you'd lost starts to come back.","best":true},{"text":"Isolate for the weekend to avoid more comments","then":"The isolation leaves the doubt with nothing to counter it."},{"text":"Spend the weekend catching up on family obligations instead","then":"The doubt deepens without any time carved out to counter it."},{"text":"Distract yourself with work all weekend","then":"The doubt is still there Monday morning, just delayed."}],"why":"Time with people who respect your path steadies confidence that constant pressure has worn thin."},{"prompt":"On Monday evening, a friend messages to check in, asking how you're doing. What do you say?","options":[{"text":"Name the specific comments honestly","then":"Saying them out loud makes them feel smaller than they did in your head.","best":true},{"text":"Say it's nothing, just a rough week","then":"The friend can't help with what you won't actually name."},{"text":"Focus on defending your choices instead of the toll","then":"The conversation misses the actual thing wearing you down."},{"text":"Change the subject, embarrassed to admit it's getting to you","then":"The doubt stays exactly as heavy as before the conversation."}],"why":"Naming the specific pressure lets a supportive friend actually help carry it."},{"prompt":"A month later, a friend who always backs you invites you to a weekly dinner with her circle. What do you do?","options":[{"text":"Say yes, and make it a regular part of your week","then":"Over the weeks, the family comments start to land with less weight.","best":true},{"text":"Say you'll come once things calm down at home","then":"Things don't calm down, and the invitation quietly lapses."},{"text":"Go once, then stop, feeling you shouldn't need it","then":"The lift from that evening fades by the next round of comments."},{"text":"Go, but spend each dinner defending your choices","then":"The dinners turn into rehearsals of the arguments you meant to leave behind."}],"why":"A regular evening with friends who back you steadies you before the next round of comments."}],"debrief":"A circle that respects your path protects your confidence; choose who gets your time when pressure is high.","relearn":"Spend time with people who respect your path to protect your confidence."},
  {"id":"yp-1009","cat":"hold-your-ground","type":"branch","persona":"any","source":"distress routes to support","hook":"Family conflict over your choices is becoming genuinely distressing, again.","steps":[{"prompt":"After a difficult call, you notice you're shaking a little. What do you do?","options":[{"text":"Reach out to a counsellor or a trusted person","then":"Talking it through helps the shakiness settle.","best":true},{"text":"Push it down and get on with the day","then":"The shakiness passes, but the same feeling returns after the next call."},{"text":"Reply to the family with an angry message","then":"The message escalates the conflict rather than easing your distress."},{"text":"Believe giving in is the only way to keep the peace","then":"You quiet the conflict for now, but the belief keeps costing you later too."}],"why":"Reaching out for support looks after your wellbeing inside a conflict you can't fully control alone."},{"prompt":"Later that week, your brother says you're 'too sensitive' and should stop reacting to the calls. What do you do?","options":[{"text":"Say it's hurting you, and that needing support is okay","then":"He's quiet, then admits he hadn't realised how hard the calls have been.","best":true},{"text":"Wonder if he's right and you're overreacting","then":"You start doubting your own distress, and the next call feels heavier."},{"text":"Decide to keep how you feel to yourself from now on","then":"The calls keep hurting, and now nobody around you knows it."},{"text":"Try to feel nothing on the calls, the way he suggests","then":"You grit your teeth through the next call and end it shaking anyway."}],"why":"Distress isn't oversensitivity; saying so plainly stops you blaming yourself for hurting."},{"prompt":"Weeks later, a relative restarts the argument in the family WhatsApp group. What do you do?","options":[{"text":"Step away from the chat and call a trusted person","then":"After talking it through, you feel steady enough to decide whether to reply.","best":true},{"text":"Reply at once, so no one thinks you've backed down","then":"The thread heats up, and you're still shaking an hour later."},{"text":"Believe you should be able to handle this alone by now","then":"You judge yourself for struggling, on top of the argument itself."},{"text":"Tell no one, since family business should stay private","then":"You carry the whole thread alone, rereading it late into the night."}],"why":"Reaching support before replying lets you respond, or not, from a steadier place."}],"debrief":"If family conflict over your choices turns distressing, reach for support: a counsellor or trusted person. None of it is your fault.","relearn":"If family conflict turns distressing, reach for a counsellor or trusted person."},
  {"id":"yp-1010","cat":"hold-your-ground","type":"branch","persona":"Sneha","source":"kind firm boundary","hook":"Relatives keep raising marriage at every gathering, every single time, and it's wearing you down.","steps":[{"prompt":"This Diwali, four different relatives ask about marriage before you've had your first sweet. What do you do?","options":[{"text":"Set the same kind, firm boundary with each one","then":"Each conversation moves on quickly, without any tension.","best":true},{"text":"Answer differently each time, hoping one version works","then":"The mixed answers start showing up as gossip within the hour."},{"text":"Stay near the kitchen all evening to dodge them","then":"You spend Diwali in the kitchen instead of with people you enjoy."},{"text":"Prepare a long, detailed answer to finally settle it","then":"The detailed answer just gives everyone more to discuss and debate."}],"why":"The same kind, firm boundary works on every relative, without needing a new approach each time."},{"prompt":"Later, your youngest cousin asks how you got through all the marriage questions this year. What do you say?","options":[{"text":"Say one kind, firm line works better than dodging","then":"She nods, taking it in for whenever she'll need it herself.","best":true},{"text":"Say it's just easier now since you've stopped caring","then":"She nods and files away 'just stop caring' as the secret, and repeats it to her sister later."},{"text":"Brush off the question, not wanting to seem like you have a 'method'","then":"She's left without anything useful for her own future gatherings."},{"text":"Tell her to just avoid the relatives when she can","then":"She nods, and starts planning which functions she can skip."}],"why":"Passing on a kind, firm line gives her something she can use at her own gatherings."},{"prompt":"At the next big gathering, a relative pivots from marriage questions to grilling you about your career instead. What do you do?","options":[{"text":"Answer the career questions with a kind, firm line too","then":"The relative shrugs, and the talk drifts to someone's new house.","best":true},{"text":"Assume career questions need a full, detailed answer","then":"You end up over explaining your career choices to everyone who asks."},{"text":"Get more defensive about career than marriage","then":"The gathering picks up on the different reaction and asks more, not less."},{"text":"Avoid all personal topics with relatives from now on","then":"It cuts off warmth along with the pressure you were trying to manage."}],"why":"A kind, firm boundary travels well; it isn't just a marriage specific trick."},{"prompt":"By the end of gathering season, relatives seem to raise it a little less often. What do you do?","options":[{"text":"Notice what's been working, and keep doing it","then":"It's a quiet, real relief to see the pattern actually shift.","best":true},{"text":"Assume the questions are over for good","then":"The questions come right back at the first wedding of the new season."},{"text":"Feel guilty that relatives might feel shut out","then":"You apologise to an aunty who hadn't felt shut out at all."},{"text":"Credit relatives for just growing tired of asking","then":"You're left unsure what actually changed, or what to keep doing."}],"why":"Noticing what worked, and why, helps you keep doing it next season."}],"debrief":"A kind, firm boundary and redirect deflects repeated pressure without rupturing the relationship.","relearn":"Set a kind, firm boundary and redirect when pressure repeats."},
  {"id":"yp-1011","cat":"hold-your-ground","type":"branch","persona":"any","source":"enforce the no","hook":"A relative keeps 'finding matches' for you despite your clear no.","steps":[{"prompt":"Your mother passes along another profile 'on the relative's behalf'. What do you do?","options":[{"text":"Tell your mother the no stands, and you'll say it yourself","then":"Your mother agrees, relieved not to be stuck in the middle.","best":true},{"text":"Look at the profile since it's already in front of you","then":"Looking reads as interest, and a follow up call comes within days."},{"text":"Get frustrated with your mother for passing it along","then":"Your mother feels blamed for a boundary that isn't about her."},{"text":"Ignore it and hope it stops on its own","then":"It doesn't stop, since no one's actually said no this time."}],"why":"Telling your mother the no stands keeps her out of the middle while you say it yourself."},{"prompt":"The relative calls you directly the next week, undeterred. What do you do?","options":[{"text":"Restate your no plainly and ask her to stop","then":"She's quiet for a second, then says she heard you, though she doesn't sound convinced.","best":true},{"text":"Let the call go to voicemail","then":"She takes the silence as still undecided, not as a no."},{"text":"Explain all your reasons for saying no","then":"The explanation opens a debate instead of closing the topic."},{"text":"Ask your mother to take this call too","then":"The message keeps arriving secondhand, and secondhand keeps not landing."}],"why":"Saying the no straight to her and asking her to stop closes any doubt left by hearing it secondhand."},{"prompt":"A month later, she raises the matchmaking with your father, hoping he'll see it differently. What do you do?","options":[{"text":"Tell your father, calmly, it's already been declined","then":"He tells her the same, and this time it actually sticks.","best":true},{"text":"Stay out of it and let your father handle it his way","then":"Without the full picture, his answer comes out vaguer than yours."},{"text":"Feel like you have to keep defending the same no forever","then":"The exhaustion of repeating it starts to outweigh the boundary."},{"text":"Get sharp with her for going around you again","then":"The sharpness becomes the story, more than the actual, reasonable no."}],"why":"Making sure everyone she might ask has the same clear answer stops the boundary from being worked around."},{"prompt":"By the next family season, the profiles have genuinely stopped arriving. What do you do?","options":[{"text":"Thank whoever helped hold the line, and let it rest","then":"It feels like a boundary that's actually settled now, not just paused.","best":true},{"text":"Stay braced for it to start again any day","then":"The bracing costs you peace a settled boundary should have given back."},{"text":"Bring it up again just to double check it's really over","then":"It reopens a topic that had genuinely closed on its own."},{"text":"Assume it stopped for reasons unrelated to the boundary","then":"You're left crediting the wrong thing, unsure what actually changed."}],"why":"Thanking the people who backed you, then letting it rest, keeps the family close once it's over."}],"debrief":"Restate your no and ask them to stop the matchmaking; a firm-but-loving no deserves respect.","relearn":"Restate your no clearly and ask them to stop the matchmaking."},
  {"id":"yp-1012","cat":"hold-your-ground","type":"branch","persona":"Nisha","source":"trust yourself","hook":"An elder insists you'll 'change your mind' about not wanting kids.","steps":[{"prompt":"Your grandmother says it again at Sunday lunch, sure of herself. What do you do?","options":[{"text":"Calmly say you trust your own knowledge of yourself","then":"She looks at you a moment longer, then lets it go for now.","best":true},{"text":"Agree you probably will, to smooth it over","then":"She takes the agreement as proof she was right all along."},{"text":"Argue that older generations don't understand this choice","then":"It turns generational rather than personal, and the point gets lost."},{"text":"Laugh it off without really answering","then":"She takes the laugh as a maybe, and brings it up again next Sunday."}],"why":"Naming your own self knowledge, calmly, holds the boundary without needing an argument."},{"prompt":"Your husband later asks if comments like that shake your confidence. What do you say?","options":[{"text":"Admit they used to, but trusting yourself gets easier","then":"He says he's noticed you sounding steadier about it lately too.","best":true},{"text":"Say they never bother you at all","then":"He can't quite tell if that's true, or just something you're saying."},{"text":"Say you're starting to wonder if she might be right","then":"He looks surprised, and asks if you've been changing your mind."},{"text":"Change the subject before answering","then":"The question sits there, unaddressed, a little heavier than before."}],"why":"Being honest that it takes practice reassures him it's a real, ongoing steadiness, not a performance."},{"prompt":"At the next family lunch, your grandmother tries a gentler version: 'wait and see, beta'. What do you do?","options":[{"text":"Thank her for the care, and say plainly you trust yourself","then":"She pats your hand, and doesn't press further this time.","best":true},{"text":"Let the gentler tone soften your actual answer","then":"You leave the lunch having agreed to more waiting than you meant."},{"text":"Point out she's said this many times already","then":"She feels caught out instead of just gently redirected."},{"text":"Avoid the topic by leaving the table early","then":"She worries she's said something wrong, unsure what happened."}],"why":"Thanking her while holding your answer keeps it steady, even when pressure comes wrapped in love."},{"prompt":"Months later, your grandmother asks, gently, whether you still feel the same about children. What do you do?","options":[{"text":"Tell her yes, simply, and thank her for asking","then":"She nods slowly. \"You do seem to know your own mind.\"","best":true},{"text":"Ask why she can't just accept it by now","then":"She looks hurt, and the gentle moment closes."},{"text":"Say you might still change your mind, to soften it","then":"Her face brightens, and she mentions it again at the next lunch."},{"text":"Bring up every time she doubted you before","then":"It turns a rare, gentle question into an old argument."}],"why":"A simple, warm yes answers her gentle question honestly, without reopening the debate."}],"debrief":"You can trust your own knowledge of yourself; you needn't accept 'you'll change your mind' to keep the peace.","relearn":"Trust your own knowledge of yourself; you needn't accept 'you'll change your mind'."},
  {"id":"yp-1013","cat":"hold-your-ground","type":"branch","persona":"any","source":"don't settle to a clock","hook":"A friend keeps nudging you to 'just settle' before you're 'too old'.","steps":[{"prompt":"She brings it up again over coffee, this time about someone specific she knows. What do you do?","options":[{"text":"Say you'd rather wait for the right fit than settle","then":"She pauses, then admits she hadn't really thought about it that way.","best":true},{"text":"Agree to meet them just to stop the nudging","then":"You spend an evening on a match you never actually wanted."},{"text":"Lower your standards a little to seem less picky","then":"You leave the coffee feeling smaller than when you arrived."},{"text":"Snap that she should worry about her own life","then":"The friendship takes a hit over a comment that came from care."}],"why":"Naming your own standard, calmly, protects it without needing to attack her concern."},{"prompt":"A week later, she apologises, saying she was just worried about you being alone. What do you do?","options":[{"text":"Thank her, and explain waiting isn't the same as being unhappy","then":"She nods, relieved, and seems to actually understand this time.","best":true},{"text":"Accept the apology without explaining further","then":"The underlying worry stays exactly where it was, unaddressed."},{"text":"Say her worry was out of line","then":"She feels judged for a concern that came from care."},{"text":"Reassure her a lot, more than the moment needs","then":"The reassurance ends up centring her feelings over the actual point."}],"why":"Naming that waiting and being unhappy aren't the same thing answers the worry at its root."},{"prompt":"Months later, at a group dinner, she jokes that you're 'the last one left'. What do you do?","options":[{"text":"Laugh, and say you're in no hurry and happy as you are","then":"The table laughs with you, and the joke loses its edge.","best":true},{"text":"Laugh along, then lie awake wondering if she's right","then":"By morning, you're scrolling matrimonial sites, feeling behind."},{"text":"List every date that didn't work out, to explain","then":"The table gets curious, and the questions run through dessert."},{"text":"Call her out sharply in front of everyone","then":"The table goes quiet, and she apologises stiffly for the rest of the night."}],"why":"Laughing it off while saying you're happy and unhurried takes the sting out of 'last one left'."},{"prompt":"A year on, you run into her at a wedding. What do you do?","options":[{"text":"Say honestly you're glad you waited","then":"She agrees, and admits she's stopped worrying about your timeline entirely.","best":true},{"text":"Feel you need to justify a whole year of waiting to her","then":"The justification undoes a confidence you'd actually earned."},{"text":"Ask if she still thinks you should settle","then":"It reopens a debate that had genuinely closed months ago."},{"text":"Avoid the topic entirely, unsure how she feels now","then":"You miss a chance to hear that her worry had actually eased."}],"why":"Saying plainly that you're glad you waited shows her that waiting was a choice, not a loss."}],"debrief":"There's no boat to miss; a pressure-driven match causes more regret than waiting for the right fit.","relearn":"Wait for the right fit; a pressure-driven match brings more regret than waiting."},
  {"id":"yp-1014","cat":"hold-your-ground","type":"branch","persona":"any","source":"not a prop","hook":"Your sibling pressures you to marry so the family 'looks complete' for an upcoming function.","steps":[{"prompt":"He brings it up again while planning the guest list. What do you do?","options":[{"text":"Say your life isn't a prop for how the family looks","then":"He goes quiet, like he hadn't heard it put that plainly before.","best":true},{"text":"Agree to at least 'consider it' for the function's sake","then":"You say you'll consider it, and he takes that as a good sign for the function."},{"text":"Get defensive about being single","then":"The conversation turns into a fight about your life choices generally."},{"text":"Suggest trimming the guest list instead of the topic","then":"He says that's not really the point, and brings it back to marriage."}],"why":"Naming your life as your own, not an appearance to manage, separates the two clearly."},{"prompt":"Later, your mother joins the guest-list talk and says 'it would just look nicer' with everyone paired off. What do you do?","options":[{"text":"Say kindly that looking nice isn't a reason to marry","then":"She pauses, considering it, and doesn't push further.","best":true},{"text":"Let the comment pass without addressing it","then":"It gets repeated at the actual function by someone else."},{"text":"Get sharp with her for the comment","then":"It turns a small comment into a bigger family moment than needed."},{"text":"Say you'll 'think about bringing someone' to keep them happy","then":"It sets up an awkward expectation you'll have to manage at the event."}],"why":"Naming it kindly, in the moment, stops the idea from quietly becoming the plan."},{"prompt":"At the function itself, a relative comments on the seating looking 'a little empty' near you. What do you do?","options":[{"text":"Brush it off lightly and enjoy the event as it is","then":"The comment fades quickly, and the rest of the evening feels easy.","best":true},{"text":"Feel embarrassed through the rest of the function","then":"The embarrassment costs you an evening you could have actually enjoyed."},{"text":"Explain to the relative why the seating is the way it is","then":"It turns a passing comment into a longer, unnecessary conversation."},{"text":"Leave the function early","then":"You miss the parts of it that had nothing to do with the comment."}],"why":"Letting a passing comment stay small keeps one remark from shaping your whole evening."},{"prompt":"After the function, your sibling admits the comments were more about his own stress than about you. What do you do?","options":[{"text":"Accept that, and say your life still isn't a prop for appearances","then":"He agrees, and says he'll push back on that kind of comment next time.","best":true},{"text":"Say you already knew that","then":"It closes off a moment where he was actually being honest with you."},{"text":"Let it go without naming the actual point","then":"The underlying idea about appearances never really gets corrected."},{"text":"Bring up every other time appearances mattered more than you","then":"It turns a good, honest moment into an old list of grievances."}],"why":"Accepting his honesty while keeping your point lets you repair things without dropping it."}],"debrief":"Your life isn't a prop for appearances; a wedding to 'complete the picture' isn't a freely-made choice.","relearn":"Your life isn't a prop for how the family looks; choose it for yourself."},
  {"id":"yp-1015","cat":"hold-your-ground","type":"branch","persona":"Karthik","source":"joint call not power play","hook":"Male relatives push you to 'put your foot down' and demand a child from your partner.","steps":[{"prompt":"Your uncle brings it up at a family gathering, half joking, half serious. What do you do?","options":[{"text":"Refuse to override your partner, and keep it a joint call","then":"He looks a little surprised, but drops the topic.","best":true},{"text":"Nod along, not wanting to argue at a family event","then":"He takes the nod as agreement, and mentions it to others."},{"text":"Say you'll 'talk to her about it', meaning to push her","then":"It sets up a conversation at home built on pressure, not partnership."},{"text":"Laugh it off without actually addressing the idea","then":"He repeats the same line at the next gathering, undeterred."}],"why":"Naming it a joint decision, plainly, refuses the 'put your foot down' framing at the source."},{"prompt":"At home, your partner asks how the gathering went. What do you say?","options":[{"text":"Tell her honestly what he said, and how you answered","then":"She listens closely, taking in exactly what was said and how you responded.","best":true},{"text":"Leave out the comment, not wanting to stress her","then":"She hears about it secondhand later, and wonders why you didn't say."},{"text":"Mention it, but say he 'has a point'","then":"It turns a family comment into pressure inside your own home."},{"text":"Joke about it to lighten the mood","then":"The joke undercuts whatever weight the moment actually had."}],"why":"Telling her honestly, and how you actually responded, keeps the partnership itself honest too."},{"prompt":"Weeks later, a different relative asks if you're 'finally taking charge'. What do you do?","options":[{"text":"Say plainly it was never yours to take charge of alone","then":"He looks unsure how to respond to that.","best":true},{"text":"Say things are 'in progress' to satisfy the question","then":"It implies a plan that isn't really there, and invites follow ups."},{"text":"Get annoyed at being asked at all","then":"The annoyance becomes the story, rather than the actual, clear answer."},{"text":"Deflect by saying it's a private matter","then":"He nods and drops it, though the 'taking charge' framing stands unanswered."}],"why":"Correcting the framing directly, not just deflecting it, answers the actual idea behind the question."},{"prompt":"Months later, your uncle mentions, almost admiringly, that you and your partner 'really talk things through'. What do you do?","options":[{"text":"Say that's exactly how it should work, between the two of you","then":"He nods, like something's actually shifted in how he sees it.","best":true},{"text":"Say 'finally you get it'","then":"It turns a moment of him coming around into a small jab."},{"text":"Downplay it, unsure if he really means it","then":"A genuine shift in his thinking goes unacknowledged."},{"text":"Credit your partner entirely for how well you communicate","then":"It quietly writes you back out of a partnership you actually held."}],"why":"Agreeing that talking it through is how it should work affirms the partnership without a jab."}],"debrief":"A child is a joint call, not a man's to demand; partnership beats 'putting your foot down'.","relearn":"A child is a joint call, not a man's to demand; partnership over power plays."},
  {"id":"yp-1016","cat":"hold-your-ground","type":"branch","persona":"Sneha","source":"let pity pass","hook":"An aunty pities you openly at a wedding: 'poor thing, all alone'.","steps":[{"prompt":"She says it loudly enough for the table to hear. What do you do?","options":[{"text":"Let the pity pass; it's her script, not your truth","then":"You turn back to your food, and the pity rolls right off.","best":true},{"text":"Correct her in detail about how full your life actually is","then":"The detailed correction reads as needing to prove something."},{"text":"Take the pity on board and feel a flash of shame","then":"The rest of the wedding feels heavier than it needs to."},{"text":"Snap that she doesn't know your life","then":"The table goes tense, and her pity somehow gets more attention."}],"why":"Letting the comment pass, without absorbing it, keeps her script from becoming your reality."},{"prompt":"Later, a cousin asks quietly if that comment got to you. What do you say?","options":[{"text":"Wonder aloud if the aunty has a point","then":"The cousin hesitates, and now you're both turning the aunty's words over."},{"text":"Say how it really felt, and that your life is full","then":"The cousin squeezes your arm. \"She says that to every single woman here.\"","best":true},{"text":"Say you're used to it, so it doesn't matter","then":"It sounds resigned rather than actually unbothered."},{"text":"Ask the cousin what she thinks of the comment","then":"She shrugs, and you find yourself waiting on her verdict about your life."}],"why":"Being honest about how it felt, while naming your full life, keeps her pity from becoming your story."},{"prompt":"At the next family wedding, you spot the same aunty heading your way. What do you do?","options":[{"text":"Greet her warmly and let whatever she says pass","then":"When the pity comes, it barely registers, and you head for the dance floor.","best":true},{"text":"Prepare a comeback in advance, just in case","then":"The prepared comeback makes the moment feel bigger than it is."},{"text":"Avoid her section of the hall this time","then":"Avoiding her costs you time with people you'd actually enjoy seeing."},{"text":"Ask someone to warn you if she's coming over","then":"It keeps you braced for a comment that's actually easy to let pass now."}],"why":"Greeting her warmly and letting the pity pass keeps your evening yours, not hers to shape."}],"debrief":"Others' pity about being unmarried isn't your truth; it reveals the script's bias, not your reality.","relearn":"Let pity pass; it's someone else's script, not your truth."},
  {"id":"yp-1017","cat":"hold-your-ground","type":"branch","persona":"Aditya","source":"refuse to erase","hook":"Your family pressures you to enter a 'normal' marriage and hide your partner of five years.","steps":[{"prompt":"Your father brings it up again, gently but firmly, over dinner. What do you do?","options":[{"text":"Gently refuse to hide the relationship you already have","then":"He goes quiet, clearly not the answer he expected.","best":true},{"text":"Believe that keeping the peace now will make this easier later","then":"He takes your quiet as room to keep planning a 'normal' match."},{"text":"Get angry and leave the table","then":"The anger becomes the story of the evening, not the actual relationship."},{"text":"Believe he only needs time, so there's nothing to say yet","then":"He keeps hoping the topic will resolve on its own, and the planning carries on."}],"why":"A gentle, clear no protects your integrity without closing the door on your father."},{"prompt":"Your mother later asks, in private, if you're 'sure this is really who you are'. What do you say?","options":[{"text":"Tell her honestly that your partner is a real part of your life","then":"She's quiet a long moment, taking in something she hadn't let herself hear.","best":true},{"text":"Wonder if you owe her a version she can accept","then":"You start rehearsing a smaller truth in your head, and she waits, unsure what you're thinking."},{"text":"Get defensive about being asked at all","then":"She retreats, and a conversation that could have opened something closes."},{"text":"Believe her question means she will never accept you","then":"You brace for the worst, and the talk ends before she can say more."}],"why":"Honest words give her something real to hold. When and how much you share is yours to judge."},{"prompt":"A week later, after another tense family call, you feel worn down and alone with it. What do you do?","options":[{"text":"Talk it through with your partner and a trusted friend","then":"With people on your side listening, the weight feels easier to carry.","best":true},{"text":"Believe you have to handle your family by yourself","then":"You carry the call alone, and it replays in your head all night."},{"text":"Wonder if you're being selfish by not giving in","then":"The doubt sits heavier on you than the call itself did."},{"text":"Hide the calls from your partner so they won't worry","then":"Your partner senses something's wrong, and you both feel further apart."}],"why":"Leaning on your partner and a trusted friend means you don't carry this pressure alone."},{"prompt":"Your father asks, quietly, what you actually want for your future. What do you say?","options":[{"text":"Say you want a life with the partner you already have","then":"He doesn't fully understand yet, but for the first time, he actually listens.","best":true},{"text":"Believe you should have it all figured out before you answer","then":"He waits while you search for the perfect answer, and the moment passes."},{"text":"Wonder if he could ever cope with the real answer","then":"You hold back, and the evening stays calm while your real answer waits."},{"text":"Ask him what he wants instead","then":"He says he wants you safe and settled, and your own answer is still unsaid."}],"why":"Naming what you truly want gives him something real to come around to, whenever you feel able."},{"prompt":"Months later, your father, still working through it, asks if your partner would like to come for dinner. What do you do?","options":[{"text":"Say yes, and thank him for asking","then":"It's a small, real step, and the dinner that follows is easier than either of you expected.","best":true},{"text":"Say yes, expecting one dinner to settle everything","then":"The dinner is warm, but you leave let down that one evening didn't change more."},{"text":"Push for a bigger gesture before agreeing to anything","then":"It turns a real, if small, step into something that feels like a test."},{"text":"Accept, but ask your partner to come as a friend","then":"It asks your partner to hide the relationship again, just for the evening."}],"why":"A warm yes to a small, real step lets your father keep moving toward your actual life."}],"debrief":"You can love your family and still refuse to erase your real partnership; the pressure to hide was never your fault.","relearn":"Refuse to erase your real partnership to make others comfortable."},
  {"id":"yp-1018","cat":"hold-your-ground","type":"branch","persona":"any","source":"opt out early","hook":"A WhatsApp group of relatives starts a thread about 'fixing' your marriage.","steps":[{"prompt":"The thread already has a dozen replies by the time you see it. What do you do?","options":[{"text":"Politely opt out and ask them to drop the topic","then":"The thread goes quiet on the subject within the hour.","best":true},{"text":"Stay silent and watch the thread grow","then":"By evening, the thread has moved from discussing to planning."},{"text":"Leave the group without a word","then":"An aunty adds you back within the hour, and the thread is still going."},{"text":"Reply to every message individually","then":"Each reply seems to invite three more messages back."}],"why":"One polite message, where everyone can see it, sets the limit before plans take shape."},{"prompt":"A relative messages you privately, apologising for the thread but hoping you'll 'at least consider it'. What do you do?","options":[{"text":"Thank them, and say plainly the topic is closed","then":"They accept it, and don't bring it up again in the group.","best":true},{"text":"Say you'll 'think about it' to be polite","then":"It leaves the door open for more messages like this one."},{"text":"Leave the private message unanswered","then":"They assume you simply missed it, and try again later."},{"text":"Ask them to convince the rest of the group for you","then":"It puts them in an awkward spot instead of you handling it directly."}],"why":"A plain, kind answer in private closes a door a polite apology tried to reopen."},{"prompt":"Weeks later, a new relative joins the family group and starts the topic up again. What do you do?","options":[{"text":"State the boundary plainly, for the new person","then":"A couple of cousins back you up, and the thread moves on.","best":true},{"text":"Assume the group already knows and say nothing","then":"The new relative has no idea, and the thread starts building again."},{"text":"Leave the group, tired of the whole topic","then":"You miss the rest of the group's actual news, not just the topic."},{"text":"Get sharp with the new relative for not knowing","then":"The new relative looks taken aback, having only just joined the group."}],"why":"Stating the limit plainly for the newcomer keeps it clear to everyone, without heat."}],"debrief":"Opting out early and asking them to drop it sets the limit before group pressure snowballs.","relearn":"Opt out early and ask them to drop it before group pressure snowballs."},
  {"id":"yp-1019","cat":"hold-your-ground","type":"branch","persona":"any","source":"don't trade for approval","hook":"A relative threatens the 'silent treatment' until you agree to marry.","steps":[{"prompt":"The calls stop overnight, right after your last clear no. What do you do?","options":[{"text":"Hold steady, and lean on a friend while you wait it out","then":"The silence is uncomfortable, but the choice stays exactly yours, and you're not carrying it alone.","best":true},{"text":"Believe that a little hinting might fix the silence faster","then":"The hint changes nothing. The silence continues, now with your hesitation baked into it."},{"text":"Ignore the silence and hope it resolves on its own","then":"It stretches on longer without anyone actually addressing it."},{"text":"Ask other relatives to intervene on your behalf","then":"It turns a private disagreement into a wider family affair."}],"why":"Holding steady, with support, keeps the decision yours; withdrawn approval was never a fair price to pay."},{"prompt":"A week in, a cousin mentions the relative is 'really hurt' by the silence. What do you do?","options":[{"text":"Say you understand, but the choice still stands","then":"The cousin nods, seeing there's no opening to push for a change.","best":true},{"text":"Feel guilty enough to consider reaching out first","then":"You draft a message reaching out, then don't send it. The guilt stays, unresolved."},{"text":"Ask the cousin to relay a longer explanation","then":"The explanation, secondhand, gets twisted into something you didn't say."},{"text":"Say the relative's hurt isn't your problem","then":"The cousin looks surprised by the bluntness and doesn't say much after."}],"why":"Naming that you understand the hurt, without caving to it, keeps empathy and boundary both intact."},{"prompt":"Two weeks on, the relative finally calls, testing whether you've changed your mind. What do you do?","options":[{"text":"Answer warmly, and confirm nothing's changed","then":"The relative goes quiet, unsure what to say next.","best":true},{"text":"Assume warmth means you also owe them a reconsideration","then":"The relative senses an opening, and picks the pressure right back up."},{"text":"Stay cold in return, to match the treatment you got","then":"It turns a boundary into a standoff neither side actually wins."},{"text":"Assume avoiding the call keeps things simple","then":"The uncertainty leaves the relative free to try again another way."}],"why":"Warmth plus an unchanged answer shows the silent treatment didn't actually move anything."},{"prompt":"Months later, the relative mentions, almost sheepishly, that the silence 'wasn't really fair'. What do you do?","options":[{"text":"Accept it, say the silence did hurt, and that you're glad to talk again","then":"The relative goes quiet, then says sorry. The relationship settles into something steadier.","best":true},{"text":"Say 'I told you so'","then":"It turns a genuine, if late, admission into a small win instead of a repair."},{"text":"Ask for a full apology for every single week of the silence","then":"The relative stiffens, and the apology turns into a debate about who hurt whom."},{"text":"Downplay it so the relative doesn't feel too bad","then":"The relative seems relieved to move past it without really addressing it."}],"why":"Accepting the admission while saying it hurt lets the relationship heal honestly."}],"debrief":"A calm, held boundary beats trading your life choice for someone's approval; the silence was never your fault.","relearn":"Hold steady; don't trade your life choice for withdrawn approval."},
  {"id":"yp-1020","cat":"hold-your-ground","type":"branch","persona":"any","source":"stop over-explaining","hook":"You realise you keep over explaining your single life to everyone who asks.","steps":[{"prompt":"A new colleague asks, casually, why you're not married yet. What do you do?","options":[{"text":"Switch to one calm sentence and stop justifying","then":"She nods, satisfied, and the conversation moves on naturally.","best":true},{"text":"Launch into the usual long explanation","then":"She listens politely, though it's clearly more than the question needed."},{"text":"Say it's none of her business","then":"The short reply lands sharper than the casual question deserved."},{"text":"Deflect with a joke that doesn't really answer","then":"She laughs, but asks a genuine follow up question anyway."}],"why":"One calm sentence answers the question fully, without inviting the long defence you've been giving."},{"prompt":"That evening, you notice how drained these questions leave you, week after week. What do you do?","options":[{"text":"Decide to try a shorter, calmer answer from now on","then":"The next time it comes up, it actually takes less energy.","best":true},{"text":"Assume a shorter answer would only work with new people","then":"You keep giving the long explanation to anyone who already knows you."},{"text":"Wonder if a shorter answer would seem 'too closed off'","then":"The worry talks you out of trying something that might actually help."},{"text":"Plan to save a longer version for people you're 'closer to'","then":"The 'closer' list somehow includes almost everyone you talk to regularly."}],"why":"Choosing to try what feels lighter is worth trusting, even if it breaks an old habit."},{"prompt":"A month later, an old friend asks the same question, expecting the usual long answer. What do you do?","options":[{"text":"Give one short, calm sentence","then":"She's a little surprised, then says she likes this version better too.","best":true},{"text":"Feel you owe her the longer version since she's known you a while","then":"The longer version returns, and with it, the old exhaustion."},{"text":"Apologise for 'being short' with her","then":"The apology undoes a boundary that never needed excusing."},{"text":"Explain why you've changed how you answer this","then":"It becomes its own long explanation, replacing the one you were dropping."}],"why":"One calm sentence beats over justifying, even with people who've heard the long version before."}],"debrief":"One calm sentence beats constant self-justification; you don't owe anyone a defence of your own life.","relearn":"One calm sentence beats over-explaining; you owe no defence of your life."},
  {"id":"yp-1021","cat":"hold-your-ground","type":"branch","persona":"any","source":"tender but honest","hook":"Your grandmother, frail and loving, begs you to marry 'before she goes'.","steps":[{"prompt":"She holds your hand and asks for a wedding date this year. What do you do?","options":[{"text":"Tell her gently you won't promise a date you don't mean","then":"She sighs, squeezes your hand, and asks how work is going instead.","best":true},{"text":"Promise a date to comfort her, planning to explain later","then":"She brightens and starts telling relatives. Explaining later feels heavier now."},{"text":"Change the subject to something she loves talking about","then":"She lets it go for now, and the question sits unanswered between you."},{"text":"Avoid visiting so the topic never comes up at all","then":"You miss her stories for weeks, and the question waits behind your absence."}],"why":"A promise you don't mean isn't real comfort; honesty with warmth respects her too."},{"prompt":"A week later, your mother calls, anxious about grandma, and asks what's going on. What do you do?","options":[{"text":"Tell her honestly that you won't marry on a deadline","then":"Your mother goes quiet, then says she just worries about her mother.","best":true},{"text":"Agree to 'think about it seriously' just to end the call","then":"Your mother relaxes, thinking you're close to yes, and asks about venues next week."},{"text":"Tell her plainly it isn't her business to ask","then":"The call turns tense, and she brings it up again within days."},{"text":"Say nothing much and change the topic fast","then":"The question isn't answered, only postponed to the next call."}],"why":"Telling your mother the truth now means one honest answer, not a story to untangle later."},{"prompt":"At the next family gathering, your grandmother takes your hand and brings up the wedding again. What do you say?","options":[{"text":"Say you hear her love, and the timing stays yours","then":"Her eyes fill a little. Then she pats your hand and says she trusts you.","best":true},{"text":"Promise to 'try harder' for her sake this year","then":"She looks hopeful again, and next month she asks for an update."},{"text":"Get defensive that she keeps asking again","then":"The mood turns awkward, and she looks hurt for the rest of the evening."},{"text":"Joke it off and quickly leave the room","then":"She laughs along, but the question stays unresolved between you both."}],"why":"Naming that you hear her, without a promise, keeps the tenderness and the truth."}],"debrief":"You can hold a loved one's tenderness and keep your timeline honest; a yes you don't mean isn't real kindness.","relearn":"Hold a loved one's tenderness and still keep your timeline honest."},
  {"id":"yp-1022","cat":"hold-your-ground","type":"branch","persona":"any","source":"hold without escalating","hook":"After your clear no, a relative escalates to 'then you're not welcome here'.","steps":[{"prompt":"He says it loud enough for the whole room to hear. What do you do?","options":[{"text":"Stay calm and hold your ground","then":"The room quiets. He mutters and looks away, but the door stays open from your side.","best":true},{"text":"Match his tone and threaten never to come back","then":"The argument gets louder, and two cousins step in to referee."},{"text":"Apologise on the spot and quietly take the no back","then":"He relaxes, but the no you meant is gone, replaced by his terms."},{"text":"Walk out immediately without saying a word","then":"You leave the tension unresolved, and people talk about it after you're gone."}],"why":"Staying warm and firm holds the line without matching his cut-off."},{"prompt":"A few days later, an aunt calls. The family is still talking about what happened, and she says they only want peace. What do you do?","options":[{"text":"Say peace doesn't mean giving up your own life","then":"She sighs, but says she understands, even if she'd have chosen differently.","best":true},{"text":"Say you probably went too far, to smooth things","then":"She nods, relieved, but the no you meant gets quietly softened in the retelling."},{"text":"Ask her to talk to him on your behalf","then":"She looks uncomfortable and says this isn't hers to fix."},{"text":"Say nothing and let the moment pass","then":"She takes your silence as agreement and moves on."}],"why":"Owning your choice, even under a second voice, keeps it yours to hold."},{"prompt":"A month later, the same relative calls to 'clear the air'. What do you do?","options":[{"text":"Take the call and calmly say where you really stand","then":"He's quieter this time. He says he was upset, not that he's changed his mind.","best":true},{"text":"Let the call go to voicemail indefinitely","then":"The tension lingers unresolved, waiting for the next gathering."},{"text":"Use the call to relitigate everything he said","then":"The old argument reheats, and you hang up more tired than before."},{"text":"Agree to whatever he wants to end the awkwardness","then":"The call ends easily, but your earlier no quietly disappears."}],"why":"Answering calmly, without reopening old fights, keeps your answer your own."}],"debrief":"Hold your no warmly and leave the door open from your side; you needn't match a cut-off with cruelty.","relearn":"Hold your no warmly and leave the door open; you needn't match a cut-off."},
  {"id":"yp-1023","cat":"hold-your-ground","type":"branch","persona":"any","source":"firm loving no","hook":"Your uncle keeps circling back to marriage talk, and you need a firm but loving no.","steps":[{"prompt":"He asks when you'll 'finally settle down'. What do you say?","options":[{"text":"Say plainly it's a no for now, and ask him to respect it","then":"He pauses, then nods and changes the subject to cricket.","best":true},{"text":"Say maybe later, just to buy some peace this evening","then":"He brightens, thinking maybe means soon, and brings it up again next week."},{"text":"Quietly agree to meet someone once, just to end the topic","then":"He looks pleased, and a profile lands in your inbox by evening."},{"text":"Snap that he should really mind his own life and business","then":"He looks stung, and the dinner turns awkward for the rest of the evening."}],"why":"A plain no on record is kinder than a maybe you'll have to walk back later."},{"prompt":"Later, he tells your parents his own version of what happened. What do you do?","options":[{"text":"Tell your parents yourself where you stand","then":"Your mother looks relieved to hear it straight from you.","best":true},{"text":"Let your parents believe whatever he told them","then":"The mix-up spreads, and you spend the next visit correcting it."},{"text":"Call your uncle to argue about what he said","then":"The call turns into a rehash of the same argument."},{"text":"Avoid your parents' next few calls entirely","then":"The confusion sits unanswered, and your mother starts to worry."}],"why":"Telling your parents yourself keeps your own words from being rewritten by someone else."},{"prompt":"At the next gathering, your uncle raises it once more, gently this time. What do you say?","options":[{"text":"Thank him for caring, then give a clear, kind no","then":"He smiles and says fair enough, then asks about your work instead.","best":true},{"text":"Give a long explanation of all your reasons","then":"He listens, but treats it as an opening to debate each one."},{"text":"Ignore the question and leave the table","then":"He looks puzzled, and the tension carries into dessert."},{"text":"Agree to look at one profile, to end the topic","then":"He looks satisfied, but you've traded your answer for a quiet evening."}],"why":"A short, warm no says it clearly without reopening the debate."}],"debrief":"You can say a firm-but-loving no and ask for it to be respected, rather than caving to end discomfort.","relearn":"Say a firm-but-loving no and ask for it to be respected."},
  {"id":"yp-1024","cat":"hold-your-ground","type":"sort","persona":"any","source":"warm or war","relearn":"A kind, firm boundary holds the line warmly; insults and cut-offs turn a boundary into a war.","hook":"Sort: a warm-but-firm boundary, or escalating into a family war?","items":[{"id":"a","text":"\"This is my decision, kindly.\""},{"id":"b","text":"Calling them backward and storming out"},{"id":"c","text":"Changing the subject gently"},{"id":"d","text":"Threatening to cut everyone off"},{"id":"e","text":"\"I love you, and my answer stands.\""},{"id":"f","text":"Trading insults to 'win'"}],"bins":[{"id":"warm","label":"Warm-but-firm","valence":"pos"},{"id":"war","label":"Starts a war","valence":"neg"}],"key":{"a":"warm","b":"war","c":"warm","d":"war","e":"warm","f":"war"}},
  {"id":"yp-1025","cat":"hold-your-ground","type":"sort","persona":"any","source":"yours or theirs","relearn":"The decision to marry or have kids is yours; 'log kya kahenge' and elders' approval are pressures, not your obligation.","hook":"Sort: actually your call, or just pressure dressed as duty?","items":[{"id":"a","text":"Whether you marry"},{"id":"b","text":"\"What will people say?\""},{"id":"c","text":"Whether you have children"},{"id":"d","text":"Beating an 'age deadline'"},{"id":"e","text":"Whom you marry, if anyone"},{"id":"f","text":"Earning relatives' approval"}],"bins":[{"id":"yours","label":"Your call","valence":"neutral"},{"id":"pressure","label":"Just pressure","valence":"neg"}],"key":{"a":"yours","b":"pressure","c":"yours","d":"pressure","e":"yours","f":"pressure"}},
  {"id":"yp-1026","cat":"hold-your-ground","type":"sort","persona":"any","source":"deflect or defend","relearn":"A short, closed line deflects a nosy question; long defences and apologies feed the pressure.","hook":"Sort: a clean deflection, or feeding the pressure?","items":[{"id":"a","text":"\"I'm happy as I am, thanks.\""},{"id":"b","text":"A ten-minute justification"},{"id":"c","text":"\"How's your week going?\""},{"id":"d","text":"Apologising for being single"},{"id":"e","text":"\"That's settled, more chai?\""},{"id":"f","text":"Listing reasons to convince them"}],"bins":[{"id":"deflect","label":"Clean deflection","valence":"pos"},{"id":"feed","label":"Feeds the pressure","valence":"neg"}],"key":{"a":"deflect","b":"feed","c":"deflect","d":"feed","e":"deflect","f":"feed"}},
  {"id":"yp-1027","cat":"hold-your-ground","type":"sort","persona":"any","source":"freely chosen or coerced","relearn":"A yes you choose is freely given; a yes to stop tears, threats or silence is coerced, not real.","hook":"Sort: a freely-chosen yes, or one squeezed out of you?","items":[{"id":"a","text":"\"Yes, because I want this.\""},{"id":"b","text":"Saying yes to stop the tears"},{"id":"c","text":"Choosing after honest thought"},{"id":"d","text":"Agreeing under a silent treatment"},{"id":"e","text":"Saying yes in your own time"},{"id":"f","text":"Caving to an ultimatum"}],"bins":[{"id":"free","label":"Freely chosen","valence":"pos"},{"id":"coerced","label":"Squeezed out","valence":"neg"}],"key":{"a":"free","b":"coerced","c":"free","d":"coerced","e":"free","f":"coerced"}},
  {"id":"yp-1060","cat":"hold-your-ground","type":"sort","persona":"any","source":"respects or dictates","relearn":"People who respect your path support and ask; those who dictate guilt-trip, threaten and decide for you.","hook":"Sort: someone who respects your path, or one who's trying to dictate it?","items":[{"id":"a","text":"\"Whatever you choose, I'm with you.\""},{"id":"b","text":"\"Do it or I'll stop speaking to you.\""},{"id":"c","text":"\"Want to talk it through?\""},{"id":"d","text":"\"You're shaming us all.\""},{"id":"e","text":"\"Your timeline, your call.\""},{"id":"f","text":"\"I've already picked the date.\""}],"bins":[{"id":"respects","label":"Respects your path","valence":"pos"},{"id":"dictates","label":"Tries to dictate","valence":"neg"}],"key":{"a":"respects","b":"dictates","c":"respects","d":"dictates","e":"respects","f":"dictates"}},
  {"id":"yp-1028","cat":"hold-your-ground","type":"sort","persona":"any","source":"steadies or erodes","relearn":"Supportive people and a held boundary steady you; absorbing pity and shame erodes your confidence.","hook":"Sort: steadies your confidence, or erodes it under pressure?","items":[{"id":"a","text":"People who respect your path"},{"id":"b","text":"Replaying every cruel comment"},{"id":"c","text":"A boundary you actually keep"},{"id":"d","text":"Taking pity on board as truth"},{"id":"e","text":"Reflecting away from the noise"},{"id":"f","text":"Measuring yourself by the market"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"erode","label":"Erodes you","valence":"neg"}],"key":{"a":"steady","b":"erode","c":"steady","d":"erode","e":"steady","f":"erode"}},
  {"id":"yp-1029","cat":"hold-your-ground","type":"reflect","persona":"any","source":"love and a boundary","relearn":"Loving your family and holding your own choices aren't opposites; you can hold both at once.","hook":"Lensy: you can love your family AND keep your own life choices. Both at once?","prompt":"What feels true?","options":["Yes","Love and a boundary","Both"],"affirm":"Loving your family and holding your own choices aren't opposites; you can hold both at once."},
  {"id":"yp-1030","cat":"hold-your-ground","type":"reflect","persona":"any","source":"self-respect","relearn":"Standing kindly but firmly for your choices is self-respect in action, and it gets easier with practice.","hook":"Lensy: holding your ground kindly is a quiet act of self-respect. Worth practising?","prompt":"What do you think?","options":["Yes","Quiet self-respect","Worth it"],"affirm":"Standing kindly but firmly for your choices is self-respect in action, and it gets easier with practice."},
  {"id":"yp-1031","cat":"hold-your-ground","type":"reflect","persona":"any","source":"a kind no","relearn":"A clear, repeated no, kindly delivered, isn't unkind: it's honest; you're allowed to mean it.","hook":"Lensy: a calm 'no', repeated, isn't unkind. How does that sit with you?","prompt":"What feels true?","options":["It sits right","A no can be kind","Still learning it"],"affirm":"A clear, repeated no, kindly delivered, isn't unkind: it's honest; you're allowed to mean it."},
  {"id":"yp-1032","cat":"hold-your-ground","type":"reflect","persona":"any","source":"owe no defence","relearn":"You don't owe anyone a justification for your single, childfree or chosen life; one calm line is enough.","hook":"Lensy: you don't owe anyone a defence of your own life. Notice that?","prompt":"What do you think?","options":["Yes","I owe no defence","Freeing"],"affirm":"You don't owe anyone a justification for your single, childfree or chosen life; one calm line is enough."},
  {"id":"yp-1033","cat":"hold-your-ground","type":"reflect","persona":"any","source":"not your obligation","relearn":"'What will people say' is a powerful pressure, but it was never your obligation to obey.","hook":"Lensy: 'log kya kahenge' is social pressure, not your obligation. Sit with that.","prompt":"What feels true?","options":["True","Pressure, not duty","Letting it go"],"affirm":"'What will people say' is a powerful pressure, but it was never your obligation to obey."},
  {"id":"yp-1034","cat":"hold-your-ground","type":"reflect","persona":"any","source":"support is strength","relearn":"Reaching for a counsellor or trusted person under heavy pressure is strength: you don't have to carry it alone.","hook":"Lensy: when pressure gets heavy, support is strength, not weakness. Agree?","prompt":"What do you think?","options":["Yes","Support is strength","Good to remember"],"affirm":"Reaching for a counsellor or trusted person under heavy pressure is strength: you don't have to carry it alone."},
  {"id":"yp-1035","cat":"hold-your-ground","type":"reflect","persona":"any","source":"warm and firm","relearn":"Warmth and firmness aren't opposites; you can hold your line without going cold or going to war.","hook":"Lensy: you can stay warm even while you hold a firm line. Picture it?","prompt":"What feels true?","options":["I can","Warm and firm","Practising"],"affirm":"Warmth and firmness aren't opposites; you can hold your line without going cold or going to war."},
  {"id":"yp-1036","cat":"hold-your-ground","type":"reflect","persona":"any","source":"my reasons my call","relearn":"Who gets your reasons, and when, is your choice; not every question has earned a full answer.","hook":"Lensy: choosing whom and when you trust with your reasons is yours too. Notice?","prompt":"What do you think?","options":["Yes","My reasons, my call","Hadn't thought of it"],"affirm":"Who gets your reasons, and when, is your choice; not every question has earned a full answer."},
  {"id":"yp-1037","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"respect and autonomy","relearn":"You can respect your family and still make your own life choices.","hook":"\"Resisting the marriage push means you're disrespecting your family.\"","myth":{"un":"Resisting the push means disrespecting your family.","re":"You can respect your family AND make your own life choices; the two aren't opposites.","why":"Autonomy and love coexist; a boundary isn't an insult."}},
  {"id":"yp-1038","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"peace isn't a forced yes","relearn":"Caring doesn't mean saying a yes you don't mean to keep the peace.","hook":"\"If you really cared, you'd just say yes to keep the peace.\"","myth":{"un":"Caring means saying yes to keep the peace.","re":"Caring doesn't require a yes you don't mean; a chosen no can be the more honest, loving answer.","why":"A yes given under pressure isn't peace, it's postponed conflict."}},
  {"id":"yp-1039","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"firm can be warm","relearn":"A no can be firm and warm at once; clarity delivered kindly is respect, not rudeness.","hook":"\"A firm 'no' to relatives is rude and you'll regret it.\"","myth":{"un":"A firm no to relatives is just rude.","re":"A no can be both firm and warm; clarity delivered kindly is respect, not rudeness.","why":"Warmth and firmness coexist; people can disagree and stay close."}},
  {"id":"yp-1040","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"boundary isn't rupture","relearn":"A calm, kind boundary holds your ground without tearing the family apart.","hook":"\"Holding your ground will tear the family apart.\"","myth":{"un":"Holding your ground will tear the family apart.","re":"A calm, kind boundary holds your ground without rupture; it's escalation, not the boundary, that ruptures.","why":"Boundaries protect relationships; warmth keeps the door open."}},
  {"id":"yp-1041","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"owe no justification","relearn":"You owe no one a justification for your life; one calm line is a complete answer.","hook":"\"You have to explain and justify your single life to everyone who asks.\"","myth":{"un":"You must justify your single life to everyone who asks.","re":"You owe no one a justification for your life; a short, calm line is a complete answer.","why":"A nosy question doesn't create an obligation to explain."}},
  {"id":"yp-1042","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"not selfish to choose","relearn":"Choosing your own life isn't selfish; it's the dignity you'd grant anyone you love.","hook":"\"Standing up to the pressure just proves you're selfish and stubborn.\"","myth":{"un":"Standing up to the pressure proves you're selfish.","re":"Choosing your own life isn't selfish; it's the same right you'd gladly grant anyone you love.","why":"Self-direction isn't selfishness; it's basic dignity."}},
  {"id":"yp-1043","cat":"hold-your-ground","type":"strike-rewrite","persona":"any","source":"held line keeps family","relearn":"A kept boundary rarely ends a loving family; you can hold your line and stay warmly connected.","hook":"\"If you don't give in now, you'll be alone with no family left.\"","myth":{"un":"Hold your line and you'll be left with no family.","re":"A kept boundary rarely ends a loving family; you can hold your line and stay connected, warmly.","why":"Fear-of-abandonment is a pressure tactic, not a likely outcome."}},
  {"id":"yp-1044","cat":"hold-your-ground","type":"spot","persona":"any","source":"care vs pressure","relearn":"The flagged lines use fear and gossip to push you, not to support you; that's pressure wearing the mask of care.","hook":"Spot the two lines that are pressure, not real concern, dressed up as care.","why":"The flagged lines use fear and gossip to push you, not to support you; that's pressure wearing the mask of care.","scene":[{"id":"a","text":"\"I just want you happy, take your time.\"","trick":false},{"id":"b","text":"\"Marry now or you'll regret it forever.\"","trick":true},{"id":"c","text":"\"I'm here whenever you want to talk.\"","trick":false},{"id":"d","text":"\"Everyone's whispering about you, you know.\"","trick":true},{"id":"e","text":"\"Your choice. I trust your judgement.\"","trick":false}]},
  {"id":"yp-1045","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot coercion","relearn":"Guilt-tripping and the silent treatment are coercion, not concern; a loving ask doesn't come with a threat attached.","hook":"Spot the two manipulative lines a relative might use to corner you.","why":"Guilt-tripping and the silent treatment are coercion, not concern; a loving ask doesn't come with a threat attached.","scene":[{"id":"a","text":"\"Take all the time you need.\"","trick":false},{"id":"b","text":"\"Say yes or you'll break your mother's heart.\"","trick":true},{"id":"c","text":"\"How are YOU doing, really?\"","trick":false},{"id":"d","text":"\"Until you agree, I won't speak to you.\"","trick":true},{"id":"e","text":"\"It's your life and your call.\"","trick":false}]},
  {"id":"yp-1046","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot the shade card","relearn":"The flagged lines price you by skin and body: marriage-market scrutiny that measures nothing real about you.","hook":"Spot the two lines that rank your worth by looks or the marriage market.","why":"The flagged lines price you by skin and body: marriage-market scrutiny that measures nothing real about you.","scene":[{"id":"a","text":"\"You're kind and you light up a room.\"","trick":false},{"id":"b","text":"\"Too dark for the good proposals, sadly.\"","trick":true},{"id":"c","text":"\"I love how curious you are.\"","trick":false},{"id":"d","text":"\"At your weight, lower your hopes.\"","trick":true},{"id":"e","text":"\"Your work really matters to people.\"","trick":false}]},
  {"id":"yp-1047","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot baby pressure","relearn":"'Incomplete' and 'a real woman would' aren't compliments; they're shame that frames a free choice as a failing.","hook":"Spot the two 'compliments' that are really pressure to have a baby.","why":"'Incomplete' and 'a real woman would' aren't compliments; they're shame that frames a free choice as a failing.","scene":[{"id":"a","text":"\"You two seem really happy together.\"","trick":false},{"id":"b","text":"\"You'd be incomplete without a child, though.\"","trick":true},{"id":"c","text":"\"Take whatever path is right for you.\"","trick":false},{"id":"d","text":"\"A real woman your age would be a mother.\"","trick":true},{"id":"e","text":"\"However your family looks, it's yours.\"","trick":false}]},
  {"id":"yp-1048","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot the cave","relearn":"The flagged lines hand the decision away to end discomfort; a kind, firm boundary keeps the choice yours.","hook":"Spot the two responses that cave, instead of holding a kind, firm line.","why":"The flagged lines hand the decision away to end discomfort; a kind, firm boundary keeps the choice yours.","scene":[{"id":"a","text":"\"This is my decision, made with care.\"","trick":false},{"id":"b","text":"\"Fine, set a date, whatever you all want.\"","trick":true},{"id":"c","text":"\"I love you, and my answer stands.\"","trick":false},{"id":"d","text":"\"Okay, I'll meet him just to stop this.\"","trick":true},{"id":"e","text":"\"Let's enjoy the day and drop the topic.\"","trick":false}]},
  {"id":"yp-1049","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot escalation","relearn":"The flagged lines reach for insults and cut-offs; holding ground stays warm and firm, it doesn't go to war.","hook":"Spot the two lines that escalate into a family war instead of holding ground.","why":"The flagged lines reach for insults and cut-offs; holding ground stays warm and firm, it doesn't go to war.","scene":[{"id":"a","text":"\"Can we agree it's settled, warmly?\"","trick":false},{"id":"b","text":"\"You're all backward and I'm done with you.\"","trick":true},{"id":"c","text":"\"I hear your worry; my answer's the same.\"","trick":false},{"id":"d","text":"\"Push me again and I'll cut you all off.\"","trick":true},{"id":"e","text":"\"Let's change the subject for now.\"","trick":false}]},
  {"id":"yp-1050","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot scare copy","relearn":"'Die alone' and 'ticking clock, settle' are scare tactics; there's no boat to miss and no one to settle for in fear.","hook":"Spot the two fear lines: scare copy, not honest concern.","why":"'Die alone' and 'ticking clock, settle' are scare tactics; there's no boat to miss and no one to settle for in fear.","scene":[{"id":"a","text":"\"There's no real deadline; take your time.\"","trick":false},{"id":"b","text":"\"You'll die alone if you don't marry now.\"","trick":true},{"id":"c","text":"\"Partnership can come at any age.\"","trick":false},{"id":"d","text":"\"Your clock's ticking: settle for anyone.\"","trick":true},{"id":"e","text":"\"Wait for the right person, truly.\"","trick":false}]},
  {"id":"yp-1051","cat":"hold-your-ground","type":"spot","persona":"any","source":"spot the override","relearn":"'You'll change your mind' and 'you can't mean it' override your own knowledge of yourself, which you're allowed to trust.","hook":"Spot the two lines that deny your right to know your own mind.","why":"'You'll change your mind' and 'you can't mean it' override your own knowledge of yourself, which you're allowed to trust.","scene":[{"id":"a","text":"\"I trust you know yourself.\"","trick":false},{"id":"b","text":"\"You'll change your mind, you always do.\"","trick":true},{"id":"c","text":"\"It's okay to be unsure for now.\"","trick":false},{"id":"d","text":"\"You can't possibly mean 'no kids'.\"","trick":true},{"id":"e","text":"\"Your call, in your own time.\"","trick":false}]},
  {"id":"yp-1052","cat":"hold-your-ground","type":"match","persona":"any","source":"pressure to boundary","relearn":"Each pressure line has a calm boundary that holds your ground without a fight.","hook":"Match each pressure line to the calm boundary that holds your ground.","pairs":[{"left":"\"When's your turn?\"","right":"\"Whenever it's right for me.\""},{"left":"\"What will people say?\"","right":"\"That's their script, not my duty.\""},{"left":"\"You'll regret it.\"","right":"\"I'm choosing this with open eyes.\""},{"left":"\"Just settle, you're not young.\"","right":"\"No real deadline. I'll wait for the right fit.\""},{"left":"\"Still single, poor thing.\"","right":"\"I'm genuinely happy, thanks.\""}]},
  {"id":"yp-1053","cat":"hold-your-ground","type":"match","persona":"any","source":"claim to truth","relearn":"Each shaming claim has a truth: worth isn't status, womanhood isn't motherhood, you know your mind.","hook":"Match each shaming claim to the truth that answers it.","pairs":[{"left":"\"You're incomplete without a child.\"","right":"Womanhood isn't motherhood."},{"left":"\"An unmarried woman has less worth.\"","right":"Worth was never marital status."},{"left":"\"Too dark for good proposals.\"","right":"Skin tone measures nothing real."},{"left":"\"You'll definitely regret it.\"","right":"You can trust your own mind."},{"left":"\"Marriage is the measure of a life.\"","right":"It's one path, not the measure."}]},
  {"id":"yp-1054","cat":"hold-your-ground","type":"match","persona":"any","source":"situation to route","relearn":"Forced marriage routes to 181/1091/112; a child married off to Childline 1098; distress to a trusted person.","hook":"Match each situation to the help route that fits it.","pairs":[{"left":"Being forced or coerced into marriage","right":"Call 181, 1091 or 112."},{"left":"A child being married off","right":"Childline 1098."},{"left":"Family-conflict distress","right":"A counsellor or trusted person."},{"left":"Confidence worn down by pressure","right":"People who respect your path."},{"left":"A nosy 'why single' question","right":"One calm, closed line."}]},
  {"id":"yp-1055","cat":"hold-your-ground","type":"match","persona":"any","source":"move to effect","relearn":"Calm boundaries and support hold your ground; caving and false promises lose you the choice.","hook":"Match each move to whether it holds your ground or loses you.","pairs":[{"left":"A calm, repeated boundary","right":"Holds your ground."},{"left":"Caving to stop the tears","right":"Loses you the choice."},{"left":"Letting a nosy line pass","right":"Keeps your peace."},{"left":"Promising a date you don't mean","right":"Builds on a false yes."},{"left":"Leaning on supportive people","right":"Steadies your confidence."}]},
  {"id":"yp-1056","cat":"hold-your-ground","type":"match","persona":"any","source":"line to pressure","relearn":"A warm-but-firm line fits each pressure, holding the boundary without rupture.","hook":"Match each warm-but-firm line to the pressure it answers.","pairs":[{"left":"\"My decision, in my own time.\"","right":"Parents shortlisting a match."},{"left":"\"That's between me and my partner.\"","right":"\"When's the good news?\""},{"left":"\"Please stop sending profiles.\"","right":"Endless matrimonial messages."},{"left":"\"I love you, and my answer stands.\"","right":"A tearful marriage plea."},{"left":"\"More chai? Let's change topic.\"","right":"An aunty's nosy probing."}]},
  {"id":"yp-1057","cat":"hold-your-ground","type":"match","persona":"any","source":"tactic to reality","relearn":"Name the tactics for what they are: coercion, social pressure, scare copy, not real duty.","hook":"Match each tactic relatives use to what it really is.","pairs":[{"left":"The silent treatment until you agree","right":"Coercion, not concern."},{"left":"\"Log kya kahenge\"","right":"Social pressure, not duty."},{"left":"Open pity about your single life","right":"The script's bias, not truth."},{"left":"\"You'll change your mind\"","right":"Overriding your own mind."},{"left":"\"Settle before the clock runs out\"","right":"Scare copy, not a real deadline."}]},
  {"id":"yp-1058","cat":"hold-your-ground","type":"match","persona":"any","source":"feeling to response","relearn":"Each pressure-feeling has a steadying response: support, a calm line, less defending.","hook":"Match each feeling under pressure to a steadying response.","pairs":[{"left":"Confidence being worn down","right":"Time with people who respect you."},{"left":"Distress from family conflict","right":"Reach for support, you're not alone."},{"left":"Caught off-guard by a question","right":"One calm, closed sentence."},{"left":"Tempted to over-explain","right":"Less defending, more redirecting."},{"left":"Doubting your own choice","right":"Reflect away from the noise."}]},
  {"id":"yp-1059","cat":"hold-your-ground","type":"match","persona":"any","source":"path to dignity","relearn":"Every path, whether married, single, childfree or a family built differently, is valid and dignified.","hook":"Match each path someone chooses to its dignified, even-handed truth.","pairs":[{"left":"Choosing to marry, even early","right":"An equally valid, respected choice."},{"left":"Choosing to stay single","right":"A full life needs no marriage."},{"left":"Choosing to be childfree","right":"A complete, valid life."},{"left":"Building a family differently","right":"Many real ways to make a family."},{"left":"Holding a boundary with love","right":"Loving family and autonomy, both."}]},
  {"id":"yp-1080","cat":"not-marrying","type":"strike-rewrite","hook":"\"At your age your 'market value' for marriage is dropping fast.\"","myth":{"un":"At your age your 'market value' for marriage is dropping fast.","re":"You aren't a stock with a price; worth is never marital status, and there's no clock setting it.","why":"People aren't priced by age; that 'value' is invented pressure."},"relearn":"You're not a 'market value'; worth is never marital status, and no clock decides it.","persona":"Sneha","source":"not a market value"},
  {"id":"yp-1081","cat":"not-marrying","type":"strike-rewrite","hook":"\"A single woman is just a burden on her parents forever.\"","myth":{"un":"A single woman is just a burden on her parents forever.","re":"An independent adult who supports herself and her family is no burden; that label is stigma, not fact.","why":"Standing on your own is the opposite of a burden."},"relearn":"A single, independent adult is no 'burden'; that label is stigma, not fact.","persona":"Sneha","source":"not a burden"},
  {"id":"yp-1082","cat":"not-marrying","type":"strike-rewrite","hook":"\"Marriage is the only thing that gives a woman security.\"","myth":{"un":"Marriage is the only thing that gives a woman security.","re":"A career, savings, friends and chosen family build real security too; marriage is one route, not the only one.","why":"Security comes from many sources, not a wedding alone."},"relearn":"Marriage isn't the only security; income, savings and chosen family build it too.","persona":"any","source":"security many sources"},
  {"id":"yp-1083","cat":"not-marrying","type":"strike-rewrite","hook":"\"If you stay single, who will look after you when you're old?\"","myth":{"un":"If you stay single, who will look after you when you're old?","re":"Marriage guarantees no caretaker; friends, family, savings and community can all hold you in old age.","why":"A spouse isn't a promise of care; many sources are."},"relearn":"Marriage guarantees no caretaker; friends, family and community can hold you in old age.","persona":"any","source":"old age care"},
  {"id":"yp-1084","cat":"not-marrying","type":"strike-rewrite","hook":"\"Settle for this 'decent' boy now or you'll be left with no one.\"","myth":{"un":"Settle for this 'decent' boy now or you'll be left with no one.","re":"Settling from fear usually brings more regret than waiting; a freely-chosen path, or none, beats a rushed one.","why":"Fear is a poor reason to marry anyone."},"relearn":"Settling from fear brings more regret than waiting; choose freely, not by deadline.","persona":"any","source":"don't settle from fear"},
  {"id":"yp-1085","cat":"not-marrying","type":"strike-rewrite","hook":"\"Your younger sister is married, so something must be wrong with you.\"","myth":{"un":"Your younger sister married first, so something's wrong with you.","re":"Marriage isn't a race with a 'correct' order; her path and yours are simply different, both valid.","why":"There's no queue you're failing to join."},"relearn":"Marriage isn't a race with a 'right' order; a sibling marrying first means nothing about you.","persona":"any","source":"no marriage queue"},
  {"id":"yp-1086","cat":"not-marrying","type":"strike-rewrite","hook":"\"A single life is fine now, but you'll be lonely and bitter later.\"","myth":{"un":"A single life is fine now, but you'll be lonely and bitter later.","re":"Loneliness comes from thin connection, not from being unmarried; deep friendships and community prevent it.","why":"Married people get lonely too; connection is what guards against it."},"relearn":"Loneliness comes from thin connection, not from being unmarried; build deep ties.","persona":"any","source":"loneliness myth"},
  {"id":"yp-1087","cat":"not-marrying","type":"strike-rewrite","hook":"\"A flat, a car, a trip alone, what's the point of all this without a husband?\"","myth":{"un":"What's the point of a flat, a car, a life, without a husband?","re":"A life you built and enjoy has a point in itself; it doesn't need a husband to mean something.","why":"A meaningful life isn't validated by a marriage."},"relearn":"A life you built and enjoy has meaning in itself; it needs no husband to count.","persona":"any","source":"life means something"},
  {"id":"yp-1088","cat":"not-marrying","type":"role-play","persona":"any","source":"light deflection","hook":"A nosy uncle corners you near the snack table at a family function. You aren't looking right now and want to keep it light.","setup":"He's got that look like he's about to make it everyone's business.","steps":[{"prompt":"He asks loudly: \"Beta, when is YOUR turn to get married?\"","options":[{"text":"\"When it's right for me. Have you tried the paneer?\"","then":"He chuckles and reaches for a plate. \"Is it any good?\"","best":true},{"text":"\"I'm trying my best, uncle. Please pray for me!\"","then":"He nods, satisfied. \"Good, good, keep trying.\""},{"text":"\"Why does everyone keep asking me this, uncle?\"","then":"He shrugs. \"Just curious, beta.\""},{"text":"\"Soon, uncle, very soon. You'll get your laddoos!\"","then":"He laughs. \"Soon, you said last year too!\""}],"why":"A light, closed deflection ends the question without a fight or an apology."},{"prompt":"He follows up: \"Your batchmates are all married already, no?\"","options":[{"text":"\"Some are. My life's just taking a different shape.\"","then":"He nods slowly. \"Fair, fair. Different paths, I suppose.\"","best":true},{"text":"\"Maybe I should catch up with them then.\"","then":"He brightens. \"That's the spirit, beta.\""},{"text":"\"Do you keep a list of who's married, uncle?\"","then":"He laughs, a little stiffly. \"Just an observation.\""},{"text":"\"I'm happy for them. I'm just not that lucky.\"","then":"He pats your shoulder. \"Your luck will turn, beta.\""}],"why":"Naming a different shape for your life, not a race, closes the comparison."},{"prompt":"As he leaves, he says: \"I'll ask around if I hear of anyone good.\"","options":[{"text":"\"That's kind, but I'm not looking right now.\"","then":"He shrugs, easy about it. \"Fair enough, beta.\"","best":true},{"text":"\"Sure, go ahead. It can't hurt to look.\"","then":"He grins. \"I already know two families!\""},{"text":"\"Please, no. That's really not needed at all.\"","then":"He looks hurt. \"Arre, I was only offering.\""},{"text":"\"Ask my mother. She handles all that.\"","then":"He nods eagerly. \"I'll speak to her tonight.\""}],"why":"A kind, clear no at the door closes it without leaving an opening."}],"relearn":"A light, closed deflection ends a nosy marriage question without a fight or an apology."},
  {"id":"yp-1089","cat":"not-marrying","type":"role-play","persona":"Sneha","source":"settled not married","hook":"At the office party, a colleague you like joins you by the snacks, drink in hand.","setup":"She leans in as the music gets louder.","steps":[{"prompt":"She says: \"You're so successful. Sad that you never settled down.\"","options":[{"text":"\"Nothing sad about it. I'm settled, just not married.\"","then":"She pauses. \"Oh. I hadn't thought of it that way.\"","best":true},{"text":"\"Yeah, I guess I left it too late, at this point.\"","then":"She nods, sympathetic. \"It happens. Don't worry.\""},{"text":"\"That's a weird thing to say at a party.\"","then":"She looks a little embarrassed. \"Fair, sorry.\""},{"text":"\"Success and marriage aren't the same thing.\"","then":"She nods. \"Of course. Still, it's a shame.\""}],"why":"Naming settled without married corrects the frame without a fight."},{"prompt":"She asks: \"But don't you want the whole package, eventually?\"","options":[{"text":"\"My package looks different, and it's already whole.\"","then":"She tilts her head. \"Already whole? Hm. Maybe.\"","best":true},{"text":"\"Maybe someday. We'll see how it goes.\"","then":"She nods, hopeful. \"There's still time, then.\""},{"text":"\"There's no 'whole package' checklist, honestly.\"","then":"She shrugs. \"Just a figure of speech.\""},{"text":"\"I don't know. Maybe I'm missing out.\"","then":"She pats your arm. \"Oh, sweetie. It'll happen.\""}],"why":"Naming your own version of whole answers the checklist directly."},{"prompt":"Later, she introduces you to someone new: \"This is my still-single, poor-thing friend.\"","options":[{"text":"\"I'll introduce myself. I'm doing great, actually.\"","then":"The new person laughs. \"Good for you. Nice to meet you.\"","best":true},{"text":"\"It's fine. Don't worry about it.\"","then":"The new person gives you a sympathetic smile. \"Aww.\""},{"text":"\"That's an awful way to describe someone.\"","then":"She flushes. \"It was a joke. Relax.\""},{"text":"\"Please stop introducing me that way.\"","then":"She laughs it off. \"Oh, you know I'm joking!\""}],"why":"Introducing yourself in your own words, lightly, replaces the label without a scene."},{"prompt":"At the end of the night, she says: \"I just want you to be happy, you know.\"","options":[{"text":"\"I know. And I am happy, exactly as I am.\"","then":"She pauses, then nods slowly. \"Okay. I'm starting to see that.\"","best":true},{"text":"\"Thanks. I hope I get there someday too.\"","then":"She squeezes your hand. \"You will. I just know it.\""},{"text":"\"You should worry about your own happiness.\"","then":"She stiffens. \"Wow. Okay, then.\""},{"text":"\"I know you mean well, so let's just enjoy the night.\"","then":"She smiles. \"Of course! We'll find you someone yet.\""}],"why":"Warmly saying you're already happy answers her worry, instead of letting it stand."}],"relearn":"You can be settled without being married; you don't owe anyone the 'poor thing' script."},
  {"id":"yp-1090","cat":"not-marrying","type":"role-play","persona":"any","source":"affirm not fix","hook":"A close friend, single and happy, goes quiet at a wedding you're both attending.","setup":"She pulls you aside, at the edge of the dance floor.","steps":[{"prompt":"She says: \"I feel like a failure at every one of these.\"","options":[{"text":"\"You're not failing at anything. You built a life you love.\"","then":"She exhales. \"I needed to hear that, actually.\"","best":true},{"text":"\"Don't worry. Your turn will come. We'll find you someone.\"","then":"She smiles thinly. \"Right. Someday.\""},{"text":"\"That's silly. Weddings don't mean anything.\"","then":"She frowns. \"They mean something to me.\""},{"text":"\"You could look into some apps, maybe.\"","then":"She sighs. \"That's not really what I meant.\""}],"why":"Affirming her chosen life names the win, instead of trying to fix her."},{"prompt":"She asks: \"Doesn't it bother you too, sometimes?\"","options":[{"text":"\"Sometimes, but it doesn't undo what I've built.\"","then":"She nods. \"That's a good way to hold it.\"","best":true},{"text":"\"Never. I don't let myself think about it.\"","then":"She raises an eyebrow. \"Never? Not even a little?\""},{"text":"\"Constantly, and I try not to think about why.\"","then":"Her face falls. \"So it never goes away?\""},{"text":"\"You shouldn't let it bother you either.\"","then":"She nods slowly. \"Easier said than done.\""}],"why":"An honest, undramatic 'sometimes' models holding the feeling without losing the win."},{"prompt":"A relative at the next table calls out: \"Aww, you two, still single?\"","options":[{"text":"\"Still living our lives, actually. Great wedding, no?\"","then":"The relative laughs, a little caught out. \"Fair, fair.\"","best":true},{"text":"\"Still trying, aunty. Hope springs eternal!\"","then":"The relative laughs. \"That's the spirit! Soon, soon.\""},{"text":"\"That's a rude thing to shout across a wedding hall.\"","then":"The relative bristles. \"It was only a joke!\""},{"text":"\"Yes, tragic, isn't it.\"","then":"The relative misses the sarcasm. \"Don't worry. It'll happen!\""}],"why":"Naming the day, together, deflects the comment without absorbing it."},{"prompt":"As the night ends, your friend says: \"Thanks for being here with me tonight.\"","options":[{"text":"\"Always. And you were never a failure, not once.\"","then":"She smiles, eyes a little wet. \"That means a lot.\"","best":true},{"text":"\"You're welcome, and hey, there's always next year.\"","then":"Her smile slips. \"Next year, as in someone for me?\""},{"text":"\"No problem. That's what friends are for.\"","then":"She nods. \"Yeah. Thanks.\""},{"text":"\"Honestly, half the night I wanted to set you up with someone.\"","then":"She laughs uncertainly. \"Wait, really? With who?\""}],"why":"Reminding her she was never a failure is the real gift of the evening."}],"relearn":"Choosing a single life isn't a failure; affirm a friend's path instead of 'fixing' it."},
  {"id":"yp-1091","cat":"not-marrying","type":"role-play","persona":"any","source":"firm kind no","hook":"At dinner, an aunty announces she's 'found a boy' for you and wants a yes today.","setup":"She's already got his photo out on her phone.","steps":[{"prompt":"She says: \"He's perfect. Just say yes and we'll fix a meeting.\"","options":[{"text":"\"Thank you, aunty, but I'm not looking right now.\"","then":"She looks surprised. \"Alright,\" she says, though she doesn't look convinced.","best":true},{"text":"\"Um, okay, share the details. I'll see, I guess.\"","then":"She beams. \"Sending his number right now!\""},{"text":"\"Please put the phone away. This isn't the time, aunty.\"","then":"She looks stung. \"I was only trying to help.\""},{"text":"\"Why does everyone keep doing this to me?\"","then":"She shrugs. \"Because we all care, beta.\""}],"why":"A firm, warm 'not looking' is a complete answer, no apology needed."},{"prompt":"She presses: \"Just one meeting. What's the harm?\"","options":[{"text":"\"The real harm is that it stops being my choice.\"","then":"She pauses. \"Hm. I hear you, beta.\" She doesn't put the phone away.","best":true},{"text":"\"Fine, one meeting, just to be polite.\"","then":"She brightens. \"Wonderful. I'll call his mother tomorrow.\""},{"text":"\"Sorry, aunty. I know I'm being really difficult.\"","then":"She pats your hand. \"You are, a little. So just meet him.\""},{"text":"\"You always say it's 'just one', aunty.\"","then":"She shrugs. \"Because it always could be the one!\""}],"why":"Naming choice, not harm, as the real issue keeps the boundary clear."},{"prompt":"Before she leaves, she says: \"I'll send his details to your mother tonight.\"","options":[{"text":"\"Please don't. I'm not looking, and I'll tell Mummy so.\"","then":"She hesitates, then puts the phone away. \"Alright. Your call.\"","best":true},{"text":"\"Fine, send them. I probably won't do anything, though.\"","then":"She beams. \"Just look at him. That's all I ask.\""},{"text":"\"Send them if you like. I'll sort it out with Mummy.\"","then":"She smiles. \"Good. She'll be so pleased.\""},{"text":"\"Do whatever makes you happy, aunty.\"","then":"She claps. \"Wonderful. I'll fix a Sunday, then.\""}],"why":"Saying no to her yourself, kindly, stops it before it reaches your mother."}],"relearn":"A firm, warm 'not looking right now' is a complete answer; you owe no yes and no apology."},
  {"id":"yp-1092","cat":"not-marrying","type":"role-play","persona":"any","source":"not too choosy","hook":"A relative keeps pushing you to lower your standards in love.","setup":"She says it after hearing about your last breakup.","steps":[{"prompt":"She says: \"Lower your standards, beta. You can't afford to be choosy now.\"","options":[{"text":"\"Knowing what I want isn't being choosy.\"","then":"She pauses. \"Fair, I suppose. I just worry.\"","best":true},{"text":"\"Maybe you're right. I should be less picky.\"","then":"She nods, relieved. \"Good, that's more sensible.\""},{"text":"\"That's a rude thing to say after a breakup.\"","then":"She looks apologetic. \"I didn't mean it that way.\""},{"text":"\"My standards are none of your business.\"","then":"She looks a little stung by the sharpness."}],"why":"Naming clarity, not pickiness, reframes what your standards actually are."},{"prompt":"She adds: \"At your age, options only get fewer, you know.\"","options":[{"text":"\"I'd rather wait than settle for the wrong fit.\"","then":"She sighs. \"I just don't want you to miss out.\"","best":true},{"text":"\"Maybe I should take the next okay option, then.\"","then":"She nods, relieved. \"Smart. Better safe than sorry.\""},{"text":"\"That's honestly a scary thing to say.\"","then":"She looks apologetic. \"I only meant to warn you.\""},{"text":"\"Options aren't the only thing that matters.\"","then":"She shrugs, unconvinced by the point."}],"why":"Choosing well beats choosing fast, whatever the count looks like."},{"prompt":"Later, she says: \"Just don't let a good one slip by out of pride.\"","options":[{"text":"\"It won't be pride. It'll be knowing what's right for me.\"","then":"She nods slowly. \"Alright. I trust your judgment.\"","best":true},{"text":"\"Maybe I am too proud. I'll reconsider.\"","then":"She looks relieved, and starts naming a name."},{"text":"\"That's not what this is about at all.\"","then":"She looks a little defensive at the correction."},{"text":"\"Nothing's slipping by. I'm just being careful.\"","then":"She shrugs, still a little unconvinced."}],"why":"Naming self-knowledge, not pride, as the real reason keeps the choice honest."}],"relearn":"Knowing what you want isn't 'too choosy'; waiting for the right fit beats settling to a deadline."},
  {"id":"yp-1093","cat":"not-marrying","type":"branch","persona":"any","source":"pause the profile","hook":"Your parents book a matrimonial profile for you without asking. They mean well.","steps":[{"prompt":"They show you the profile, already live online. What do you do?","options":[{"text":"Thank them for caring, then ask them to pause it","then":"They look surprised, then agree to pause it for now.","best":true},{"text":"Let it stay live to avoid an argument tonight","then":"The profile stays up, and responses start coming in by morning."},{"text":"Delete it yourself without telling them","then":"They discover it's gone and feel blindsided by the silence."},{"text":"Shout that they had no right to do this","then":"The evening turns into a fight neither of you wanted."}],"why":"Thanking them keeps the love visible while the pause keeps the choice yours."},{"prompt":"A week later, on a call home, your mother says a family saw the profile and wants to talk. What do you do?","options":[{"text":"Say kindly but clearly that you won't meet them","then":"Your mother sighs, but says she'll let the family know.","best":true},{"text":"Ask a sibling to tell her for you instead","then":"Your sibling mentions it, but the message loses some of its force."},{"text":"Snap that she should never have made the profile","then":"The call turns tense, and the family's question is left hanging."},{"text":"Say you'll think about it, just to end the call","then":"Your mother takes it as a maybe and tells the family to wait."}],"why":"Saying it kindly and clearly yourself stops a maybe from turning into a meeting."},{"prompt":"Months later, your parents raise the profile once more, hoping for a yes. What do you do?","options":[{"text":"Say you'll bring it up yourself if you want to","then":"They accept it, a little wistfully, and let the topic rest.","best":true},{"text":"Agree to move forward just to keep the peace","then":"The peace holds for now, at the cost of a choice you didn't make."},{"text":"Get annoyed they're still holding onto it","then":"The annoyance overshadows the actual conversation."},{"text":"Promise a date by which you'll decide","then":"The promised date becomes its own new pressure."}],"why":"Saying you'll raise it yourself, if you ever want to, keeps the choice and the timing with you."}],"debrief":"You can love your family AND keep this choice yours; a kind, clear no protects both.","relearn":"Thank them for caring, then ask them to pause it. It stays your decision."},
  {"id":"yp-1094","cat":"not-marrying","type":"branch","persona":"Sneha","source":"happy as i am","hook":"A married friend keeps hinting you should 'lock someone down before it's too late'.","steps":[{"prompt":"She brings it up again over coffee. What do you do?","options":[{"text":"Tell her you're happy as you are, and ask her to trust you","then":"She looks a little surprised, then nods and changes the subject.","best":true},{"text":"Laugh it off without actually addressing it, honestly","then":"The comment goes unanswered, and she brings it up again next time."},{"text":"Get irritated and end the coffee early","then":"You leave frustrated, and the friendship feels a little strained."},{"text":"Agree you probably should get on it","then":"The agreement doesn't sit right, even as you say it."}],"why":"Naming your happiness and asking for trust sets a kind, clear boundary."},{"prompt":"She sends a matchmaking app link 'just in case'. What do you do?","options":[{"text":"Thank her kindly, and say you're not looking","then":"She says fair enough, and doesn't send another one.","best":true},{"text":"Download it quietly, just to see","then":"A small yes you didn't quite mean sits open on your phone now."},{"text":"Ignore the link without a reply","then":"She sends a follow-up asking if you saw it."},{"text":"Tell her to stop sending things like this","then":"She looks stung, though she meant it kindly."}],"why":"A clear, warm no closes the topic without punishing her good intentions."},{"prompt":"At her anniversary party, she introduces you to a single cousin anyway. What do you do?","options":[{"text":"Say hello warmly, with zero pressure on the moment","then":"You have a nice, easy chat that goes nowhere in particular, and that's fine.","best":true},{"text":"Play along like it's a set-up, to please her","then":"You spend the night performing interest you don't actually feel."},{"text":"Make it obvious you're annoyed at the setup","then":"The cousin feels awkward, and so does the rest of the party."},{"text":"Avoid the cousin for the whole evening","then":"The avoidance is noticeable, and a little unkind to someone who did nothing wrong."}],"why":"Meeting the moment lightly, without pressure, keeps your no intact and kind."}],"debrief":"Even a loving friend's 'clock' talk is pressure, not truth; a calm boundary keeps both.","relearn":"Tell a well-meaning friend you're happy as you are; her 'clock' is pressure."},
  {"id":"yp-1095","cat":"not-marrying","type":"branch","persona":"any","source":"job not wait","hook":"You're offered a great job in another city, but relatives say to 'marry first, move later'.","steps":[{"prompt":"The offer has a two-week deadline to accept. What do you do?","options":[{"text":"Accept the job on your own timeline, not theirs","then":"You accept, and start planning the move with real excitement.","best":true},{"text":"Ask the company for more time to 'sort things out'","then":"You get a week more, and spend it fielding rishtas instead of packing."},{"text":"Wait to accept until the family gives its blessing","then":"The blessing never quite comes, and you accept on the last day, drained."},{"text":"Accept, but tell no one until you're gone","then":"The secrecy buys you space, and costs you their trust later."}],"why":"Your career doesn't need a wedding's permission to move forward."},{"prompt":"Once word of the move gets out, relatives call to weigh in again. What do you do?","options":[{"text":"Tell them the city doesn't decide your marriage timeline","then":"They're not fully convinced, but they stop arguing the point.","best":true},{"text":"Promise to prioritise finding someone once you land","then":"The promise adds a second deadline to an already big move."},{"text":"Stop taking their calls for a while","then":"The silence buys peace now, and questions later."},{"text":"Agree the move was maybe a mistake","then":"Doubt creeps into a decision you were sure about days ago."}],"why":"Separating geography from marriage keeps the real decision yours."},{"prompt":"Settled in the new city, you meet someone you like. What do you do?","options":[{"text":"Let it develop at its own pace, city and all","then":"The relationship grows steadily, alongside the new job.","best":true},{"text":"Rush it, to prove the move didn't cost you anything","then":"The rushing puts pressure on something that was going fine."},{"text":"Ask relatives what they think before going further","then":"Opinions pour in about someone they've never met, and your own view blurs."},{"text":"Announce it to relatives early, so they'll ease off","then":"Within a day, the family group wants a name, a photo and a date."}],"why":"Letting things develop naturally beats rushing to justify a choice."},{"prompt":"A year in, relatives admit the move worked out well. What do you do?","options":[{"text":"Accept it warmly, without needing an apology","then":"You let the moment be simple, no scorekeeping needed.","best":true},{"text":"Remind them how wrong they were, at length","then":"The point lands, but the visit turns a little sour."},{"text":"Downplay your own success to keep the peace","then":"You shrink your own win to avoid a small moment of friction."},{"text":"Say nothing and let the comment pass unanswered","then":"The moment passes, but it feels smaller than it could have."}],"why":"Accepting the good news simply is more useful than winning the old argument."}],"debrief":"Your life doesn't have to wait behind a wedding; building it now is fully valid.","relearn":"Marriage isn't a prerequisite for your life; build it on your own timeline."},
  {"id":"yp-1096","cat":"not-marrying","type":"branch","persona":"any","source":"don't shrink","hook":"A matchmaker says being 30 and independent will put boys off.","steps":[{"prompt":"She suggests listing you as 27, with a smaller job title. What do you do?","options":[{"text":"Say no, and keep your real age and title","then":"She sighs, but agrees to send the honest profile forward.","best":true},{"text":"Knock off a year or two, just to get more responses","then":"The responses increase, built on a version of you that isn't quite true."},{"text":"Keep your age, but play down the job title","then":"She's pleased, and your profile now undersells work you're proud of."},{"text":"Ask your mother whether you should do it","then":"Your mother says a small change can't hurt, and now it's two against one."}],"why":"The right person won't need a smaller, dimmer version of you."},{"prompt":"A match writes back, keen to meet, and asks what you do for work. What do you do?","options":[{"text":"Tell him plainly what you do, title and all","then":"He says it sounds interesting, and asks to meet for coffee that weekend.","best":true},{"text":"Say you have \"just a small office job\", as she suggested","then":"He agrees to meet, and you feel the smaller version settle around you."},{"text":"Ask him first what he does, and match how big you sound to his","then":"He says he works in insurance, and you dim your answer to sit below his."},{"text":"Ask the matchmaker what you should tell him","then":"She says to keep it light, and the answer is hers, not yours."}],"why":"Telling him plainly who you are means any interest is in the real you."},{"prompt":"The matchmaker says honesty 'never works' for women your age. What do you do?","options":[{"text":"Stay honest, even if it means fewer matches","then":"She shrugs and says it's up to you, and your profile stays true.","best":true},{"text":"Take her word for it and adjust further","then":"The adjustments keep compounding, further from the real you."},{"text":"Argue with her about her whole business","then":"The argument doesn't change how the search runs."},{"text":"Start wondering if your age really is the problem","then":"The doubt follows you into every new profile you open."}],"why":"Staying honest filters for someone who wants the real you, not a smaller one."}],"debrief":"You never have to shrink your age or success to be 'chosen'; the right person won't ask it.","relearn":"Don't shrink yourself to seem 'marriageable'; the right person won't need the lie."},
  {"id":"yp-1097","cat":"not-marrying","type":"branch","persona":"any","source":"what i want","hook":"You realise you've been dating only to silence relatives, not because you want a partner.","steps":[{"prompt":"You're about to swipe on another app, out of habit. What do you do?","options":[{"text":"Pause and ask what YOU actually want right now","then":"You put the phone down, and the honesty feels like relief.","best":true},{"text":"Keep swiping, since stopping feels like giving up","then":"You keep going through motions that don't feel like yours."},{"text":"Delete the app in frustration, mid-swipe","then":"The app's gone, but the real question stays unanswered."},{"text":"Message a match anyway, to feel productive","then":"The message goes out, sent more from habit than actual interest."}],"why":"Asking what you want, not what quiets them, is the real anchor here."},{"prompt":"A relative asks how the 'search' is going this week. What do you do?","options":[{"text":"Tell them honestly you're taking a pause to think","then":"They're a little surprised, but they let it be for now.","best":true},{"text":"Say it's going great, to avoid a longer talk","then":"The easy answer buys peace, and buries the real question again."},{"text":"Snap that the search was never really yours","then":"The sharpness surprises them, and the real point gets lost."},{"text":"Promise a match is close, just to satisfy them","then":"The promise adds pressure to a search you're not even sure you want."}],"why":"An honest pause is more useful than a comforting performance."},{"prompt":"A week on, sitting with the question, a feeling becomes clear. What do you do?","options":[{"text":"Trust what that clarity is actually telling you","then":"The clarity becomes a real answer, not just a guess.","best":true},{"text":"Override the feeling, since relatives expect progress","then":"You override the feeling, and end up back where you started."},{"text":"Share the feeling widely for validation","then":"Everyone weighs in, and your own answer gets crowded out."},{"text":"Ignore it and keep swiping anyway","then":"The apps stay open, but the question hasn't actually moved."}],"why":"The feeling you notice in the quiet is worth more than outside noise."},{"prompt":"Weeks later, you think about whether dating is even part of the plan right now. What do you do?","options":[{"text":"Date only if and when it's what you want","then":"Whatever you decide, it feels like yours this time.","best":true},{"text":"Carry on at the old pace, just with better intentions","then":"The old habits keep running things, despite the better intentions."},{"text":"Tell relatives you're 'serious' now to please them","then":"The framing puts the old pressure right back in the room."},{"text":"Set a deadline to find someone by year-end","then":"The deadline turns dating back into a task on someone else's clock."}],"why":"Deciding on your own terms, not a schedule, keeps the reasons honest."}],"debrief":"Ask 'what do I want?', not 'what quiets them?'; your life is the one you have to live.","relearn":"Ask what YOU want, not what quiets relatives; that's the real anchor."},
  {"id":"yp-1098","cat":"not-marrying","type":"branch","persona":"any","source":"stand with her","hook":"Your cousin is being pressured into a marriage she's said she doesn't want.","steps":[{"prompt":"She pulls you aside at a family gathering, looking scared. What do you do?","options":[{"text":"Listen quietly, and tell her you believe her","then":"She exhales, like she's been holding her breath for days.","best":true},{"text":"Tell her to just refuse loudly, right now","then":"She looks more frightened. \"It's not that simple,\" she says quietly."},{"text":"Tell her to calm down. It's probably fine.","then":"She goes quiet, and doesn't say anything more today."},{"text":"Promise to fix it yourself immediately","then":"She looks alarmed. \"Please don't say anything yet,\" she says."}],"why":"Believing her first, without pushing, is what lets her keep talking."},{"prompt":"Over the next few days, she opens up more, saying she feels she has no choice. What do you do?","options":[{"text":"Tell her it's not her fault, and ask what she needs","then":"She softens a little. \"I don't know yet,\" she says. \"Just this, for now.\"","best":true},{"text":"Tell her what she should do about it","then":"She goes quiet, like the decision got taken from her again."},{"text":"Tell her to just adjust. Everyone does, honestly.","then":"She looks away. \"That's what everyone keeps saying,\" she says."},{"text":"Change the subject so she can relax","then":"The moment closes, and the fear stays exactly where it was."}],"why":"Naming that it's not her fault opens space, instead of adding pressure."},{"prompt":"She says she's scared to say no to her parents directly. What do you do?","options":[{"text":"Offer to sit with her while she figures out next steps","then":"She nods, relieved not to be facing it completely alone.","best":true},{"text":"Offer to talk to her parents on her behalf","then":"She looks worried. \"Please don't. It might make it worse,\" she says."},{"text":"Tell her she has to leave right now","then":"She flinches. \"I can't just leave,\" she says, pulling back."},{"text":"Say you'll stay out of it, since it's a family matter","then":"She looks smaller, like a door just quietly closed."}],"why":"Respecting her pace, without taking over, keeps her decisions hers."},{"prompt":"A week later, she says the pressure hasn't eased. What do you do?","options":[{"text":"Share the helpline number, gently, for if she needs it","then":"She takes down the number quietly. \"Just in case,\" she says.","best":true},{"text":"Tell her she needs to go to the police today","then":"She looks frightened. \"Not yet, please,\" she says."},{"text":"Tell her parents yourself without asking her","then":"She looks betrayed. \"I trusted you with this,\" she says quietly."},{"text":"Wait for her to bring it up again herself","then":"The silence between visits leaves her carrying it alone."}],"why":"A number she can use in her own time supports her without forcing her hand."},{"prompt":"Months later, she calls, finally ready to act. What do you do?","options":[{"text":"Help her call the helpline and stay with her through it","then":"She makes the call, no longer facing it by herself.","best":true},{"text":"Tell her it's about time she did something","then":"She goes quiet at the edge in your voice, even now."},{"text":"Take over the whole situation for her","then":"She feels pushed aside from a choice that's finally hers to make."},{"text":"Tell her you always knew this day would come","then":"The comment lands oddly, more about you than about her."}],"why":"Standing beside her as she finally acts respects both her fear and her courage."}],"debrief":"If anyone is pressured or forced into marriage, call 181, 1091, 112 or Childline 1098.","relearn":"Stand with someone being pressured; forced marriage is never okay. Reach for help."},
  {"id":"yp-1099","cat":"not-marrying","type":"branch","persona":"Sneha","source":"home not waiting room","hook":"You enjoy living alone, but everyone treats your flat as a 'temporary phase' before marriage.","steps":[{"prompt":"You want to finally paint the walls and hang real art. What do you do?","options":[{"text":"Do it now; this is your real home, not a waystation","then":"The walls go up in colour you love, and the flat finally feels like yours.","best":true},{"text":"Wait, in case a husband wants different walls someday","then":"The walls stay bare, waiting for a person who isn't here yet."},{"text":"Ask family for approval on the colours first","then":"The approval process turns your own home into a group decision."},{"text":"Decide it's not worth the effort for a 'phase'","then":"The flat stays half-finished, like a life on hold."}],"why":"Treating your home as real, now, is how you actually live in it."},{"prompt":"A relative offers to store your things 'for when you move in with him'. What do you do?","options":[{"text":"Decline warmly, and say this flat is your home","then":"Your things stay right where they belong, in your own home.","best":true},{"text":"Accept, just in case it turns out to be useful","then":"Half your things sit in someone else's garage, waiting on a maybe."},{"text":"Get annoyed at the assumption behind the offer","then":"The relative looks taken aback, and the room goes quiet for a moment."},{"text":"Laugh it off without really answering","then":"The relative takes the laugh as a maybe, and asks again next week."}],"why":"A kind no protects the home you've actually built, not a hypothetical one."},{"prompt":"Years pass, and someone calls your flat 'cute, for now'. What do you do?","options":[{"text":"Correct them warmly; it's simply home","then":"They pause, then smile. \"Fair point,\" they say.","best":true},{"text":"Let the comment pass. It's not worth a fight.","then":"The comment passes, and so does another small chance to name it."},{"text":"Agree it's temporary, to keep things easy","then":"Years of building it gets waved away in one sentence."},{"text":"Get defensive about how long you've lived there","then":"The defensiveness says more than the correction would have."}],"why":"Naming it as home, plainly, ends the waiting-room story for good."}],"debrief":"A single life isn't a waiting room before the 'real' one; it's your real life, now.","relearn":"Your single home is a real home now, not a waiting room before marriage."},
  {"id":"yp-1100","cat":"not-marrying","type":"sort","hook":"Sort: builds a full life beyond marriage, or just pressure to wed?","items":[{"id":"a","text":"Deep friendships and chosen family"},{"id":"b","text":"\"Settle before you're 'too old'\""},{"id":"c","text":"Work and savings you're proud of"},{"id":"d","text":"\"Log kya kahenge if you don't marry\""},{"id":"e","text":"Hobbies and a community you love"},{"id":"f","text":"\"Everyone your age is married already\""}],"bins":[{"id":"life","label":"Builds a full life","valence":"pos"},{"id":"pressure","label":"Just pressure","valence":"neg"}],"key":{"a":"life","b":"pressure","c":"life","d":"pressure","e":"life","f":"pressure"},"relearn":"Friendships, work and community build a full life; 'settle before you're old', 'log kya kahenge' and 'everyone's married' are just pressure.","persona":"any","source":"life vs pressure"},
  {"id":"yp-1101","cat":"not-marrying","type":"sort","hook":"Sort: a freely-chosen reason to marry, or a fear-driven one?","items":[{"id":"a","text":"You found a partner you truly want to build with"},{"id":"b","text":"You're scared of dying alone"},{"id":"c","text":"You're ready and it feels right for you"},{"id":"d","text":"Relatives won't stop nagging"},{"id":"e","text":"You both want a shared life together"},{"id":"f","text":"You feel you've 'run out of time'"}],"bins":[{"id":"free","label":"Freely chosen","valence":"pos"},{"id":"fear","label":"Fear-driven","valence":"neg"}],"key":{"a":"free","b":"fear","c":"free","d":"fear","e":"free","f":"fear"},"relearn":"Wanting a partner, readiness and a shared life are free reasons; fear of dying alone, nagging and 'out of time' are pressure.","persona":"any","source":"free vs fear"},
  {"id":"yp-1102","cat":"not-marrying","type":"spot","hook":"Spot the two lines that pressure, not support, a single friend.","scene":[{"id":"a","text":"\"Your life looks really full, happy for you\"","trick":false},{"id":"b","text":"\"Hurry, your good years are running out\"","trick":true},{"id":"c","text":"\"Take your time, the right one is worth it\"","trick":false},{"id":"d","text":"\"Just adjust and marry whoever's available\"","trick":true},{"id":"e","text":"\"Single or married, you're doing great\"","trick":false}],"why":"'Good years running out' and 'just adjust and marry whoever' pressure; the rest truly support.","relearn":"Real support never adds a clock or a 'just settle'; those two lines pressure.","persona":"any","source":"support vs pressure lines"},
  {"id":"yp-1103","cat":"not-marrying","type":"match","hook":"Match each pressure line to the calm truth that answers it.","pairs":[{"left":"\"You're too old to marry\"","right":"No boat to miss; a full life comes at any age"},{"left":"\"Something's wrong with you\"","right":"Nothing's wrong; many choose single from plenty"},{"left":"\"Who'll care for you when old?\"","right":"Friends, family, savings can; marriage promises nothing"},{"left":"\"You'll regret staying single\"","right":"A pressured marriage brings more regret"},{"left":"\"An unmarried woman has less worth\"","right":"Worth is never marital status"}],"relearn":"Every 'you should marry' line has a calm truth; worth was never a wedding.","persona":"any","source":"pressure to truth"},
  {"id":"yp-1104","cat":"not-marrying","type":"match","hook":"Match each single-life worry to what actually steadies it.","pairs":[{"left":"Fear of loneliness later","right":"Investing in deep friendships and chosen family"},{"left":"Doubt from constant nagging","right":"Reconnecting with what you actually want"},{"left":"Wanting a partner, eventually","right":"Waiting for the right one on your own timeline"},{"left":"Feeling judged at weddings","right":"Letting others' pity pass as their script, not your truth"},{"left":"Worry about money alone","right":"Building your own savings and security"}],"relearn":"Each single-life worry has a real steadier, none of which is a rushed marriage.","persona":"Sneha","source":"worry to steadier"},
  {"id":"yp-1105","cat":"not-marrying","type":"reflect","hook":"Lensy: a full, rich life genuinely needs no marriage at all. Sit with that.","prompt":"What lands for you?","options":["My life is already full","I get to choose this","No wedding needed to matter"],"affirm":"A meaningful life is already yours, with or without a marriage; nothing is missing.","relearn":"A full, rich, meaningful life needs no marriage; nothing is missing without one.","persona":"any","source":"already full"},
  {"id":"yp-1106","cat":"not-marrying","type":"reflect","hook":"Lensy: other people's pity about you being single says more about their script than your life.","prompt":"How do you want to hold that?","options":["I'll let the pity pass","Their script, not my truth","I'm not waiting for anything"],"affirm":"Pity reveals the script's bias, not your reality; you can let it pass and keep your peace.","relearn":"Pity about being single reflects others' script, not your life; let it pass.","persona":"Sneha","source":"let pity pass"},
  {"id":"yp-1107","cat":"not-marrying","type":"reflect","hook":"Lensy: you can want a partner someday AND be completely happy single right now. Both true.","prompt":"Which feels right?","options":["Happy now, open later","No rush either way","My timeline is mine"],"affirm":"Wanting partnership someday and being happy single now aren't in conflict; the timeline is yours.","relearn":"You can be happy single now AND open to a partner later; the timeline is yours.","persona":"any","source":"happy now open later"},
  {"id":"yp-1170","cat":"script-and-choice","type":"strike-rewrite","hook":"\"There's a right order: degree, job, marriage, kids, in that sequence.\"","myth":{"un":"There's a right order: degree, job, marriage, kids, in that sequence.","re":"There's no fixed order; you can build your life's parts in whatever sequence fits you.","why":"That 'sequence' is a custom, not a rule your life owes anyone."},"relearn":"There's no fixed life sequence to follow; build your life in the order that fits you.","persona":"any","source":"no fixed order"},
  {"id":"yp-1171","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Two people in love will obviously want the same standard life.\"","myth":{"un":"Two people in love will obviously want the same standard life.","re":"Love means choosing a shared life together, not defaulting to the standard one.","why":"A couple gets to design their own path, not inherit a template."},"relearn":"A couple designs the shared life they actually want, not a default template.","persona":"any","source":"couple designs"},
  {"id":"yp-1172","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Adopting is 'plan B': a real family is your own blood.\"","myth":{"un":"Adopting is 'plan B': a real family is your own blood.","re":"Family is built by love and care, not only by blood; an adopted child is fully your child.","why":"Belonging is made by the people who show up, not by genetics alone."},"relearn":"Family is made by love and care; there are many real ways to build one.","persona":"any","source":"many ways to family"},
  {"id":"yp-1173","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Picking your own life over what's expected is just selfishness.\"","myth":{"un":"Picking your own life over what's expected is just selfishness.","re":"Choosing the life that's honestly yours is self-respect, not selfishness.","why":"You're the one who lives every day of your choice; owning it is fair, not selfish."},"relearn":"Choosing the life that's genuinely yours is self-respect, not selfishness.","persona":"any","source":"self-respect"},
  {"id":"yp-1174","cat":"script-and-choice","type":"strike-rewrite","hook":"\"A queer couple can't really build a family in India, so why bother.\"","myth":{"un":"A queer couple can't really build a family in India, so why bother.","re":"India has no same-sex marriage yet, but queer couples do build real, loving families and lives.","why":"A shared home, partnership and chosen family are real, whatever the law currently recognises."},"relearn":"Queer couples build real, loving families and lives, even where the law lags.","persona":"Aditya","source":"queer family real"},
  {"id":"yp-1175","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Stray from the usual path and you'll end up regretting it and alone.\"","myth":{"un":"Stray from the usual path and you'll end up regretting it and alone.","re":"A freely chosen path, even an unusual one, tends to bring less regret than a borrowed script.","why":"People more often regret the life they were pressured into than the one they chose."},"relearn":"A freely chosen path brings less regret than a life you were pressured into.","persona":"any","source":"less regret"},
  {"id":"yp-1176","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Choosing not to marry means you've simply given up on life.\"","myth":{"un":"Choosing not to marry means you've simply given up on life.","re":"Choosing not to marry is choosing a different full life, not giving up on one.","why":"Many people pick single life from abundance, not defeat."},"relearn":"Choosing not to marry is choosing a different full life, not giving up.","persona":"Sneha","source":"not giving up"},
  {"id":"yp-1177","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Cross thirty unmarried and the good options are basically gone.\"","myth":{"un":"Cross thirty unmarried and the good options are basically gone.","re":"There's no boat to miss; a full life, and partnership if wanted, can begin at any age.","why":"A real partnership forms when the right person and moment meet, not by a deadline."},"relearn":"There's no boat to miss; a full life and partnership can come at any age.","persona":"Sneha","source":"no boat to miss"},
  {"id":"yp-1178","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Settle for whoever's available now: you can't afford to be choosy.\"","myth":{"un":"Settle for whoever's available now. You can't afford to be choosy.","re":"Waiting for the right fit on your own timeline beats settling to beat a deadline.","why":"A rushed, pressured match risks far more regret than patiently choosing well."},"relearn":"Wait for the right fit on your timeline; don't settle just to beat a deadline.","persona":"any","source":"don't settle"},
  {"id":"yp-1179","cat":"script-and-choice","type":"strike-rewrite","hook":"\"Real adulthood only starts the day you get married.\"","myth":{"un":"Real adulthood only starts the day you get married.","re":"You're a full adult by living your own life responsibly: no certificate confers it.","why":"Maturity grows from how you live, not from a marital status."},"relearn":"Adulthood comes from how you live, not from being married.","persona":"any","source":"adulthood by living"},
  {"id":"yp-1180","cat":"script-and-choice","type":"strike-rewrite","hook":"\"The whole point of life is to settle down; anything else is a phase.\"","myth":{"un":"The whole point of life is to settle down; anything else is a phase.","re":"Settling down is one good aim among many; your own purpose can look entirely different.","why":"People draw meaning from many sources, not one prescribed milestone."},"relearn":"Settling down is one valid aim, not the single point of every life.","persona":"any","source":"one aim not the point"},
  {"id":"yp-1181","cat":"script-and-choice","type":"spot","hook":"Spot the two lines that pressure you onto the default script.","scene":[{"id":"a","text":"\"Whatever life you choose, I'm with you\"","trick":false},{"id":"b","text":"\"Everyone's married by your age, just do it\"","trick":true},{"id":"c","text":"\"Take your time and decide for yourself\"","trick":false},{"id":"d","text":"\"Stop overthinking and settle already\"","trick":true},{"id":"e","text":"\"It's your call, fully\"","trick":false}],"why":"'Everyone's married, just do it' and 'settle already' push the script; the others leave the choice with you.","relearn":"Lines that say 'just do it like everyone' push a script; 'it's your call' respects your choice.","persona":"any","source":"spot the pressure"},
  {"id":"yp-1182","cat":"script-and-choice","type":"spot","hook":"Spot the two beliefs that aren't true about building a family.","scene":[{"id":"a","text":"There are many valid ways to build a family","trick":false},{"id":"b","text":"Only your own biological child counts as real","trick":true},{"id":"c","text":"Adoption builds a fully real family","trick":false},{"id":"d","text":"A childfree life can be just as full","trick":false},{"id":"e","text":"A woman is incomplete until she's a mother","trick":true}],"why":"'Only biological counts' and 'incomplete until a mother' are myths; family takes many real forms and womanhood isn't motherhood.","relearn":"Family takes many real forms; womanhood isn't motherhood.","persona":"any","source":"spot the family myth"},
  {"id":"yp-1183","cat":"script-and-choice","type":"spot","hook":"Spot the two lines that judge a choice instead of respecting it.","scene":[{"id":"a","text":"\"You know your own life best\"","trick":false},{"id":"b","text":"\"You'll definitely regret this one day\"","trick":true},{"id":"c","text":"\"I respect whatever you decide\"","trick":false},{"id":"d","text":"\"That's not how decent people live\"","trick":true},{"id":"e","text":"\"Your path, your call\"","trick":false}],"why":"'You'll regret it' and 'not how decent people live' judge the choice; the others respect that it's yours.","relearn":"'You'll regret it' and 'not how decent people live' judge; respecting your call honours the choice.","persona":"any","source":"spot the judging"},
  {"id":"yp-1184","cat":"script-and-choice","type":"spot","hook":"Spot the two claims that rank a life by the wrong measure.","scene":[{"id":"a","text":"A life is measured by kindness and growth","trick":false},{"id":"b","text":"Your worth is your marital status","trick":true},{"id":"c","text":"Character and contribution are real worth","trick":false},{"id":"d","text":"An unmarried person is worth less","trick":true},{"id":"e","text":"You're whole exactly as you are","trick":false}],"why":"'Worth is your marital status' and 'unmarried is worth less' rank a life wrongly; worth is character, never status.","relearn":"Worth is character and kindness, never marital status.","persona":"any","source":"spot the wrong measure"},
  {"id":"yp-1185","cat":"script-and-choice","type":"spot","hook":"Spot the two timeline lines built to scare you.","scene":[{"id":"a","text":"\"There's no one right age for this\"","trick":false},{"id":"b","text":"\"Your clock is ticking, hurry up\"","trick":true},{"id":"c","text":"\"Take the time you genuinely need\"","trick":false},{"id":"d","text":"\"Decide now or you'll be left behind\"","trick":true},{"id":"e","text":"\"Your timeline can look different\"","trick":false}],"why":"'Your clock is ticking' and 'or you'll be left behind' are scare lines; there's no one right age and no boat to miss.","relearn":"'Clock is ticking' and 'left behind' are scare lines; there's no one timeline.","persona":"any","source":"spot the scare"},
  {"id":"yp-1186","cat":"script-and-choice","type":"spot","hook":"Spot the two lines that treat looks as your value.","scene":[{"id":"a","text":"\"Your worth has nothing to do with skin tone\"","trick":false},{"id":"b","text":"\"Get fairer or no good rishta will come\"","trick":true},{"id":"c","text":"\"Who you are is your real worth\"","trick":false},{"id":"d","text":"\"Lose weight first, then we'll find a match\"","trick":true},{"id":"e","text":"\"The marriage market measures nothing real\"","trick":false}],"why":"'Get fairer' and 'lose weight first' make looks your value; the market and colourism measure nothing real about you.","relearn":"Looks, skin tone and the marriage market measure nothing real about your worth.","persona":"any","source":"spot the colourism"},
  {"id":"yp-1187","cat":"script-and-choice","type":"spot","hook":"Spot the two lines that dismiss your own knowledge of yourself.","scene":[{"id":"a","text":"\"I trust you know what's right for you\"","trick":false},{"id":"b","text":"\"You're too young to know; you'll change\"","trick":true},{"id":"c","text":"\"It's okay to be unsure for now\"","trick":false},{"id":"d","text":"\"Everyone wants kids eventually, you will too\"","trick":true},{"id":"e","text":"\"Only you can decide this\"","trick":false}],"why":"'You'll change' and 'everyone wants kids, you will too' override your self-knowledge; you can trust what you know.","relearn":"Trust your own knowledge of yourself; 'you'll change your mind' isn't a fact about you.","persona":"Nisha","source":"spot the override"},
  {"id":"yp-1188","cat":"script-and-choice","type":"sort","hook":"Sort each line: respects your autonomy, or pressures you?","items":[{"id":"a","text":"\"Whatever you choose, I'm with you\""},{"id":"b","text":"\"Just settle, everyone does\""},{"id":"c","text":"\"It's completely your decision\""},{"id":"d","text":"\"You're running out of time\""},{"id":"e","text":"\"Take all the time you need\""},{"id":"f","text":"\"Stop being difficult and marry\""}],"bins":[{"id":"respects","label":"Respects you","valence":"pos"},{"id":"pressures","label":"Pressures you","valence":"neg"}],"key":{"a":"respects","b":"pressures","c":"respects","d":"pressures","e":"respects","f":"pressures"},"relearn":"Lines that leave the choice with you respect autonomy; 'just settle, you're out of time' pressures.","persona":"any","source":"respect vs pressure"},
  {"id":"yp-1189","cat":"script-and-choice","type":"sort","hook":"Sort each into: a real way to build a family, or a myth?","items":[{"id":"a","text":"Marrying and raising kids"},{"id":"b","text":"Adopting a child"},{"id":"c","text":"Choosing to be childfree"},{"id":"d","text":"\"Only blood is real family\""},{"id":"e","text":"A chosen family of friends"},{"id":"f","text":"\"You're incomplete without a baby\""}],"bins":[{"id":"real","label":"Real path","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Marrying, adopting, childfree, chosen family are all real; 'only blood' and 'incomplete without a baby' are myths.","persona":"any","source":"family real vs myth"},
  {"id":"yp-1190","cat":"script-and-choice","type":"sort","hook":"Sort: a real measure of a person, or an imposed one?","items":[{"id":"a","text":"Kindness and character"},{"id":"b","text":"Marital status"},{"id":"c","text":"How you treat people"},{"id":"d","text":"Skin tone"},{"id":"e","text":"Growth and the love you give"},{"id":"f","text":"Your score on the rishta market"}],"bins":[{"id":"real","label":"Real worth","valence":"pos"},{"id":"imposed","label":"Imposed","valence":"neg"}],"key":{"a":"real","b":"imposed","c":"real","d":"imposed","e":"real","f":"imposed"},"relearn":"Character, kindness and growth are real worth; marital status, skin tone and the market are imposed.","persona":"any","source":"real vs imposed"},
  {"id":"yp-1191","cat":"script-and-choice","type":"sort","hook":"Sort: whose call is each one, yours, or society's noise?","items":[{"id":"a","text":"Whether you want children"},{"id":"b","text":"\"Log kya kahenge\""},{"id":"c","text":"Whom you spend your life with"},{"id":"d","text":"Relatives' approval rating"},{"id":"e","text":"When, if ever, you marry"},{"id":"f","text":"The colony aunties' verdict"}],"bins":[{"id":"yours","label":"Your call","valence":"pos"},{"id":"noise","label":"Just noise","valence":"neg"}],"key":{"a":"yours","b":"noise","c":"yours","d":"noise","e":"yours","f":"noise"},"relearn":"Your partner, kids and marriage are your call; 'log kya kahenge' and aunties' verdicts are just noise.","persona":"any","source":"your call vs noise"},
  {"id":"yp-1192","cat":"script-and-choice","type":"sort","hook":"Sort each life into: a valid path, or 'not a real life'?","items":[{"id":"a","text":"Single and thriving by choice"},{"id":"b","text":"Married with three kids"},{"id":"c","text":"A childfree couple"},{"id":"d","text":"\"That's just a sad, empty life\""},{"id":"e","text":"Partnered, unmarried, content"},{"id":"f","text":"\"They clearly settled for less\""}],"bins":[{"id":"valid","label":"Valid life","valence":"pos"},{"id":"verdict","label":"A judging verdict","valence":"neg"}],"key":{"a":"valid","b":"valid","c":"valid","d":"verdict","e":"valid","f":"verdict"},"relearn":"Single, married, childfree and partnered-unmarried are all valid; 'sad, empty' is just a judging verdict.","persona":"any","source":"valid vs verdict"},
  {"id":"yp-1193","cat":"script-and-choice","type":"sort","hook":"Sort: a question worth asking yourself, or one you owe no answer?","items":[{"id":"a","text":"\"What life do I genuinely want?\""},{"id":"b","text":"\"When's the good news?\""},{"id":"c","text":"\"What matters most to me?\""},{"id":"d","text":"\"Why are you still single?\""},{"id":"e","text":"\"Does this path fit me?\""},{"id":"f","text":"\"When will you give them a grandchild?\""}],"bins":[{"id":"owe","label":"Worth asking yourself","valence":"pos"},{"id":"dont","label":"You owe no answer","valence":"neg"}],"key":{"a":"owe","b":"dont","c":"owe","d":"dont","e":"owe","f":"dont"},"relearn":"Ask yourself what you want; you owe no one an answer to 'when's the good news?' or 'why still single?'.","persona":"any","source":"owe vs don't"},
  {"id":"yp-1194","cat":"script-and-choice","type":"sort","hook":"Sort each reply to pressure: warm-but-firm, or self-losing?","items":[{"id":"a","text":"\"I know you care; this is my decision\""},{"id":"b","text":"\"Fine, do whatever you want with my life\""},{"id":"c","text":"\"Let's change the subject, please\""},{"id":"d","text":"\"Okay, set up the meeting, I give up\""},{"id":"e","text":"\"My answer's the same, and I love you\""},{"id":"f","text":"\"I'll just marry to stop the nagging\""}],"bins":[{"id":"firm","label":"Warm but firm","valence":"pos"},{"id":"lost","label":"Loses yourself","valence":"neg"}],"key":{"a":"firm","b":"lost","c":"firm","d":"lost","e":"firm","f":"lost"},"relearn":"A warm, firm boundary holds your ground; caving or marrying 'to stop the nagging' loses you.","persona":"any","source":"firm vs lost"},
  {"id":"yp-1195","cat":"script-and-choice","type":"sort","hook":"Sort: a freeing belief about timing, or a pressuring one?","items":[{"id":"a","text":"\"There's no one right age\""},{"id":"b","text":"\"It's now or never for you\""},{"id":"c","text":"\"My timeline can be my own\""},{"id":"d","text":"\"The clock is running out\""},{"id":"e","text":"\"Partnership can come at any age\""},{"id":"f","text":"\"You've already missed the boat\""}],"bins":[{"id":"free","label":"Freeing","valence":"pos"},{"id":"press","label":"Pressuring","valence":"neg"}],"key":{"a":"free","b":"press","c":"free","d":"press","e":"free","f":"press"},"relearn":"'No one right age' frees you; 'now or never' and 'missed the boat' are pressuring scare lines.","persona":"any","source":"timing free vs press"},
  {"id":"yp-1196","cat":"script-and-choice","type":"sort","hook":"Sort each statement: true about a childfree life, or a myth?","items":[{"id":"a","text":"It can be full of love and purpose"},{"id":"b","text":"\"It's selfish to choose it\""},{"id":"c","text":"Womanhood isn't motherhood"},{"id":"d","text":"\"You'll regret it for sure\""},{"id":"e","text":"You owe no one a justification"},{"id":"f","text":"\"You're not a complete woman\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"A childfree life is full and valid and owes no justification; 'selfish', 'you'll regret it' and 'incomplete' are myths.","persona":"Nisha","source":"childfree true vs myth"},
  {"id":"yp-1197","cat":"script-and-choice","type":"sort","hook":"Sort: a reason that's truly yours, or a borrowed one?","items":[{"id":"a","text":"\"Because this life genuinely fits me\""},{"id":"b","text":"\"Because everyone else did it\""},{"id":"c","text":"\"Because I've thought it through\""},{"id":"d","text":"\"Because people will talk otherwise\""},{"id":"e","text":"\"Because it's what I actually want\""},{"id":"f","text":"\"Because my relatives expect it\""}],"bins":[{"id":"yours","label":"Truly yours","valence":"pos"},{"id":"borrowed","label":"Borrowed","valence":"neg"}],"key":{"a":"yours","b":"borrowed","c":"yours","d":"borrowed","e":"yours","f":"borrowed"},"relearn":"A reason rooted in what fits you is yours; 'everyone did it' and 'people will talk' are borrowed.","persona":"any","source":"yours vs borrowed reason"},
  {"id":"yp-1198","cat":"script-and-choice","type":"sort","hook":"Sort: stands with someone pressured, or piles on?","items":[{"id":"a","text":"\"Your choice is valid; I've got you\""},{"id":"b","text":"\"They're right, you should just marry\""},{"id":"c","text":"\"Tell me how I can back you up\""},{"id":"d","text":"\"Stop embarrassing the family\""},{"id":"e","text":"\"You don't have to explain yourself\""},{"id":"f","text":"\"Everyone agrees something's wrong with you\""}],"bins":[{"id":"stands","label":"Stands with them","valence":"pos"},{"id":"piles","label":"Piles on","valence":"neg"}],"key":{"a":"stands","b":"piles","c":"stands","d":"piles","e":"stands","f":"piles"},"relearn":"Backing a loved one's choice breaks the pressure cycle; piling on with the crowd deepens it.","persona":"any","source":"stands vs piles"},
  {"id":"yp-1199","cat":"script-and-choice","type":"branch","persona":"any","source":"wedding aunt","hook":"At a wedding, an aunt loudly asks the whole table when YOUR turn is. You aren't looking right now and would rather keep it light.","steps":[{"prompt":"The whole table turns to you, waiting. What do you do?","options":[{"text":"Smile, say 'when it's right for me', and change the topic","then":"The table chuckles and moves on to the next course.","best":true},{"text":"Mumble a fake date just to make her stop","then":"The fake date gets repeated as fact for the rest of the night."},{"text":"Snap that it's none of her business, loud enough for all","then":"A public snap starts a scene, and a rift with the family."},{"text":"Laugh and agree it's high time, so she'll drop it","then":"She beams, and 'high time' gets passed around the table as good news."}],"why":"A smile, a simple line and a new topic close the question without a scene."},{"prompt":"Later, the aunt finds you alone and quietly returns to the subject. What do you do?","options":[{"text":"Tell her kindly that it's your call, and leave it there","then":"She nods. \"Alright, alright,\" she says, though she doesn't sound finished.","best":true},{"text":"Explain all your reasons, so she finally understands","then":"Each reason becomes something new for her to argue with."},{"text":"Promise to think about it seriously this year","then":"She takes it as a yes-in-waiting and tells your mother."},{"text":"Avoid her for the rest of the wedding","then":"The avoidance is noticeable, and the question waits for the next event."}],"why":"Telling her kindly it's your call, without a debate, keeps the boundary steady."},{"prompt":"As you leave, she calls out that she'll find someone by the next wedding. What do you say?","options":[{"text":"Laugh, wave, and call back 'we'll see, aunty!'","then":"Your laugh sounds like a yes, and her plan for 'next time' stays alive."},{"text":"Say yes and let her go ahead and look","then":"A profile arrives on WhatsApp before you've even reached the car."},{"text":"Smile, and ask her kindly not to look for anyone","then":"She pauses, surprised, then nods. \"Alright, I hear you.\"","best":true},{"text":"Say nothing and just walk faster","then":"The silence reads as either agreement or offence, unclear which."}],"why":"A kind, direct ask to stop closes the matchmaking itself, not just tonight's talk."}],"debrief":"A light, warm-but-firm deflection closes a nosy question without a fight.","relearn":"A light, closed deflection ends a nosy 'when's your turn?' without a fight."},
  {"id":"yp-1200","cat":"script-and-choice","type":"branch","persona":"any","source":"paused rishta","hook":"Your parents lined up a rishta meeting you never agreed to.","steps":[{"prompt":"They tell you the family is arriving this Sunday. What do you do?","options":[{"text":"Calmly say no to Sunday, and ask them to pause the search","then":"They look surprised, but agree to postpone the visit.","best":true},{"text":"Go along silently to avoid a fight","then":"Sunday comes, and you're in a room with strangers you never chose to meet."},{"text":"Cut off contact and storm out","then":"You leave for a friend's place, and the family goes quiet for days."},{"text":"Cancel it yourself without telling them, at least for now","then":"They find out and feel blindsided by the secrecy."}],"why":"Saying no calmly, and asking for a pause, is clearer than silence or a blow-up."},{"prompt":"A few days later, your parents ask where you actually stand on marriage. What do you do?","options":[{"text":"Tell them honestly, even if it isn't what they hope","then":"They're quiet for a while, but they listen to the whole answer.","best":true},{"text":"Say you'll marry soon, so they'll stop worrying","then":"The worry eases for them, and a deadline appears for you."},{"text":"Refuse to explain anything at all","then":"The silence leaves them guessing, and a little hurt."},{"text":"Blame them for setting it up too fast","then":"The blame turns their question into an argument."}],"why":"An honest answer, even an unwelcome one, respects them more than a cover story."},{"prompt":"A month later, they mention another family who would like to meet. What do you do?","options":[{"text":"Tell them kindly you want the search paused","then":"They sigh, but agree to turn the family down for now.","best":true},{"text":"Agree to a meeting you're still not sure about","then":"The meeting happens, built on a yes that isn't fully yours."},{"text":"Get frustrated they're asking again so soon","then":"The frustration overshadows what could be a simple answer."},{"text":"Avoid the conversation entirely","then":"The avoidance leaves the question hanging over every visit."}],"why":"A kind, clear ask to pause keeps the timing, and the choice, yours."},{"prompt":"Months on, your parents ask how they'll know if you ever want their help. What do you do?","options":[{"text":"Say you'll come to them, if you ever want it","then":"They look relieved to have an answer they can trust.","best":true},{"text":"Say they can keep an eye out, just in case","then":"The search quietly restarts, and a biodata arrives within a month."},{"text":"Give them a date to check back with you","then":"The date turns into a deadline everyone is watching."},{"text":"Tell them to stop asking about it, ever","then":"The door shuts hard, and they feel pushed out of your life."}],"why":"Offering to come to them yourself keeps the timeline, and the choice, yours."}],"debrief":"A clear, loving no that asks them to pause beats silent compliance or a blow-up.","relearn":"Restate your no and ask them to pause the matchmaking; a firm-but-loving no deserves respect."},
  {"id":"yp-1201","cat":"script-and-choice","type":"branch","persona":"Nisha","source":"own childfree call","hook":"You've quietly realised you don't want children, but everyone assumes you will.","steps":[{"prompt":"Over dinner, your husband asks what you picture for the next few years. What do you say?","options":[{"text":"Tell him plainly that you don't want children","then":"He listens closely, and the honesty opens a real conversation.","best":true},{"text":"Say you're still deciding, to buy some time","then":"The 'still deciding' answer buys time, and delays the real talk."},{"text":"Say what you think he wants to hear","then":"The comfortable answer isn't quite the true one."},{"text":"Change the subject before he can ask more","then":"The question waits, unanswered, for another day."}],"why":"Saying what you know about yourself, plainly, is how the real conversation starts."},{"prompt":"A few days later, he says he has always pictured kids in your future. What do you do?","options":[{"text":"Ask where he stands, and share honestly where you are","then":"He takes a breath, and the two of you talk it through, slowly and honestly.","best":true},{"text":"Tell him he'll come around to your view eventually","then":"He goes quiet, feeling his own view has been decided for him."},{"text":"Say kids might happen someday, to keep things calm","then":"The calm holds, but he keeps planning for a future you don't want."},{"text":"Get defensive that he assumed anything at all","then":"He says he was only being honest, and the talk stalls there."}],"why":"Sharing where you are, and asking where he is, makes it a decision you face together."},{"prompt":"Your mother-in-law starts asking when the 'good news' is coming. What do you do?","options":[{"text":"Tell her calmly it's for the two of you to decide","then":"She looks taken aback, but lets the subject drop for today.","best":true},{"text":"Leave it to your husband to handle her","then":"He mumbles something vague, and she keeps asking him instead."},{"text":"Explain in detail why you don't want children","then":"She argues each point, and the talk turns into a family debate."},{"text":"Say 'soon, hopefully' to keep the peace","then":"She beams, and the question returns next month with more hope."}],"why":"A calm 'that's ours to decide' owns the choice without owing anyone a justification."}],"debrief":"A childfree life is complete and valid; trust your own knowledge of yourself.","relearn":"Trust your own knowledge of yourself; a childfree life is a complete, valid choice."},
  {"id":"yp-1202","cat":"script-and-choice","type":"branch","persona":"any","source":"decline colourism","hook":"A relative keeps suggesting fairness creams before your rishta meetings.","steps":[{"prompt":"She hands you a bag of creams before the first meeting. What do you do?","options":[{"text":"Say your worth isn't your skin tone; decline calmly","then":"She looks surprised, but puts the bag away without a fight.","best":true},{"text":"Take the bag, just to avoid an argument before the meeting","then":"The bag sits on your shelf, a small compromise you didn't want."},{"text":"Throw the bag away in front of her","then":"She stares at the bin, and your mother spends the ride to the meeting smoothing things over."},{"text":"Say nothing and quietly start using them","then":"By the second week, you're checking your face in every mirror."}],"why":"Declining calmly names the market as false, without a fight."},{"prompt":"She says the last match 'passed' because of your complexion. What do you do?","options":[{"text":"Say that's the market's bias, not your worth","then":"She pauses, unsure how to respond to that.","best":true},{"text":"Wonder quietly if she's right about it","then":"You replay her words that night, and the doubt follows you into the next meeting."},{"text":"Get angry at her for repeating it","then":"The anger lands on the messenger, not the actual problem."},{"text":"Ask what shade would have worked better, then","then":"She names a lighter shade, and starts listing which creams would match it."}],"why":"Naming the bias as the problem, not your face, keeps your worth intact."},{"prompt":"At the next meeting, the family comments on your skin directly. What do you do?","options":[{"text":"Stay composed and decide if this family fits you","then":"The room goes awkward and the comment isn't repeated. Afterwards you think over whether this family fits you.","best":true},{"text":"Apologise for how you look, out of habit","then":"The apology teaches the room that the comment was fair."},{"text":"Snap back with a jab about their own looks","then":"The room goes cold, and the talk turns to how you reacted instead of what was said."},{"text":"Tell yourself the family is probably just being honest","then":"The thought follows you home, and the comment starts to feel like a fact."}],"why":"Staying composed, without apologising for your looks, holds your worth steady."},{"prompt":"Afterwards, your relative asks how the meeting went, and brings up the creams again. What do you do?","options":[{"text":"Say plainly you won't be using them","then":"She looks surprised, then a little thoughtful.","best":true},{"text":"Say you'll try them before the next meeting","then":"She smiles, and a second bag arrives at your door that week."},{"text":"Say they probably would have helped","then":"She nods, pleased, and says she will pick out the best ones for you."},{"text":"Get irritated at the question itself","then":"She says she only asked, and the question about the creams hangs there."}],"why":"A plain, unapologetic answer refuses the ranking without a fight."}],"debrief":"Skin tone and the marriage market measure nothing real; worth isn't your looks.","relearn":"Your worth isn't your looks or skin tone; colourism measures nothing real."},
  {"id":"yp-1203","cat":"script-and-choice","type":"branch","persona":"any","source":"don't rush to keep up","hook":"Friends are marrying fast and you feel a pull to rush a relationship to keep up.","steps":[{"prompt":"A third friend announces her engagement this month. What do you do?","options":[{"text":"Notice the pull, and choose your own pace anyway","then":"The pull passes, and your own pace stays steady.","best":true},{"text":"Message an ex to see if he's still available","then":"The message opens an old door out of comparison, not want."},{"text":"Decide you're clearly falling behind","then":"The comparison story starts to feel like fact."},{"text":"Avoid the engagement news entirely","then":"The avoidance doesn't quiet the pull, just the noise around it."}],"why":"Noticing the pull without acting on it keeps the pace genuinely yours."},{"prompt":"You match with someone fun, but not quite right, on an app. What do you do?","options":[{"text":"Enjoy the match without forcing it into more","then":"The match stays light, honest about what it actually is.","best":true},{"text":"Push it forward fast, to match your friends' pace","then":"The pushing strains something that was never meant to be that."},{"text":"End it abruptly out of frustration","then":"The abrupt end skips a perfectly fine, light connection."},{"text":"Compare him constantly to your friends' partners","then":"The comparison ruins a match that was fine on its own terms."}],"why":"Letting a match be what it is, honestly, beats forcing a fit that isn't there."},{"prompt":"At the third wedding this year, the aunties pull you onto the dance floor, teasing that you're next. What do you do?","options":[{"text":"Laugh it off; a joke isn't a deadline","then":"You laugh along, unbothered by the old ribbing.","best":true},{"text":"Take it as a sign to move faster","then":"An aunty's joke becomes an odd new pressure in your head."},{"text":"Refuse to dance at all, pointedly","then":"The pointed refusal makes a bigger scene than the moment needed."},{"text":"Book a matchmaker the next morning, just in case","then":"A deadline you never set starts running your weekends."}],"why":"A wedding joke is tradition, not a real timeline; there's no boat to miss."}],"debrief":"There's no boat to miss; wait for the right person. Don't settle to a deadline.","relearn":"Wait for the right person on your own timeline; don't settle to a deadline."},
  {"id":"yp-1204","cat":"script-and-choice","type":"branch","persona":"Nisha","source":"allowed to be unsure","hook":"You're genuinely unsure whether you want kids, and people demand a firm answer.","steps":[{"prompt":"A friend asks point-blank if you're having kids or not. What do you say?","options":[{"text":"Say honestly you're still unsure, and that's allowed","then":"She nods, a little surprised, and doesn't push further.","best":true},{"text":"Say 'yes, someday' just to end the questions","then":"The 'yes' follows you into the next conversation as fact."},{"text":"Get irritated at being asked so directly","then":"The irritation surprises her; it was a genuine question."},{"text":"Brush it off with a joke, hiding the real answer","then":"The joke lands, but nobody learns you're genuinely unsure."}],"why":"Naming your uncertainty honestly gives you room, without faking a certainty you don't have."},{"prompt":"Your husband asks if the uncertainty worries you. What do you do?","options":[{"text":"Say it's okay to sit with the not-knowing together","then":"He relaxes. \"Together sounds good,\" he says.","best":true},{"text":"Say you'll force yourself to decide by a date","then":"The forced date adds pressure to a decision that needs room."},{"text":"Say you'll go with whatever he wants","then":"He looks relieved, then unsure whether you actually agree."},{"text":"Say it shouldn't be a topic between you two","then":"The topic doesn't go away, just underground."}],"why":"Sitting with the not-knowing, together, is honest room the decision needs."},{"prompt":"A relative insists you must 'want something', deep down. What do you do?","options":[{"text":"Say uncertainty is a real, honest answer too","then":"The relative pauses, unsure how to argue with that.","best":true},{"text":"Guess an answer just to satisfy the question","then":"The guess gets repeated as your real position from then on."},{"text":"Say maybe they know better than you do","then":"Handing over the question doesn't actually answer it."},{"text":"Refuse to discuss it at all, ever again","then":"The topic goes silent, but the pressure just moves elsewhere."}],"why":"Naming uncertainty as a real, honest answer refuses forced certainty."}],"debrief":"You can be honestly unsure about children; you owe no one forced certainty.","relearn":"You can be honestly unsure about children; you don't owe anyone forced certainty."},
  {"id":"yp-1205","cat":"script-and-choice","type":"branch","persona":"Aditya","source":"plan on facts","hook":"As a queer couple, you're weighing how to build a family in India.","steps":[{"prompt":"A friend mentions same-sex marriage 'must be legal by now'. What do you do?","options":[{"text":"Correct it gently; India has no same-sex marriage yet","then":"He looks surprised. \"Oh, I didn't realise,\" he says.","best":true},{"text":"Let the mistake stand. It's easier for now","then":"The mistake spreads, and someone else repeats it as fact next week."},{"text":"Get frustrated at how little people know","then":"You snap at him, and he looks taken aback by the edge in your voice."},{"text":"Say you're not sure either, honestly","then":"The uncertainty leaves him with the wrong idea still standing."}],"why":"Correcting the record gently keeps the planning grounded in what's real."},{"prompt":"You and your partner sit down to talk about routes to a family. What do you do?","options":[{"text":"Read up on the actual legal routes available to you","then":"The research is dense, but it gives you something solid to plan on.","best":true},{"text":"Assume nothing's possible, and don't bother researching","then":"Weeks pass, and you still have no idea which routes exist for you."},{"text":"Believe a hopeful rumour without checking it","then":"The rumour turns out to be false, and the setback stings more."},{"text":"Wait for the law to change before researching","then":"Months pass while the law stays as it is, and you still have no plan."}],"why":"Planning on facts, not hope or despair, keeps the path realistic and real."},{"prompt":"A relative asks how two men could possibly have a child. What do you do?","options":[{"text":"Share what you're comfortable sharing, accurately","then":"She listens, surprised to get a straight answer.","best":true},{"text":"Answer with a legal route you only half remember","then":"She repeats your half-remembered answer to the family, and it turns out to be wrong."},{"text":"Get defensive at the way she asked it","then":"The defensiveness makes the real answer harder to hear."},{"text":"Agree with her that it can't really be done","then":"She nods and tells the family it can't be done, and the idea settles in as fact."}],"why":"You owe no explanation; if you do answer, plain facts replace confusion, guesses and despair."},{"prompt":"You learn about a legal restriction that affects one of the routes open to you. What do you do?","options":[{"text":"Adjust the plan honestly around the real restriction","then":"The plan shifts, still grounded in what's actually possible.","best":true},{"text":"Ignore the restriction and hope it won't apply to you","then":"Ignoring it risks a setback further down a longer road."},{"text":"Shelve the whole plan the moment one restriction hits","then":"You put the plan aside in the sting of the moment, though the restriction had not closed every route."},{"text":"Assume a lawyer will find a way around it","then":"You wait for a lawyer to find a way, and the plan stalls with no answer yet."}],"why":"Adjusting honestly around real restrictions keeps the plan buildable."},{"prompt":"Some time later, a fresh setback affects your family plans. What do you do?","options":[{"text":"Talk it through together and decide the next step as a couple","then":"It takes time, but the two of you decide together what comes next.","best":true},{"text":"Take it as proof the whole plan was a mistake","then":"You go quiet about the plan, and your partner asks what changed."},{"text":"Hide the setback from your partner to protect him","then":"The hiding adds a second problem to the first one."},{"text":"Rush a workaround without checking if it's legal","then":"You rush into a workaround nobody has checked, and a bigger risk opens up."}],"why":"A setback isn't a verdict on the plan; deciding the next step together keeps it your choice."}],"debrief":"India has no same-sex marriage yet, but queer couples build real families; plan on facts.","relearn":"Queer couples build real families on the actual routes, not false legal hope or despair."},
  {"id":"yp-1206","cat":"script-and-choice","type":"branch","persona":"any","source":"stand with cousin","hook":"A cousin, 20 and younger than you, is being pressured into an early marriage and looks to you.","steps":[{"prompt":"She finds you alone at a family gathering, looking uneasy. What do you do?","options":[{"text":"Listen first, and believe what she tells you","then":"She relaxes slightly, like she's been waiting to be believed.","best":true},{"text":"Say you'll tell her parents right away, to fix it","then":"She looks frightened. \"Please don't. Not yet.\""},{"text":"Tell her she's too young to understand the pressure","then":"She goes quiet, and the door that had opened starts to close."},{"text":"Change the subject to lighten the mood","then":"The moment passes, and she doesn't bring it up again today."}],"why":"Believing her first, without taking over, keeps the door open."},{"prompt":"A few days later, she says she doesn't know how to say no to the family. What do you do?","options":[{"text":"Help her find words she could actually say","then":"You practise a few lines together, and she looks a little steadier.","best":true},{"text":"Tell her exactly what to say, word for word","then":"The words are yours, not quite hers, and she looks unsure repeating them."},{"text":"Say she just has to be braver about it","then":"She looks down, as if being scared were her fault."},{"text":"Offer to say no for her, directly","then":"She looks torn between relief and losing her own voice in it."}],"why":"Helping her find her own words respects her voice in a decision that's hers."},{"prompt":"A week later, she says the family set a date anyway. What do you do?","options":[{"text":"Ask what she needs from you right now","then":"She thinks, then says she just needs someone to know.","best":true},{"text":"Tell her parents yourself without her knowing","then":"She finds out later and feels her trust was used without asking."},{"text":"Tell her to just go along with it for peace","then":"She nods slowly, and stops meeting your eyes."},{"text":"Urge her to leave home tonight, whatever it takes","then":"She looks terrified, and says she has nowhere to go."}],"why":"Asking what she needs, rather than deciding for her, keeps her choices hers."},{"prompt":"She asks if there's really anything that can be done. What do you do?","options":[{"text":"Share the helpline, and offer to be with her","then":"She saves the number, and for the first time looks a little less alone.","best":true},{"text":"Tell her it's basically out of her hands now","then":"She goes quiet, hearing her own hopelessness said aloud."},{"text":"Promise you'll personally stop the wedding","then":"The promise is bigger than what you can actually deliver."},{"text":"Say it's really between her and her parents","then":"The distance leaves her carrying the fear on her own."}],"why":"It's never her fault; a real number and real company offer help without overpromising."},{"prompt":"Weeks later, an aunt takes you aside and tells you to stop 'filling her head'. What do you do?","options":[{"text":"Say calmly that you'll keep being there for her","then":"The aunt huffs and walks off, and your cousin still messages you that night.","best":true},{"text":"Agree to step back, to keep the family calm","then":"The aunt looks satisfied, and your cousin stops hearing from you."},{"text":"Tell the aunt everything your cousin shared with you","then":"The aunt confronts your cousin that evening, and she stops confiding in you."},{"text":"Shout that the family is ruining her life","then":"The row spills over, and your cousin is the one who gets blamed."}],"why":"Staying steady for her, without breaking her trust or starting a row, keeps you on her side."}],"debrief":"If anyone is pressured or forced into marriage, call 181, 1091, 112 or Childline 1098.","relearn":"Stand with a loved one being pressured; break the pressure cycle for a younger relative."},
  {"id":"yp-1207","cat":"script-and-choice","type":"branch","persona":"any","source":"reset the measure","hook":"You keep grading your whole life by one measure: are you married yet.","steps":[{"prompt":"On a quiet Sunday, you catch yourself feeling behind again. What do you do?","options":[{"text":"Pause and ask what you actually value about your week","then":"You notice good talks, work you're proud of, and rest you took.","best":true},{"text":"Text a married friend to ask if you're falling behind","then":"She says you're fine, but the reassurance fades by evening."},{"text":"Let the thought stand, since you're probably behind","then":"The thought settles in and colours the rest of your day."},{"text":"Open a matrimonial app just to feel like you're doing something","then":"You close it an hour later, no closer to feeling settled."}],"why":"Naming what you value resets the measure better than any outside reassurance."},{"prompt":"A cousin on a family call jokes that you're 'still waiting'. What do you focus on?","options":[{"text":"What you're actually building right now","then":"You answer easily, and the joke loses its sting fast.","best":true},{"text":"Whether she has a point about your timeline","then":"You spend the call doing quiet math on your age instead of listening."},{"text":"A sharp comeback for next time","then":"You rehearse a line all evening instead of enjoying the call."},{"text":"Whether your parents feel the same way she does","then":"You leave the call more worried about them than about yourself."}],"why":"Your own answer matters more than a script written by someone else's joke."},{"prompt":"A day later, you sit down to list what makes a week feel good to you. What tops the list?","options":[{"text":"Work, friendships, rest, days that feel like mine","then":"The list feels honest, and 'married yet' never makes it.","best":true},{"text":"How close I am to checking the marriage box","then":"The list mostly retells the old measure in new words."},{"text":"What would impress my relatives most","then":"The list ends up being about them, not you."},{"text":"Skip it, since this feels like a silly exercise","then":"You skip it, and the old measure quietly stays in charge."}],"why":"A list built from your own values shows the real measure, not the borrowed one."},{"prompt":"A friend asks how you're doing, really. What do you tell her?","options":[{"text":"That you're starting to notice what actually matters to you","then":"She says that sounds like relief, and you realise it is.","best":true},{"text":"That you're fine, but you'll only feel settled once you're engaged","then":"She nods kindly, but your sense of being settled is still tied to a future date."},{"text":"That you're behind but trying not to think about it","then":"Saying it out loud makes the old measure feel heavier."},{"text":"That everything's perfect, no notes","then":"She senses you're holding something back, and the talk stays surface."}],"why":"Naming what you're noticing keeps your own measure in charge, wherever you're starting from."},{"prompt":"Months later, someone at a function asks about 'good news' again. What do you say?","options":[{"text":"Smile, and talk about the life you're actually living","then":"You talk easily about your week, and the question passes without weight.","best":true},{"text":"Give a rehearsed line and change the subject fast","then":"It works, but you still feel a flicker of the old measure underneath."},{"text":"Decide the question proves you're behind after all","then":"You replay it all evening, and the old measure creeps back in."},{"text":"Joke that you're 'still on the market'","then":"It gets a laugh, but it also feeds the very idea you're dropping."}],"why":"Answering from your real life, not a script, is what keeps the old measure from deciding for you."}],"debrief":"Anchor your worth in who you are, not whether you've 'settled down'. You're whole either way.","relearn":"Anchor your worth in who you are, not whether you've 'settled down'."},
  {"id":"yp-1208","cat":"script-and-choice","type":"branch","persona":"any","source":"love and autonomy","hook":"You want a life that doesn't match the script, but fear disappointing your parents.","steps":[{"prompt":"At Sunday lunch, your father says he just wants to see you 'settled' soon. What do you do?","options":[{"text":"Tell him gently that you're building a different, full life","then":"He listens, quiet, then asks what that life looks like for you.","best":true},{"text":"Nod along and let him believe you'll marry soon","then":"He relaxes, already picturing plans you haven't agreed to."},{"text":"Get defensive and say he doesn't understand you","then":"The lunch turns tense, and neither of you really hears the other."},{"text":"Change the subject to avoid the topic entirely","then":"Lunch stays easy, but the real conversation waits for another day."}],"why":"Naming your own path gently opens a door, instead of dodging it or agreeing to something you don't mean."},{"prompt":"A week later, your mother calls, still turning the conversation over in her mind. What do you say?","options":[{"text":"Explain what you actually want your future to hold","then":"She's quiet, then admits she never really asked you that before.","best":true},{"text":"Reassure her everything will work out, without saying how","then":"She's comforted for now, but the same worry returns by next call."},{"text":"Tell her it's none of her concern","then":"She goes quiet, hurt, and the call ends short."},{"text":"Ask her to stop worrying and hang up","then":"The call ends fast, but her worry doesn't."}],"why":"Sharing what you actually want answers her fear better than reassurance or distance."},{"prompt":"At a family function, a relative loudly asks if you've 'seen sense yet'. What do you do?","options":[{"text":"Staying calm and naming that this is your call","then":"The relative shrugs and moves to the next topic at the table.","best":true},{"text":"Laughing it off without saying anything real","then":"The laugh works for the room, but leaves your actual answer unsaid."},{"text":"Matching their volume and arguing back","then":"The table goes quiet, and the story spreads by evening."},{"text":"Leaving the table to avoid the question","then":"You miss the rest of the evening, and the question just waits for next time."}],"why":"A calm, clear line holds your ground without turning the room into an audience for a fight."},{"prompt":"Months on, your father asks if you're happy with how things turned out. What do you tell him?","options":[{"text":"That you are, and that this life is genuinely yours","then":"He nods slowly, and for the first time seems to actually believe you.","best":true},{"text":"That you're managing, to keep him from worrying","then":"He looks relieved, but the real answer stays between you."},{"text":"That you're not sure, just to be agreeable","then":"He looks concerned again, and the old worry returns."},{"text":"That it's complicated, and change the subject","then":"The moment passes without either of you saying what's true."}],"why":"A plain, honest yes lets him see the choice is working, not just tolerated."}],"debrief":"You can love your family and not let them dictate your life. Both can be true.","relearn":"You can love your family and still not let them dictate your life."},
  {"id":"yp-1209","cat":"script-and-choice","type":"branch","persona":"any","source":"reach for support","hook":"Family conflict over your choice to stay single has started to weigh on you.","steps":[{"prompt":"After another round of arguing about marriage, you notice you're not sleeping well. What do you do?","options":[{"text":"Reach out to a counsellor or a trusted person","then":"Saying it out loud to someone steady already makes it feel lighter.","best":true},{"text":"Push through and hope it settles on its own","then":"The tiredness carries straight into the next family gathering too."},{"text":"Blame yourself for upsetting everyone with your choice","then":"The guilt piles on top of the tiredness, and nothing about the arguing changes."},{"text":"Agree to meet a match, just to end the arguing","then":"The arguing stops, but the decision was never really yours."}],"why":"A counsellor or trusted person helps carry the weight; you don't have to hold it alone."},{"prompt":"That night, replaying the conflict, you try to pin down what's actually been hardest about it. What do you land on?","options":[{"text":"That you feel unheard, not just pressured","then":"Naming that to yourself makes it clearer what you actually need to say, and to whom.","best":true},{"text":"That your family is simply wrong about everything","then":"It feels satisfying to think, but it doesn't get you any closer to a way forward."},{"text":"That you probably just need to try harder to please them","then":"The thought doesn't sit right, even as you think it."},{"text":"That it's nothing. You're managing fine","then":"The thought passes, but the tiredness underneath doesn't."}],"why":"Naming what feels unheard, not just the pressure, is what turns into something you can actually say."},{"prompt":"At the next family dinner, an uncle brings up marriage again. How do you handle it now?","options":[{"text":"Stay calm and repeat your answer clearly","then":"You feel steadier than before, even though the question is the same.","best":true},{"text":"Let a cousin answer for you and stay out of it","then":"Your cousin fumbles the answer, and the uncle turns back to you later."},{"text":"Snap at him in front of everyone","then":"The table goes tense, and the real issue gets lost in the moment."},{"text":"Apologise to everyone for causing so much trouble","then":"The table quiets, but you leave feeling you owed them that apology."}],"why":"A steady, repeated answer holds the line without needing to feel resolved first."}],"debrief":"When family conflict turns distressing, reach for support: a counsellor or a trusted person. It is never your fault.","relearn":"If family conflict over your choices turns distressing, reach for support."},
  {"id":"yp-1210","cat":"script-and-choice","type":"match","hook":"Match each nosy line to a calm, closed reply.","pairs":[{"left":"\"Why still single?\"","right":"\"I'm happy as I am\""},{"left":"\"When's the good news?\"","right":"\"Nothing to report; how are you?\""},{"left":"\"Clock's ticking!\"","right":"\"My timeline's my own\""},{"left":"\"Settle down already\"","right":"\"I'll decide when it's right\""},{"left":"\"Log kya kahenge?\"","right":"\"Their talk isn't my obligation\""}],"relearn":"A calm, closed reply ends a nosy question without a fight or a justification.","persona":"any","source":"closed replies"},
  {"id":"yp-1211","cat":"script-and-choice","type":"match","hook":"Match each pressure to the truth that answers it.","pairs":[{"left":"\"You're incomplete without a child\"","right":"Womanhood isn't motherhood"},{"left":"\"Unmarried means less worth\"","right":"Worth was never status"},{"left":"\"You'll change your mind\"","right":"You know your own life"},{"left":"\"You've missed the boat\"","right":"There's no boat to miss"},{"left":"\"Get fairer for a match\"","right":"Colourism measures nothing"}],"relearn":"Each common pressure has a steady answering truth: worth isn't status, childfree is complete, you know your life.","persona":"any","source":"pressure to truth"},
  {"id":"yp-1212","cat":"script-and-choice","type":"match","hook":"Match each life choice to the respect it deserves.","pairs":[{"left":"Marrying young by choice","right":"Equally valid"},{"left":"Staying single","right":"A full life"},{"left":"Being childfree","right":"Complete"},{"left":"Adopting","right":"Real family"},{"left":"Partnering later","right":"On your timeline"}],"relearn":"Every freely chosen path, whether early marriage, single, childfree, adoptive or later, deserves equal respect.","persona":"any","source":"choice to respect"},
  {"id":"yp-1213","cat":"script-and-choice","type":"match","hook":"Match each situation to the right help route.","pairs":[{"left":"Being forced into marriage","right":"Call 181, 1091 or 112"},{"left":"A child being married off","right":"Childline 1098"},{"left":"Family-conflict distress","right":"A counsellor or trusted person"},{"left":"Just a nosy relative","right":"A calm boundary"},{"left":"Doubting your own choice","right":"Quiet reflection, your call"}],"relearn":"Forced marriage to 181, 1091 or 112; a child married off to Childline 1098; distress to a counsellor or trusted person.","persona":"any","source":"help routes"},
  {"id":"yp-1214","cat":"script-and-choice","type":"match","hook":"Match the right question to ask yourself in each moment.","pairs":[{"left":"Facing the default script","right":"\"What do I actually want?\""},{"left":"Hearing 'log kya kahenge'","right":"\"Is this mine to carry?\""},{"left":"A big life decision","right":"\"Does this fit me?\""},{"left":"Drowning in others' opinions","right":"\"What do I think, quietly?\""},{"left":"Years from now","right":"\"Could I own this choice?\""}],"relearn":"Ask not 'what's expected?' but 'what do I actually want?', reflecting quietly away from the noise.","persona":"any","source":"questions to self"},
  {"id":"yp-1215","cat":"script-and-choice","type":"match","hook":"Match each thing to where worth does, or doesn't, live.","pairs":[{"left":"Kindness you show","right":"Real worth"},{"left":"Your marital status","right":"Not your worth"},{"left":"How you grow","right":"Builds worth"},{"left":"Your skin tone","right":"Measures nothing"},{"left":"The love you give","right":"True worth"}],"relearn":"Worth lives in character, growth and love, never in marital status or skin tone.","persona":"any","source":"where worth lives"},
  {"id":"yp-1216","cat":"script-and-choice","type":"match","hook":"Match each belief to whether it frees you or boxes you in.","pairs":[{"left":"\"One path, not the path\"","right":"Frees you"},{"left":"\"Everyone must settle down\"","right":"Boxes you in"},{"left":"\"My life, my call\"","right":"Sets you free"},{"left":"\"There's one right timeline\"","right":"Traps you"},{"left":"\"Many ways to a good life\"","right":"Opens doors"}],"relearn":"'One path not the path' and 'my call' free you; 'everyone must settle' and 'one timeline' box you in.","persona":"any","source":"frees vs boxes"},
  {"id":"yp-1217","cat":"script-and-choice","type":"match","hook":"Match each way of building a family to what makes it real.","pairs":[{"left":"Biological children","right":"One real way"},{"left":"Adoption","right":"Love and care"},{"left":"A childfree partnership","right":"Full on its own"},{"left":"A chosen family","right":"The people who show up"},{"left":"Co-parenting with kin","right":"Shared raising"}],"relearn":"Family is real through love and care; biological, adoptive, childfree, chosen: all are real ways.","persona":"Aditya","source":"real family ways"},
  {"id":"yp-1218","cat":"script-and-choice","type":"role-play","persona":"any","source":"warm boundary","hook":"A relative insists you must marry within the year, and won't let it go.","setup":"At tea, he brings up marriage again, more insistent than before.","steps":[{"prompt":"He says: \"I've already found some good families. When can we start meeting them?\"","options":[{"text":"\"I know you care, but this is my decision to make.\"","then":"He pauses. \"Fair enough. I just want you settled.\"","best":true},{"text":"\"Maybe next year. Let's not rush into it now.\"","then":"He nods, relieved, and starts planning around 'next year' instead."},{"text":"\"Stop interfering in my life, please.\"","then":"He looks wounded. \"I'm only trying to help.\""},{"text":"\"Okay fine, go ahead and show me who you found.\"","then":"He brightens and starts describing families before you can think twice."}],"why":"Naming it as your decision, warmly, holds the line without shutting him out."},{"prompt":"At the next visit, he says: \"Your mother and I both think you're taking too long about this.\"","options":[{"text":"\"I know you both care. It's still my decision.\"","then":"He sighs. \"Alright. We just worry. That's all.\"","best":true},{"text":"\"Fine, I'll think about meeting one family.\"","then":"He tells your mother you've agreed, before you've decided anything."},{"text":"\"So now it's two against one?\"","then":"The visit turns tense, and dinner is quieter than usual."},{"text":"\"Whatever makes you both happy, I suppose.\"","then":"He takes that as a yes, and a meeting gets fixed for next week."}],"why":"Repeating the same warm line, even against two voices, keeps your answer consistent."},{"prompt":"A few weeks later, he catches you alone and asks, \"So? Where are we with this?\"","options":[{"text":"\"Same answer. Tell me about your garden instead.\"","then":"He chuckles despite himself and starts talking about his tomatoes.","best":true},{"text":"\"I'm still thinking about it. Give me some more time.\"","then":"He takes 'thinking about it' as progress and asks again the next week."},{"text":"\"Why do you keep asking the same thing?\"","then":"He looks defensive. \"Because I care, that's why.\""},{"text":"\"Fine, one meeting, just to end this.\"","then":"A meeting gets arranged before you've really agreed to it."}],"why":"A steady repeat, paired with a redirect, closes the topic without another round of debate."},{"prompt":"Months later, after all that back and forth, he finally says: \"I still don't fully understand it, but I've stopped pushing.\"","options":[{"text":"\"Thank you for trusting me, even now.\"","then":"He smiles. \"You're still my family. That's what matters.\"","best":true},{"text":"\"So can I count on you to tell the others too?\"","then":"He looks caught off guard. \"One thing at a time, beta.\""},{"text":"\"Good, because I was getting tired of this.\"","then":"He looks stung, and takes a step back rather than closer."},{"text":"\"I told you so. I knew you'd come around.\"","then":"He goes quiet, and the warmth between you cools a little."}],"why":"Thanking him for trusting you keeps the relationship warm now that the boundary has held."}],"relearn":"Hold a marriage boundary warmly: 'I know you care, and this is my decision.'"},
  {"id":"yp-1219","cat":"script-and-choice","type":"role-play","persona":"Sneha","source":"light deflection","hook":"You're happy with your life, but family dinners keep turning into questions about it.","setup":"Tonight, an aunty leans over during dessert.","steps":[{"prompt":"Aunty asks: \"So beta, why still no shaadi? What's the delay?\"","options":[{"text":"\"Happily single for now. So, how's everyone doing?\"","then":"Aunty blinks, then laughs and asks about your cousin's exams instead.","best":true},{"text":"\"I don't know. Maybe no one wants me.\"","then":"Aunty tuts sympathetically and starts listing matches she knows."},{"text":"\"That's a rather personal thing to ask at dinner, aunty.\"","then":"The table goes quiet. Aunty says she 'only asked out of love'."},{"text":"\"Soon, soon. I'm sure it'll happen.\"","then":"Aunty brightens and asks when exactly 'soon' will be."}],"why":"A light, closed line ends the question warmly, with no defence needed."},{"prompt":"Uncle says: \"No, but really, beta, when's this shaadi happening?\"","options":[{"text":"\"Happily single. Tell me about your last holiday instead.\"","then":"Uncle chuckles. \"Fine, fine. Let me tell you about Goa.\"","best":true},{"text":"\"Give me some time, maybe next year.\"","then":"Uncle nods. \"Next year, pakka? I'll remind you.\""},{"text":"\"Why does everyone keep asking me this?\"","then":"Uncle shrugs. \"Because we all care about you, no?\""},{"text":"\"I really don't know anymore. Can we please stop asking me this?\"","then":"The table goes a bit awkward, and uncle looks taken aback."}],"why":"Repeating the same light line, and redirecting, keeps the question from becoming a debate."},{"prompt":"Months later, a relative asks at another gathering: \"Still single, hain?\"","options":[{"text":"\"Very happily so. Now, who's trying that new sweet shop?\"","then":"The conversation shifts easily to sweets, no awkward pause at all.","best":true},{"text":"\"Still working on it. Don't worry.\"","then":"The relative nods, unconvinced, and asks again at the next function."},{"text":"\"Yes, and honestly, I'm getting a bit tired of this question by now.\"","then":"The relative looks taken aback, and the mood cools slightly."},{"text":"\"Maybe soon. Who knows.\"","then":"The relative takes 'maybe soon' as a hopeful sign and tells others."}],"why":"A light, warm deflection lets the evening move on without a fight or a defence."}],"relearn":"A light, closed deflection ends 'why still single?' without a fight or a defence."},
  {"id":"yp-1220","cat":"script-and-choice","type":"role-play","persona":"Nisha","source":"deflect baby question","hook":"Your family treats your baby plans as everyone's business.","setup":"At tonight's family dinner, dessert has just arrived.","steps":[{"prompt":"Uncle asks: \"So, any good news yet? When are we celebrating?\"","options":[{"text":"\"No news to share. We're happy as we are, thanks.\"","then":"Uncle nods and moves on to asking about the food instead.","best":true},{"text":"\"We've had some medical trouble, and I owe you all the details.\"","then":"Uncle looks sympathetic, and the questions about doctors and tests start coming."},{"text":"\"Soon, soon. Don't worry about it.\"","then":"Uncle brightens, thinking 'soon' means an announcement is close."},{"text":"\"Why is that even anyone's business but ours?\"","then":"Uncle looks taken aback, and the table goes a little quiet."}],"why":"A calm no-news answer closes the topic without inviting more questions or explanations."},{"prompt":"Your mother-in-law asks over tea: \"Any good news to share yet?\"","options":[{"text":"\"Nothing to share right now. This chai is lovely, though.\"","then":"She smiles and starts talking about the chai instead.","best":true},{"text":"\"We're trying, and we'll tell you the moment there's news.\"","then":"She nods, delighted, and says she'll check in every few weeks."},{"text":"\"I really wish people would stop asking me this.\"","then":"She looks a little hurt. \"I only ask because I care.\""},{"text":"\"I keep wondering if I'm letting everyone down.\"","then":"She looks concerned and starts suggesting doctors you should see."}],"why":"Owing no explanation, and redirecting warmly, keeps the moment light and closes the topic."},{"prompt":"At a cousin's baby shower, someone asks: \"So when's it going to be your turn?\"","options":[{"text":"\"We're happy exactly as we are, actually.\"","then":"The person nods, a little surprised, and asks about the shower gifts instead.","best":true},{"text":"\"Maybe next year. We'll see.\"","then":"The person takes 'we'll see' as a promise and brings it up again soon."},{"text":"\"You really shouldn't ask people that, you know.\"","then":"The person looks embarrassed, and the moment turns a bit awkward."},{"text":"\"Honestly, I've stopped even trying to answer that question anymore.\"","then":"The person looks unsure how to respond, and the silence stretches a moment."}],"why":"Saying you're happy as you are, plainly, ends the guessing without owing anyone an answer."}],"relearn":"You don't owe anyone a child; deflect 'when are you having kids?' calmly."},
  {"id":"yp-1221","cat":"script-and-choice","type":"role-play","persona":"any","source":"boundary and redirect","hook":"Pressure to marry keeps repeating despite a clear no you've already given.","setup":"Tonight, the same relative brings it up again at dinner.","steps":[{"prompt":"The relative says: \"We really think you should reconsider and meet this family.\"","options":[{"text":"\"Same answer. Let's talk about something else.\"","then":"The relative sighs and starts talking about the weather instead.","best":true},{"text":"\"Let's just wait and see how I feel later.\"","then":"The relative takes 'wait and see' as a maybe and follows up in a week."},{"text":"\"Stop bringing this up, seriously.\"","then":"The relative looks offended and brings it up twice as often now."},{"text":"\"Fine. One meeting probably won't hurt anything.\"","then":"A meeting gets arranged before you've properly agreed to anything."}],"why":"Repeating the same short answer, and changing the subject, ends the round without a fight."},{"prompt":"The next day, a different aunt calls and asks: \"So, when is this happening?\"","options":[{"text":"\"I'm still not looking to marry right now. How's your garden doing?\"","then":"Aunt laughs and happily switches to talking about her tomatoes.","best":true},{"text":"\"Maybe I'll think about it a bit more.\"","then":"Aunt tells the family you're 'thinking about it', and the calls continue."},{"text":"\"Why does everyone keep calling about this?\"","then":"Aunt sighs. \"Because we're all one family, that's why.\""},{"text":"\"Honestly I don't even know what I want anymore, so who knows.\"","then":"Aunt sounds worried now, and asks if everything is okay with you."}],"why":"A short, consistent answer to every caller keeps your line from getting muddled or reopened."},{"prompt":"At the next family gathering, three relatives raise it together: \"We really think it's time.\"","options":[{"text":"\"My answer hasn't changed. Let's talk about something else.\"","then":"The group quiets, and one of them changes the subject to cricket.","best":true},{"text":"\"Okay, okay, I'll consider it properly this time.\"","then":"The group brightens, thinking 'consider it' means you're close to yes."},{"text":"\"Can everyone please just drop this already?\"","then":"The group goes quiet, a little stung by the sharp tone."},{"text":"\"I don't know what to say anymore. Honestly, I've lost track.\"","then":"The group exchanges looks, unsure whether to push further or stop."}],"why":"The same calm line, even to a group, holds the boundary without escalating the moment."},{"prompt":"Weeks later, your mother says: \"I've stopped bringing it up myself, you know.\"","options":[{"text":"\"Thank you, Ma. That means a lot to me.\"","then":"She smiles, and the two of you talk about something else entirely.","best":true},{"text":"\"Good, because I was getting really tired of this.\"","then":"She looks a little stung, even though she agrees to stop."},{"text":"\"See, I told you all I meant it.\"","then":"She looks a bit defensive, even though she's backing off."},{"text":"\"I know. It's about time, honestly.\"","then":"The moment feels flatter than it should, given how far you've come."}],"why":"Thanking her for respecting the boundary keeps the relationship warm now that it's held."}],"relearn":"Set a kind, firm boundary and redirect when the pressure repeats."},
  {"id":"yp-1222","cat":"script-and-choice","type":"role-play","persona":"any","source":"name your path","hook":"You want to tell your parents you've chosen a different life.","setup":"Tonight, after dinner, you decide to finally say it plainly.","steps":[{"prompt":"Your father asks: \"Beta, why do you seem so hesitant to talk to us lately?\"","options":[{"text":"\"I've decided on a life that's different, and I want to explain it.\"","then":"He sits back. \"Okay. I'm listening.\"","best":true},{"text":"\"It's nothing. I'm just tired.\"","then":"He lets it go, but the tension between you stays."},{"text":"\"Why do you always assume there's something seriously wrong?\"","then":"He looks taken aback. \"I'm not assuming. I'm asking.\""},{"text":"\"I'll tell you eventually, just not today.\"","then":"He nods slowly, but you can tell he's still worried."}],"why":"Naming it plainly, instead of hiding it, lets him actually respond to what's true."},{"prompt":"Your mother says: \"Whatever it is, we just want to understand.\"","options":[{"text":"\"I've thought this through carefully. This is genuinely me.\"","then":"She nods. \"Then help us understand it with you.\"","best":true},{"text":"\"You'll understand eventually. I don't want to explain now.\"","then":"She looks unsettled, filling the silence with her own guesses."},{"text":"\"You wouldn't understand anyway.\"","then":"She looks hurt. \"Give us a chance to try.\""},{"text":"\"It's just a normal life. Don't make it a big thing.\"","then":"She nods, but you can tell she doesn't quite believe you."}],"why":"Naming your certainty, without shutting them out, invites them to actually understand."},{"prompt":"Your father asks quietly: \"Are you sure this is really what you want?\"","options":[{"text":"\"Yes. I've weighed it for a long time, and I'm sure.\"","then":"He exhales, then nods. \"Then I want to support that.\"","best":true},{"text":"\"I think so, but I could change my mind if you're upset.\"","then":"He looks uneasy. \"I don't want you choosing for us.\""},{"text":"\"Why would I tell you if I wasn't sure?\"","then":"He raises his hands. \"It's a fair thing for a father to ask.\""},{"text":"\"Ask me again in a year, and we'll see.\"","then":"He nods slowly, and the question waits between you."}],"why":"Saying plainly that you're sure gives him something real to stand behind."}],"relearn":"Tell family honestly you've thought it through and chosen the life that's right for you."},
  {"id":"yp-1223","cat":"script-and-choice","type":"role-play","persona":"any","source":"hold your worth","hook":"Your looks have become a family topic whenever a rishta comes up.","setup":"At a family function, an aunty pulls you aside during photos.","steps":[{"prompt":"Aunty says: \"You know, beta, you'd photograph so much better a shade fairer.\"","options":[{"text":"\"I'm not changing my skin for anyone's approval. I'm fine as I am.\"","then":"Aunty pauses, then shrugs. \"Just saying, for the photos.\"","best":true},{"text":"\"Maybe I should try those fairness creams.\"","then":"Aunty nods approvingly and mentions a brand she likes."},{"text":"\"That's a really rude thing to say to me.\"","then":"Aunty looks wounded. \"I only meant it kindly.\""},{"text":"\"Okay, I'll think about it, maybe.\"","then":"Aunty looks pleased and brings it up again at the next function."}],"why":"Naming your worth plainly refuses the comment without needing to explain or soften it."},{"prompt":"Later, a cousin says: \"Don't mind her. She means well, you know.\"","options":[{"text":"\"Maybe, but it still wasn't okay to say.\"","then":"Cousin nods. \"Fair. I'll say something next time.\"","best":true},{"text":"\"It's fine. I'm used to it by now.\"","then":"Cousin shrugs, and the comment quietly stays unaddressed."},{"text":"\"She's honestly always like this.\"","then":"Cousin laughs it off, and the moment passes without much thought."},{"text":"\"I guess I shouldn't take it so seriously.\"","then":"Cousin looks relieved you're not upset, and it's never mentioned again."}],"why":"Naming that it wasn't okay, even kindly meant, keeps your worth from being brushed aside."},{"prompt":"At the next family event, aunty says: \"Your sister, now, she should try to be a shade fairer too.\"","options":[{"text":"\"Please don't say that to her either. It isn't true.\"","then":"Aunty looks surprised, then quieter, and lets the topic go.","best":true},{"text":"\"She's young. She probably won't even notice.\"","then":"Your sister overhears anyway, and it quietly stings."},{"text":"\"You really need to stop saying things like that.\"","then":"Aunty looks defensive, and the room feels tense for a moment."},{"text":"\"Aunty doesn't mean anything by it. Let's move on.\"","then":"Your sister hears it too, and no one says otherwise."}],"why":"Speaking up for someone else, calmly, stops the comment from becoming a family habit."},{"prompt":"Months later, aunty says: \"I've stopped commenting on anyone's skin now, you know.\"","options":[{"text":"\"Thank you. That means a lot to hear.\"","then":"Aunty smiles, a little sheepish. \"Old habits, I suppose.\"","best":true},{"text":"\"Good, because it really bothered people.\"","then":"Aunty looks a touch defensive, even while agreeing."},{"text":"\"See, I told you it wasn't okay.\"","then":"Aunty nods, but the moment feels a little flat."},{"text":"\"About time, honestly.\"","then":"Aunty looks stung, even though she's backing off."}],"why":"Thanking her for the change keeps the relationship warm now that the comment has stopped."}],"relearn":"Your worth isn't your skin tone; you don't owe the marriage market a 'fairer' you."},
  {"id":"yp-1224","cat":"script-and-choice","type":"role-play","persona":"any","source":"stand with her aloud","hook":"Your sister is pressured about marriage and looks to you.","setup":"Tonight, after a tense call, she comes to your room.","steps":[{"prompt":"She says: \"They keep telling me I have to decide by this year. I don't know what to do.\"","options":[{"text":"\"Your choice is valid, and I'm with you no matter what you pick.\"","then":"She exhales, relieved. \"I needed to hear that from someone.\"","best":true},{"text":"\"Maybe just pick someone so this pressure will finally stop.\"","then":"She looks more unsettled, weighing a choice that isn't really hers."},{"text":"\"Honestly, they might have a point about the timing.\"","then":"She looks hurt, hearing doubt from you too."},{"text":"\"Just ignore them. It'll blow over eventually.\"","then":"She nods, but the pressure doesn't actually stop."}],"why":"Backing her choice, plainly, gives her one steady voice in a room full of pressure."},{"prompt":"At dinner, your mother says: \"This whole thing has me so stressed.\"","options":[{"text":"\"Her choice is valid. I'm with her on this.\"","then":"Your mother goes quiet, then softens a little. \"I just worry.\"","best":true},{"text":"\"Maybe you're right. I'll talk to her.\"","then":"Your mother nods, relieved, and asks you to 'convince' your sister."},{"text":"\"You're honestly the one putting all this pressure on her, not me.\"","then":"The table tenses, and dinner turns quiet for a while."},{"text":"\"I'm staying out of it from now on.\"","then":"Your sister notices your silence later, and feels a little more alone."}],"why":"Repeating that her choice is valid, even to your mother, keeps your sister from standing alone."},{"prompt":"Weeks later, your sister tells you, nervous: \"I've decided. I want to wait.\"","options":[{"text":"\"I'm proud of you for choosing what's actually right for you.\"","then":"She smiles, steadier than before. \"That helps more than you know.\"","best":true},{"text":"\"Are you sure? That's a big decision to make.\"","then":"She second-guesses herself again, hearing your hesitation."},{"text":"\"I hope you're ready for everything people are going to say about this.\"","then":"She looks anxious again, right when she'd found her footing."},{"text":"\"Okay, well, good luck with that.\"","then":"She nods, but the moment feels flatter than it should."}],"why":"Meeting her decision with pride, not doubt, is what real support sounds like."}],"relearn":"Stand with a loved one being pressured; say their choice is valid and you're with them."},
  {"id":"yp-1225","cat":"script-and-choice","type":"reflect","hook":"Lensy: marriage and kids are one path, not the measure of a life. Sit with that.","prompt":"What feels true for you?","options":["One path","Not the measure","My life, my call"],"affirm":"One path among many, and yours to choose freely. The measure of a life is so much more than a status.","relearn":"Marriage and kids are one valid path, not the measure of a life.","persona":"any","source":"one path reflect"},
  {"id":"yp-1226","cat":"script-and-choice","type":"reflect","hook":"Lensy: the question isn't 'what's expected of me?' but 'what do I actually want?'.","prompt":"Which question will you carry?","options":["What I want","Not what's expected","Quietly, my own"],"affirm":"Asking what you genuinely want, away from the noise, is how you build a life that's truly yours.","relearn":"Ask not 'what's expected?' but 'what do I actually want?'.","persona":"any","source":"what i want reflect"},
  {"id":"yp-1227","cat":"script-and-choice","type":"reflect","hook":"Lensy: a childfree life can be just as full of love and purpose as any other.","prompt":"What sits right with you?","options":["Full of love","Purpose, my way","Complete as is"],"affirm":"Meaning comes from many sources; parenthood is one, not the only one. A childfree life is whole.","relearn":"A childfree life can be just as full of love, purpose and meaning as any other.","persona":"Nisha","source":"childfree full reflect"},
  {"id":"yp-1228","cat":"script-and-choice","type":"reflect","hook":"Lensy: you can love your family and still not let them write your life.","prompt":"What's true for you?","options":["I love them","And it's my life","Both can be true"],"affirm":"Love and autonomy aren't opposites. You can hold both: care for them, and choose for yourself.","relearn":"You can love your family and still not let them dictate your life.","persona":"any","source":"love and autonomy reflect"},
  {"id":"yp-1229","cat":"script-and-choice","type":"reflect","hook":"Lensy: your worth was never your marital status, your looks, or anyone's market.","prompt":"Where does your worth live?","options":["In who I am","Not in status","Not in looks"],"affirm":"Worth lives in your character, kindness and growth, never in a status or a marriage market.","relearn":"Your worth was never your marital status, looks, or the marriage market.","persona":"any","source":"worth reflect"},
  {"id":"yp-1230","cat":"script-and-choice","type":"reflect","hook":"Lensy: choosing to marry and have kids is equally valid and worthy of respect.","prompt":"What feels even-handed to you?","options":["That's valid too","No pressure either way","Respect every path"],"affirm":"The stance is against pressure, not against marriage. Every freely chosen path deserves respect.","relearn":"Choosing to marry and have kids is equally valid and worthy of respect: no pressure either way.","persona":"any","source":"even-handed reflect"},
  {"id":"yp-1231","cat":"script-and-choice","type":"reflect","hook":"Lensy: whichever path you choose, choose it freely, own it fully, and respect everyone else's.","prompt":"What will you carry forward?","options":["Choose freely","Own it fully","Respect others' paths"],"affirm":"Freely chosen, fully owned, and generous to every other path: that's a life lived on your own terms.","relearn":"Whichever path you choose, choose it freely, own it fully, and respect everyone else's.","persona":"any","source":"carry forward reflect"},
  {"id":"yp-1260","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: before the next family WhatsApp ping about rishtas, ask yourself one thing first, 'what do I actually want?'. Useful?","prompt":"What do you think?","options":["Yes","Ask myself first","The real question"],"affirm":"Starting from 'what do I actually want?' keeps the choice yours, before anyone else weighs in.","relearn":"Ask not 'what's expected?' but 'what do I actually want?'.","persona":"any","source":"the real question"},
  {"id":"yp-1261","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: you can sit quietly with this, away from every aunty's opinion, and just notice what feels true for you. Try it?","prompt":"What do you think?","options":["Yes","Sit with it","Away from the noise"],"affirm":"A quiet, honest check-in with yourself, free of others' voices, often brings the clearest answer.","relearn":"Reflect privately on what you truly want, away from the noise.","persona":"any","source":"private reflection"},
  {"id":"yp-1262","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: marrying and raising kids is a beautiful path too, just as worthy as any other. Hold that alongside your own choice?","prompt":"What do you think?","options":["Yes","Equally worthy","Hold both"],"affirm":"Marrying and having children is an equally valid, respected path; this is about freedom, never against anyone.","relearn":"Choosing to marry and have kids is equally valid and worthy of respect.","persona":"any","source":"no pressure either way"},
  {"id":"yp-1263","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: your life, your call, on marriage, on children, on the whole shape of it. Sit with that freedom a second?","prompt":"What do you think?","options":["Yes","My life my call","Feel the freedom"],"affirm":"Your life is genuinely yours to shape, on marriage, children and the whole path; that's real freedom.","relearn":"Your life, your call, on marriage, children and the whole path.","persona":"any","source":"your life your call"},
  {"id":"yp-1264","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: the stance here is simple, respect every path, never pressure, never shame. Does that feel right to carry?","prompt":"What do you think?","options":["Yes","Respect every path","Carry it"],"affirm":"Respecting every path and worth-beyond-status, with no pressure or shame, is the whole stance.","relearn":"The stance: respect every path, never pressure, never shame.","persona":"any","source":"the stance"},
  {"id":"yp-1265","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: if a cousin is being pushed toward a wedding she's unsure about, you could be the one voice that says 'your call'. Want to be that?","prompt":"What would you offer?","options":["I'm with you","Your call","No pressure from me"],"affirm":"Being the one person who respects someone's choice can change how they weather the whole pressure.","relearn":"Validate and stand with a loved one being pressured; be the voice that respects their call.","persona":"any","source":"being an ally"},
  {"id":"yp-1266","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: you can love your parents deeply AND keep this decision your own. Can both be true at once?","prompt":"What do you think?","options":["Yes, both","Love and decide","They co-exist"],"affirm":"You can love your family fully and still hold your own choices; the two were never in conflict.","relearn":"You can love your family and still not let them dictate your life.","persona":"any","source":"love and autonomy"},
  {"id":"yp-1267","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: whichever path you walk, marry or not, kids or not, you get to own it fully. Ready to carry that?","prompt":"What will you carry?","options":["Choose freely","Own it fully","Respect every path","Worth beyond status"],"affirm":"Choose freely and own it fully, and respect everyone else's path; that's the heart of your path being your call.","relearn":"Whichever path you choose, choose it freely, own it fully, and respect everyone else's.","persona":"any","source":"carry forward"},
  {"id":"yp-1268","cat":"tools-and-reflection","type":"reflect","hook":"Lensy, to Sneha: a full single life isn't a waiting room, it's a life. Does naming it that way help?","prompt":"What do you think?","options":["Yes","Not a waiting room","A full life now"],"affirm":"A single life is a whole life right now, not a pause before the 'real' one begins.","relearn":"A single life is full now, not a waiting room for marriage.","persona":"Sneha","source":"not a waiting room"},
  {"id":"yp-1269","cat":"tools-and-reflection","type":"reflect","hook":"Lensy, to Nisha: 'unsure about kids' is an honest, allowed answer, you don't owe anyone forced certainty. Sit with that?","prompt":"What do you think?","options":["Yes","Unsure is okay","No forced certainty"],"affirm":"You can be honestly unsure about children; you owe no one a rushed or performed certainty.","relearn":"You can be honestly unsure about children; you don't owe anyone forced certainty.","persona":"Nisha","source":"unsure is okay"},
  {"id":"yp-1270","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: 'log kya kahenge' is a sentence about other people's comfort, not your obligation. Notice the difference?","prompt":"What do you think?","options":["Yes","Their comfort, not my duty","I see it"],"affirm":"'Log kya kahenge' is social pressure dressed as concern; it was never an obligation you signed.","relearn":"Recognise 'log kya kahenge' as social pressure, not your obligation.","persona":"any","source":"naming the pressure"},
  {"id":"yp-1271","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: the people who truly love you care who you are, not your relationship status. Who comes to mind?","prompt":"What do you think?","options":["Yes","They love who I am","I have a few"],"affirm":"People who truly love you value who you are, not whether you've 'settled down'.","relearn":"People who truly love you value who you are, not your relationship status.","persona":"any","source":"who really loves you"},
  {"id":"yp-1272","cat":"tools-and-reflection","type":"reflect","hook":"Lensy, to Karthik: men feel a quieter version of 'settle down' too, even if it lands hardest on women. Does naming it help?","prompt":"What do you think?","options":["Yes","I feel it too","Hardest on women, still real"],"affirm":"Men feel a version of this pressure too, even though it falls hardest on women; both can be true.","relearn":"Men feel a version of the 'settle down' pressure too, though it falls hardest on women.","persona":"Karthik","source":"men feel it too"},
  {"id":"yp-1273","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: a meaningful life can be measured by kindness, growth and love, not by a marriage certificate. Worth holding onto?","prompt":"What do you think?","options":["Yes","Kindness and growth","Not the certificate"],"affirm":"Measure a life by kindness, growth and love; marital status was never the real yardstick.","relearn":"Measure a life by kindness, growth and love, not marital status.","persona":"any","source":"the real measure"},
  {"id":"yp-1274","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: if family conflict over your choices ever gets too heavy, reaching for a counsellor or trusted person isn't weakness. Agree?","prompt":"What do you think?","options":["Yes","Reaching out is strength","Good to know"],"affirm":"When the conflict gets heavy, leaning on a counsellor or trusted person is a strong, kind move.","relearn":"If family conflict over your choices turns distressing, reach for support.","persona":"any","source":"reaching for support"},
  {"id":"yp-1275","cat":"tools-and-reflection","type":"reflect","hook":"Lensy, to Aditya: building a family the law doesn't yet recognise still builds a real family. Does that land as true?","prompt":"What do you think?","options":["Yes","Real either way","A family is a family"],"affirm":"A family built on love and commitment is real, whatever recognition the law has yet to catch up to.","relearn":"There are many ways to build a family; love and commitment make it real.","persona":"Aditya","source":"many ways to family"},
  {"id":"yp-1276","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: 'you'll change your mind' is someone else's guess, not your truth. You're allowed to trust your own knowing. Right?","prompt":"What do you think?","options":["Yes","Trust my own knowing","Their guess, not my truth"],"affirm":"You can trust your own knowledge of yourself; 'you'll change your mind' is a guess, not a verdict.","relearn":"Trust your own knowledge of yourself; you needn't accept 'you'll change your mind'.","persona":"any","source":"trust your knowing"},
  {"id":"yp-1277","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: there's no boat to miss, the right partnership, if you want one, can arrive at any age. Does that ease the rush?","prompt":"What do you think?","options":["Yes","No boat to miss","No rush"],"affirm":"There's no 'boat' to miss; a full life, and partnership if wanted, can come on your own timeline.","relearn":"There's no 'boat' to miss; the right partnership can come at any age.","persona":"any","source":"no boat to miss"},
  {"id":"yp-1278","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: choosing not to marry can come from abundance, a full life you don't want to trade. Recognise that in yourself?","prompt":"What do you think?","options":["Yes","From abundance","Not from lack"],"affirm":"Many choose single life from abundance, not lack; there's nothing missing to apologise for.","relearn":"Nothing is wrong with being single; many choose it from abundance, not lack.","persona":"any","source":"from abundance"},
  {"id":"yp-1279","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: you don't owe anyone a justification for the life you're living. Permission to stop explaining yourself?","prompt":"What do you think?","options":["Yes","Stop explaining","I owe no justification"],"affirm":"You owe no one a justification for your path; a calm, unexplained choice is complete on its own.","relearn":"You don't owe anyone a justification for your life choices.","persona":"any","source":"no justification owed"},
  {"id":"yp-1280","cat":"tools-and-reflection","type":"reflect","hook":"Lensy: one child, several, or none, each can be exactly right for a different couple. Does that make room for everyone?","prompt":"What do you think?","options":["Yes","Room for everyone","All can be right"],"affirm":"One child, several or none can all be right; the decision belongs to the couple, not the relatives.","relearn":"One child, several, or none can all be right; the decision belongs to the couple.","persona":"any","source":"all can be right"},
  {"id":"yp-1281","cat":"tools-and-reflection","type":"sort","hook":"Sort each line: a kind, firm boundary, or caving to the pressure?","items":[{"id":"a","text":"\"This is my decision to make\""},{"id":"b","text":"\"Fine, fix the match, whatever\""},{"id":"c","text":"\"I love you, and my answer is still no\""},{"id":"d","text":"\"I'll just go along to keep peace\""},{"id":"e","text":"\"Please stop the matchmaking\""},{"id":"f","text":"\"You decide, I can't say no to you\""}],"bins":[{"id":"firm","label":"Holds the boundary","valence":"pos"},{"id":"cave","label":"Caves","valence":"neg"}],"key":{"a":"firm","b":"cave","c":"firm","d":"cave","e":"firm","f":"cave"},"relearn":"A warm-but-firm boundary holds your ground; caving or letting them decide loses you.","persona":"any","source":"boundary vs caving"},
  {"id":"yp-1282","cat":"tools-and-reflection","type":"sort","hook":"Sort each: a truth this game stands on, or an imposed myth?","items":[{"id":"a","text":"Worth isn't marital status"},{"id":"b","text":"An unmarried woman is incomplete"},{"id":"c","text":"Womanhood isn't motherhood"},{"id":"d","text":"You'll regret staying childfree"},{"id":"e","text":"There's no one timeline"},{"id":"f","text":"Marriage is the measure of a life"}],"bins":[{"id":"truth","label":"Truth","valence":"pos"},{"id":"myth","label":"Imposed myth","valence":"neg"}],"key":{"a":"truth","b":"myth","c":"truth","d":"myth","e":"truth","f":"myth"},"relearn":"Worth-isn't-status, womanhood-isn't-motherhood, no-one-timeline are truths; 'incomplete' and 'the measure' are imposed myths.","persona":"any","source":"truth vs myth"},
  {"id":"yp-1283","cat":"tools-and-reflection","type":"sort","hook":"Sort each route to the right kind of support (India).","items":[{"id":"a","text":"A cousin being forced to marry"},{"id":"b","text":"A teen being married off"},{"id":"c","text":"Heavy family conflict, no force"},{"id":"d","text":"Someone threatened into a wedding"},{"id":"e","text":"You just need to think alone"},{"id":"f","text":"A friend feeling alone in it"}],"bins":[{"id":"helpline","label":"Call a helpline","valence":"tell"},{"id":"trusted","label":"A counsellor or trusted person","valence":"neutral"}],"key":{"a":"helpline","b":"helpline","c":"trusted","d":"helpline","e":"trusted","f":"trusted"},"relearn":"Forced marriage and a child married off go to a helpline; family-conflict distress goes to a counsellor or trusted person.","persona":"any","source":"routing support"},
  {"id":"yp-1284","cat":"tools-and-reflection","type":"sort","hook":"Sort each: a freely-owned choice, or pressure deciding for you?","items":[{"id":"a","text":"\"I chose this life on purpose\""},{"id":"b","text":"\"I married to stop the questions\""},{"id":"c","text":"\"We decided kids aren't for us\""},{"id":"d","text":"\"I caved before the deadline\""},{"id":"e","text":"\"I'm waiting for the right person\""},{"id":"f","text":"\"They picked, I went along\""}],"bins":[{"id":"owned","label":"Freely owned","valence":"pos"},{"id":"pressured","label":"Pressure decided","valence":"neg"}],"key":{"a":"owned","b":"pressured","c":"owned","d":"pressured","e":"owned","f":"pressured"},"relearn":"A freely-owned choice is yours; a pressure-driven one, made to stop questions or beat a deadline, causes more regret.","persona":"any","source":"owned vs pressured"},
  {"id":"yp-1285","cat":"tools-and-reflection","type":"sort","hook":"Sort each thing: a real measure of a person, or an imposed yardstick?","items":[{"id":"a","text":"Their kindness and character"},{"id":"b","text":"Their skin tone"},{"id":"c","text":"How they treat people"},{"id":"d","text":"Their marriage-market 'rating'"},{"id":"e","text":"Their growth over the years"},{"id":"f","text":"Whether they've 'settled down'"}],"bins":[{"id":"real","label":"Real worth","valence":"pos"},{"id":"imposed","label":"Imposed yardstick","valence":"neg"}],"key":{"a":"real","b":"imposed","c":"real","d":"imposed","e":"real","f":"imposed"},"relearn":"Character, kindness and growth are real worth; skin tone, market 'ratings' and 'settled down' are imposed yardsticks.","persona":"any","source":"real vs imposed worth"},
  {"id":"yp-1286","cat":"tools-and-reflection","type":"sort","hook":"Sort each line said to a single friend: supportive, or quiet pressure?","items":[{"id":"a","text":"\"Your life looks full and happy\""},{"id":"b","text":"\"Don't be too picky now\""},{"id":"c","text":"\"Glad you're choosing on your terms\""},{"id":"d","text":"\"The clock's ticking, you know\""},{"id":"e","text":"\"Take all the time you need\""},{"id":"f","text":"\"Who'll look after you when old?\""}],"bins":[{"id":"support","label":"Supportive","valence":"pos"},{"id":"pressure","label":"Quiet pressure","valence":"neg"}],"key":{"a":"support","b":"pressure","c":"support","d":"pressure","e":"support","f":"pressure"},"relearn":"Support trusts your timeline; 'don't be picky', 'clock's ticking' and 'who'll look after you' are quiet pressure.","persona":"any","source":"support vs pressure"},
  {"id":"yp-1287","cat":"tools-and-reflection","type":"sort","hook":"Sort each line: a real, valid life, or a myth about one?","items":[{"id":"a","text":"Single and thriving at 40"},{"id":"b","text":"\"Childfree means an empty life\""},{"id":"c","text":"A queer couple raising a niece"},{"id":"d","text":"\"Unmarried means no real life\""},{"id":"e","text":"Marrying later, at 38"},{"id":"f","text":"Adopting as a single parent"}],"bins":[{"id":"valid","label":"A valid life","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"valid","b":"myth","c":"valid","d":"myth","e":"valid","f":"valid"},"relearn":"Single, queer-parenting, later, single-adopting are all valid lives; 'childfree is empty' and 'unmarried isn't a real life' are myths.","persona":"any","source":"all valid"},
  {"id":"yp-1288","cat":"tools-and-reflection","type":"match","hook":"Match each nosy line to a calm, closed comeback.","pairs":[{"left":"\"Why still single?\"","right":"\"Happy with how things are\""},{"left":"\"When's the good news?\"","right":"\"We'll share if there's news\""},{"left":"\"You're getting older\"","right":"\"I'm right on my own time\""},{"left":"\"Don't be so picky\"","right":"\"I'd rather wait than settle\""},{"left":"\"Log kya kahenge?\"","right":"\"Their comfort isn't my duty\""}],"relearn":"A light, closed comeback ends a nosy question warmly, without a fight or a defensive speech.","persona":"any","source":"closed comebacks"},
  {"id":"yp-1289","cat":"tools-and-reflection","type":"match","hook":"Match each truth to who in this story it frees.","pairs":[{"left":"Worth isn't status","right":"Sneha, single and full"},{"left":"Womanhood isn't motherhood","right":"Nisha, unsure on kids"},{"left":"Many ways to family","right":"Aditya, building his own"},{"left":"Men feel it too","right":"Karthik, named honestly"},{"left":"No one timeline","right":"Anyone, on their schedule"}],"relearn":"Each truth frees a real person: worth-isn't-status, womanhood-isn't-motherhood, many-ways-to-family.","persona":"any","source":"truth to person"},
  {"id":"yp-1290","cat":"tools-and-reflection","type":"match","hook":"Match the moment to the tool that fits it.","pairs":[{"left":"The pressure repeats again","right":"A kind, firm boundary"},{"left":"You feel pulled by the script","right":"Ask what you actually want"},{"left":"A relative is being pushed","right":"Stand with them as ally"},{"left":"Someone is being forced","right":"The right helpline route"},{"left":"You need to decide","right":"A quiet, private moment"}],"relearn":"The toolkit: a firm boundary, the real question, being an ally, the help route, a private reflection.","persona":"any","source":"moment to tool"},
  {"id":"yp-1291","cat":"tools-and-reflection","type":"match","hook":"Match each help need to its exact India route.","pairs":[{"left":"Forced into a wedding","right":"181 or 1091"},{"left":"Threatened, in danger now","right":"112"},{"left":"A child being married off","right":"Childline 1098"},{"left":"Family conflict, no force","right":"A counsellor"},{"left":"Feeling unsupported","right":"A trusted person"}],"relearn":"Forced marriage -> 181/1091/112; a child married off -> 1098; family-conflict distress -> a counsellor or trusted person.","persona":"any","source":"exact routes"},
  {"id":"yp-1292","cat":"tools-and-reflection","type":"match","hook":"Match each path to the freedom that names it.","pairs":[{"left":"Staying single","right":"A full life, no marriage"},{"left":"Being childfree","right":"Complete, by choice"},{"left":"Marrying later","right":"On your own timeline"},{"left":"Marrying and raising kids","right":"Equally valid, freely chosen"},{"left":"Partnering differently","right":"Family in many forms"}],"relearn":"Every path, single, childfree, later, married, partnered differently, is a valid, freely-chosen life.","persona":"any","source":"path to freedom"},
  {"id":"yp-1293","cat":"tools-and-reflection","type":"match","hook":"Match each 'concern' to the social control hiding inside it.","pairs":[{"left":"\"For your own good\"","right":"Pressure dressed as care"},{"left":"\"What will people say?\"","right":"Their comfort, not your duty"},{"left":"\"You'll be lonely\"","right":"Fear used to push a yes"},{"left":"\"Everyone your age has\"","right":"Comparison, not your timeline"},{"left":"\"It's just how it's done\"","right":"A script, not a rule"}],"relearn":"'Log kya kahenge' and 'for your own good' are social control, not truth; name the pressure to loosen its grip.","persona":"any","source":"control in disguise"},
  {"id":"yp-1294","cat":"tools-and-reflection","type":"match","hook":"Match each pressure line to the truth that quietly disarms it.","pairs":[{"left":"\"A woman's incomplete without a child\"","right":"Womanhood isn't motherhood"},{"left":"\"You'll regret it later\"","right":"You know your own life"},{"left":"\"Marriage makes you an adult\"","right":"You're a full adult either way"},{"left":"\"Your looks decide your value\"","right":"Worth isn't looks or skin tone"},{"left":"\"Settle before it's too late\"","right":"There's no deadline to beat"}],"relearn":"Each pressure has a disarming truth: womanhood-isn't-motherhood, you-know-your-life, worth-isn't-looks.","persona":"any","source":"disarming truths"},
  {"id":"yp-1295","cat":"tools-and-reflection","type":"match","hook":"Match each person's situation to the support that fits.","pairs":[{"left":"Cousin forced toward a wedding","right":"Helpline 181 / 1091 / 112"},{"left":"A neighbour's child married off","right":"Childline 1098"},{"left":"You, drained by family rows","right":"A counsellor's calm ear"},{"left":"A friend feeling judged","right":"You, standing with her"},{"left":"You, unsure what you want","right":"A quiet evening to reflect"}],"relearn":"Force routes to a helpline; a child married off to 1098; distress and doubt to a counsellor, friend or quiet reflection.","persona":"any","source":"situation to support"},
  {"id":"yp-1296","cat":"tools-and-reflection","type":"match","hook":"Match each thing you can offer a pressured loved one.","pairs":[{"left":"When she's doubting herself","right":"\"Your choice makes sense\""},{"left":"When she feels alone","right":"\"I'm right here with you\""},{"left":"When relatives pile on","right":"\"Your call, not theirs\""},{"left":"When she's exhausted","right":"\"You owe no explanation\""},{"left":"When she needs more help","right":"\"Let's find someone to talk to\""}],"relearn":"Standing with a loved one, validating, accompanying, redirecting pressure, can change how they weather it.","persona":"any","source":"what to offer"},
  {"id":"yp-1297","cat":"tools-and-reflection","type":"match","hook":"Match each carry-forward truth to its short form.","pairs":[{"left":"One path, not the path","right":"Many lives are valid"},{"left":"Worth isn't status","right":"Never your marital state"},{"left":"Childfree is complete","right":"Womanhood isn't motherhood"},{"left":"Your life, your call","right":"You decide your path"},{"left":"Respect every path","right":"Even the one you didn't pick"}],"relearn":"Carry forward: one path not the path, worth isn't status, childfree is complete, your life your call.","persona":"any","source":"carry forward short"},
  {"id":"yp-1298","cat":"tools-and-reflection","type":"match","hook":"Match each question to the kinder one to ask instead.","pairs":[{"left":"\"What's expected of me?\"","right":"\"What do I actually want?\""},{"left":"\"Who'll approve of this?\"","right":"\"Does this feel true to me?\""},{"left":"\"Am I running out of time?\"","right":"\"Is this my own timeline?\""},{"left":"\"What will they say?\"","right":"\"Whose life is this?\""},{"left":"\"Should I just settle?\"","right":"\"Is this freely chosen?\""}],"relearn":"Swap 'what's expected?' for 'what do I actually want?', and the choice becomes yours again.","persona":"any","source":"better questions"},
  {"id":"yp-1299","cat":"tools-and-reflection","type":"match","hook":"Match each form of family to how it can be built (India-accurate).","pairs":[{"left":"Marrying and having kids","right":"The default script, freely chosen"},{"left":"A childfree marriage","right":"Complete as it is"},{"left":"A single person adopting","right":"Possible, within CARA rules"},{"left":"A queer couple's home","right":"Real, though law lags behind"},{"left":"Chosen family and friends","right":"A circle you build yourself"}],"relearn":"Family takes many real forms; be honest that Indian law lags on queer marriage, without erasing the real routes.","persona":"any","source":"forms of family"},
  {"id":"yp-1300","cat":"tools-and-reflection","type":"match","hook":"Match each 'what if' worry to a steadying reframe.","pairs":[{"left":"\"What if I end up alone?\"","right":"Chosen family and friendship are real"},{"left":"\"What if I regret no kids?\"","right":"You can trust your own knowing"},{"left":"\"What if I marry too late?\"","right":"There's no boat to miss"},{"left":"\"What if they're disappointed?\"","right":"Their pity isn't your truth"},{"left":"\"What if I'm being selfish?\"","right":"Choosing your own life isn't selfish"}],"relearn":"Each 'what if' has a steadying reframe; fear was never a good reason to abandon your own path.","persona":"any","source":"steadying reframes"},
  {"id":"yp-1301","cat":"tools-and-reflection","type":"match","hook":"Match each pressure source to a healthy boundary with it.","pairs":[{"left":"A pushy relative","right":"\"This is my decision to make\""},{"left":"A nosy neighbour","right":"A light, closed deflection"},{"left":"Endless matchmaking","right":"\"Please stop arranging matches\""},{"left":"Comparison to cousins","right":"\"My path is my own\""},{"left":"Guilt-trips","right":"\"I love you, and the answer's no\""}],"relearn":"Different pressures meet different warm-but-firm boundaries; you can be loving and clear at once.","persona":"any","source":"boundary per source"},
  {"id":"yp-1302","cat":"tools-and-reflection","type":"match","hook":"Match each line to whether it respects or overrides autonomy.","pairs":[{"left":"\"It's your life to shape\"","right":"Respects your autonomy"},{"left":"\"We'll decide for you\"","right":"Overrides your autonomy"},{"left":"\"Take your time deciding\"","right":"Leaves the choice yours"},{"left":"\"You have no say in this\"","right":"Erases your choice"},{"left":"\"Whatever you choose, we're here\"","right":"Supports without steering"}],"relearn":"Respect leaves the choice yours; overriding or 'deciding for you' erases the autonomy that was always yours.","persona":"any","source":"respect vs override"},
  {"id":"yp-1303","cat":"tools-and-reflection","type":"match","hook":"Match each milestone myth to a truer way to see a life.","pairs":[{"left":"\"Marriage equals success\"","right":"Success has many shapes"},{"left":"\"Kids make a complete woman\"","right":"You're complete already"},{"left":"\"Single means something's wrong\"","right":"Single is a full choice"},{"left":"\"Late means missed the boat\"","right":"There's no boat to miss"},{"left":"\"Childfree means selfish\"","right":"It's an honest, valid choice"}],"relearn":"Swap milestone myths for truer measures: success has many shapes, single and childfree are full, valid choices.","persona":"any","source":"milestone myths"},
  {"id":"yp-1304","cat":"tools-and-reflection","type":"match","hook":"Match each value to the kind of worth it builds.","pairs":[{"left":"Kindness to others","right":"Worth people feel"},{"left":"Steady personal growth","right":"Worth that lasts"},{"left":"Honest relationships","right":"Worth you can trust"},{"left":"Living on your own terms","right":"Worth you own"},{"left":"Respecting others' paths","right":"Worth that uplifts"}],"relearn":"Values, growth and relationships build lasting worth; marital status and looks were never the real measure.","persona":"any","source":"values build worth"},
  {"id":"yp-1305","cat":"tools-and-reflection","type":"branch","persona":"any","source":"backing your sister","hook":"Your younger sister is pushed toward a match she's unsure about, and looks to you.","steps":[{"prompt":"She whispers that she doesn't know if she even likes him. What do you do?","options":[{"text":"Tell her the choice is hers and you'll back her","then":"She exhales. \"I just needed someone to say that.\"","best":true},{"text":"Tell her to give him a proper chance first","then":"She nods, but the doubt doesn't really go anywhere."},{"text":"Tell her the family has already decided, basically","then":"She feels the choice slipping further from her hands."},{"text":"Say nothing. It's not your place to weigh in","then":"She's left carrying the doubt on her own."}],"why":"Naming the choice as hers, and backing her, gives her steadier ground to decide from."},{"prompt":"At the next meeting, relatives ask her to 'decide soon, no more delaying'. What do you do?","options":[{"text":"Ask them to give her the time she actually needs","then":"The room quiets, and your sister looks a little less cornered.","best":true},{"text":"Tell her privately to hurry up and just decide","then":"She feels the same pressure, just from one more voice now."},{"text":"Stay quiet so you don't cause a scene","then":"The pressure in the room continues unchallenged."},{"text":"Agree with the relatives that it's taking too long","then":"Your sister looks betrayed, hearing it from you too."}],"why":"Asking for time on her behalf shows her you're still standing with her, out loud."},{"prompt":"She eventually says no to the match, and looks nervous telling the family. What do you do?","options":[{"text":"Stand beside her while she says it, calmly","then":"Her voice steadies, knowing she isn't saying it alone.","best":true},{"text":"Let her say it alone so it feels like her decision","then":"She says it, but her voice shakes through the whole thing."},{"text":"Suggest she soften the no so it lands easier","then":"The no gets muddled, and the family assumes she might change her mind."},{"text":"Tell her privately she's making a mistake","then":"She second-guesses a decision she'd actually already made."}],"why":"Standing beside her while she says it is what backing her looks like when it counts."}],"debrief":"One person who respects her call can change how she weathers the whole pressure.","relearn":"Validate a loved one's choice and stand with them; don't add to the pressure."},
  {"id":"yp-1306","cat":"tools-and-reflection","type":"branch","persona":"any","source":"the wedding circle","hook":"At a wedding, relatives circle you with 'beta, ab tumhari baari' (your turn next).","steps":[{"prompt":"The circle tightens, waiting for your answer. What do you do?","options":[{"text":"Smile and give a light, closed deflection","then":"The circle laughs along and drifts back to the buffet line.","best":true},{"text":"Give a long, defensive explanation of your plans","then":"The explanation only invites three more follow-up questions."},{"text":"Say nothing and look at your phone","then":"The silence gets awkward, and someone fills it for you."},{"text":"Joke that you're 'never getting married'","then":"The joke gets repeated all evening, and not quite the way you meant it."}],"why":"A light, closed line ends the topic warmly, without opening a debate."},{"prompt":"Later, one relative catches you alone and asks more seriously. What do you focus on?","options":[{"text":"Smiling, and keeping the answer light","then":"She nods, satisfied, and asks about the wedding food instead.","best":true},{"text":"Explaining your reasons in more detail this time","then":"She listens, then treats it as an opening to debate each one."},{"text":"Getting a little defensive about being asked again","then":"The conversation turns a bit tense for the rest of the evening."},{"text":"Changing your story to something that sounds simpler","then":"It works for now, but it isn't quite what you meant to say."}],"why":"A calm, light answer holds up better than a longer one invented on the spot."},{"prompt":"By the end of the night, someone jokes that you 'dodged the whole family'. What do you say?","options":[{"text":"Laugh and say you just enjoyed the dance floor more","then":"The room laughs with you, and the evening ends on an easy note.","best":true},{"text":"Apologise for not having better news to share","then":"The apology lands oddly, since you'd done nothing wrong."},{"text":"Point out how many times you were actually asked","then":"It's true, but it turns a light joke into a small complaint."},{"text":"Say you'll have news 'one of these days'","then":"It gets a laugh, but it also quietly promises something you didn't mean."}],"why":"A light close, right to the end, keeps the whole evening easy instead of heavy."}],"debrief":"A warm, closed line keeps your peace and the gathering's, no fight, no over-explaining.","relearn":"A light, closed deflection ends a nosy question without a fight."},
  {"id":"yp-1307","cat":"tools-and-reflection","type":"branch","persona":"any","source":"asking them to stop","hook":"Your parents keep arranging meetings you didn't ask for, and it's straining things.","steps":[{"prompt":"Another meeting shows up on the calendar without warning. What do you do?","options":[{"text":"Calmly ask them to stop the matchmaking, warmly","then":"They look surprised, but agree to talk about it properly.","best":true},{"text":"Say nothing and just skip the meeting quietly","then":"The meeting gets rescheduled, since no one actually said no."},{"text":"Ask a sibling to cancel it for you","then":"Your sibling cancels it, but the awkward conversation just moves to them instead of you."},{"text":"Attend it anyway to avoid an argument","then":"They take your attendance as a green light for more."}],"why":"A calm, direct ask names the problem, instead of letting silence get misread as consent."},{"prompt":"Your mother says she's 'just trying to help you not miss your chance'. What do you say?","options":[{"text":"Thank her for caring, and say plainly that the matchmaking needs to stop","then":"She looks unsettled, but says she'll try to hold back.","best":true},{"text":"Let her explain everything, and agree to think about it a bit more","then":"She takes that as encouragement to keep arranging things."},{"text":"Tell her she's not actually helping at all","then":"She looks hurt, and the conversation turns defensive."},{"text":"Go along with the next one to keep her happy","then":"The pattern continues exactly as before."}],"why":"Naming the ask again, warmly, keeps the boundary clear even against good intentions."},{"prompt":"A profile arrives from an aunty a week later. What do you do?","options":[{"text":"Tell your parents plainly that the matchmaking must stop","then":"They exchange a look and finally seem to take it seriously.","best":true},{"text":"Let this one go, since it's just one more","then":"Another profile arrives the following week, right on schedule."},{"text":"Block the aunty's number quietly without saying anything to anyone","then":"The aunty is confused, and your parents are caught in the middle."},{"text":"Look at the profile, just to be polite","then":"Looking at it gets read as real interest."}],"why":"Restating the same ask, again and again, keeps your no from quietly fading."},{"prompt":"A month later, your father says he's finally stopped fixing meetings, for good this time. What do you say?","options":[{"text":"Thank him, and say it's made things easier between you","then":"He looks pleased, and dinner feels lighter than it has in months.","best":true},{"text":"Say it's about time, honestly","then":"He looks a little stung, even though he's stopped."},{"text":"Ask if he's really going to keep this up for good this time","then":"He looks defensive, hearing doubt instead of thanks."},{"text":"Say nothing and just move on","then":"The change goes unacknowledged, and the moment passes flat."}],"why":"Naming what's better now protects the change, instead of letting it pass unnoticed."}],"debrief":"Restating your no warmly, and asking them to stop, deserves respect and protects the bond.","relearn":"Restate your no clearly; ask them to stop the matchmaking, warm but firm."},
  {"id":"yp-1308","cat":"tools-and-reflection","type":"branch","persona":"any","source":"marrying to silence talk","hook":"A close friend has just said yes to a marriage proposal.","steps":[{"prompt":"She tells you saying yes felt easier than facing the family's questions again. What do you do?","options":[{"text":"Gently ask if it's what she actually wants","then":"She pauses, and admits she hasn't really asked herself that.","best":true},{"text":"Tell her that's good, since at least the talk will stop","then":"She nods, but something in her voice sounds unsure."},{"text":"Tell her she's making a mistake","then":"She gets defensive, and the conversation shuts down fast."},{"text":"Say nothing. It's her decision after all","then":"She's left alone with a question she hasn't actually faced."}],"why":"Asking what she truly wants opens space she hasn't given herself to consider yet."},{"prompt":"A week later, she admits she's been avoiding thinking about it. What do you say?","options":[{"text":"Tell her there's no rush to decide under pressure","then":"She exhales, like she'd been waiting for permission to slow down.","best":true},{"text":"Tell her the wedding planning will help her feel sure","then":"She throws herself into planning instead of the actual question."},{"text":"Tell her she should have thought of this earlier","then":"She feels worse, and stops talking to you about it."},{"text":"Say it's probably fine. Most people feel unsure","then":"She takes that as a reason to keep pushing the doubt aside."}],"why":"Naming that there's no rush gives her room to actually think, instead of just proceeding."},{"prompt":"Months on, she tells you she has made her own decision about the engagement, and it feels settled. What do you say?","options":[{"text":"Tell her you're proud she listened to herself","then":"She smiles and says it means more than you know.","best":true},{"text":"Say you always hoped she'd decide the other way","then":"She goes quiet, and her choice now feels like it has to answer to yours."},{"text":"Ask if she's really sure","then":"She looks unsettled again, right after finding some clarity."},{"text":"Say you knew all along what she would choose","then":"It stings a little, even though you meant it kindly."}],"why":"Naming that she listened to herself honours her choice, whatever it is."}],"debrief":"A pressure-driven marriage causes more regret than a freely chosen path, so ask what she wants instead of cheering her on.","relearn":"A pressure-driven marriage causes more regret than a freely-chosen path."},
  {"id":"yp-1309","cat":"tools-and-reflection","type":"branch","persona":"any","source":"when it gets heavy","hook":"Family rows about your choices have started keeping you up at night.","steps":[{"prompt":"Another row ends with your mother crying. What do you do?","options":[{"text":"Reach out to a counsellor or trusted person","then":"Talking it through with someone steady helps you sleep that night.","best":true},{"text":"Bottle it up and just push through alone","then":"The next row hits just as hard, with nothing processed from the last."},{"text":"Blame yourself for her tears and your choices","then":"The guilt weighs on you all night, and you can't sleep."},{"text":"Agree to whatever she wants to stop the crying","then":"The row ends, but the decision behind it was never really yours."}],"why":"Reaching for a counsellor or trusted person helps far more than carrying the distress alone."},{"prompt":"In the days that follow, you try to pin down what's actually been keeping you up. What do you land on?","options":[{"text":"That the rows themselves, not just the outcome, wear you down","then":"Naming that to yourself makes it clearer what you actually need to say, and to whom.","best":true},{"text":"That you probably need to just give in and let it go eventually","then":"The thought doesn't sit right, even as you think it."},{"text":"That your mother is completely unreasonable","then":"It feels satisfying to think, but it doesn't get you any closer to rest."},{"text":"That it's nothing, really. You're managing fine","then":"The thought passes, but the tiredness stays exactly where it was."}],"why":"Naming what's actually wearing you down is what real support can work with, whenever you reach for it."},{"prompt":"The next family row starts to build. How do you handle it now?","options":[{"text":"Stay calm, hold your line, and step away if it escalates","then":"You leave the room steadier than you would have a month ago.","best":true},{"text":"Push through it and hope it all resolves itself eventually","then":"The row runs its course, and you're drained again by the end."},{"text":"Match the tension and argue back","then":"The row gets louder, and nobody actually feels heard."},{"text":"Give in early just to shorten the row","then":"It's over faster, but the same pattern is set to repeat."}],"why":"Holding your line calmly, with a way out if it escalates, keeps the row from running you."}],"debrief":"Family rows are never your fault, and reaching for support is a strong, healthy move, not a failure.","relearn":"If family conflict over your choices turns distressing, reach for support."},
  {"id":"yp-1310","cat":"tools-and-reflection","type":"branch","persona":"any","source":"child marriage route","hook":"Wedding talk has turned quiet and hurried in your family.","steps":[{"prompt":"You overhear your aunt finalising wedding details for your sixteen-year-old cousin. What do you do?","options":[{"text":"Help your cousin reach Childline 1098 right away","then":"The call connects her to people trained exactly for this.","best":true},{"text":"Talk to her parents alone and try to reason with them","then":"They wave you off, and the planning quietly continues."},{"text":"Wait to see if the wedding date actually gets fixed","then":"More days pass, and the planning moves further along."},{"text":"Tell your cousin to simply refuse when the day comes","then":"The full weight of stopping it lands on her alone."}],"why":"Childline 1098 is the exact route for a child being married off; it isn't something to wait on."},{"prompt":"Your cousin calls, scared, and says she doesn't know what happens next. What do you tell her?","options":[{"text":"That it's not her fault, and Childline 1098 is there for her","then":"She sounds steadier, hearing she isn't facing this alone.","best":true},{"text":"That she should probably try talking her own parents out of it, alone","then":"She hangs up more frightened, carrying a job that isn't hers to do."},{"text":"That she just needs to be braver about this","then":"She feels blamed for something she never chose."},{"text":"That everything will probably sort itself out","then":"The reassurance is hollow, and the planning doesn't stop."}],"why":"Telling her it's not her fault, while getting her real help right now, is what she needs to hear most."},{"prompt":"A relative notices you and your cousin talking often and says to stay out of 'family matters'. What do you do?","options":[{"text":"Keep it light and say you're just cousins catching up","then":"The relative relaxes, and your cousin's calls to you stay private.","best":true},{"text":"Apologise, and quietly step back from the whole situation entirely","then":"The relative nods, satisfied, though your cousin still turns to you when it's hard."},{"text":"Argue loudly that the whole family is wrong","then":"The row gets attention, but it isn't the kind that protects her."},{"text":"Tell the relative you know about the wedding and it isn't right","then":"The relative goes cold, and the family starts watching your cousin's phone."}],"why":"Keeping her confidence protects her lifeline while Childline 1098 is there to act."},{"prompt":"Weeks later, your cousin says she's scared to make the call by herself. What do you say to her?","options":[{"text":"Offer to sit beside her while she calls Childline 1098","then":"She lets out a breath and says she can do it if you're there.","best":true},{"text":"Tell her to tell no one else, not even Childline 1098","then":"She agrees, and stays alone with it, out of reach of anyone who could step in."},{"text":"Tell her to wait until things feel calmer at home","then":"She agrees, and the days pass while the wedding plans move forward."},{"text":"Make the call yourself without telling her first","then":"She hears about it afterwards and feels the choice was taken from her."}],"why":"Staying beside her makes the call possible, and none of this was ever her fault."}],"debrief":"A child being married off is never acceptable; Childline 1098 is the exact route to reach.","relearn":"A child being married off needs Childline 1098, the right help, right away."},
  {"id":"yp-1311","cat":"tools-and-reflection","type":"branch","persona":"any","source":"examine the drift","hook":"You catch yourself drifting toward the default script just because everyone assumes it.","steps":[{"prompt":"You realise you're planning a proposal you're not sure you even want. What do you do?","options":[{"text":"Pause and ask what life you actually want","then":"The question feels uncomfortable, but also strangely clarifying.","best":true},{"text":"Keep planning. It's probably just nerves","then":"The planning continues, and the doubt quietly rides along."},{"text":"Ask your parents what they think you should do","then":"Their answer fills the space where your own should be."},{"text":"Speed up the timeline to get past the doubt faster","then":"The doubt doesn't disappear. It just gets less time to be heard."}],"why":"Pausing to ask what you actually want reclaims a choice that was drifting on autopilot."},{"prompt":"A friend asks how the planning is going. What do you tell her?","options":[{"text":"That you're actually stepping back to think it through","then":"She nods slowly. \"That sounds like the harder call, honestly.\"","best":true},{"text":"That it's going fine, mostly on autopilot","then":"Saying it out loud makes the autopilot feel more obvious."},{"text":"That everyone expects it, so you're just doing it","then":"She looks a little concerned, hearing 'expects' instead of 'want'."},{"text":"That you don't really want to talk about it","then":"The question goes unanswered, including for yourself."}],"why":"Naming that you're pausing, out loud, makes the pause feel real instead of just private."},{"prompt":"Your partner asks if something's changed between you two. What do you say?","options":[{"text":"That you're figuring out what you actually want, honestly","then":"They look relieved you said it, since they'd felt it too.","best":true},{"text":"That nothing's changed. Everything's fine","then":"The gap between you both stays, just unnamed now."},{"text":"That you're just stressed about the planning","then":"It's partly true, but it skips the real question underneath."},{"text":"That it's too soon to talk about, so you'd rather wait","then":"The moment passes, and the real conversation waits again."}],"why":"Honesty about what you're actually weighing gives you both real ground to stand on."},{"prompt":"Months later, you've decided what you genuinely want. What do you tell the people around you?","options":[{"text":"The truth, plainly, even if it's not the expected script","then":"It's harder to say, but it finally feels like your own choice.","best":true},{"text":"A version that's easier for everyone else to hear","then":"It goes down easily, but it isn't quite what you decided."},{"text":"As little as possible, to avoid questions","then":"The questions come anyway, just with less to go on."},{"text":"That you'll 'figure it out eventually'","then":"It buys time, but the choice you already made stays unsaid."}],"why":"Naming your real choice plainly is what makes it genuinely yours, not just less awkward."}],"debrief":"The script is worth examining, not just following. The real question is what life you want.","relearn":"Pause and ask what life you actually want, rather than following the default script."},
  {"id":"yp-1312","cat":"tools-and-reflection","type":"branch","persona":"any","source":"warm not cruel","hook":"A relative says 'shaadi toh karni hi padegi' (you'll have to marry) at every visit.","steps":[{"prompt":"He says it again the moment you walk through the door. What do you do?","options":[{"text":"Hold it warmly: say this is yours to decide","then":"He pauses, a little disarmed by how calm you are.","best":true},{"text":"Laugh it off without really giving him an answer","then":"The laugh works today, but he says it again the very next visit."},{"text":"Snap back and threaten to cut him off","then":"The room goes tense, and the visit ends earlier than planned."},{"text":"Agree just to get past the doorway","then":"He takes the agreement seriously, and starts asking for dates."}],"why":"A warm, firm boundary holds your ground without matching his intensity."},{"prompt":"At the next visit, he brings it up again, a little more insistent. What do you do?","options":[{"text":"Stay warm and steady, and say it's still yours to decide","then":"He grumbles, but moves on to asking about your work instead.","best":true},{"text":"Try a longer explanation this time","then":"The explanation becomes something for him to argue point by point."},{"text":"Leave the table until dinner settles down a bit","then":"You miss the rest of dinner, and the topic just waits for you."},{"text":"Tell him to mind his own business","then":"Dinner turns cold, and the visit sours for everyone at the table."}],"why":"Repeating the same calm line, without escalating, keeps the boundary from becoming a fight."},{"prompt":"Months later, he still brings it up, but more gently now. What do you say?","options":[{"text":"Thank him for easing up, and hold the same line","then":"He nods. \"Old habits. I'm trying, at least.\"","best":true},{"text":"Tell him he should stop completely, for good","then":"He looks defensive, even though he'd actually softened."},{"text":"Say nothing and just change the subject","then":"The shift he's made goes quietly unnoticed."},{"text":"Joke that he'll never really stop","then":"It's funny, but it undercuts the real change he's making."}],"why":"Noticing the shift, warmly, encourages more of it without giving up your own ground."}],"debrief":"You can love your family and still not let them dictate your life. Warm but firm beats caving or cruelty.","relearn":"Hold a marriage boundary warmly: 'I know you care, and this is my decision.'"},
  {"id":"yp-1313","cat":"tools-and-reflection","type":"spot","hook":"Spot the two lines that pressure, not support.","scene":[{"id":"a","text":"\"Take all the time you need\"","trick":false},{"id":"b","text":"\"Your clock is ticking, hurry\"","trick":true},{"id":"c","text":"\"I'm glad you're choosing freely\"","trick":false},{"id":"d","text":"\"Don't end up alone, just settle\"","trick":true},{"id":"e","text":"\"Whatever you decide, I'm here\"","trick":false}],"why":"'Clock is ticking' and 'don't end up alone, just settle' are pressure; the others trust your timeline.","relearn":"Support trusts your timeline; 'ticking clock' and 'just settle' are pressure in disguise.","persona":"any","source":"pressure vs support"},
  {"id":"yp-1314","cat":"tools-and-reflection","type":"spot","hook":"Spot the two claims that aren't this game's stance.","scene":[{"id":"a","text":"Every path deserves respect","trick":false},{"id":"b","text":"Childfree people are selfish","trick":true},{"id":"c","text":"No pressure in any direction","trick":false},{"id":"d","text":"Marrying early is a mistake","trick":true},{"id":"e","text":"Marrying is equally valid","trick":false}],"why":"'Childfree is selfish' and 'marrying early is a mistake' both judge a path; the stance shames neither.","relearn":"The stance respects every path, never shaming childfree people OR those who marry, even early.","persona":"any","source":"neither-shamed stance"},
  {"id":"yp-1315","cat":"tools-and-reflection","type":"spot","hook":"Spot the two lines that measure worth by the wrong thing.","scene":[{"id":"a","text":"\"You're kind and you show up\"","trick":false},{"id":"b","text":"\"Too dark for a good match\"","trick":true},{"id":"c","text":"\"You've grown so much\"","trick":false},{"id":"d","text":"\"Unmarried, so less respectable\"","trick":true},{"id":"e","text":"\"People trust you\"","trick":false}],"why":"Skin tone and marital status measure nothing real; kindness, growth and trust are the actual worth.","relearn":"Worth isn't your looks, skin tone or marital status; character and contribution are the real measure.","persona":"any","source":"wrong yardsticks"},
  {"id":"yp-1316","cat":"tools-and-reflection","type":"spot","hook":"Spot the two help routes that are WRONG (not the verbatim India set).","scene":[{"id":"a","text":"Forced marriage -> 181 / 1091 / 112","trick":false},{"id":"b","text":"Child married off -> just call 100","trick":true},{"id":"c","text":"Child married off -> Childline 1098","trick":false},{"id":"d","text":"Family distress -> a counsellor","trick":false},{"id":"e","text":"Forced marriage -> just wait it out","trick":true}],"why":"A child married off goes to Childline 1098, and force is never to 'wait out', it routes to 181/1091/112.","relearn":"Forced marriage -> 181/1091/112; a child married off -> Childline 1098; never invent a route.","persona":"any","source":"catch the wrong route"},
  {"id":"yp-1317","cat":"tools-and-reflection","type":"spot","hook":"Spot the two responses that override autonomy.","scene":[{"id":"a","text":"\"It's your life to shape\"","trick":false},{"id":"b","text":"\"We've already decided for you\"","trick":true},{"id":"c","text":"\"Take your time with it\"","trick":false},{"id":"d","text":"\"You don't get a say here\"","trick":true},{"id":"e","text":"\"Whatever you choose, we're here\"","trick":false}],"why":"'We've decided for you' and 'you don't get a say' erase your choice; the others leave it yours.","relearn":"Whether, when and whom you marry, and whether to have kids, is yours; no one decides it for you.","persona":"any","source":"override vs respect"},
  {"id":"yp-1318","cat":"tools-and-reflection","type":"spot","hook":"Spot the two lines that treat a single life as a deficit.","scene":[{"id":"a","text":"\"Your single life looks full\"","trick":false},{"id":"b","text":"\"Poor thing, all alone\"","trick":true},{"id":"c","text":"\"You chose this on purpose\"","trick":false},{"id":"d","text":"\"Something must be wrong with her\"","trick":true},{"id":"e","text":"\"Happy and independent\"","trick":false}],"why":"'Poor thing' and 'something must be wrong' frame single life as lack; it's often chosen from abundance.","relearn":"Others' pity isn't your truth; a single life is full, often chosen from abundance, not lack.","persona":"Sneha","source":"deficit framing"},
  {"id":"yp-1319","cat":"tools-and-reflection","type":"spot","hook":"Spot the two lines that are myths, not truths, about motherhood.","scene":[{"id":"a","text":"Womanhood isn't motherhood","trick":false},{"id":"b","text":"A woman is incomplete without a child","trick":true},{"id":"c","text":"Childfree can be a full life","trick":false},{"id":"d","text":"You'll definitely regret no kids","trick":true},{"id":"e","text":"The choice belongs to the couple","trick":false}],"why":"'Incomplete without a child' and 'you'll definitely regret it' are imposed myths, not truths about a life.","relearn":"Womanhood isn't motherhood; childfree is a complete life, and the choice belongs to the couple.","persona":"Nisha","source":"motherhood myths"},
  {"id":"yp-1320","cat":"tools-and-reflection","type":"role-play","persona":"any","source":"the closed deflection","hook":"A relative corners you at a function with the same old question.","setup":"Tonight, he catches you near the snack table.","steps":[{"prompt":"He asks: \"So, when are YOU getting married, hm?\"","options":[{"text":"\"I'm really happy with how my life is, thanks for asking.\"","then":"He blinks, then laughs. \"Fair enough. Good for you.\"","best":true},{"text":"\"I don't know. Maybe I'm just unlucky.\"","then":"He looks sympathetic and starts naming eligible matches he knows."},{"text":"\"Why is that any of your business?\"","then":"He looks taken aback. \"I was only asking, beta.\""},{"text":"\"Soon, I think, fingers crossed.\"","then":"He brightens and asks for more details about 'soon'."}],"why":"A calm, happy answer closes the question warmly, without a defence or an excuse."},{"prompt":"His wife adds gently: \"We only ask because we care about you.\"","options":[{"text":"\"I know. This one just doesn't need an answer.\"","then":"She nods. \"Fair. I'll tell him to ease off.\"","best":true},{"text":"\"It's fine. I'm used to people asking.\"","then":"She nods, and the question keeps coming at every visit."},{"text":"\"He could still be a bit more careful, honestly.\"","then":"She looks a touch defensive on his behalf."},{"text":"\"Maybe I am overreacting a little.\"","then":"She looks relieved you're not holding it against him."}],"why":"Naming that you simply don't owe an answer keeps the boundary clear, even when it's excused as harmless."},{"prompt":"At another function, months later, he starts to ask, then catches himself. \"Never mind,\" he says.","options":[{"text":"\"Thank you for not asking this time.\"","then":"He smiles, a little proud of himself. \"Trying, beta.\"","best":true},{"text":"\"You almost asked again, didn't you.\"","then":"He looks a bit caught out, and the moment turns awkward."},{"text":"\"See, you can learn.\"","then":"He looks stung by the jab, even though he'd held back."},{"text":"\"I noticed. Anyway, how's your health been?\"","then":"He answers easily, though the effort you noticed goes unthanked."}],"why":"Noticing the change out loud, kindly, makes it easier for him to keep it up."}],"relearn":"A light, closed deflection ends a nosy question without a fight."},
  {"id":"yp-1321","cat":"tools-and-reflection","type":"role-play","persona":"any","source":"worth and boundary","hook":"Your mother worries about what the relatives think of you.","setup":"Tonight, after another relative's comment, she brings it up again.","steps":[{"prompt":"Mother says: \"Beta, marrying is really the only way this family will respect you.\"","options":[{"text":"\"My worth isn't marital status, Ma. This is mine to decide.\"","then":"She's quiet a moment. \"I just want them to see you right.\"","best":true},{"text":"\"Maybe you're right. I should really think about it more.\"","then":"She nods, relieved, and starts mentioning names again."},{"text":"\"That's a ridiculous thing to say, honestly.\"","then":"She looks hurt. \"I'm only telling you how it is.\""},{"text":"\"Fine, find someone then. I give up.\"","then":"She looks pleased and starts calling relatives with the news."}],"why":"Naming your worth plainly, while still holding the boundary, refuses the idea without a fight."},{"prompt":"A week later, she says: \"Your aunt has strong opinions about all this too, you know.\"","options":[{"text":"\"I care about respect. I just won't earn it through marriage.\"","then":"She pauses, then almost smiles. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Tell her I'm thinking about it seriously.\"","then":"She passes that along, and your aunt takes it as real progress."},{"text":"\"Tell her to mind her own business.\"","then":"She looks uncomfortable relaying that to your aunt."},{"text":"\"I don't really know what to tell her about it.\"","then":"She sighs, and the question comes right back next visit."}],"why":"Separating respect from marriage gives her a way to answer without giving ground."},{"prompt":"At a family lunch, your grandmother says, gently: \"Beta, when will you marry and make us proud?\"","options":[{"text":"\"I know, Dadi. My worth just isn't tied to a wedding.\"","then":"She pats your hand. \"You've always had a mind of your own.\"","best":true},{"text":"\"I know, Dadi. I'll think it over properly.\"","then":"She nods, hopeful, and mentions it again before dessert."},{"text":"\"Everyone keeps saying this. It's exhausting.\"","then":"She looks a little wounded by the sharp tone."},{"text":"\"Maybe you're all right and I'm the one who's wrong.\"","then":"She looks concerned, hearing you doubt yourself out loud."}],"why":"The same steady line, said gently, keeps your worth intact even against a softer version of the pressure."},{"prompt":"Months later, your mother says: \"I've stopped saying that to you, you know.\"","options":[{"text":"\"Thank you, Ma. That really means a lot to hear.\"","then":"She smiles, a little shy. \"I'm still learning too, beta.\"","best":true},{"text":"\"Good, because it never made any sense.\"","then":"She looks a bit stung, even while agreeing with you."},{"text":"\"See, I was right about it the whole time.\"","then":"She looks defensive, even though she's actually softening."},{"text":"\"About time, honestly.\"","then":"She looks hurt, even though she's backing off the line."}],"why":"Thanking her for the shift keeps the relationship warm now that the pressure has eased."}],"relearn":"Your worth was never your marital status; hold the boundary warmly and firmly."},
  {"id":"yp-1322","cat":"tools-and-reflection","type":"role-play","persona":"Nisha","source":"owe no justification","hook":"At family lunches, one uncle treats your plans as his business.","setup":"Today's lunch is winding down, and dessert has just arrived.","steps":[{"prompt":"Uncle asks: \"So, any good news yet? When's the celebration?\"","options":[{"text":"\"If there's news, we'll share it. Until then, we're happy.\"","then":"Uncle nods, and moves on to asking about the food instead.","best":true},{"text":"\"It's a bit complicated medically. Let me explain everything.\"","then":"Uncle listens, sympathetic, and the whole table turns quiet."},{"text":"\"That's really not something to ask at the table, uncle.\"","then":"Uncle looks embarrassed, and dessert gets awkward for a minute."},{"text":"\"Soon, hopefully. Just give us a little time, uncle.\"","then":"Uncle brightens, taking 'soon' as a sign of news, and starts counting months."}],"why":"You owe no one a child or a justification; a calm no-news answer closes it cleanly."},{"prompt":"His wife adds gently: \"We only ask because we love seeing this family grow.\"","options":[{"text":"\"I understand. It's still not something we owe an answer on.\"","then":"She nods. \"Fair enough. I'll remind him.\"","best":true},{"text":"\"I know. You'll be the first to hear, promise.\"","then":"She smiles, hopeful, and asks again by the next visit."},{"text":"\"He could still be a bit more careful asking.\"","then":"She looks a little defensive on his behalf."},{"text":"\"Maybe I should just tell them everything.\"","then":"She looks concerned, hearing you consider explaining it all."}],"why":"Naming that you owe no explanation, kindly, closes the topic without opening the door further."},{"prompt":"At another lunch, months later, uncle starts to ask, then stops. \"Never mind,\" he says.","options":[{"text":"\"Thank you for not asking this time, uncle.\"","then":"He smiles, a little sheepish. \"Trying, trying.\"","best":true},{"text":"\"You almost asked, didn't you.\"","then":"He looks caught out, and the moment turns a bit awkward."},{"text":"\"See, you can hold back after all.\"","then":"He looks stung by the jab, even though he held back."},{"text":"\"I noticed. So, how's your garden doing?\"","then":"He answers about the garden happily, and his effort goes unacknowledged."}],"why":"Noticing the change kindly makes it easier for him to keep holding back."}],"relearn":"You don't owe anyone a child or a justification; deflect 'when are the kids?' calmly."},
  {"id":"yp-1323","cat":"tools-and-reflection","type":"role-play","persona":"any","source":"no deadline","hook":"A friend has been getting anxious about marriage lately.","setup":"Tonight, she calls, sounding rattled.","steps":[{"prompt":"She says: \"I think I just have to say yes. I'm running out of time.\"","options":[{"text":"\"There's no boat to miss. Wait for the right person, on your time.\"","then":"She's quiet, then exhales. \"I needed to hear that.\"","best":true},{"text":"\"Yeah, better hurry up before it's too late.\"","then":"She sighs, and starts drafting a text to say yes."},{"text":"\"Just say no if you're not sure, simple.\"","then":"She feels dismissed, like it's easier said than done."},{"text":"\"Maybe he'll grow on you eventually.\"","then":"She nods, unconvinced, and the doubt stays right where it was."}],"why":"There's no deadline to beat; waiting for the right fit matters more than beating a clock."},{"prompt":"The next day, she says: \"My mother keeps saying good matches don't wait around.\"","options":[{"text":"\"A pressure-driven yes usually brings more regret, not less.\"","then":"She goes quiet, turning that over. \"That actually makes sense.\"","best":true},{"text":"\"Your mother probably has more of a point than you think.\"","then":"She feels the deadline pressing in harder than before."},{"text":"\"Tell your mother to stop pressuring you.\"","then":"She sighs. \"Easy for you to say, not your mother.\""},{"text":"\"Maybe just say yes and see how it goes.\"","then":"She starts talking herself into it, just to end the wait."}],"why":"Naming that a rushed yes often costs more later helps her weigh the choice, not just the clock."},{"prompt":"Weeks later, she calls, relieved: \"I called it off. I've decided to actually wait.\"","options":[{"text":"\"I'm proud of you for waiting for what's actually right.\"","then":"She laughs, relieved. \"Me too. It feels like my choice now.\"","best":true},{"text":"\"I hope the right one shows up soon for you.\"","then":"She smiles, but the 'soon' hangs there like a new deadline."},{"text":"\"Are you sure that was the right call?\"","then":"She second-guesses a decision she'd actually felt sure about."},{"text":"\"Good, that guy really didn't seem right for you at all, anyway.\"","then":"She feels judged a little, even though you meant to be kind."}],"why":"Naming it as her choice, not a race, honours the waiting she chose for herself."}],"relearn":"There's no 'boat' to miss. Wait for the right person on your own timeline, and don't settle to a deadline."},
  {"id":"yp-1324","cat":"tools-and-reflection","type":"role-play","persona":"any","source":"not selfish","hook":"You're childfree by choice, and some people have strong views on that.","setup":"Tonight, at a dinner party, a guest brings it up over dessert.","steps":[{"prompt":"The guest says: \"Honestly, a childfree life is just selfish and empty.\"","options":[{"text":"\"It's an honest choice, not a selfish one, and it can be full.\"","then":"The guest pauses, surprised. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Maybe, but it's my choice to make.\"","then":"The guest shrugs. \"Sure, but still, kind of sad, no?\""},{"text":"\"That's a really offensive thing to say.\"","then":"The table goes quiet, and the guest looks defensive."},{"text":"\"You might be right. Maybe it is a bit selfish.\"","then":"The guest nods kindly, and the label seems to settle over you."}],"why":"Calling it honest, not selfish, and full of meaning answers the claim instead of accepting it."},{"prompt":"The host tries to smooth it over: \"He didn't mean anything by it.\"","options":[{"text":"\"Maybe not, but it's still worth naming.\"","then":"The host nods slowly. \"Fair. I'll mention it to him.\"","best":true},{"text":"\"It's fine. People say that all the time.\"","then":"The comment quietly stands, uncorrected, for the rest of the evening."},{"text":"\"He clearly meant something by it.\"","then":"The host looks caught between the two of you."},{"text":"\"I probably shouldn't have said anything.\"","then":"The host looks relieved, and the moment is smoothed over too fast."}],"why":"Naming it as worth addressing, even gently, keeps the comment from just being brushed away."},{"prompt":"Weeks later, the guest asks, genuinely curious: \"What is your life actually like, then?\"","options":[{"text":"\"Full. Work, friends, causes I care about, real purpose.\"","then":"The guest nods, thoughtful. \"That actually sounds like a lot.\"","best":true},{"text":"\"It's nice, I guess, once you get used to it.\"","then":"The guest nods politely, but doesn't seem convinced."},{"text":"\"Why do you even care now, suddenly?\"","then":"The guest looks a little taken aback by the edge in it."},{"text":"\"Honestly, it's complicated to explain.\"","then":"The guest lets the question drop, though something about it clearly stays with them."}],"why":"Naming what actually fills your life shows the fullness, instead of just defending against the claim."},{"prompt":"At the next dinner party, the guest says: \"I've thought about it since. I was too quick to judge.\"","options":[{"text":"\"Thank you. That means a lot to hear.\"","then":"The guest smiles. \"I was wrong before, and glad to say so.\"","best":true},{"text":"\"I guess I finally convinced you.\"","then":"The guest looks a touch sheepish at the callback."},{"text":"\"I wasn't sure you'd ever come around, honestly.\"","then":"The guest looks a little put off by the doubt in it."},{"text":"\"Well. That's nice of you to say.\"","then":"The moment passes, warm but a little flat."}],"why":"Simply accepting the shift, warmly, lets the changed view stand without reopening the old fight."}],"relearn":"Choosing not to have children is a legitimate, autonomous choice, not selfish; a childfree life can be full."},
  {"id":"yp-1325","cat":"tools-and-reflection","type":"role-play","persona":"Karthik","source":"even-handed truth","hook":"The 'settle down' pressure has been weighing on you lately.","setup":"Tonight, at a friend's gathering, the talk turns to marriage.","steps":[{"prompt":"A friend says: \"Come on. It's only women who really feel this. You wouldn't get it.\"","options":[{"text":"\"Men feel a version of it too, though it lands hardest on women.\"","then":"The friend pauses. \"Huh. I hadn't considered that, actually.\"","best":true},{"text":"\"You're right. Men have it totally easy.\"","then":"The friend nods, and the conversation moves on without you."},{"text":"\"That's not fair. Men have it just as hard.\"","then":"The friend looks skeptical. \"Really? Just as hard?\""},{"text":"\"I guess I've never really thought about it.\"","then":"The friend shrugs, and the moment passes without much said."}],"why":"Naming both truths, that men feel it too and it lands harder on women, is the honest answer."},{"prompt":"A friend's sister joins in: \"Can I actually tell you what it's like for us?\"","options":[{"text":"\"Please do. I'd like to listen, and share mine after.\"","then":"She nods. \"Thanks for asking. Okay, here's what it's like.\"","best":true},{"text":"\"Sure, but I think we actually have it about the same.\"","then":"She looks unconvinced, and the conversation gets tense."},{"text":"\"Honestly, I've heard this speech before.\"","then":"She goes quiet, her point unsaid."},{"text":"\"Maybe another time. I don't want to make this heavy.\"","then":"She looks a little disappointed the topic just closes."}],"why":"Listening first, then sharing your own version, keeps the talk even-handed without talking over her."},{"prompt":"A cousin says: \"Guys never really talk about this stuff, huh.\"","options":[{"text":"\"We probably should more. It's real, just quieter.\"","then":"The cousin nods, thoughtful. \"Maybe we should talk more, then.\"","best":true},{"text":"\"Not much to say, honestly. We're fine.\"","then":"The cousin shrugs, and the topic quietly ends there."},{"text":"\"Women have it so much worse. There's no comparison.\"","then":"The cousin looks a little surprised you dismissed your own experience."},{"text":"\"I don't really feel it, personally.\"","then":"The cousin nods, but something in your voice doesn't quite match."}],"why":"Naming that the pressure is real, just quieter, invites an honest conversation instead of silence."}],"relearn":"Men feel a version of the 'settle down' pressure too, though it falls hardest on women."},
  {"id":"yp-1326","cat":"tools-and-reflection","type":"role-play","persona":"Aditya","source":"a real family","hook":"You and your partner have built a life together over the years.","setup":"Tonight, at a family function, one relative says it plainly.","steps":[{"prompt":"A relative says: \"Let's be honest. That's not a real family. The law doesn't recognise it.\"","options":[{"text":"\"It's a family built on love, even where the law hasn't caught up.\"","then":"The relative pauses, unsure how to argue with that.","best":true},{"text":"\"I guess you're right. None of it really counts for much anyway.\"","then":"The relative nods, and the comment stands unanswered in the room."},{"text":"\"You have no right to say that to me.\"","then":"The relative looks defensive. \"I was just being honest.\""},{"text":"\"Maybe someday the law will change. Who knows.\"","then":"The relative shrugs, and the moment passes without really landing."}],"why":"Naming the family as real, on your own terms, refuses the legal gap as the final word."},{"prompt":"A cousin asks quietly: \"Doesn't it bother you that it's not official, though?\"","options":[{"text":"\"Sometimes, and it's not fair. Official isn't the same as real.\"","then":"The cousin nods slowly. \"Huh. I hadn't thought of it that way.\"","best":true},{"text":"\"I try not to think about it too much.\"","then":"The cousin looks a little worried for you, unconvinced."},{"text":"\"It does. Maybe we're expecting too much from everyone.\"","then":"The cousin looks uneasy, hearing you take the blame for a gap that isn't yours."},{"text":"\"I guess we'll just have to wait and see.\"","then":"The cousin nods, but the question sits there a while longer."}],"why":"Naming that official and real aren't the same keeps the relationship's worth from depending on the law."},{"prompt":"Months later, the same relative asks, with real interest this time: \"How is he doing these days?\"","options":[{"text":"\"He's doing well. Thank you for asking properly.\"","then":"The relative nods, a little awkward but genuine. \"Good. I'm glad.\"","best":true},{"text":"\"Oh, now you're interested?\"","then":"The relative looks stung, even though the question was sincere."},{"text":"\"He's great. Let's forget everything that was said before.\"","then":"The relative looks relieved, but the earlier comment never gets addressed."},{"text":"\"He's fine, I guess.\"","then":"The relative senses the coolness, and the moment stays distant."}],"why":"Meeting a genuine question warmly gives the relationship room to actually grow."}],"relearn":"A family built on love and commitment is real, even where Indian law lags on recognising it."},
  {"id":"yp-1327","cat":"tools-and-reflection","type":"role-play","persona":"any","source":"you're not alone","hook":"Your cousin has gone quiet and tired at every family gathering lately.","setup":"Tonight, she pulls you aside.","steps":[{"prompt":"She whispers: \"They won't stop pushing me to say yes to this proposal. I don't know what to do anymore.\"","options":[{"text":"\"This isn't your fault. You don't have to know yet. I'm here.\"","then":"She exhales, some of the tension leaving her shoulders.","best":true},{"text":"\"Maybe just do what they want. It's easier.\"","then":"She nods, but something in her looks even more tired."},{"text":"\"You have to stand up to them right now.\"","then":"She looks overwhelmed, like the ask is too much right now."},{"text":"\"I'm sure it'll sort itself out eventually.\"","then":"She nods, unconvinced, and the pressure doesn't actually ease."}],"why":"Believing her, and reminding her none of this is her fault, is what she needs most right now."},{"prompt":"Her mother says: \"She just needs a push. That's all.\"","options":[{"text":"\"She needs support, not another push.\"","then":"Her mother pauses, then softens slightly. \"Maybe.\"","best":true},{"text":"\"Maybe you're right. A small push could help.\"","then":"Her mother nods, and the pressure on your cousin continues."},{"text":"\"You're the reason she's this stressed.\"","then":"Her mother looks stung, and the room turns tense."},{"text":"\"I don't really want to get involved.\"","then":"Her mother shrugs, and your cousin loses one more ally."}],"why":"Naming what she actually needs, support not pressure, protects her without attacking anyone."},{"prompt":"A few days later, she says quietly: \"I don't think I can keep saying no by myself.\"","options":[{"text":"\"If you want to call 181, 1091 or 112, I'll sit with you.\"","then":"She's quiet, then says, \"Okay. Knowing you'd be there helps.\"","best":true},{"text":"\"Just hold out a little longer. It'll pass.\"","then":"She sighs, and the pressure keeps building with no support in sight."},{"text":"\"Maybe you should just say yes, so this stops.\"","then":"She goes quiet, like even you have given up on another way."},{"text":"\"I'm sure your parents will back off eventually.\"","then":"She waits for that to happen, but the pressure doesn't ease."}],"why":"Getting her real help, together, matters more than facing this alone or waiting it out."},{"prompt":"Weeks later, your cousin tells the family, steadier now: \"I've decided, and this is final.\"","options":[{"text":"\"I'm proud of you. That took real courage to say.\"","then":"She smiles, a little teary. \"It means a lot, having you say that.\"","best":true},{"text":"\"I hope everyone accepts it eventually.\"","then":"She nods, but the uncertainty in the room lingers."},{"text":"\"Are you sure you're ready for what comes next?\"","then":"She looks unsettled again, right after finding her footing."},{"text":"\"Good. That's finally settled then.\"","then":"The moment feels smaller than it should, given how hard it was."}],"why":"Naming her courage, plainly, honours what it actually took for her to say it."}],"relearn":"Validate a loved one being pressured, and help her reach real support; she isn't alone in it."},
  {"id":"yp-1328","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"The only real question is when you'll finally settle down.\"","myth":{"un":"The only real question is when you'll finally settle down.","re":"The real question is 'what life do I actually want?', not 'what's expected of me?'.","why":"A life built on your own answer fits far better than one built on others' expectations."},"relearn":"Ask not 'what's expected?' but 'what do I actually want?'.","persona":"any","source":"the real question"},
  {"id":"yp-1329","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"This game is just telling everyone not to marry.\"","myth":{"un":"This game is just telling everyone not to marry.","re":"The stance is respect for every path, never pressure toward marriage, and never shame for choosing it.","why":"The enemy here is pressure, not any path; marrying is an equally valid, respected choice."},"relearn":"The stance respects every path: no pressure toward marriage, no shame for those who marry.","persona":"any","source":"not anti-marriage"},
  {"id":"yp-1330","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"Standing by your single cousin just encourages her to throw her life away.\"","myth":{"un":"Standing by your single cousin just encourages her to throw her life away.","re":"Standing with a pressured loved one helps her hold her own choice, it doesn't 'throw a life away'.","why":"One person who respects her call can change how she weathers the whole pressure."},"relearn":"Validate and stand with a loved one being pressured; be the voice that respects their choice.","persona":"any","source":"being an ally"},
  {"id":"yp-1331","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"If your family pushes you, the brave thing is to cut them off.\"","myth":{"un":"If your family pushes you, the brave thing is to cut them off.","re":"You can love your family and still not let them dictate your life, warm but firm, not a cut-off.","why":"A warm, firm boundary protects both your choice and a relationship worth keeping."},"relearn":"You can love your family and still hold your boundary; cruelty and cut-off aren't the brave answer.","persona":"any","source":"warm not cut-off"},
  {"id":"yp-1332","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"If you're forced into marriage, there's really nowhere to turn.\"","myth":{"un":"If you're forced into marriage, there's really nowhere to turn.","re":"Forced marriage is never acceptable, and there is help: call 181, 1091, 112, or Childline 1098 for a child.","why":"These are the dedicated routes for exactly this; no one has to face coercion with no support."},"relearn":"If anyone is pressured or forced into marriage, call 181, 1091, 112 or Childline 1098.","persona":"any","source":"there is help"},
  {"id":"yp-1333","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"A woman who doesn't have a child has wasted her life.\"","myth":{"un":"A woman who doesn't have a child has wasted her life.","re":"Womanhood isn't motherhood; a childfree life can be just as full of love, purpose and meaning.","why":"Meaning comes from many sources; parenthood is one path to it, not the only one."},"relearn":"Womanhood isn't motherhood; a childfree life is a complete, meaningful life.","persona":"Nisha","source":"not wasted"},
  {"id":"yp-1334","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"Carry one lesson from here: marriage is the finish line.\"","myth":{"un":"Carry one lesson from here: marriage is the finish line.","re":"Carry this instead: one path not the path, worth isn't status, childfree is complete, your life your call.","why":"A life has many valid shapes; no single milestone is the measure of all of them."},"relearn":"Carry forward: one path not the path, worth isn't status, childfree is complete, your life your call.","persona":"any","source":"carry forward"},
  {"id":"yp-1335","cat":"tools-and-reflection","type":"strike-rewrite","hook":"\"Your skin tone and 'marriage-market value' decide what you're worth.\"","myth":{"un":"Your skin tone and 'marriage-market value' decide what you're worth.","re":"Worth isn't your looks, skin tone or the marriage market; character and contribution are real worth.","why":"Colourism and market 'ratings' measure nothing real about who a person actually is."},"relearn":"Your worth isn't your looks, skin tone or the marriage market; those measure nothing real.","persona":"any","source":"market measures nothing"},
  {"id":"yp-1350","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"A woman past 30 and unmarried has clearly lost her value.\"","myth":{"un":"A woman past 30 and unmarried has clearly lost her value.","re":"Your value never sat in your age or your marital status, and an unmarried woman at any age has lost nothing.","why":"Worth is who you are; a birthday and an empty ring finger change none of it."},"relearn":"An unmarried woman at any age has lost nothing; worth isn't your age or status.","persona":"Sneha","source":"age isn't expiry"},
  {"id":"yp-1351","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"A fairer, slimmer girl gets the better rishta, so that's her real worth.\"","myth":{"un":"A fairer, slimmer girl gets the better rishta, so that's her real worth.","re":"Skin tone and body size are not worth; the rishta scoring that ranks them measures nothing real about a person.","why":"Colourism and looks-ranking are prejudice dressed as standards, not a true read of anyone."},"relearn":"Skin tone and body size aren't worth; rishta-ranking measures nothing real about you.","persona":"any","source":"colourism named"},
  {"id":"yp-1352","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"Once she's a mother she'll finally matter to the family.\"","myth":{"un":"Once she's a mother she'll finally matter to the family.","re":"She mattered fully before any child; a person's worth doesn't switch on when they become a parent.","why":"Worth is inherent and constant, not unlocked by a pregnancy or a grandchild."},"relearn":"Your worth doesn't switch on when you become a parent; it was always there.","persona":"Nisha","source":"worth isn't unlocked"},
  {"id":"yp-1353","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"He's nearly 35 and not settled, so something must be wrong with him.\"","myth":{"un":"He's nearly 35 and not settled, so something must be wrong with him.","re":"An unmarried man isn't broken either; the 'settle down' pressure lands on men too, just usually lighter.","why":"The script measures no one truly, whatever their gender; not-yet-married says nothing about a person."},"relearn":"Unmarried men aren't broken; the settle-down pressure lands on them too, usually lighter.","persona":"Karthik","source":"his version too"},
  {"id":"yp-1354","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"Your value is whatever the rishta-walas rate you out of ten.\"","myth":{"un":"Your value is whatever the rishta-walas rate you out of ten.","re":"No matchmaker's rating is your value; a person isn't a profile to be scored for a marriage market.","why":"Being ranked by strangers for a match measures their bias, not your worth."},"relearn":"No matchmaker's rating is your value; you're not a profile to be scored.","persona":"any","source":"not a score"},
  {"id":"yp-1355","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"A divorced woman is 'used' and worth less now.\"","myth":{"un":"A divorced woman is 'used' and worth less now.","re":"Ending a marriage takes nothing from a person's worth; she is whole, and 'used' is a slur, not a fact.","why":"Worth doesn't shrink with a divorce; that judgement is shaming, not truth."},"relearn":"Ending a marriage takes nothing from your worth; you're whole either way.","persona":"any","source":"after divorce"},
  {"id":"yp-1356","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"At every wedding you're the cautionary tale until you marry.\"","myth":{"un":"At every wedding you're the cautionary tale until you marry.","re":"You're a full guest with your own life, not a warning; the staring says more about the room than about you.","why":"Being unmarried at a function isn't a flaw on display; it's just someone else's curiosity."},"relearn":"You're a full person at any wedding, not a cautionary tale for being unmarried.","persona":"Sneha","source":"not the warning"},
  {"id":"yp-1357","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"A working woman who isn't a wife or mother has wasted her real purpose.\"","myth":{"un":"A working woman who isn't a wife or mother has wasted her real purpose.","re":"There's no single 'real purpose' assigned by gender; a life of work, care and meaning is whole on its own.","why":"Purpose isn't one prescribed role; many lives are full without marriage or children."},"relearn":"There's no one assigned purpose; a life of work and meaning is whole on its own.","persona":"any","source":"no assigned purpose"},
  {"id":"yp-1358","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"If even your own family pities you for being single, you should believe them.\"","myth":{"un":"If even your own family pities you for being single, you should believe them.","re":"Their pity is the script talking, not a verdict on your life; you don't have to adopt how they feel about it.","why":"Concern can be sincere and still wrong; their worry isn't proof anything's missing."},"relearn":"Family pity is the script talking, not a verdict; you needn't adopt how they feel.","persona":"any","source":"pity isn't proof"},
  {"id":"yp-1359","cat":"worth-beyond-status","type":"strike-rewrite","hook":"\"Childless at 38 means your life is empty.\"","myth":{"un":"Childless at 38 means your life is empty.","re":"A life without children isn't empty; it can be as full of love, work and meaning as any other.","why":"Meaning comes from many places; parenthood is one source, not the only one."},"relearn":"A childfree life isn't empty; it can be as full of love and meaning as any.","persona":"Nisha","source":"full either way"},
  {"id":"yp-1360","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: your worth has stayed exactly the same through every birthday no rishta came. Feel that?","prompt":"What lands for you?","options":["It never moved","Same me throughout","My worth isn't dated"],"affirm":"Your worth didn't rise or fall with any year or any proposal; it has been whole the whole time.","relearn":"Your worth doesn't change with your age or whether a proposal came.","persona":"Sneha","source":"steady worth"},
  {"id":"yp-1361","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: picture meeting yourself as a stranger would, no marital status attached. Still plenty there?","prompt":"What do you notice?","options":["Plenty there","A whole person","More than a status"],"affirm":"Strip the labels and a whole person remains, with all your kindness, work and history intact.","relearn":"You're a whole person beneath any label; marital status isn't the sum of you.","persona":"any","source":"beneath the label"},
  {"id":"yp-1362","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: think of someone you love. Did their relationship status ever change how much they're worth to you?","prompt":"What comes up?","options":["Never did","I love who they are","Status didn't matter"],"affirm":"You love people for who they are, not their marital status, and the same truth holds for you.","relearn":"You love people for who they are, not their status; the same is true of you.","persona":"any","source":"mirror the love"},
  {"id":"yp-1363","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: the mirror shows the same skin a rishta might rank. Whose verdict actually matters here?","prompt":"What feels true?","options":["Mine does","My skin is just mine","Not theirs to grade"],"affirm":"Your skin tone is yours, not a grade for anyone to assign; colourism measures nothing real about you.","relearn":"Your skin tone is yours, not a grade; colourism measures nothing real.","persona":"any","source":"the mirror"},
  {"id":"yp-1364","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: imagine your worth as something no one can add to or subtract from. How does carrying that feel?","prompt":"What stirs?","options":["Lighter","No one can dock it","Mine to keep"],"affirm":"Your worth isn't a balance others top up or deduct from; it's yours, steady, and entirely your own.","relearn":"Your worth isn't a balance others can add to or subtract from; it's steadily yours.","persona":"any","source":"no one's ledger"},
  {"id":"yp-1365","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: a cousin marries young and you're 'still waiting'. Does her timeline shrink your worth?","prompt":"What sits true?","options":["Not at all","Different paths","Both whole"],"affirm":"Her path and yours are both whole; another person's timeline says nothing about your worth.","relearn":"Another person's timeline says nothing about your worth; both paths are whole.","persona":"any","source":"her path, mine"},
  {"id":"yp-1366","cat":"worth-beyond-status","type":"reflect","hook":"Lensy: when a relative says 'when will you be a mother', notice your value isn't waiting on that answer.","prompt":"What do you feel?","options":["It isn't waiting","I'm enough now","Already whole"],"affirm":"Your value isn't on hold until a child arrives; you are complete and worthy right now, child or no child.","relearn":"Your value isn't on hold until a child arrives; you're complete right now.","persona":"Nisha","source":"not on hold"},
  {"id":"yp-1367","cat":"worth-beyond-status","type":"sort","hook":"Sort: a true measure of a person, or a marriage-market label that isn't?","items":[{"id":"a","text":"How they treat people who can't repay them"},{"id":"b","text":"Their skin tone and height"},{"id":"c","text":"The way they keep their promises"},{"id":"d","text":"Whether the rishta is 'a good match'"},{"id":"e","text":"What they've quietly built and learned"},{"id":"f","text":"Their family's 'status' on a biodata"}],"bins":[{"id":"true","label":"True measure","valence":"pos"},{"id":"label","label":"Market label","valence":"neg"}],"key":{"a":"true","b":"label","c":"true","d":"label","e":"true","f":"label"},"relearn":"Character and how you keep your word are true measures; skin tone and biodata status are just labels.","persona":"any","source":"measure vs label"},
  {"id":"yp-1368","cat":"worth-beyond-status","type":"sort","hook":"Sort: which belong on a person's worth, and which the world just pins on?","items":[{"id":"a","text":"Their kindness"},{"id":"b","text":"Being someone's wife"},{"id":"c","text":"Their honesty"},{"id":"d","text":"Being someone's mother"},{"id":"e","text":"The courage to live their own way"},{"id":"f","text":"A 'settled' tag from relatives"}],"bins":[{"id":"theirs","label":"Truly theirs","valence":"pos"},{"id":"pinned","label":"Pinned on by world","valence":"neg"}],"key":{"a":"theirs","b":"pinned","c":"theirs","d":"pinned","e":"theirs","f":"pinned"},"relearn":"Kindness, honesty and courage are truly yours; wife/mother/'settled' tags are pinned on by others.","persona":"any","source":"yours vs pinned"},
  {"id":"yp-1369","cat":"worth-beyond-status","type":"sort","hook":"Sort each line: kind self-talk you can keep, or marriage-market shame to drop?","items":[{"id":"a","text":"\"My worth isn't up for rating\""},{"id":"b","text":"\"I'm too dark to be picked\""},{"id":"c","text":"\"I like the person I've become\""},{"id":"d","text":"\"My biodata is weak so I am too\""},{"id":"e","text":"\"My life is mine to be proud of\""},{"id":"f","text":"\"I'm rejected goods now\""}],"bins":[{"id":"keep","label":"Keep","valence":"pos"},{"id":"drop","label":"Drop","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"'My worth isn't up for rating' is true; 'too dark', 'weak biodata' and 'rejected goods' are shame to drop.","persona":"any","source":"keep vs drop"},
  {"id":"yp-1370","cat":"worth-beyond-status","type":"sort","hook":"Sort: a reason someone is genuinely respected, or just a status they hold?","items":[{"id":"a","text":"They show up for their friends"},{"id":"b","text":"They're married into a 'good' family"},{"id":"c","text":"They do their work with care"},{"id":"d","text":"They have two children"},{"id":"e","text":"They keep learning and growing"},{"id":"f","text":"They married 'on time'"}],"bins":[{"id":"earned","label":"Genuinely respected","valence":"pos"},{"id":"status","label":"Just a status","valence":"neg"}],"key":{"a":"earned","b":"status","c":"earned","d":"status","e":"earned","f":"status"},"relearn":"Showing up, careful work and growth earn real respect; marrying 'on time' or into status doesn't.","persona":"any","source":"respect vs status"},
  {"id":"yp-1371","cat":"worth-beyond-status","type":"sort","hook":"Sort: a fair way to weigh your own life, or the script's unfair scale?","items":[{"id":"a","text":"Did I act with kindness this year?"},{"id":"b","text":"Am I married by the 'right' age?"},{"id":"c","text":"Did I grow into someone I respect?"},{"id":"d","text":"Do I have the 'expected' number of kids?"},{"id":"e","text":"Did I keep faith with the people I love?"},{"id":"f","text":"Did relatives approve of my choices?"}],"bins":[{"id":"fair","label":"Fair scale","valence":"pos"},{"id":"unfair","label":"Script's scale","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Kindness, growth and loyalty are a fair scale; age-married, kid-count and approval are the script's.","persona":"any","source":"fair scale"},
  {"id":"yp-1372","cat":"worth-beyond-status","type":"sort","hook":"Sort: even-handed truth about the pressure, or a take that misses?","items":[{"id":"a","text":"It falls hardest on women"},{"id":"b","text":"Only women ever feel it"},{"id":"c","text":"Men feel a lighter version too"},{"id":"d","text":"Men have it just as bad as women"},{"id":"e","text":"The script constrains everyone unequally"},{"id":"f","text":"Pressure means someone's worth is low"}],"bins":[{"id":"true","label":"Even-handed & true","valence":"pos"},{"id":"off","label":"Misses the mark","valence":"neg"}],"key":{"a":"true","b":"off","c":"true","d":"off","e":"true","f":"off"},"relearn":"It hits women hardest, men feel a lighter version, and it constrains everyone unequally; pressure isn't worth.","persona":"Karthik","source":"even-handed sort"},
  {"id":"yp-1373","cat":"worth-beyond-status","type":"sort","hook":"Sort what truly makes a home worth being in: real, or just on paper?","items":[{"id":"a","text":"Care and respect between people"},{"id":"b","text":"A married couple on the nameplate"},{"id":"c","text":"Safety to be yourself there"},{"id":"d","text":"A child to 'complete' it"},{"id":"e","text":"Laughter and being known"},{"id":"f","text":"Looking 'proper' to neighbours"}],"bins":[{"id":"real","label":"Makes it real","valence":"pos"},{"id":"paper","label":"Just on paper","valence":"neg"}],"key":{"a":"real","b":"paper","c":"real","d":"paper","e":"real","f":"paper"},"relearn":"Care, safety and laughter make a home; a married nameplate or a child 'to complete it' don't define worth.","persona":"any","source":"home, real vs paper"},
  {"id":"yp-1374","cat":"worth-beyond-status","type":"sort","hook":"Sort: anchors your worth steady, or hands it to others to grade?","items":[{"id":"a","text":"Knowing who you are"},{"id":"b","text":"Waiting for relatives' approval"},{"id":"c","text":"Your own sense of having lived well"},{"id":"d","text":"Chasing a higher 'market value'"},{"id":"e","text":"The respect you have for yourself"},{"id":"f","text":"Needing a wedding to feel okay"}],"bins":[{"id":"steady","label":"Anchors you","valence":"pos"},{"id":"graded","label":"Hands it to others","valence":"neg"}],"key":{"a":"steady","b":"graded","c":"steady","d":"graded","e":"steady","f":"graded"},"relearn":"Self-knowledge and self-respect anchor your worth; chasing approval or a wedding hands it to others.","persona":"any","source":"anchor vs graded"},
  {"id":"yp-1375","cat":"worth-beyond-status","type":"sort","hook":"Sort each thing a relative might 'congratulate' or 'pity': what actually says nothing about worth?","items":[{"id":"a","text":"Your honesty and warmth"},{"id":"b","text":"Still being unmarried at 35"},{"id":"c","text":"The good you do quietly"},{"id":"d","text":"Not having had a child yet"},{"id":"e","text":"How you've grown through hard years"},{"id":"f","text":"Marrying 'a bit late'"}],"bins":[{"id":"worth","label":"Real worth","valence":"pos"},{"id":"nothing","label":"Says nothing","valence":"neg"}],"key":{"a":"worth","b":"nothing","c":"worth","d":"nothing","e":"worth","f":"nothing"},"relearn":"Honesty, your quiet good and your growth are worth; unmarried-at-35 or 'late' marriage say nothing about it.","persona":"any","source":"congrats vs pity"},
  {"id":"yp-1376","cat":"worth-beyond-status","type":"sort","hook":"Sort: a thought that protects your worth from the marriage market, or one that hands it over?","items":[{"id":"a","text":"\"Their scoring isn't my mirror\""},{"id":"b","text":"\"A rejection means I'm less\""},{"id":"c","text":"\"I decide what I'm worth\""},{"id":"d","text":"\"I must look fairer to matter\""},{"id":"e","text":"\"My value isn't a biodata field\""},{"id":"f","text":"\"More proposals would prove me\""}],"bins":[{"id":"guards","label":"Protects you","valence":"pos"},{"id":"gives","label":"Hands it over","valence":"neg"}],"key":{"a":"guards","b":"gives","c":"guards","d":"gives","e":"guards","f":"gives"},"relearn":"'Their scoring isn't my mirror' guards your worth; 'a rejection means I'm less' hands it to the market.","persona":"any","source":"guard the gate"},
  {"id":"yp-1377","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that grade a woman by her looks.","scene":[{"id":"a","text":"\"She's so kind and sharp\"","trick":false},{"id":"b","text":"\"She's too dark for a good match\"","trick":true},{"id":"c","text":"\"She's built a life she loves\"","trick":false},{"id":"d","text":"\"If only she'd lose weight she'd marry\"","trick":true},{"id":"e","text":"\"She's good at what she does\"","trick":false}],"why":"'Too dark for a match' and 'lose weight she'd marry' grade her by looks; the others see the actual person.","relearn":"Your worth isn't your looks or skin tone; colourism measures nothing real about you.","persona":"any","source":"catch the looks-grading"},
  {"id":"yp-1378","cat":"worth-beyond-status","type":"spot","hook":"Spot the two things relatives say that tie a woman's worth to a child.","scene":[{"id":"a","text":"\"She's wonderful with or without kids\"","trick":false},{"id":"b","text":"\"A woman's incomplete till she's a mother\"","trick":true},{"id":"c","text":"\"Her choice on children is hers\"","trick":false},{"id":"d","text":"\"What's the point of her if not a baby?\"","trick":true},{"id":"e","text":"\"She knows her own life\"","trick":false}],"why":"'Incomplete till a mother' and 'what's the point if not a baby' tie her worth to a child; the rest don't.","relearn":"Womanhood isn't motherhood; a childfree woman is complete, and her choice is hers.","persona":"Nisha","source":"catch the child-pressure"},
  {"id":"yp-1379","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that score someone for the marriage market.","scene":[{"id":"a","text":"\"What a thoughtful person he is\"","trick":false},{"id":"b","text":"\"Decent biodata, family's a bit low though\"","trick":true},{"id":"c","text":"\"He treats people really well\"","trick":false},{"id":"d","text":"\"Fair, tall, good salary, that's the value\"","trick":true},{"id":"e","text":"\"He's honest and easy to trust\"","trick":false}],"why":"The biodata-scoring and 'fair, tall, salary = value' lines rank for the market; the others see the person.","relearn":"A marriage-market score isn't your value; you're a person, not a profile to be ranked.","persona":"any","source":"catch the scoring"},
  {"id":"yp-1380","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that say an unmarried adult is somehow less.","scene":[{"id":"a","text":"\"She's a full adult, married or not\"","trick":false},{"id":"b","text":"\"Poor thing, all alone at her age\"","trick":true},{"id":"c","text":"\"Her single life looks pretty full\"","trick":false},{"id":"d","text":"\"Such a waste, no one took her\"","trick":true},{"id":"e","text":"\"She seems genuinely content\"","trick":false}],"why":"'Poor thing, all alone' and 'no one took her' frame single as lesser; the rest see a full, content adult.","relearn":"Worth was never your marital status; an unmarried adult is whole and full, not a waste.","persona":"Sneha","source":"catch the pity"},
  {"id":"yp-1381","cat":"worth-beyond-status","type":"spot","hook":"Spot the two 'compliments' that are really about marrying you off.","scene":[{"id":"a","text":"\"You're so capable\"","trick":false},{"id":"b","text":"\"Pretty enough to get a great rishta\"","trick":true},{"id":"c","text":"\"You've got a real talent\"","trick":false},{"id":"d","text":"\"Learn to cook and you'll be set for marriage\"","trick":true},{"id":"e","text":"\"You think things through well\"","trick":false}],"why":"'Pretty enough for a rishta' and 'cook and you'll be set for marriage' aim you at a match; the rest see you.","relearn":"A compliment that's really about your marriageability isn't about your real worth.","persona":"any","source":"catch the rishta-aim"},
  {"id":"yp-1382","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that make a man's value about being 'settled'.","scene":[{"id":"a","text":"\"He's reliable and kind\"","trick":false},{"id":"b","text":"\"Not settled yet? Something's off with him\"","trick":true},{"id":"c","text":"\"He's built a steady, honest life\"","trick":false},{"id":"d","text":"\"A man's only respected once he's a husband\"","trick":true},{"id":"e","text":"\"People trust him for good reason\"","trick":false}],"why":"'Something's off if not settled' and 'only respected as a husband' tie his value to status; the rest don't.","relearn":"Adulthood and respect aren't conferred by marital status; men feel this pressure too.","persona":"Karthik","source":"catch the husband-tag"},
  {"id":"yp-1383","cat":"worth-beyond-status","type":"spot","hook":"Spot the two thoughts that let a rishta rejection sink your self-worth.","scene":[{"id":"a","text":"\"Their no is about fit, not my value\"","trick":false},{"id":"b","text":"\"If they said no, I must be defective\"","trick":true},{"id":"c","text":"\"I'm still the same worthy person\"","trick":false},{"id":"d","text":"\"Each rejection proves I'm unlovable\"","trick":true},{"id":"e","text":"\"One match's opinion isn't a verdict\"","trick":false}],"why":"'I must be defective' and 'proves I'm unlovable' hand a rejection power over your worth; the rest don't.","relearn":"A rishta rejection is about fit, not your value; one match's no is no verdict on you.","persona":"any","source":"catch the spiral"},
  {"id":"yp-1384","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that judge a divorced woman's worth.","scene":[{"id":"a","text":"\"She's whole and starting fresh\"","trick":false},{"id":"b","text":"\"Divorced means damaged goods now\"","trick":true},{"id":"c","text":"\"Her marriage ended; she didn't\"","trick":false},{"id":"d","text":"\"Who'll take her with that baggage?\"","trick":true},{"id":"e","text":"\"She's the same strong person\"","trick":false}],"why":"'Damaged goods' and 'baggage' shame her for a divorce; the rest see a whole person whose marriage ended.","relearn":"Ending a marriage takes nothing from your worth; 'damaged goods' is a slur, not a fact.","persona":"any","source":"catch the divorce-shame"},
  {"id":"yp-1385","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that make a childfree life sound like a failure.","scene":[{"id":"a","text":"\"Her life's full as it is\"","trick":false},{"id":"b","text":"\"No kids? So selfish and empty\"","trick":true},{"id":"c","text":"\"She chose this and she's content\"","trick":false},{"id":"d","text":"\"She'll die with regrets, mark my words\"","trick":true},{"id":"e","text":"\"Meaning comes from many places\"","trick":false}],"why":"'Selfish and empty' and 'die with regrets' shame a childfree life; the rest treat it as full and chosen.","relearn":"A childfree life is complete and not selfish; meaning comes from many sources, not only kids.","persona":"Nisha","source":"catch the regret-script"},
  {"id":"yp-1386","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that reduce someone to their family's 'status'.","scene":[{"id":"a","text":"\"He's earned everything he has\"","trick":false},{"id":"b","text":"\"Good family, so he must be worth more\"","trick":true},{"id":"c","text":"\"Judge him by how he acts\"","trick":false},{"id":"d","text":"\"Low family means low value, simple\"","trick":true},{"id":"e","text":"\"He's decent regardless of background\"","trick":false}],"why":"'Good family = worth more' and 'low family = low value' price a person by lineage; the rest judge the person.","relearn":"Your worth isn't your family's 'status'; character and how you act are the real measure.","persona":"any","source":"catch the lineage-pricing"},
  {"id":"yp-1387","cat":"worth-beyond-status","type":"spot","hook":"Spot the two 'helpful' lines at the wedding that quietly shame the single guest.","scene":[{"id":"a","text":"\"Lovely to see you, glad you came\"","trick":false},{"id":"b","text":"\"You next, beta, before it's too late!\"","trick":true},{"id":"c","text":"\"How's your work going these days?\"","trick":false},{"id":"d","text":"\"Tsk, still alone, don't be so fussy\"","trick":true},{"id":"e","text":"\"Come, sit with us and eat\"","trick":false}],"why":"'You next before it's too late' and 'still alone, don't be fussy' shame the single guest; the rest are warm.","relearn":"You're a full guest at any function, not a problem to be married off 'before it's too late'.","persona":"Sneha","source":"catch the wedding-jab"},
  {"id":"yp-1388","cat":"worth-beyond-status","type":"spot","hook":"Spot the two ideas a parent absorbed that they shouldn't pass to a daughter.","scene":[{"id":"a","text":"\"Your worth is yours, whatever you choose\"","trick":false},{"id":"b","text":"\"Lighter skin will get you a better match\"","trick":true},{"id":"c","text":"\"I'll respect the life you build\"","trick":false},{"id":"d","text":"\"Marry on time or you'll be a burden\"","trick":true},{"id":"e","text":"\"I'm proud of who you are\"","trick":false}],"why":"'Lighter skin, better match' and 'marry on time or be a burden' pass on the script; the rest free her.","relearn":"Don't pass on colourism or the timeline; a daughter's worth isn't her looks or marriage date.","persona":"any","source":"catch the inherited script"},
  {"id":"yp-1389","cat":"worth-beyond-status","type":"spot","hook":"Spot the two thoughts to drop the next time the 'you're less' message creeps in.","scene":[{"id":"a","text":"\"This is their script, not my truth\"","trick":false},{"id":"b","text":"\"Maybe they're right that I'm lacking\"","trick":true},{"id":"c","text":"\"My worth didn't go anywhere\"","trick":false},{"id":"d","text":"\"I should shrink and apologise for my life\"","trick":true},{"id":"e","text":"\"I get to like the life I've made\"","trick":false}],"why":"'Maybe I'm lacking' and 'shrink and apologise' let the message in; the rest keep your own truth in charge.","relearn":"When 'you're less' creeps in, drop it deliberately; your worth didn't go anywhere.","persona":"any","source":"catch the creep"},
  {"id":"yp-1390","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"the lunch jab","hook":"An uncle has a habit of picking at your life choices at family lunches.","setup":"This time, over dessert, he turns to you.","steps":[{"prompt":"Uncle says: \"Beta, at your age, unmarried, what's the value of all this degree-shegree?\"","options":[{"text":"\"My worth isn't a marriage date, uncle. I'm proud of what I'm building.\"","then":"Uncle pauses, then shrugs. \"Just saying. That's all.\"","best":true},{"text":"\"Haan, you're right. I should hurry and settle.\"","then":"Uncle nods, pleased, and starts naming eligible matches."},{"text":"\"That's a really insulting thing to say.\"","then":"Uncle looks wounded. \"I only meant it as a joke.\""},{"text":"\"Maybe the degree was a waste. Who knows.\"","then":"Uncle looks satisfied, and repeats the jab at the next lunch."}],"why":"Naming your worth plainly refuses the jab without needing to defend the degree itself."},{"prompt":"A cousin says: \"He's old school. Don't let it bother you.\"","options":[{"text":"\"I won't, but it still wasn't okay to say.\"","then":"Cousin nods. \"Fair. I'll mention it to him.\"","best":true},{"text":"\"It's fine. I'm used to comments like that.\"","then":"Cousin shrugs, and the comment quietly stays unaddressed."},{"text":"\"He's honestly always like this at lunches.\"","then":"Cousin laughs it off, and the moment passes lightly."},{"text":"\"Maybe I shouldn't take it so personally.\"","then":"Cousin looks relieved you're not upset, and it's dropped."}],"why":"Naming that it wasn't okay, even from an old-school uncle, keeps your worth from being brushed off."},{"prompt":"Months later, uncle asks, with real curiosity this time: \"How's the work going, really?\"","options":[{"text":"\"It's going well. Thank you for asking properly.\"","then":"Uncle nods, a bit awkward but genuine. \"Good. Proud of you.\"","best":true},{"text":"\"Oh, now you're interested?\"","then":"Uncle looks stung, even though the question was sincere."},{"text":"\"It's been going well this whole time, actually.\"","then":"Uncle looks a little sheepish, realising he'd never really asked before."},{"text":"\"It's fine, I guess.\"","then":"Uncle senses the coolness, and the moment stays distant."}],"why":"Meeting a genuine question warmly gives the relationship room to actually grow."}],"relearn":"Adulthood and respect aren't conferred by marriage; your worth isn't a wedding date."},
  {"id":"yp-1391","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"the 'fairer' rejection","hook":"A rishta falls through because the family wanted someone 'fairer'.","setup":"Tonight, a friend tries to be practical.","steps":[{"prompt":"She says: \"Maybe you should look into some fairness creams, you know, to widen your options.\"","options":[{"text":"\"Their colourism is the problem, not me. My skin tone measures nothing.\"","then":"She pauses, a little unsure how to respond to that.","best":true},{"text":"\"You're right. Maybe I should try fairness creams.\"","then":"She nods approvingly and mentions a brand she's seen advertised."},{"text":"\"That's a really hurtful thing to suggest.\"","then":"She looks defensive. \"I was just trying to help.\""},{"text":"\"Maybe I should ask them what I should change.\"","then":"She offers to find out through a cousin, and you start waiting on their verdict."}],"why":"Naming the bias as theirs, not yours, refuses to let their prejudice become your problem."},{"prompt":"Your mother says: \"The next family might feel differently, you know.\"","options":[{"text":"\"Maybe, but I'm not changing for anyone's bias.\"","then":"Your mother pauses, then nods slowly. \"Fair enough, beta.\"","best":true},{"text":"\"I hope so. I'll try to look nicer next time.\"","then":"Your mother relaxes, and the pressure to 'improve' continues quietly."},{"text":"\"Everyone keeps bringing this up. It's exhausting.\"","then":"Your mother looks a little hurt by the sharp tone."},{"text":"\"Maybe I really am the problem here.\"","then":"Your mother looks concerned, hearing you doubt yourself."}],"why":"Holding your ground, even against a hopeful reframe, keeps the bias from becoming your task to fix."},{"prompt":"Your cousin says: \"A new rishta is coming on Sunday. How are you feeling about it?\"","options":[{"text":"\"Nervous, but the bias was never about me.\"","then":"Your cousin smiles. \"Good. Go as you are.\"","best":true},{"text":"\"Maybe a bit more makeup wouldn't hurt.\"","then":"Your cousin nods and offers to lend you her concealer."},{"text":"\"I should just cancel and avoid the risk.\"","then":"Your cousin frowns. \"You'll only worry about it all week.\""},{"text":"\"I need a comeback ready, just in case.\"","then":"Your cousin laughs and helps you rehearse lines all evening."}],"why":"Repeating the truth to yourself, ahead of time, keeps the old bias from setting the terms again."},{"prompt":"Months later, your friend says: \"I was wrong to suggest those creams.\"","options":[{"text":"\"Thank you for saying that. It means a lot.\"","then":"She smiles, a little sheepish. \"I should've known better.\"","best":true},{"text":"\"Yeah, that really wasn't okay of you.\"","then":"She looks a bit stung, even while agreeing with you."},{"text":"\"See, I told you it wasn't me.\"","then":"She looks defensive, even though she's actually apologising."},{"text":"\"It's fine. Don't worry about it.\"","then":"The apology lands, but the earlier hurt stays unspoken."}],"why":"Thanking her for the apology, and saying it means a lot, honours both the hurt and the repair."}],"relearn":"Colourism measures nothing real about you; a rishta's bias is theirs, not your flaw."},
  {"id":"yp-1392","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"after her divorce","hook":"Your sister, divorced, has started to believe what relatives are calling her.","setup":"Tonight, she says it quietly, curled up on the sofa.","steps":[{"prompt":"She says: \"They call me 'used' now. Maybe they're right, in a way.\"","options":[{"text":"\"You're whole, didi. A marriage ended, but your worth certainly didn't.\"","then":"She's quiet, then a small nod. \"I needed to hear that.\"","best":true},{"text":"\"Maybe just remarry fast so people stop talking.\"","then":"She nods, and starts thinking about matrimonial sites again."},{"text":"\"That's a disgusting thing for them to say.\"","then":"She agrees, but the word 'used' still sits there."},{"text":"\"Try not to let it get to you too much.\"","then":"She nods, but the word keeps circling back anyway."}],"why":"Naming her wholeness plainly refuses the word instead of just sympathising with it."},{"prompt":"The next day she says: \"I keep hearing that word every time I see them.\"","options":[{"text":"\"That word is their cruelty, not a fact about you.\"","then":"She repeats it quietly, and something in her steadies.","best":true},{"text":"\"Try to avoid them for a while, if you can manage it.\"","then":"The word waits for her at the next gathering anyway."},{"text":"\"I'd cut them off completely, to be honest.\"","then":"She looks unsure she's ready for that big a step."},{"text":"\"Maybe it'll feel less true with time.\"","then":"She waits for the feeling to pass, but it doesn't yet."}],"why":"Naming it as their cruelty, not a fact, helps the word lose its grip on her."},{"prompt":"Weeks later, she says: \"The word doesn't sting the same way now.\"","options":[{"text":"\"That's your own strength, not luck.\"","then":"She smiles. \"Maybe. I like hearing that, though.\"","best":true},{"text":"\"I'm glad they finally backed off.\"","then":"It's kind, but the shift she made herself goes unnamed."},{"text":"\"Are you sure it won't come back, though?\"","then":"She looks unsettled again, right after finding some peace."},{"text":"\"Good, took them long enough.\"","then":"She looks a little stung by the offhand tone."}],"why":"Naming her own strength, not luck or circumstance, honours what she actually worked through."}],"relearn":"Ending a marriage takes nothing from your worth; shaming words aren't facts."},
  {"id":"yp-1393","cat":"worth-beyond-status","type":"role-play","persona":"Nisha","source":"'incomplete as a woman'","hook":"A childfree colleague has been quiet and low at work all week.","setup":"Tonight, she opens up over dinner.","steps":[{"prompt":"She says: \"Someone actually told me I'm incomplete as a woman today.\"","options":[{"text":"\"You're complete as you are. Womanhood isn't motherhood.\"","then":"She's quiet, then a small smile. \"I needed that, thank you.\"","best":true},{"text":"\"Well, you might regret it later. Who really knows.\"","then":"She looks stung, hearing doubt from you too."},{"text":"\"That's a horrible thing to say to you, honestly.\"","then":"She agrees, but the word 'incomplete' still sits there."},{"text":"\"Try not to let it get to you tonight, okay?\"","then":"She nods, but the comment keeps circling back anyway."}],"why":"Naming her completeness plainly refuses the label instead of just sympathising with it."},{"prompt":"She asks: \"Do you think I'll regret it someday, honestly?\"","options":[{"text":"\"I trust you know your own life best.\"","then":"She exhales. \"That's what I needed to hear, actually.\"","best":true},{"text":"\"Maybe. You never really know for sure.\"","then":"The doubt she came in with gets a little heavier."},{"text":"\"Of course not. Don't even think about it.\"","then":"It's kind, but the real question she asked goes unanswered."},{"text":"\"Let's talk about something lighter tonight.\"","then":"She nods, but the question stays between you, unanswered."}],"why":"Trusting her own knowledge of herself is hers to claim; your role is to back that, not guess for her."},{"prompt":"A month later, she says: \"The comment still crosses my mind sometimes.\"","options":[{"text":"\"That's the comment, not the truth about you.\"","then":"She nods slowly. \"Right. It's the comment, not me.\"","best":true},{"text":"\"Maybe it'll fade with time. Don't worry.\"","then":"She waits for it to fade, but it doesn't yet."},{"text":"\"You should confront whoever said that.\"","then":"She looks unsure she's ready for that confrontation."},{"text":"\"Try to think about something else instead.\"","then":"The comment resurfaces anyway, just quieter."}],"why":"Naming the comment as the source, not her, keeps it from becoming a verdict she carries."},{"prompt":"Months later, she says: \"The comment barely registers anymore.\"","options":[{"text":"\"Good. Your completeness was never in question.\"","then":"She smiles. \"It helped, having someone say that plainly.\"","best":true},{"text":"\"Nice. I guess people finally get it now.\"","then":"It's kind, but it credits other people, not the steadiness she built."},{"text":"\"See, I told you it would fade in time.\"","then":"She feels a little dismissed, hearing it as your win."},{"text":"\"That's good to hear. I'm glad to know.\"","then":"The moment feels flatter than it should, given how far she's come."}],"why":"Naming that her completeness was never actually in doubt honours her own steadiness."}],"relearn":"Womanhood isn't motherhood; a childfree woman is complete, and the choice is hers."},
  {"id":"yp-1394","cat":"worth-beyond-status","type":"role-play","persona":"Sneha","source":"the loud pity","hook":"A relative always seems to have an opinion about your life.","setup":"Tonight, in front of several other guests, she turns to you.","steps":[{"prompt":"She says: \"Such a nice person, and still no one married her. So sad, really.\"","options":[{"text":"\"I'm not waiting to be married off, auntie. I'm happy with my life.\"","then":"She blinks, then laughs it off. \"Just saying, beta.\"","best":true},{"text":"\"I know, I know. I'm trying my best to find someone.\"","then":"She looks sympathetic and starts listing good matches she knows."},{"text":"\"That's a really rude thing to say out loud.\"","then":"She looks wounded. \"I only said it out of love.\""},{"text":"\"Maybe I really am unlucky. Who knows.\"","then":"She looks satisfied, and repeats the pity at the next gathering."}],"why":"Naming that you're happy, plainly, refuses the pity instead of confirming it."},{"prompt":"A cousin says: \"She means well. She's just from another generation.\"","options":[{"text":"\"Maybe, but it still wasn't okay to say.\"","then":"Cousin nods. \"Fair. I'll say something next time.\"","best":true},{"text":"\"It's fine. I'm used to comments like that.\"","then":"Cousin shrugs, and the comment quietly stays unaddressed."},{"text":"\"She's honestly always like this, though.\"","then":"Cousin laughs it off, and the moment passes lightly."},{"text":"\"Maybe I shouldn't take it so personally.\"","then":"Cousin looks relieved you're not upset, and it's dropped."}],"why":"Naming that it wasn't okay, even from an older relative, keeps your worth from being brushed off."},{"prompt":"At the next gathering, she starts to say it again, then catches herself. \"Never mind,\" she says.","options":[{"text":"\"Thank you for catching that, auntie.\"","then":"She smiles, a little proud of herself. \"Trying, beta.\"","best":true},{"text":"\"You almost said it again, didn't you.\"","then":"She looks a bit caught out, and the moment turns awkward."},{"text":"\"See, you can learn after all.\"","then":"She looks stung by the jab, even though she held back."},{"text":"\"I noticed. Anyway, how's your garden?\"","then":"She answers easily, though the effort you noticed goes unthanked."}],"why":"Noticing the change out loud, kindly, makes it easier for her to keep it up."},{"prompt":"Months later, she introduces you to a guest: \"This one is living a really full life.\"","options":[{"text":"\"Thank you. That's exactly how it feels.\"","then":"She smiles. \"I was wrong before, and glad to say so.\"","best":true},{"text":"\"I guess I finally convinced you.\"","then":"She looks a touch sheepish at the callback."},{"text":"\"I wasn't sure you'd ever really see it.\"","then":"She looks a touch put off by the doubt in it."},{"text":"\"Well. That's nice of you to say.\"","then":"The moment passes, warm but a little flat."}],"why":"Simply accepting the shift, warmly, lets the changed view stand without reopening the old fight."}],"relearn":"Others' pity about being unmarried isn't your truth; let it pass and keep your worth."},
  {"id":"yp-1395","cat":"worth-beyond-status","type":"role-play","persona":"Karthik","source":"taken seriously","hook":"Your father has strong opinions about when a man finally earns respect.","setup":"Tonight, your father says it at dinner.","steps":[{"prompt":"Father says: \"Beta, a man isn't taken seriously until he's married with a son.\"","options":[{"text":"\"I hear you, papa. My worth isn't a wife or a son.\"","then":"Father pauses, then nods slowly. \"Fair enough, I suppose.\"","best":true},{"text":"\"You're right. No one really respects a single man. I'll rush it, honestly.\"","then":"Father brightens, and starts asking around for matches."},{"text":"\"That's a really old-fashioned thing to say.\"","then":"Father looks wounded. \"I'm only telling you the truth.\""},{"text":"\"Papa, did you see the match last night?\"","then":"Father answers about the match, but the comment sits there unanswered."}],"why":"Naming your worth plainly, while still hearing him, refuses the idea without a fight."},{"prompt":"An uncle repeats it at a family visit a week later: \"Same thing goes for you too, you know.\"","options":[{"text":"\"I know you believe that, but it isn't how I measure myself.\"","then":"Uncle pauses, then shrugs. \"Fair. Your life, I suppose.\"","best":true},{"text":"\"Maybe you're right. I should hurry.\"","then":"Uncle nods, pleased, and mentions it again by evening."},{"text":"\"Everyone keeps saying this. It's tiring.\"","then":"Uncle looks a little wounded by the sharp tone."},{"text":"\"Maybe I really am not taken seriously by anyone.\"","then":"Uncle looks concerned, hearing you doubt yourself."}],"why":"The same steady line, said calmly, keeps your worth intact even against repeated pressure."},{"prompt":"Months later, your father says: \"I've stopped repeating that to you myself.\"","options":[{"text":"\"Thank you, papa. That really does mean something to me.\"","then":"Father smiles, a little shy. \"I'm still learning too, beta.\"","best":true},{"text":"\"Maybe you're right about all of it. I should probably hurry up now.\"","then":"Father looks surprised and a little worried, hearing you doubt yourself."},{"text":"\"See, I was right about it the whole time.\"","then":"Father looks defensive, even though he's actually softening."},{"text":"\"About time, honestly.\"","then":"Father looks hurt, even though he's backing off the line."}],"why":"Thanking him for the shift keeps the relationship warm now that the pressure has eased."}],"relearn":"Adulthood and respect aren't conferred by marriage or a son; men feel this pressure too."},
  {"id":"yp-1396","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"rated 'average'","hook":"A younger cousin is shaken after being rated by a matchmaker.","setup":"Tonight, she calls you, still crying about it.","steps":[{"prompt":"She says: \"The matchmaker rated me 'average'. Maybe that's just what I am.\"","options":[{"text":"\"A matchmaker's rating isn't your value. Not a profile to be scored.\"","then":"She's quiet, then a small sniffle. \"I needed to hear that.\"","best":true},{"text":"\"Don't worry. We'll find someone who'll happily overlook that eventually.\"","then":"She nods, but the fix quietly stays outside of her."},{"text":"\"That's a disgusting way to rate a person.\"","then":"She agrees, but the feeling of being 'average' stays there."},{"text":"\"Try not to let one rating get to you.\"","then":"She nods, but the word 'average' keeps replaying anyway."}],"why":"Naming her worth plainly, apart from any rating, gives her something truer to hold."},{"prompt":"She asks: \"But why does the rating even matter to people, then?\"","options":[{"text":"\"Because the system is broken, not because something's wrong with you.\"","then":"She nods slowly. \"That actually makes more sense.\"","best":true},{"text":"\"Because they're trying to be helpful, probably.\"","then":"She takes that as reason to keep trusting the rating."},{"text":"\"Because people are cruel, honestly.\"","then":"She nods, but the question stays half answered."},{"text":"\"I don't really know why, to be fair.\"","then":"She's left without much of an answer either way."}],"why":"Naming the system, not her, as the source keeps the rating from feeling like a verdict."},{"prompt":"Weeks later, she says: \"That word 'average' doesn't shake me the way it used to.\"","options":[{"text":"\"That's you, standing in your own worth now.\"","then":"She grins. \"Yeah. It actually feels like mine.\"","best":true},{"text":"\"Good, maybe they've stopped rating people.\"","then":"It's kind, but the shift she made herself goes unnamed."},{"text":"\"Are you sure it'll last, though?\"","then":"She looks unsettled again, right after finding her footing."},{"text":"\"That's nice to hear.\"","then":"The moment feels a little flatter than it should."}],"why":"Naming the change as hers, not luck, honours the worth she's claimed for herself."}],"relearn":"No matchmaker's rating is your value; you're a person, not a profile to be scored."},
  {"id":"yp-1397","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"marry up","hook":"A friend has been thinking hard about marriage lately.","setup":"Tonight, she opens up over coffee, half joking, half not.","steps":[{"prompt":"She says: \"Honestly, I'll only feel like someone once I marry into a good family.\"","options":[{"text":"\"You're already someone. A family's name doesn't add to who you are.\"","then":"She pauses, surprised. \"I hadn't thought of it that way.\"","best":true},{"text":"\"Yeah, marry up and you'll finally matter.\"","then":"She starts scrolling profiles from 'better' families."},{"text":"\"That's a really sad way to think about yourself.\"","then":"She feels judged, and the joke turns a bit awkward."},{"text":"\"Maybe you're right. Names do open doors.\"","then":"She nods, and the idea settles in a little deeper."}],"why":"Naming her worth as already whole answers the claim instead of just agreeing with it."},{"prompt":"She says: \"My mother keeps mentioning a well-connected family.\"","options":[{"text":"\"A name won't make you more you than you already are.\"","then":"She goes quiet, turning that over. \"That actually helps.\"","best":true},{"text":"\"Your mother probably knows best about this.\"","then":"She lets her mother's opinion carry more weight than her own."},{"text":"\"Tell your mother to stop pushing that.\"","then":"She sighs. \"Easy for you to say, not your mother.\""},{"text":"\"Maybe it's worth considering, for the connections.\"","then":"She starts weighing the family's name over her own feelings."}],"why":"Reminding her that a name adds nothing keeps the choice about her, not the connections."},{"prompt":"A month later, she says: \"I met someone from an ordinary family. I really like him.\"","options":[{"text":"\"How you feel with him matters more than his name.\"","then":"She smiles, relieved. \"Yeah. That's what actually matters.\"","best":true},{"text":"\"Just make sure his family's decent, at least.\"","then":"She starts quietly weighing his family against the 'better' one."},{"text":"\"Are you sure that's enough for you, though?\"","then":"She second-guesses a feeling that had actually felt clear."},{"text":"\"I guess names aren't everything, sometimes.\"","then":"The old idea softens, but doesn't fully let go yet."}],"why":"Naming what actually matters, how she feels, gives her real ground to choose from."},{"prompt":"Months later, she says: \"I feel like someone, finally, being honest about what I actually want.\"","options":[{"text":"\"That's you, not any family's name.\"","then":"She laughs, teary. \"Yeah. It really is just me.\"","best":true},{"text":"\"I'm glad you found someone who feels right.\"","then":"It's kind, but her own shift goes uncredited."},{"text":"\"See, it really was about finding the right connections.\"","then":"It echoes the very idea she'd been trying to let go of."},{"text":"\"That's nice to hear.\"","then":"The moment feels flatter than it should, given how far she's come."}],"why":"Naming that the feeling is hers, not borrowed from a name, honours the real shift she made."}],"relearn":"A family's 'status' doesn't add to your worth; you're already whole as you are."},
  {"id":"yp-1398","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"the unmarried daughter","hook":"Your mother has seemed low and withdrawn for days.","setup":"Tonight, she says it quietly, unable to meet your eyes.","steps":[{"prompt":"She says: \"The neighbours call you 'the unmarried daughter'. I feel ashamed.\"","options":[{"text":"\"Their gossip isn't my worth, ma. Nothing to be ashamed of.\"","then":"She's quiet, then a small nod. \"I needed to hear that.\"","best":true},{"text":"\"Fine, I'll just marry the next proposal so they'll stop.\"","then":"She looks relieved, and starts asking around for proposals."},{"text":"\"That's a horrible thing for them to say to you.\"","then":"She agrees, but the shame in her voice stays there."},{"text":"\"Try not to let the neighbours get to you.\"","then":"She nods, but the gossip keeps weighing on her anyway."}],"why":"Naming that gossip measures nothing real relieves her shame without a rushed decision."},{"prompt":"The next week she says: \"I keep hearing it every time I step outside.\"","options":[{"text":"\"That's their gossip, not a fact about us.\"","then":"She repeats it quietly, and something in her voice steadies.","best":true},{"text":"\"Try to avoid them for a while, ma.\"","then":"The gossip waits for her at the gate anyway."},{"text":"\"Honestly, I'd confront them about it.\"","then":"She looks unsure she's ready for that confrontation."},{"text":"\"Maybe it'll stop bothering you with time.\"","then":"She waits for the feeling to pass, but it doesn't yet."}],"why":"Naming it as gossip, not a fact, helps it lose its grip on both of you."},{"prompt":"Weeks later, she says: \"The comments don't sting the way they used to.\"","options":[{"text":"\"Good. You held steady, and we never needed their approval.\"","then":"She smiles, a little steadier. \"Maybe we didn't, at that.\"","best":true},{"text":"\"I'm glad the neighbours have finally stopped talking.\"","then":"It's kind, but the shift she made herself goes unnamed."},{"text":"\"Are you sure it won't come back, though?\"","then":"She looks unsettled again, right after finding some peace."},{"text":"\"Good. Let's not bring the neighbours up again.\"","then":"She nods, but the subject closes before she can say how it felt."}],"why":"Naming that approval was never needed honours the steadiness she found instead."}],"relearn":"'Log kya kahenge' is social pressure, not your worth; neighbours' labels measure nothing."},
  {"id":"yp-1399","cat":"worth-beyond-status","type":"role-play","persona":"any","source":"'lucky to get a match'","hook":"A relative has strong, ugly opinions about skin tone and marriage prospects.","setup":"Tonight, at dinner in front of the children, she starts on your cousin Meera's rishta.","steps":[{"prompt":"She says: \"Honestly, Meera is lucky to even get a match, with skin like hers.\"","options":[{"text":"\"Please don't, auntie. Her skin tone says nothing about her worth.\"","then":"Auntie pauses, a little caught out by the calm firmness.","best":true},{"text":"\"Haha, true. She should be grateful for anyone.\"","then":"Auntie laughs, pleased, and repeats it for the table."},{"text":"\"That's a disgusting thing to say at dinner.\"","then":"Auntie looks defensive. \"I was just being honest.\""},{"text":"\"Maybe she should try to lighten her skin.\"","then":"Auntie nods approvingly and starts naming remedies."}],"why":"Naming her worth plainly, in the moment, stops the comment before the children absorb it."},{"prompt":"Your other cousin murmurs after dinner: \"Auntie says things like this a lot. Should someone talk to her about it properly?\"","options":[{"text":"\"I think so. The kids were listening too.\"","then":"Your cousin pauses. \"Fair point. I'll say something too.\"","best":true},{"text":"\"No, it's fine. I'm used to comments like that.\"","then":"Your cousin shrugs, and the comment quietly stays unaddressed."},{"text":"\"There's no point. She's always like this.\"","then":"Your cousin laughs it off, and the moment passes lightly."},{"text":"\"Maybe I shouldn't take it so seriously.\"","then":"Your cousin looks relieved you're not upset, and it's dropped."}],"why":"Naming who was in the room, the children, keeps the stakes clear, not just personal."},{"prompt":"Months later, the same relative starts to repeat the comment, then catches herself. \"Never mind,\" she says.","options":[{"text":"\"Thank you for catching that, auntie.\"","then":"She smiles, a little proud of herself. \"Trying, for the kids.\"","best":true},{"text":"\"You almost said it again, didn't you.\"","then":"She looks a bit caught out, and the moment turns awkward."},{"text":"\"See, you can learn after all.\"","then":"She looks stung by the jab, even though she held back."},{"text":"\"I noticed. Anyway, how's your garden?\"","then":"She answers easily, though the effort you noticed goes unthanked."}],"why":"Noticing the change out loud, kindly, makes it easier for her to keep it up."}],"relearn":"Skin tone says nothing about worth; don't let colourism be spoken as if it's true."},
  {"id":"yp-1400","cat":"worth-beyond-status","type":"branch","persona":"Sneha","source":"the aunty corner","hook":"An aunty corners you, needling that you're 'not getting younger' with no shaadi in sight.","steps":[{"prompt":"She says it loud enough for others nearby to hear. What do you do?","options":[{"text":"Stay warm, redirect, and ask about her family","then":"She moves on easily, and the moment passes without a scene.","best":true},{"text":"Mumble 'soon, soon' and feel small","then":"You've quietly agreed your worth is on someone else's clock."},{"text":"Snap 'mind your own business' and walk off","then":"The room goes stiff, and the story feeds gossip for days."},{"text":"Launch into a full explanation of your life plans","then":"The explanation only invites three more follow-up questions."}],"why":"A warm, closed deflection keeps your worth steady; you owe no justification."},{"prompt":"Later, another relative repeats the same line, a little louder. What do you focus on?","options":[{"text":"Staying calm and closing it with a light, warm line","then":"The line lands with less weight the second time around.","best":true},{"text":"Answering the question properly, to make them stop","then":"The answer only opens the door to more questions."},{"text":"Getting visibly annoyed at the repetition of it all","then":"The room notices, and the story gets retold by evening."},{"text":"Agreeing that you should probably hurry up now","then":"The comment sinks in a little deeper than it should."}],"why":"Consistency, not a bigger reaction, is what keeps the comment from actually landing."},{"prompt":"By the end of the evening, someone jokes about how the night went for you. What do you say?","options":[{"text":"Laugh and say your worth was never up for debate","then":"The room laughs with you, and the evening ends on an easy note.","best":true},{"text":"Say you're just very good at avoiding the topic","then":"The room nods, but it frames the evening as dodging, not standing firm."},{"text":"Say you wonder if you've been too fussy all along","then":"A few relatives nod, and the fussy tag sticks for the rest of the night."},{"text":"Say you'll have some 'good news' for them eventually","then":"It gets a laugh, but it also quietly feeds the very question you closed."}],"why":"Naming your worth plainly, even in a joke, closes the evening on your own terms."}],"debrief":"A light, calm deflection ends the jab, and staying consistent keeps it from landing.","relearn":"A light, firm deflection ends the jab without conceding your worth."},
  {"id":"yp-1401","cat":"worth-beyond-status","type":"branch","persona":"any","source":"'too dark' rejection","hook":"A rishta's family rejects you for being 'too dark'.","steps":[{"prompt":"You hear the reason through a relative, blunt and plain. What do you tell yourself?","options":[{"text":"Their colourism is theirs to carry; my skin tone measures nothing","then":"The thought steadies you, even though the sting is still there.","best":true},{"text":"Maybe fairness creams would finally make me 'acceptable' to them","then":"You open a search for creams, and the thought sits uneasily."},{"text":"They're right. I'm not good enough","then":"Their prejudice quietly becomes something you start to believe."},{"text":"Just avoid that side of the family for a while","then":"The distance helps briefly, but the thought waits underneath."}],"why":"Naming the rejection as colourism, not a verdict on you, refuses to let it become the truth."},{"prompt":"A relative says the family 'probably did you a favour anyway'. What do you say?","options":[{"text":"Say colourism was their bias, and never a fair reason","then":"The relative nods, a little unsure how to respond to that.","best":true},{"text":"Agree, and joke that you dodged a bullet","then":"The joke gets a laugh, but the sting stays underneath it."},{"text":"Say nothing. It's easier not to talk about it","then":"The comment sits there, unaddressed and a little heavier."},{"text":"Say maybe you really should try to look 'better' for the next one","then":"You quietly agree to measure yourself by their standard."}],"why":"Naming that the reason itself was never valid keeps you from absorbing their bias."},{"prompt":"Weeks later, a friend is rejected the same way, and comes to you upset. What do you tell her?","options":[{"text":"Tell her plainly that colourism measures nothing real","then":"She holds onto that, like it's something she needed someone to say.","best":true},{"text":"Tell her these things happen and not to dwell on it","then":"She nods, but the hurt stays exactly where it was."},{"text":"Tell her maybe it's worth trying some remedies","then":"She starts to wonder if the rejection was somehow fair."},{"text":"Tell her she's honestly better off without a family like that one","then":"It's kind, but the reason for the rejection goes unnamed."}],"why":"Naming colourism for what it is helps her keep her worth separate from their bias, too."},{"prompt":"A new rishta comes along, and you catch yourself worrying how you'll be judged. What do you do?","options":[{"text":"Remind yourself your skin tone was never the measure","then":"The worry eases, even though it hasn't disappeared completely.","best":true},{"text":"Decide to wear lighter makeup, just in case","then":"You go into the meeting a little further from yourself."},{"text":"Cancel the meeting to avoid the risk entirely","then":"The worry stays exactly as it was, just postponed."},{"text":"Prepare a defence in case someone comments","then":"You spend the meeting braced instead of actually present."}],"why":"Repeating the truth to yourself, before it's tested, keeps the old bias from setting the terms."},{"prompt":"Months later, a cousin mentions the earlier rejection, almost in passing. What do you say?","options":[{"text":"Say it taught you plenty about their bias, and nothing about you","then":"The cousin nods, and the story finally feels behind you.","best":true},{"text":"Say it probably stung because you're too sensitive","then":"The topic closes, but you've blamed yourself for a sting that was never yours."},{"text":"Say you still wonder if you could have somehow done things differently","then":"The doubt resurfaces, right when it had started to fade."},{"text":"Say it worked out fine in the end, no big deal","then":"It's true, but the unfairness of it goes unnamed."}],"why":"Naming the lesson as theirs, not yours, is what lets the memory finally lose its weight."}],"debrief":"Colourism measures nothing real; a skin-tone rejection is their bias.","relearn":"A 'too dark' rejection is colourism, not a read of your worth."},
  {"id":"yp-1402","cat":"worth-beyond-status","type":"branch","persona":"any","source":"settle down and relax","hook":"A relative tells you to forget the stretch role and just settle down instead.","steps":[{"prompt":"The comment lands right before your interview. What do you do?","options":[{"text":"Go for it anyway. Your growth is real worth","then":"You walk into the interview steadier than the comment left you.","best":true},{"text":"Drop it, since 'it won't matter once you marry'","then":"You shrink a choice that was genuinely yours to make."},{"text":"Take it but feel guilty for 'choosing career'","then":"A false choice sits with you through the whole interview."},{"text":"Snap at the relative for the comment","then":"The moment turns tense, and the nerves before the interview double."}],"why":"Your growth and work are real worth; no single path is the measure of a life."},{"prompt":"A month later, at a different family gathering, the same relative brings up 'settling down' again. What do you do?","options":[{"text":"Talk plainly about what excites you in your work","then":"They listen despite themselves, and the comment loses its edge.","best":true},{"text":"Downplay your work so it seems like less of a big deal","then":"You shrink your own excitement to make it smaller for them."},{"text":"Point out how often they doubt you","then":"The moment turns into an old argument instead of a new one."},{"text":"Say nothing and let the comment sit","then":"It sits there, and a little of your own excitement dims with it."}],"why":"Naming what excites you shows the growth is real, without needing to argue the point."},{"prompt":"A year on, the relative admits things have 'actually gone somewhere' for you. What do you say?","options":[{"text":"Thank them, and say the growth has meant a lot to you","then":"They nod, a touch surprised, and ask more about the work.","best":true},{"text":"Say you knew it would work out eventually","then":"The moment feels a little more about proving a point than sharing."},{"text":"Remind them they doubted it in the first place","then":"The comment reopens a debate that had actually quieted down."},{"text":"Shrug it off like it's no big deal","then":"You downplay something that's genuinely mattered to you."}],"why":"Naming what the growth has meant, warmly, lets the moment be about the work, not the old doubt."}],"debrief":"Your growth and contribution are real worth; no one path is the measure of a life.","relearn":"Growth builds lasting worth; settling isn't the only 'real' path."},
  {"id":"yp-1403","cat":"worth-beyond-status","type":"branch","persona":"any","source":"'a disappointment'","hook":"Your brother calls you 'a disappointment' for being 35 and unmarried.","steps":[{"prompt":"He says it flatly, in front of your parents. What do you do?","options":[{"text":"Stay warm, hold ground, and reject the label","then":"The room goes quiet, but you don't take the word on.","best":true},{"text":"Agree you've failed and open a matrimonial site","then":"You take on shame that was never actually yours to carry."},{"text":"Scream that he's a coward and cut him off","then":"The cut-off costs a bond you could otherwise have kept."},{"text":"Laugh it off like it doesn't bother you","then":"It bothers you more than you let on, and it stays unaddressed."}],"why":"You can love your family and still not accept 'disappointment' as a verdict on you."},{"prompt":"Your mother later says he 'didn't mean it that way'. What do you say?","options":[{"text":"Say the word still landed, meant or not","then":"She nods slowly. \"I'll talk to him about it.\"","best":true},{"text":"Say it's fine. You're over it already","then":"She relaxes, but the word stays exactly where it landed."},{"text":"Say she's just making excuses for him","then":"She looks defensive, and the conversation turns tense."},{"text":"Say nothing, since it's easier not to reopen it","then":"The word sits there, unaddressed, waiting for the next visit."}],"why":"Naming that it landed, even if unintended, keeps your worth from quietly absorbing it."},{"prompt":"At the next gathering, your brother avoids you, awkward but not apologetic. What do you do?","options":[{"text":"Say hello warmly, and leave the next move to him","then":"He relaxes a little, relieved not to be frozen out, and asks how work is going.","best":true},{"text":"Ask your mother to make him apologise","then":"Your mother sighs, and the request only leaves him more guarded."},{"text":"Bring up the comment again to make your point","then":"The old argument reopens instead of easing."},{"text":"Ignore him completely for the rest of the night","then":"The silence says plenty, and nobody actually talks it through."}],"why":"A warm hello keeps the door open, and the apology can still be his to give."},{"prompt":"Months later, your brother says he's sorry, unprompted. What do you say?","options":[{"text":"Thank him, and say the word still mattered to you","then":"He nods. \"I know. I shouldn't have said it.\"","best":true},{"text":"Say it's fine. Forget it ever happened","then":"The apology lands, but the earlier hurt stays unspoken."},{"text":"Say it's a bit late for that now","then":"He looks stung, even though he was trying to make it right."},{"text":"Change the subject before it gets awkward","then":"The apology hangs there, only half received."}],"why":"Accepting the apology while naming that it mattered honours both the hurt and the repair."}],"debrief":"You can love your family and still not accept 'disappointment' as a verdict.","relearn":"'Disappointment' is imposed shame, not truth; hold your worth warmly."},
  {"id":"yp-1404","cat":"worth-beyond-status","type":"branch","persona":"Nisha","source":"'wasting her womanhood'","hook":"A childfree friend is told she's 'wasting her womanhood' by someone at work.","steps":[{"prompt":"She repeats the comment to you, still visibly shaken. What do you do?","options":[{"text":"Tell her she's complete; womanhood isn't motherhood","then":"She exhales, like she'd needed someone to say that plainly.","best":true},{"text":"Stay quiet, since it's not your place to weigh in","then":"Your silence lets the comment quietly stand as if it were true."},{"text":"Say maybe they have a point. She might regret it","then":"You echo the regret script, and add to the pressure she's facing."},{"text":"Tell her to just ignore people like that","then":"She nods, but the comment still sits heavy underneath."}],"why":"Womanhood isn't motherhood; standing with her breaks the shame instead of letting it stand."},{"prompt":"A week later, she admits she's started to doubt her own choice. What do you say?","options":[{"text":"Remind her the choice was always hers to trust","then":"She nods slowly, like the doubt is starting to loosen its grip.","best":true},{"text":"Ask if she's sure she doesn't want kids at all","then":"The question feeds the very doubt she'd come to you with."},{"text":"Tell her she can always change her mind later","then":"It's meant kindly, but it treats her certainty as unfinished."},{"text":"Say nothing, since it's really her decision","then":"She's left to work through the doubt on her own."}],"why":"Trusting her own knowledge of herself is hers to claim; your role is to back that, not question it."},{"prompt":"Months later, she says the comment doesn't sting the way it used to. What do you say?","options":[{"text":"Tell her that's her own certainty, not luck","then":"She smiles, steadier than she's been in a while.","best":true},{"text":"Say you're glad people finally stopped bothering her","then":"It's kind, but the certainty she found gets credited to everyone but her."},{"text":"Ask if she's completely sure it won't come back","then":"She looks unsettled again, right after finding some peace."},{"text":"Say it probably just takes time for everyone","then":"It's true in general, but her own part in it goes unnamed."}],"why":"Naming her steadiness as her own achievement honours the work she did to get there."}],"debrief":"Womanhood isn't motherhood; standing with a loved one breaks the shame cycle.","relearn":"A childfree life is complete; stand with someone shamed for it."},
  {"id":"yp-1405","cat":"worth-beyond-status","type":"branch","persona":"any","source":"the reunion","hook":"At a reunion, you feel 'less than' your married school friends.","steps":[{"prompt":"The feeling hits hardest as everyone shares their 'updates'. What do you do?","options":[{"text":"Recall that worth was never status, and reconnect as you are","then":"You relax into the evening as the equal you always were.","best":true},{"text":"Quietly compare and list what you 'lack'","then":"You use their scale to measure yourself, and leave feeling smaller."},{"text":"Hint that you're 'about to settle down too'","then":"You perform a plan you don't have, and the feeling stays."},{"text":"Leave early before it gets to your turn","then":"You avoid the moment, but the feeling follows you home anyway."}],"why":"Your worth was never marital status; recalling that lets you meet old friends as an equal."},{"prompt":"Later that night, a classmate texts, kindly asking how your life's really going. What do you tell her?","options":[{"text":"The truth: full, busy, genuinely yours","then":"She replies with a row of hearts. \"That actually sounds like a great life.\"","best":true},{"text":"A version that sounds closer to hers","then":"It's easier to say, but it isn't really your life you're describing."},{"text":"That it's fine, nothing much to report","then":"The small answer leaves you feeling smaller than the truth would."},{"text":"Turn it around and ask about her life instead","then":"She happily tells you everything about hers, and yours never comes up."}],"why":"Describing your actual life, plainly, shows a fullness that needs no comparison to hers."},{"prompt":"The next morning, a friend from the reunion tells you that you 'seem really happy'. What do you say?","options":[{"text":"Say thank you. You genuinely are","then":"It feels good to simply agree, without adding a qualifier.","best":true},{"text":"Say you're happy 'for now', with a shrug","then":"The shrug quietly undercuts the truth you'd just claimed."},{"text":"Say you're happy, then apologise for having no big news","then":"The apology makes it sound like you owe them an update."},{"text":"Deflect with a joke instead of answering","then":"The moment passes, but the compliment never really lands."}],"why":"Accepting the compliment plainly lets your happiness stand on its own, with no asterisk."}],"debrief":"Your worth was never marital status; you meet old friends as a full equal.","relearn":"Worth was never marital status; you're a full equal married or not."},
  {"id":"yp-1406","cat":"worth-beyond-status","type":"branch","persona":"Karthik","source":"cousin married first","hook":"You feel 'less of a man' since your cousin married first.","steps":[{"prompt":"The feeling hits hardest at your cousin's wedding itself. What do you do?","options":[{"text":"Recall that your worth isn't a wedding date","then":"You stay grounded, and are genuinely happy for your cousin.","best":true},{"text":"Rush into a match to 'catch up'","then":"A pressure-driven choice starts to feel like more risk than relief."},{"text":"Resent your cousin and cool the bond","then":"A false race quietly turns into a real rift between you."},{"text":"Put on a brave face and hope no one notices","then":"You get through the day, but the feeling doesn't actually lift."}],"why":"Your worth isn't a wedding date; men feel a version of this pressure too."},{"prompt":"At the reception, an uncle jokes that you're 'falling behind'. What do you say?","options":[{"text":"Laugh it off and say you're not racing anyone","then":"The uncle chuckles, and the comment loses its weight.","best":true},{"text":"Say you're 'working on it', to end the joke fast","then":"The line invites the uncle to check in again soon."},{"text":"Get visibly annoyed at the joke","then":"The reception mood dips for a moment, over something small."},{"text":"Agree you probably should hurry up","then":"The joke sinks in a little deeper than it should."}],"why":"Naming that there's no race keeps the joke from actually landing as truth."},{"prompt":"A friend admits he feels the same pressure, but never talks about it. What do you say?","options":[{"text":"Say it's real for men too, though it lands harder on women","then":"Your friend looks relieved, like he'd been waiting to hear that.","best":true},{"text":"Say it's nothing next to what women face","then":"Your friend nods, but the moment stops being about him."},{"text":"Say he shouldn't worry about it so much","then":"Your friend nods, but the feeling doesn't actually lift."},{"text":"Change the subject before it gets too personal","then":"Your friend goes quiet, and the moment closes without being said."}],"why":"Naming the pressure as real for men, and harder for women, gives another man room to talk."},{"prompt":"A year later, your cousin asks if you still feel behind. What do you say?","options":[{"text":"Say no. You found your own timeline instead","then":"Your cousin smiles. \"Good. That's honestly all that matters.\"","best":true},{"text":"Say you're still working on catching up","then":"The framing keeps the old race alive, still."},{"text":"Say the wedding never really bothered you","then":"It's not quite true, and your cousin can tell."},{"text":"Say you'd rather not talk about it","then":"The old feeling stays unexamined, just quieter now."}],"why":"Naming your own timeline, honestly, shows the pressure lost its grip on you."}],"debrief":"Men feel a version of this too; worth isn't a wedding date.","relearn":"A man's worth isn't a wedding date; another's timeline isn't his."},
  {"id":"yp-1407","cat":"worth-beyond-status","type":"branch","persona":"any","source":"ranked by looks","hook":"Relatives keep ranking your sister by her looks. She's started to shrink.","steps":[{"prompt":"At dinner, someone ranks her against a cousin again. What do you do?","options":[{"text":"Tell her she's whole, and shut the looks talk down","then":"She feels backed up, and the ranking loses its usual pass.","best":true},{"text":"Join the jokes so she 'toughens up'","then":"You become one more voice grading her instead of protecting her."},{"text":"Ignore it, since that's how relatives talk","then":"Treating it as normal lets her quietly absorb it."},{"text":"Pull her aside after to comfort her privately","then":"It helps a little, but the comment already landed in front of everyone."}],"why":"Looks and skin tone aren't worth; standing with her, in the moment, protects her self-image."},{"prompt":"A relative brings up your sister's looks again, a little louder this time. What do you do?","options":[{"text":"Say ranking a person's looks is the real problem","then":"The relative pauses, unsure how to argue with that plainly.","best":true},{"text":"Tell your sister to just ignore the relative","then":"She nods, but the ranking continues with nobody speaking up for her."},{"text":"Get sharp and snap at the relative","then":"The dinner turns tense, and your sister looks more uncomfortable."},{"text":"Let it go this time, since it's not worth a scene","then":"You quietly hand the moment back to the ranking."}],"why":"Naming the actual problem, calmly, holds the line without needing to raise your voice."},{"prompt":"Months later, your sister stands taller when the comments come up now. What do you say?","options":[{"text":"Tell her you've noticed, and you're proud of her","then":"She smiles. \"That means a lot, hearing you say it.\"","best":true},{"text":"Say the comments probably don't matter anyway","then":"It's kind, but what actually changed for her goes unnamed."},{"text":"Ask if the comments still bother her, just in case","then":"The question reopens something that had started to settle."},{"text":"Say nothing, and just let the change be","then":"The moment passes without her hearing that it was noticed."}],"why":"Naming the change you've seen, plainly, honours the ground she's found for herself."}],"debrief":"Looks and skin tone aren't worth; standing with her protects her self-image.","relearn":"Don't let looks-ranking pass as normal; back up someone it wears down."},
  {"id":"yp-1408","cat":"worth-beyond-status","type":"match","hook":"Match each marriage-market jab to the truth that answers it.","pairs":[{"left":"\"Too dark for a match\"","right":"Skin tone measures nothing real"},{"left":"\"Incomplete without a husband\"","right":"You're whole, partnered or not"},{"left":"\"What's a woman without a child?\"","right":"Womanhood isn't motherhood"},{"left":"\"Matchmaker rated you average\"","right":"You're a person, not a profile"},{"left":"\"Still single, what a waste\"","right":"Worth was never marital status"}],"relearn":"Each jab has a truth: skin tone, a husband, a child or a rating isn't your worth.","persona":"any","source":"jab to truth"},
  {"id":"yp-1409","cat":"worth-beyond-status","type":"match","hook":"Match each pressure line to what it really reveals.","pairs":[{"left":"Pity that you're single","right":"Their bias, not a flaw in your life"},{"left":"'Log kya kahenge'","right":"Social control, not your obligation"},{"left":"Rejected over your looks","right":"Their colourism, not your verdict"},{"left":"'You'll regret being childfree'","right":"Their script, not your self-knowledge"},{"left":"'A man's nothing till married'","right":"Pressure men feel, not a measure"}],"relearn":"Pity, gossip, a rejection or a regret-warning reveal the script's bias, not anything true about you.","persona":"any","source":"what it reveals"},
  {"id":"yp-1410","cat":"worth-beyond-status","type":"match","hook":"Match each source of worth to where it truly comes from.","pairs":[{"left":"How you treat people","right":"Your character"},{"left":"The work you've built","right":"Your contribution"},{"left":"Becoming someone you respect","right":"Your growth"},{"left":"The people you've stood by","right":"Your relationships"},{"left":"Living life on your own terms","right":"Your courage"}],"relearn":"Real worth comes from character, contribution, growth, relationships and courage, never from status.","persona":"any","source":"sources of worth"},
  {"id":"yp-1411","cat":"worth-beyond-status","type":"match","hook":"Match each shaky thought to the steady truth that holds your worth in place.","pairs":[{"left":"\"A rejection means I'm less\"","right":"One match's no is no verdict on you"},{"left":"\"I'm incomplete without marriage\"","right":"You're whole exactly as you are"},{"left":"\"My value is my biodata\"","right":"You're a person, not a profile"},{"left":"\"Lighter skin would make me matter\"","right":"Colourism measures nothing real"},{"left":"\"I've let the family down\"","right":"That's imposed shame, not truth"}],"relearn":"Each shaky thought has a steady truth: you're whole, not a profile, and shame isn't a verdict.","persona":"any","source":"shaky to steady"},
  {"id":"yp-1412","cat":"worth-beyond-status","type":"match","hook":"Match each life choice to why it takes nothing from a person's worth.","pairs":[{"left":"Staying single","right":"A full life needs no marriage"},{"left":"Being childfree","right":"A complete life, womanhood isn't motherhood"},{"left":"Marrying late","right":"There's no boat to miss and no one timeline"},{"left":"Divorcing","right":"A marriage ended, your worth didn't"},{"left":"Marrying and having kids","right":"An equally valid, respected path"}],"relearn":"Single, childfree, late, divorced or married-with-kids: every path is valid and takes nothing from worth.","persona":"any","source":"choice, not deficit"},
  {"id":"yp-1413","cat":"worth-beyond-status","type":"match","hook":"Match each thing relatives 'score' to what it actually has to do with your worth.","pairs":[{"left":"Your skin tone","right":"Nothing at all"},{"left":"Your kindness","right":"Everything that's truly yours"},{"left":"Your marital status","right":"Not one thing"},{"left":"How you keep your word","right":"Real, lasting worth"},{"left":"Your family's 'standing'","right":"Nothing about who you are"}],"relearn":"Skin tone, marital status and family 'standing' have nothing to do with worth; kindness and integrity do.","persona":"any","source":"score vs nothing"},
  {"id":"yp-1414","cat":"worth-beyond-status","type":"match","hook":"Match each even-handed truth to who it's mainly about, without dismissing anyone.","pairs":[{"left":"The pressure falls hardest here","right":"On women"},{"left":"A lighter version of it lands here too","right":"On men"},{"left":"The script constrains this group","right":"Everyone, unequally"},{"left":"Worth stays untouched for","right":"All of them, whatever the pressure"},{"left":"The thing to push back on is","right":"The pressure, not any path"}],"relearn":"It hits women hardest, men feel a lighter version, it constrains everyone; push back on pressure, not paths.","persona":"Karthik","source":"even-handed match"},
  {"id":"yp-1415","cat":"worth-beyond-status","type":"match","hook":"Match each kind thing to say to yourself with the worth-truth it carries.","pairs":[{"left":"\"I like the life I've built\"","right":"My worth is mine to define"},{"left":"\"Their opinion isn't my mirror\"","right":"The market measures nothing real"},{"left":"\"I'm whole right now\"","right":"No status is pending to complete me"},{"left":"\"My choices are mine to own\"","right":"I weigh most in my own life"},{"left":"\"I'm proud of who I've become\"","right":"Growth is real worth"}],"relearn":"Kind self-talk carries real truths: your worth is yours, you're whole now, and growth is worth.","persona":"any","source":"self-talk to truth"},
  {"id":"yp-1416","cat":"worth-beyond-status","type":"spot","hook":"Spot the two lines that price a person like an item in a biodata.","scene":[{"id":"a","text":"\"She's thoughtful and easy to be around\"","trick":false},{"id":"b","text":"\"Convent-educated, fair, slim, that's the package\"","trick":true},{"id":"c","text":"\"He's honest about who he is\"","trick":false},{"id":"d","text":"\"Government job and tall, so high value\"","trick":true},{"id":"e","text":"\"They each seem genuinely kind\"","trick":false}],"why":"'Fair, slim, the package' and 'tall, high value' price people like products; the rest see real people.","relearn":"You're not a biodata package to be priced; your worth isn't a list of marriage-market traits.","persona":"any","source":"catch the pricing"},
];

